INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f56dc154-6be4-443b-b472-7cff4926834b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur?', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'fd55cb5604c9ba88_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d56ff0ff-8f1d-43eb-be5f-4ee5ec01f957', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet?', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'e1eb08504a04278b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25ce8352-bc35-4a0c-8291-2df6ac6b503a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model?', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '26b7c14bdd3543ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4cd5019-45a6-4384-aaef-5b2c7c259ade', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes?', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '7c58764ff1fd110b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbedd1fc-16af-4b53-a7ed-88f28d224b40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network?', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'f24aefb11f0905e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0af10ee1-30af-495a-bcf2-a33cdba7073b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device?', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a5af32cdb3b940b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb5fac19-71d1-410e-a3b8-7817c348732d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed?', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5bfe64230ccfccfe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a413c70b-eb2c-480b-9703-9dd4ae85e340', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device?', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '29e4530713ae302e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86309170-0bfa-4804-bb61-b3fce6a563a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device?', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '537339b8d9a30f0f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('100f06f1-5520-4fa0-96fd-e2051bcedb3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos?', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c52566a883d8c490_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a0fce86-57d2-4ca4-9868-66944ca550a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI?', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '14ea9c41fc64932d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e9675e4-7d2d-4001-a0ad-c2eda10c26a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI?', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '04fb27abab0a99f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dba38a8f-fe18-4006-b175-92678a25fd62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device?', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '95f84ebc3fe83433_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90874cdf-fd96-4bb4-9466-05b3c92aad67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI?', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '73ba15cc7b9e1f3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f589f07a-bc1d-4324-86a2-63f57454c273', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device?', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2c371bc01d9672ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37bdb33a-b44d-4faa-be57-5c15512fef3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device?', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e049e54bd5971cef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a32f5ee5-4871-4160-9300-ff2f5432d26c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos?', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '2456d01e4b5b9a0d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8214b1a6-93bf-4395-b1e1-4a7f8f4d9813', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface?', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '96c2320bc7cb5cf4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d26f8930-4be8-472f-916c-6c20c793ef55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos?', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4ed0e19d73b49a82_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0bee488-734b-4991-a0fe-ab0874828dee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device?', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5af92cd30c2bae13_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d091a3df-87df-449f-99bc-d97589240f9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device?', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f073c3d7c3eb3a2a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cf40804-86c2-4702-9c14-2d28210c7f0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS?', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '45643d1ff051f8a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dbb7bb5-e824-44c7-bfbd-bb4cee5685f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device?', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '193466b289c3cd69_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('234f6d26-6a83-49ff-9739-6735e46dc22d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos?', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'a05a78b519cfb88f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d013efb-cd22-43ef-8b7a-0ac3a01f146e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos?', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ee5083d156cd7f8d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06b4d762-6c6f-4f56-bfc7-9e08a588d133', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos?', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bf95894abf617ce6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a600779-1a9a-4ec6-95d8-3f87a068fca1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos?', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c9f4e1dce0128a52_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5be0fda0-1c6f-4f85-bc20-66e1edc63b9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies?', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c30fc75093d6e1ac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d467b2a3-09b3-4505-97f9-386519dfe0f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos?', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e0cbee133b05a951_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dc5d3ea-1b9d-4d27-ade2-982040b9d213', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device?', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '87189909d3bb3ff5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bad9b0b-af26-4f91-9712-f98ab87307a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 2).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '0a01bde7bbe83e0b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3e50671-feaf-42d5-b411-441864cb5de2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 2).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 2).', '{}', 'Networking Fundamentals', 14.0, 'e4e75846875ed596_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('485c23f0-5a6f-4626-88c5-50f3648096a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 2).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 2).', '{}', 'Networking Fundamentals', 14.0, '466ff7e8493a6668_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a589f6ee-277a-4ed2-800f-fb0b0a5956d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 2).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 2).', '{}', 'Networking Fundamentals', 12.0, '0780905dc9d2c7b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d06e5a4-ea10-47a0-b3f7-d2123d2ab19b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 2).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 2).', '{}', 'Networking Fundamentals', 14.0, '4aae70dc01d21b59_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aa13063-10e2-4cb7-9f15-894c01ce250b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 2).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '15a81bd1e1396dbd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c44b060e-be54-41fa-9813-c97b5ca3f9fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 2).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f183f0fcc94a6328_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea91f1f4-7ccd-4904-8e19-41a71fce680a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 2).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd03948f437837db9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea7c0af3-462b-4a6d-bc40-93f1c3cc753c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 2).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f7a6d855ede04832_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('181d1cc8-05dc-4326-82e2-06b1f7e2b5c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 2).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a884e056060d89af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c0544ef-6122-4a77-8bb1-f48fcc6c8570', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 2).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5294ab7e941dd5ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e389961-d024-4a9a-b779-0b6cae405084', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 2).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3a777530bb8b9680_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d77cfae-4b4e-4d74-a325-f7a3bb99e938', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 2).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '07a72b8f666f7b02_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fcb9c25-e9de-4c2b-a3e4-6f179cdc8988', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 2).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ba0d82ef1c50a62a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90bf5a55-20b0-4011-9f35-f4a2cc5d6937', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 2).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '09bda7c8899a7969_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3be95249-04f0-453a-903c-554fdf04fdba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 2).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fa14f84f7692cedb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f788bcc7-643c-4691-a9c8-d3dfc3420781', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 2).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7d790937dd4f42e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96d27432-ce05-4cb2-84b7-64b446743c3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 2).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '60bc7436529d45ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de48eca8-927e-47e2-9f73-98b0a75ff99c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 2).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '40b02be47462f444_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e832e1f-cbb3-4ece-86c4-41ebb654c748', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 2).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4931b4ccedef0b63_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81158c2f-fbee-4e02-bd78-d46880a4c5fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 2).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '76848e13da7f575c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0e3c65d-ebf2-4902-9132-ed871f24ba46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 2).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8bc40c3659d4118c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('765388aa-82ce-44e3-abeb-8bba6423382c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 2).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '30208fc807c8eef2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc5a2b72-ae97-4ead-b152-810459f28b00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 2).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e696bd2ec39b891d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97da3d1f-0c6d-403e-b89b-02c9ef4b302a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 2).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '07f4f557479a61ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('328e5b0c-0ea3-4506-8618-19213f9b5998', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 2).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5d76f861e269e85c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42fb2ce3-fcf5-44a2-9d51-20ccbef32da2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 2).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '3083e439657d7cdb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cea56a8d-2830-4327-9e20-0bb8a560ccc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 2).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '78c992a3f5be99d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6155b9b4-173f-4088-82f9-e771ed145172', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 2).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9342a780c195a13b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e925423-a16b-4a97-b3f6-b44e4adbf276', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 2).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '91fb1d5a4532a8b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97201f2f-94a1-40bd-a817-dae3e6ef072c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 3).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '06da7bf53f489122_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5405d3d5-fc12-4b70-9fde-5c1d5d958ab7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 3).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 3).', '{}', 'Networking Fundamentals', 14.0, '23e039ee175ad38f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9d0f1b8-b4e0-4e16-9e2a-ceb411121e80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 3).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 3).', '{}', 'Networking Fundamentals', 14.0, '7cd5beb8122784a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29d84fbd-a76b-40e0-99c2-575f248fc637', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 3).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 3).', '{}', 'Networking Fundamentals', 12.0, 'f17223cdca23d172_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bf3a035-6f15-499f-b278-ef11675565df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 3).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 3).', '{}', 'Networking Fundamentals', 14.0, 'f6a554b78cc7b5ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5b342a9-c4c8-4533-a6e3-8d0dd0bdfc7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 3).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '9ac5db8ee4853020_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('287a77a5-d890-40ed-8074-0a5b879e86aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 3).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'eac525b4793349c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06bdabe2-294b-469b-8139-547b2ebbe229', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 3).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0341cb7178ca6bfe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae34d060-fb2e-40bc-999e-4c0ff5d11fd2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 3).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8f1d9ea6d503e38c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b404adf-bcca-446d-847c-37b1fcd4e0e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 3).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '796fd678c3295943_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7ffe259-843a-46a5-b96e-832da6404fb6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 3).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9963dba2ad7b57e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afec8929-5065-44f5-a16a-ee7d271a2eb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 3).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ae63a22b40c7c6e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15fb2344-f0bb-4d96-b1f0-0005f9c51cfa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 3).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '616f434be45bdc5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef3c9aa5-6f0d-4e1f-8e24-200acdaa1104', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 3).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8b13604b92fdff90_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0852e0d0-8076-4eff-82bf-5cd8b328a5f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 3).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bbfcff5ba45ba1f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c4018de-3a02-47e3-a3fa-31b8ab24ca27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 3).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '84c442027315ee70_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33ca014a-ff3c-42ce-845e-a1435d107874', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 3).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '15f4473c508576f7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4258498c-657f-4d6d-848a-26793acfc886', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 3).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '900e15be0743d086_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71622a87-7145-49fa-99c9-66f1da0a4726', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 3).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '097bdf0c69c90e5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dae8a742-21b7-4515-a8d2-02589929e7a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 3).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '292eb7f7051a781b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f664002-9285-4774-8ff0-11037f403edf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 3).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3d603a060c8e1489_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffa76677-490f-40a8-8067-10a84fd3ff0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 3).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '65bbf8ad7f7bc691_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9ecc338-682d-4fea-aaba-fe36e50a0a61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 3).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '55c27ffdff7b1046_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e08840db-f79d-439a-9d66-414309b8edce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 3).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4b30352bc0a89a01_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99fc1b02-8cc2-47e8-bcc1-b63248bdca2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 3).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '18f33aba91b42667_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c64cb77-554f-4605-b06e-ac6103cc6565', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 3).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '710768056126dfa8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ffdd707-2d7e-47ac-b7ad-4c9e51404d43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 3).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5c60979b8cb1ff38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a1eeb27-1e16-4d55-9047-fa4c031251ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 3).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '04b0bb3cfc244f29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00d2cc8e-8b4d-4988-ae30-6e4a85ec6071', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 3).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'af6d2ece020c5797_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acf06dee-5336-4aa9-8e6f-c496deb81961', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 3).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '66c5462a8f584d3c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13fca4a2-f60c-488b-9f97-41825731bb11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 4).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3c8a9e6d2dd2400d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d626195f-cda2-4d98-93c9-1a1a5f687023', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 4).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 4).', '{}', 'Networking Fundamentals', 14.0, 'e5d58360ddbbc73a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75610efd-b768-423c-ada8-fd2ebb889276', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 4).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 4).', '{}', 'Networking Fundamentals', 14.0, '947df955108cb18e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df76f33d-1799-4402-911e-28da8fd6dad5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 4).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 4).', '{}', 'Networking Fundamentals', 12.0, '28a86b0d10629307_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b6d49f7-fff2-4d95-bfd3-913f495b4ed2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 4).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 4).', '{}', 'Networking Fundamentals', 14.0, '3ff8c89029675353_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83bfea09-5b03-4bab-8b9e-8d07b0aad5d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 4).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '145d3a8cf79eeb55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51ffe98a-8cce-4908-9faa-a447c76385d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 4).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ad9af70e0cd29e05_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1aee9c69-5ece-469a-b6ee-e67a012c0dc4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 4).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f9b89863145205a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dec10eff-2087-4318-996b-44d225003e6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 4).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '15067c5332ac89d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d8e8413-3df9-4b18-ac87-684fe47cc41d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 4).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '9d2990996054c972_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('810e1a1c-0a4b-4363-a44a-a13d63a056f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 4).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e7a15f93f658f931_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9524306c-7122-451a-af56-113a0231c65c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 4).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7c0192702347e15b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('398e0587-1368-4520-a1cf-0d7ad3c658cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 4).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '96a098dac53a2acc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6642607-961f-464b-a4e2-b6e85856ea72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 4).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '23e9744a966ceeb6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7433283-1c3f-4937-8570-d607dc707b0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 4).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '800fd3e9dfde31c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cf5d05f-c9a0-48f9-82a3-36f19a9609a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 4).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '64fd18687e8a9b10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c727c2a4-13ee-4ee8-b90b-15c1a8e3cbe5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 4).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f57bf5d5d436f349_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57f5b774-be18-4c5f-a0f6-922ff3778562', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 4).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '327c28743918587a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5abdf86-ce50-4e9f-b61a-f9d80c78f230', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 4).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1ac530b2e2905a23_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6baab90-ad7f-4324-90d6-e3a86dd64cf8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 4).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a8d6c0ee33d96dfe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b0ea26e-e4cd-4570-8324-423a01375198', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 4).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6d3e39aa77996bfe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aba53c92-ca51-4f10-9be6-cf9b93c02dc3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 4).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a8f286ed6287dbc0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00994d41-f575-4a8a-a950-28a5635fe394', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 4).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5f56dbd948b8b3da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60091d53-fc10-4b15-b768-31068be429c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 4).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7097835247396c7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d28f834c-e48c-4602-8032-c24e42aafe5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 4).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6e419c729aaefd5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cda0d0df-5810-4a07-9bb0-0e8e87f7c073', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 4).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8c59c3cdcf690924_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e140fc0b-b4e9-4450-93db-583490471b23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 4).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8e798fa299c364df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0b8f8dc-ba64-4d1f-b890-cc725a1913f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 4).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8c476223f1da2058_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8085389f-d180-4c14-bb09-82c75a553923', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 4).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '132bf698a4eae3d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b3718c0-3419-4d16-a4c8-1db110fe4146', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 4).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '870a32f0eeba7251_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d61e64b-e9a6-48e1-a2d8-5f61b1531b91', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 5).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '808b1d598ea3e06d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2646e433-43ce-4a2f-90d4-b448fe3e8e18', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 5).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 5).', '{}', 'Networking Fundamentals', 14.0, 'fd5a06a500fa6e14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad1ed068-57a7-430a-b858-6259d07f4376', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 5).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 5).', '{}', 'Networking Fundamentals', 14.0, '5ffb61af3b53a98e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de835449-a0cd-439e-8acb-939f653b2cec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 5).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 5).', '{}', 'Networking Fundamentals', 12.0, '1dc7eb15e7d5b773_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b73d2478-f5c0-4f13-a5a3-a3456d1d2ddc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 5).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 5).', '{}', 'Networking Fundamentals', 14.0, 'b27c9ef2d2acc67e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0edab94-0676-4d12-8855-4df19b365bbd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 5).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'adc646cbbfa7df6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87175e41-9cf4-4c23-b24c-a5d481a2e25b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 5).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '89e5a3bc260bb9db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('370aa334-3ea8-444c-aff2-9b25e3f6406b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 5).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ccb16d89ca2d8e81_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52e4c14b-0e09-4d09-a114-0efb3e2085bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 5).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b974287abfce86ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8698ee83-9110-4050-b0fa-dac1a1fa3ee1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 5).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3fa8ce28804b33f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ce80b15-cc92-4b4d-9b81-1cf67359b37c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 5).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'be1718d0e243f237_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9236c228-7fc2-41b3-b7db-597f2ceffeed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 5).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '118b821429ff6659_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a1f5cb2-6e4e-4982-9abe-0ea90da16a58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 5).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6f325f3f4ce779d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11c581b7-7e31-4f99-a524-fcfa1440b200', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 5).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8d5cc0f0b98bb9bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51e4c43b-37db-4d72-9228-2a0dfb1d1b3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 5).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c8ae3eeeafaeba74_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f42a8ac-843c-4126-9427-d35307ae9f70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 5).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '75b04945e44e4000_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('216d06a6-5581-4e8f-a72c-d038c4fe7579', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 5).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '32fc9d8ee425240f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64dc81b8-791c-4a31-acd7-0c6d4fac5e65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 5).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c42f47ffe3d94276_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b810869d-c943-4e48-9e4b-0f4ff3c02309', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 5).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0aa57e2d5f838851_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c47309f-bf66-43dd-abaf-62b839f6e0e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 5).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2613152d3a1d961c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90830d22-596f-40d5-be67-061698e1a792', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 5).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5dda15403c8d6823_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1baee705-b514-4753-9ebe-d28b3017b959', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 5).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2f80238ace6c56db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdf861d3-4fc2-480c-9355-a202bc306b00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 5).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '527827ac6fbbb111_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e6ec8d0-275c-457a-9d8f-8be563c69c05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 5).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'db8fa3d56f5146b6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e9f81ed-3c54-4f18-b976-c9d39eb9f5ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 5).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd9562bc8c873a432_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5659f9b1-e27c-4014-9d1e-1f959ed3b7f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 5).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bfef4317ceb857b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('831afcf6-280c-463d-b217-6e239e00f75c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 5).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '1496e57631a1d06b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf63ebee-7160-41c9-a890-063f2d767b8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 5).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '78ae44504eba755e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d122a8d9-cb82-4a96-bc35-d6266a251dde', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 5).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'da6ab8dbab9a8555_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a248922-1042-4d4b-8f33-5d50d9469809', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 5).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '191aa2342d7d1cb1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae350431-5ed1-4858-b6ca-611ddb2e1918', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 6).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd7af1df752d11483_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3b939a3-73fc-41e8-b8db-a2dd6b6aa98f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 6).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 6).', '{}', 'Networking Fundamentals', 14.0, '505963c5d9aa2d5a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa3a1dde-7145-413c-bb8a-3f7584f31f10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 6).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 6).', '{}', 'Networking Fundamentals', 14.0, 'a37a509846b8599d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97a409c0-4a93-476a-a015-0da309b418ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 6).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 6).', '{}', 'Networking Fundamentals', 12.0, '313a2c019b1415b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea596d2d-0882-4407-b377-cb92e75d83e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 6).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 6).', '{}', 'Networking Fundamentals', 14.0, '8b49c4ba1546cdfd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7da34b0-b594-463d-99f4-59373aa274e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 6).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a83f81a224ce41df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f609c588-3ad7-4e7c-b7ee-7fea7e02b5ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 6).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '77a48a0d09713f32_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0016bb09-caf9-4971-9c4b-d28beee3c8e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 6).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6e994541c923d415_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69e9a556-3452-4ff1-8f39-2d046923bea2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 6).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2e629c7be2f2dc79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ab7a6a0-f862-49b8-bc91-07bc93caffd1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 6).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '31fd48903627038e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d80fff13-1415-4ee1-adc8-3f3d2461c2a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 6).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '39345547f1c3b334_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2295c98e-428e-499c-bd87-fcad0332e1c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 6).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '40d2dedb507ab871_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50312422-0dfe-4a2c-b4e0-361a316734f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 6).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6785cfc181ac512e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fd5a1b9-4bd3-4090-90e6-8de5bdd7a4ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 6).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'aa589a71a5e99557_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6535484e-09d3-428b-be0c-1e40267547b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 6).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f5d71d9092e67877_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c58c9bc-9227-4221-85f9-d43c0ef6f272', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 6).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1a129574c158665c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4039c49d-5640-4e26-819a-33db2e251b5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 6).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'da0359c28fa7ca09_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2da0eb7b-fb6b-4327-8d71-364a89b0565e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 6).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '65009855879f154d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a434878-d148-4c53-a8a0-c948bbfeb6a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 6).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'eb3c7b678bd50b35_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fefdad5-b4da-454b-9852-e6a15e7e5a0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 6).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '826613b8a2787283_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8fa77e4-6911-44d3-9389-185c4faa95ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 6).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6087980c70de0cac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3100ccfe-ad1d-4b8b-9fa3-858d60e2ed66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 6).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a6e1a81c5a38a3a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a319e09c-0785-472d-a457-37581a862966', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 6).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ab809f160a000851_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('182c46a4-769d-4ed9-8001-c558ee59edb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 6).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ba8d8ef1e70f4f3c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dab1544b-ef42-40cb-b32a-e9d387f4e0f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 6).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b6c87cef988195ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34184aef-1f7e-4143-9750-e3dafe88a3d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 6).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6279e27cd6a441e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f81016e1-f919-4ac8-9988-192277eab3b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 6).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '2d2dac7a4ae130f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caea2eb4-a30c-466e-99bf-e72e1e4658dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 6).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '1443110162707066_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b464921a-e68e-4cc6-b535-2cd4d557e555', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 6).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '659c945cb6c2e015_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e91cd273-a794-4590-95df-b1fa0c06773a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 6).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '75f5beefd5f0efa8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee2ad483-2a41-4e67-8568-06b186e8c55c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 7).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '0532218b4b017464_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76b64326-f44c-47fe-9bd1-f9c109860c2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 7).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 7).', '{}', 'Networking Fundamentals', 14.0, '5c15e24f16e33073_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08ec25af-85ec-48f5-9db1-4c6313fdb2ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 7).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 7).', '{}', 'Networking Fundamentals', 14.0, '06c3409ccc1c6afb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aea64981-419c-4917-b9d5-8476a9d44e2e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 7).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 7).', '{}', 'Networking Fundamentals', 12.0, 'ca27c171c1847c57_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdb77eed-0b53-4211-9bc7-fe305f51a969', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 7).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 7).', '{}', 'Networking Fundamentals', 14.0, 'd8b3d6279cd9f80b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38f7f3f8-2d09-44c6-9e65-3ad0cb9b10f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 7).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2cfc624233ee710f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a119a9f-d704-4f09-9dfe-1c02894ae8fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 7).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '89e04d5c12d938b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('276d394b-6b99-41fb-bad0-98626447a44c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 7).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '43d23d4e76890efa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d82580de-865d-44a7-9d59-cc5ffa5f4049', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 7).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8b135207b72ae0d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccba2b6f-e2bf-4000-9aed-a83168551add', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 7).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '0cf50a85d7b59f11_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('443ff44d-686b-49f5-a3e1-e0d84488982c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 7).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b235e0dfbc62674c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c2d7469-8ad5-42b4-9158-760c878307dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 7).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'efb94c16b8285ebb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('292b9f36-5c07-405a-a103-8d8547fbe3e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 7).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '02ab2a5e3ab5d58c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bda24dc-490c-412f-a464-763ff73d0b04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 7).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1ba87cc1adc43a07_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3116290-51f3-4677-8e8e-311449ddae0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 7).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '540c4d783f592b74_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff8ac300-a6ed-4682-93b7-b340cc79f2f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 7).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '20af359ead5064d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac68ba21-b539-407a-802b-8bfaecb561a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 7).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd28b090d980fe83e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77988fc4-9003-45a7-9919-792c3030fa54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 7).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '52b21e3484056be8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f15c2386-7d65-4bea-b551-d074f475b47b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 7).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0609c70cfe340ebd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80d0e2ba-8deb-4703-ad3f-126ae6b09fb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 7).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '56d0dba3fc5f562e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5c42256-6e5c-459f-bd1a-6ce5ba62337f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 7).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a2f9b60138e94877_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fa40f51-6eb7-4337-b877-c0c91b4cdb06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 7).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3e6670dc405e50db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('faee40fa-0587-44fc-b48f-1572c381eed5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 7).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b3ee894a0dade9c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74415cb7-0327-45f6-9cbb-f06d7e3d14b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 7).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f30d6b29b6ba498d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f54a562-1069-45ee-972e-4b6e986e1559', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 7).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cfcc595286555c9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8eee63c-25ac-4189-bfa5-f136de3c1635', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 7).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '28f6063bfbf1b047_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d8f1102-657b-4ed5-9eaf-cb68a342eb37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 7).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '3ed0dd9dc59188df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1150182a-7b68-49cd-bf8d-600d595f590d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 7).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'cdaddadf20c7a18c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('828a15d4-2773-477f-9ba3-801f3e6be439', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 7).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '80f024453405fe6e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ec460bd-f896-488c-b016-4609963a0ea3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 7).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4225e2f21bc51785_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4df55dd-038a-46dc-99c3-301e2ae2a613', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 8).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '90a3abd63cb45162_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6186ba0d-20a8-4fc8-aff7-ba79a412b68c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 8).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 8).', '{}', 'Networking Fundamentals', 14.0, 'b661c68b46c91a03_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e4b0915-261e-4834-90a1-2c498f121bff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 8).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 8).', '{}', 'Networking Fundamentals', 14.0, '6710b943c5e9286a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('678c83d1-001f-4da6-980a-1fad49a02a52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 8).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 8).', '{}', 'Networking Fundamentals', 12.0, 'c026668b503c906a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbd08846-2103-4b81-b703-d4b8969a1ecb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 8).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 8).', '{}', 'Networking Fundamentals', 14.0, '6569f489ee086a5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('beb20496-2fd8-438b-96f4-106185422ef0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 8).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '10e54d0119eb5848_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed5ef1ae-143c-4c4b-803f-664bc019969f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 8).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4185517e9edbd404_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85571af4-ca1a-49b8-a737-7a8707c53ce9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 8).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'db58217fa88eed6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e6c5ab6-4013-451e-8bb8-f92bb058328e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 8).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '31cf1ac5c33dd627_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cea009c-1a1b-42f1-95a7-6dcba6a6467d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 8).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '4783d27d48bda1e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('658db1e0-8e8a-4fd5-8da6-4bc89a33cd74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 8).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4e8a886376f54966_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45f241aa-ef43-44c7-b66e-cf1ff3443988', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 8).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2e8916eb569e673f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f01785cd-de84-43d7-9d9c-25ba90c1fc06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 8).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '120ecb00f810aae1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b59f0a4-6f5f-4efc-b626-587032ddb5ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 8).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9fe21739c8fc8f52_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a90b5b1b-2b0a-4789-96a8-7f3d7e2bdc61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 8).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6a54e46a6c509403_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('790e5166-45cd-4ce2-9590-1ccd06796ad4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 8).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '527ff43ce30de00a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4af7cfeb-d9a4-43e8-866e-498fb832f747', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 8).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '378fb563a1b7b406_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd93f3f9-bbe8-4fe2-8eb2-787011fd6084', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 8).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '3cd3447c6bebca24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6e6afbd-ce4c-4510-a3f7-26af79bfa4f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 8).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0a911d884dd4fa6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('964459e4-87fb-4065-9aaf-63072cfdadbb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 8).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a02512f1c1abc652_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dea14d2-0dbc-49b4-8eab-7ed790d9f735', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 8).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c9c20d7c11ed9ce1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bad8f76c-bee1-4fc5-b742-1ae76e55d8a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 8).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ad6fbf4fd8b1bd5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5ec1422-2e84-45f7-a266-65e30be369fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 8).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '395b85fc9dca9d70_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d86ea93-e9f7-40ee-847c-d4fff6371199', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 8).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '0236269a31d9a0b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2b09bb2-2d13-41cc-9d66-53d038a6afa1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 8).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2ca83d7e1ebc637c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f127b52f-cdf5-47d5-b7f7-bbd8dc00c227', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 8).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '463e811c5d0cb26e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3aa30ce-9d8a-4688-9c65-7485737c2eaf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 8).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8d3f5d54e87bc882_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('223adfa8-3b08-4943-b427-2c3f5c6c339c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 8).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'acb25446e026b8d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4551584b-f0ea-4e85-bcd7-492ae31ef758', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 8).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '945a9bbe08554121_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a68ac8c7-b16c-446c-99ca-e9bda89aaefe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 8).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '890834d6e04880c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0567f79b-cb0c-463c-9fe5-4be9ee7d6088', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 9).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '08300ec7e2063885_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62e9af54-62ff-4e73-8ba3-776266a104a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 9).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 9).', '{}', 'Networking Fundamentals', 14.0, 'dab16ab95d6789d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef659e1d-858d-402d-9926-5d5a19b9ec28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 9).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 9).', '{}', 'Networking Fundamentals', 14.0, '6e30eae3dfd3ab43_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6794b09-970c-4779-a215-1dcbe20f2ed4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 9).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 9).', '{}', 'Networking Fundamentals', 12.0, '75799c9a52de0283_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d49b411f-5d0e-403e-b304-5add5ae70734', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 9).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 9).', '{}', 'Networking Fundamentals', 14.0, '3c1f4f6ee53413cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e07ee48-87af-46a9-b87d-31477e789922', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 9).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3b995d390f8c8dad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbd3a4fe-83e5-45cd-9e2a-03b9f20a7dae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 9).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e9a7a6077f67eb9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('102af8c3-00fc-4d03-9cd9-9f6591843fe4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 9).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '62ff521237447ded_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb83e4a7-511d-4f40-a1d4-7b91a41a34a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 9).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2999bfc8614e6c30_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa6a2d26-a620-4d74-96e4-0b187ad55fe9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 9).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '2aa7abedd4208ed7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2c98f1c-7856-423d-b840-2176f56d50c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 9).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4b1d57785d77d11b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fd09bfe-c8db-436b-afdf-0df6d8d81ca0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 9).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '409156484667d72e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('380b522f-a0af-4448-b5d5-b560c337654e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 9).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cfdae26b670f112d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81515381-0114-4b8a-a65e-337d799fa226', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 9).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3a646584a505e5b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e3abaa6-badd-48b8-be54-bf603389fcf7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 9).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'da44c973a0819740_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5739a6b-ffa8-4df5-883d-b1f3919c1c6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 9).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8c6b0fc047398488_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d02bb33e-80bc-4c42-91ca-42eee0a514ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 9).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '45aafcf608a998ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caa48432-365d-4f30-b2c8-56e5e7801d7e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 9).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f2aefeb8f3e87d07_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a06a4b0-444b-4208-a565-0eb6a857f742', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 9).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9cdf283b0f0173a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49e4fa28-2de7-4737-b488-8c7df22a8622', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 9).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7db3fbd035fd1e26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('649a80b7-320f-4a8b-ab22-89f2d0a8b0d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 9).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ba85c84efb87c813_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d3046a1-0583-408f-901a-d12d2aaadd73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 9).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ea1c6354d26b58ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c1ab849-0ffe-4210-ad3e-faf7f4884965', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 9).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6fc6a28b6a880dba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e69e484-9db1-4a13-a7c9-81c9277988a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 9).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '894190064e62dfea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29a39c27-397a-4c30-a0aa-e44228941e05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 9).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7960e72a0b351835_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0b65d50-02e4-46ff-bdab-4cf6ca2e4236', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 9).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '853bdb6963c3318f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ea14de6-af22-4b30-8552-17e912b19f82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 9).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '9bc1289ab9e23d2f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c26a49e-f3a2-4c3b-981f-ba93f8030ff5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 9).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8a1e97f8bccf986d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64a72074-c20e-4350-8750-962d27376e45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 9).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9aa6aebe8f630c9e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('932d6498-9aec-423e-b2bd-36479bc616c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 9).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '235dd2232c2755e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c6fa958-9a7a-4d28-872c-7bc9b33fce0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 10).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '9f7d5098edcc7a88_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de13858f-20a6-4dd4-a07b-10fcc857bd80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 10).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 10).', '{}', 'Networking Fundamentals', 14.0, '468273aa429a8338_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a4d9759-f573-4d39-b61e-1db89cca24cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 10).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 10).', '{}', 'Networking Fundamentals', 14.0, 'd5e5edf53ea4dc5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e812082-106d-4e5e-8259-00daae4e1923', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 10).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 10).', '{}', 'Networking Fundamentals', 12.0, 'c78ee123158e73a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b691c5e4-8f46-47d8-a715-8191cb1f1735', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 10).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 10).', '{}', 'Networking Fundamentals', 14.0, '9361a64484832534_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('683a13c6-f4e0-4ae2-a155-301cdc884a6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 10).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'db4fc0500486e5f5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f13c0fd9-c29e-4963-8c4e-029c5a8078c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 10).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ca8e111e00f10c32_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e425d449-7fa8-41bd-8826-60e7ae8f4a4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 10).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '06e6b5596b535701_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5415b30-7d3e-48a6-acef-afb69cb332d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 10).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8ac22861456e9aaf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36eada62-eff5-4bac-991e-3fb1c64ed15f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 10).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '9c3db99032622f70_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('758d154f-906c-4952-8c7e-6818dfc0bdff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 10).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ebb042fc5afa2765_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97158b7b-467e-4500-a7aa-828b159c404d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 10).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'eecdda3dbc97c3b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f1c8d90-b780-4e69-b742-408206a994fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 10).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ee50338940fe7882_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c7d6b5f-9156-4083-a390-cd6341f4a5c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 10).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c8f10f8642f30d72_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64e2488d-3037-4493-80f3-6205fb85be68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 10).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c27a904ac6d7209e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('362586b1-7602-45e7-8611-069a0ced9a74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 10).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd35858c6be51166b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bc96952-e003-4e40-ad36-7145094cff35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 10).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '429ac4aba7347b20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('636774a6-85ec-455f-9811-42b1e805b9b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 10).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '08456a7bf6b88a66_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5bc7c47-26a1-4386-82a7-367c3ca215f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 10).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b3a6024bbfe604b6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d2a7150-0ac4-43fd-afa0-6d795bbea519', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 10).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e10fad0e17f51d5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2694a3f6-262a-424b-b642-83dfe6fd3380', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 10).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1f764ce31422f5a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fffa3f00-41ba-4e1f-9229-a5be1ed554e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 10).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b7e71abeb5c5fb6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15db2427-93f7-4754-9e4a-2cdc45977d4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 10).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3482a1fb27924d33_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d233cb1b-45f7-44ce-b346-895826beff7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 10).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '889d2afb95891372_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dedac24c-5971-438e-b4ed-64bd0f045a38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 10).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '17b8b30aa5cba188_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71169def-cdb5-4a6d-b3dc-bcefa5ad0dba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 10).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4ddac3c5b29b2abb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0b9c2a6-2d73-4c0c-bd75-7ef1f19b8d74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 10).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '91bc3c2f54ec2923_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f99eb76-992b-4d07-ae7e-ea7ee4474b36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 10).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '153254970d7d398b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('629d3801-b82d-46bd-8bb3-43f33af80f76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 10).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9a606f1e48beb8d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0345844e-a6b8-4502-a8c4-3886c5bd2e0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 10).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 10).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9751343e1ff8ebc4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ee7f5ba-24be-4e68-b87b-677dd74c3339', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 11).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ab591d7800019eb3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76bfd164-c255-458d-a1b4-4dd7e3098850', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 11).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 11).', '{}', 'Networking Fundamentals', 14.0, '902a8c5ef07736a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eba36503-5131-428e-ace3-fb4d1eace7df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 11).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 11).', '{}', 'Networking Fundamentals', 14.0, '3d058ad6ddfbf692_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10dfe076-96d5-47f1-8b69-43f51e4ef96f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 11).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 11).', '{}', 'Networking Fundamentals', 12.0, '77606d20b2c2f589_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04f4ea8a-e517-44e6-9717-6d670ddc35da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 11).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 11).', '{}', 'Networking Fundamentals', 14.0, '00df21f98fb27a41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6edacc21-a189-4aac-b120-91baa0b54360', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 11).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'fc6515662d17d6bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d408930-ce05-4659-917c-2f881bc9b265', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 11).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '518ef8232e030458_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfeba7b2-b9ec-490f-b9fd-b9a38b8f8357', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 11).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9a65f0cd3f1ae9ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3f7330e-18e1-4927-b2e4-4c34b5a4df7e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 11).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e03724a25a3d08a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0825e7b0-d6c0-4c2c-afa5-e8966b149fee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 11).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'bb9c430b75392497_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b0d642a-c95e-4457-a24d-f7e012c605f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 11).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5add8cec3b0cc324_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('921b496c-5985-4216-82b6-788f2f35119b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 11).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f072cb5801a05c64_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b248d3e-9d06-497a-818e-8f4caeb9bb2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 11).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fc7b69c7685d8da7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b89d5cfa-a22b-4dc1-905a-7355de7817a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 11).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0137584e4e686d55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70205f82-8a5e-42e7-a591-8f5d3d2490eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 11).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a817ea0b4bd72c0b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('299898f5-b3e9-430d-9fd5-7d2e892a3329', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 11).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6f67a6059b50faee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cffedab4-0018-475a-a8b7-a0f8328d1b4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 11).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a9b3aa85c789b9b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3d9577c-228f-48f0-b851-985727c44d2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 11).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4b81f782c2802b20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d50db8a-c677-4dc6-86a4-3b74343b29b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 11).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c59b4156d7769720_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b78f35a-93d0-490e-aa64-2fe1bd658365', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 11).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'cf48d8639c65f89e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efdb4b0c-5f47-4f9a-85c2-b4f5ffa96192', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 11).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6c6ff489f665d083_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b7fe8ed-1329-4e49-bf63-e8d60fe7fee9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 11).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8ac26bef862700de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44a2c743-2240-4aa5-9646-62e160bc92de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 11).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c828777bff9c7b73_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a764568-0858-48c4-b07b-047c1082171c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 11).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '73db1ebf9188cb8d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('961b9f0e-fa03-4af0-b359-bf6ef6622f20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 11).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'de822a6fc8439e6f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b27fd7a3-d324-4911-8b14-a029c12017d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 11).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '013183c62a38a350_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('136bd3f1-761a-41bd-8d45-52d294c877f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 11).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'fdc037007574f8cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b28702fc-f1a5-4215-b7a2-0168918067ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 11).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b1eddf809376ed49_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6fc3ff4-2a6f-4721-9384-cbaf2e716c0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 11).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c43fdadd6cb76db3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('164bc5b9-070b-45fa-b1e8-390af6ed8395', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 11).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 11).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f10b38bceb94d300_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8831e865-1ef0-4df4-b6a4-935248e28285', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 12).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b1e0eb56d8c294b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65eead76-477c-46b7-9873-529443ef8b3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 12).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 12).', '{}', 'Networking Fundamentals', 14.0, 'bf8c915d1d294725_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1115679e-c6a2-46b2-9524-be86ea55d541', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 12).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 12).', '{}', 'Networking Fundamentals', 14.0, 'e597ad2505fd94e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b90e3388-ba20-4925-9dcd-a796e13716d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 12).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 12).', '{}', 'Networking Fundamentals', 12.0, '8660491bb4f2ec75_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5a59b7d-e4fc-4a02-89ae-3b61bfe32f7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 12).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 12).', '{}', 'Networking Fundamentals', 14.0, 'da93818db278a7db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da15610e-a1a2-4df9-961f-da656ff6de0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 12).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1cc49f1111df7c84_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3f954e4-1b7c-4764-b270-6dfc4fea7879', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 12).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '131f1c8cdc97f4a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bf95299-853b-4d3d-b482-463b90ff0fa9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 12).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fc1f299e5c2f908a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25ad1db1-743a-4a8c-83ba-10ad0dea006b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 12).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '79b0369ba6cd7b16_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('491314d7-71e6-49dc-a89c-ea472848b58e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 12).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '41b68bcea9b8b5de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e880275-07d7-4d62-baa8-d7a72b02bc54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 12).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e4bca309c53bcebd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58dbfc8b-ec37-4882-8c00-d678bdd13cb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 12).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e407985d126e216c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef3a8d97-315d-4746-91d0-033081334c2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 12).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd2994296f395acd8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0836097d-d886-49a4-b6a4-643d8be6dc16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 12).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '655c5713969d60f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb8753f5-6e68-4bd0-a3c9-e0a183618fc5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 12).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9adafff8759d30af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6d995ed-fa7f-443d-8996-3bf731b19541', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 12).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '10ebef44a9d2e460_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdb8151b-2887-466d-bdf2-e86f98cd52a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 12).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '411841c461681073_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eba4caf1-5182-442b-8dbc-244267f13ecf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 12).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '076ac0c97e9f6899_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3be76c7e-43a8-4575-bbdf-bb2b683d8cd1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 12).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7ac12afa4fc66c05_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d531fac2-5ff6-47a7-8f6d-a0d4458306cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 12).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '343c4614b369d9fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('015c9bbf-37cc-446d-bdf2-fde345fada5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 12).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bb93d18bb2b54ad8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78f70231-719d-4458-a60e-3a05f7f078b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 12).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5f4099b89f94b299_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3754415c-d50b-4530-856d-6384d2d9b2b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 12).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0c7e101af97443f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98a8a090-8850-4ca2-bd2b-918e5558645b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 12).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '543da554809c20c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdbdca56-8cdf-4bb4-9d1d-782bd6981940', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 12).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b152dccdd8e09283_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('294c92f6-c7ff-4212-b521-263fe7e29e3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 12).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4fedfbc943f58843_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5867999a-6ce9-4153-bb5e-9e84ef4144bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 12).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '19b5ffa85d8ce921_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2366cb8-f0f2-490c-b5c5-6d8a68fd2f6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 12).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f37fccdbd6391abf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('768b2261-b272-404e-abc7-3e5d23aa7b0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 12).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '37da35f069ddfb10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f46b194c-a912-4ea5-b1fc-471351ae3fca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 12).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 12).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '79f587909e37c541_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02374f47-5fb1-4165-915a-2dc555ef9b37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 13).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '7075b813f9fd88c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b0b2189-d6c8-488a-8016-4e994cdc4f8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 13).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 13).', '{}', 'Networking Fundamentals', 14.0, 'c89984bb17ce2834_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd84de0e-bb72-4a51-8114-7ef4018cc3d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 13).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 13).', '{}', 'Networking Fundamentals', 14.0, '176d68b30ab19e14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dd144bd-77b2-4bf3-83f8-fb8a0ac01ac8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 13).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 13).', '{}', 'Networking Fundamentals', 12.0, 'ecd6f1dc3eb0a2da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a19bd130-4fdf-40c3-909e-bee02dfcca8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 13).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 13).', '{}', 'Networking Fundamentals', 14.0, '4616055c36f42c7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('438971b6-c2f8-468a-ac41-6d2b8d207785', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 13).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '81b1bbf07cfbbcdf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a7f429d-1ed3-49d0-9bfa-86cdb6febdac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 13).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'accf2f04f3881f42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79477cfb-5f06-4ac6-8772-ab46fa863910', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 13).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0d63a1042b876aba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0a021d2-e348-4afe-9280-276e4a8a46bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 13).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e80b7e4bce65ec9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c2843b5-4c83-40e7-a60a-0682a5d5b09b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 13).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ba698b6176cb6d5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7be5f355-5145-4fcb-8db2-80ba5debcb5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 13).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'edc4bcf587befb0e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db97d419-9dcb-445e-acd2-6095703318b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 13).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '004bc5a1e56f2784_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2187be4a-5a34-4f50-8122-bafe027a4a76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 13).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'bc4b470261586299_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e15213b4-20e0-4114-a098-2ecc926812fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 13).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e16138c7c5bb6e8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbcda0f6-d794-4249-8e73-bdb7ae00797f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 13).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0f00f63e63b43f62_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e0887f6-776d-485b-9012-83bd95926015', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 13).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0de874d5a3743d68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb4bd468-e50c-4b08-a0f1-6c0c312485f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 13).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '62ddb71f5958228d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a342256-45bc-4711-9eb2-2033fa6dfa52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 13).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a48c1fc635cb386e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e2d27c0-dfbf-41e4-a72c-2da3077faa17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 13).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '71b500f1a846a447_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0802ffa0-59db-4e3e-a18a-359033c5b711', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 13).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3d4741ee59e02b47_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c042e00-1b8a-45e8-947d-533fce1d548f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 13).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ff04fb54faba8593_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a16c438-def9-461c-80f9-37af3a260f25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 13).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ac68c145a3687bdc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aeb3a682-8ff3-4f50-8105-a1944034dd63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 13).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7a24a9751e08a18d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c27d9ff-6bb5-4dba-80f7-18a3a4ff5adc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 13).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6a92bfda74e192a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eda0225-4a20-4447-b09c-4928ce44705d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 13).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '123e8b809caed816_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f341cee9-3014-49de-8122-e0f0cdbe3d65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 13).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fba5b2ccf8e8191d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c268a624-9ce7-481a-aa88-f45c0f810c1c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 13).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0e60679f070aa984_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('787256b5-ad4b-4530-a448-59e8ccc67279', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 13).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '1b6ed7807b203702_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6941b4bc-e7aa-47fc-b7e2-03925a834442', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 13).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fbfed3e2c704f008_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54788c41-eaa0-4241-b6f6-20739954fa2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 13).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 13).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8acd34349f21c651_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6197d12d-dd11-480d-b794-c31ccf4aab5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 14).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '7bc258d897614aaa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bf8b743-e1c7-4524-841b-afb502898e39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 14).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 14).', '{}', 'Networking Fundamentals', 14.0, '3c277b9abf9826ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e351435f-d0df-4071-8b41-493c3967a068', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 14).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 14).', '{}', 'Networking Fundamentals', 14.0, 'a89bfa6c2da7a7fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eef17c8-306f-4335-acca-c12e6c37f6e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 14).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 14).', '{}', 'Networking Fundamentals', 12.0, '1462a3e0b0c6c986_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d8ba996-bc84-45f1-b316-af001ceda686', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 14).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 14).', '{}', 'Networking Fundamentals', 14.0, 'a91bc2b0999f935b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fd9a3f4-c6cd-489d-87ec-6af0fd59a2c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 14).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'dababe1af7a439f7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81d26200-3939-497e-a97d-2881b6d844ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 14).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3e3bc8d1ff461677_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d6e5a40-23ac-4c71-9a1f-deb19ea95b07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 14).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cce2d4268dd663b6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62ea32ec-39aa-47a2-a731-e2b3a17b2b53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 14).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ce8ca6956718615b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0373a52e-23f3-45d5-b66c-92424b4220c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 14).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '17f5dd715d8f11e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a62370f1-1583-41e9-8d70-ca0709160cba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 14).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e29334624790e02b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81a7f9f9-c4ba-423b-98ed-bda47a20240e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 14).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9ea1471743482d76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82f14009-74bd-4ac4-b33e-4f9a79ae793e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 14).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3fe37d4cdd3c4eed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('734bc4bd-bb6b-4a94-86f9-2129ad83ba02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 14).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bca1d93102a663c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5afa5785-1753-4d20-a16d-a5f10bb88302', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 14).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ea1b68da1fb2f47b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7e9cede-01a2-476e-a338-08556d63f911', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 14).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1b6dc0623b9b83c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4de861c4-7778-4130-9e01-0bbbca7e3aaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 14).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e3015a27017035a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e69e71b-8433-485d-9a23-00092cf55ba7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 14).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '52baf2a63eb7c83a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e3ffa55-dd0d-4c36-8c93-7ce42f513cac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 14).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd6ed7e0978ba72c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e928c911-e804-452c-8c17-314cf41f441c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 14).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b339d3242566d874_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5920501e-a081-4245-8b5d-5db7d0273fe9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 14).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a1bacb20d74be54f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49850ee8-ae5b-4c0b-abcc-25a18409e217', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 14).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '85e29f0587454df0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1911691f-0dfc-4339-87c2-bf8fe3d78bfa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 14).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '39fa5d2f45b5f9e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7fbb971-9b56-409e-80ed-5af4c5930e2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 14).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '444eec6c1a262807_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('402d6fbf-0e04-4111-a280-6731eadb9556', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 14).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '95d77b033bb606ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b50c799-8e09-4ec6-9c96-034d65cc3dd2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 14).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6c8269590ba942ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d7c4905-6cad-4b1d-85d6-01ff57279cd2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 14).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '20d61a6d2ce98275_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('268fb4d4-3c4f-4df3-924a-e7b7c7b8d661', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 14).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '44e3dc5ae14baf3e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b3a4595-dbc2-444a-b685-942633bf6b8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 14).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '20594984dd567f0e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d007b035-8814-4e25-8458-143764dd9b15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 14).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 14).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1bc3f0543766a94d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a49d6fd8-a163-4342-bfce-0921adc59f9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 15).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2e8a5b472afece36_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c21440c-ab6e-48f1-8db8-d11713dfb5e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 15).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 15).', '{}', 'Networking Fundamentals', 14.0, '2bf7cf4f9eedd7f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9bc5600-7187-4b49-aa5c-8d3615c88e86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 15).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 15).', '{}', 'Networking Fundamentals', 14.0, '70f09d9f701e82ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15f82124-6862-4709-8ad4-8b1caa952a34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 15).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 15).', '{}', 'Networking Fundamentals', 12.0, '9291482dd885e623_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0321e484-c32d-4cff-8bd3-c9d0d2ff117c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 15).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 15).', '{}', 'Networking Fundamentals', 14.0, '1617423dcd36f263_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1f0d059-c6b7-437d-b221-57b68f695b22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 15).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'acb3279d2a641b9a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbdc7790-d96b-4789-8db5-efb86f382cb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 15).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ddf58f313360e254_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4e516b3-a06e-4e15-97de-aa5dbca3fc46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 15).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f3d2a43cc9f494f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('148462ac-3e7d-47b6-96ab-497c6aefcb8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 15).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c65f6d04fa74d936_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b49544ff-6a21-42e1-9209-2fe159e21011', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 15).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ef16f3100573aaae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67bd139e-0f59-4a0e-9975-89e0525e63e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 15).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c89cf38a83bdebfb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f787d705-ee8f-4aa7-8507-480f4f2da525', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 15).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '606c361c471a7798_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0d56251-b0e8-4b46-806e-0986da89c026', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 15).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '47fa173a1be4f067_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('012fa4f5-c0f4-4ee3-93b9-e3a2345c2f50', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 15).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '531b5d548fcb8e76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72c9e381-8d68-485c-9812-2c0565a09681', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 15).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '04f7a2bb52ee4024_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4caecaa2-a2f8-4b5a-9cd5-e3466b940620', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 15).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c7ff6321997e69a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eba56214-1724-49d4-8330-115fe8052239', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 15).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '8f6e08eb07ba40c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76a6b52b-a0ff-42f6-b811-333fca5ae75f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 15).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '16606100a7bb1e68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('713ccdad-b676-4a1e-8451-5d3ab11e04e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 15).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '31a503719a24dae8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('472face6-4ad0-4e6d-b5a0-fadecfc56dc6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 15).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1a3e337e31820ed5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02c5d6a7-b573-4a31-a88d-d40351852409', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 15).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '929d75cb8d7c2e85_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0d8a7d8-669a-43c6-aad8-f9ff98d90b22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 15).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'cea276722704bc95_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14891f36-49ef-451f-a97a-92c3d5d4f130', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 15).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '879bdf27505029f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('245214c6-1c7d-4f07-ac71-5061ec32fd29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 15).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4969e5b3de7a4c5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a928570-059a-4e2d-83bb-4759565e673c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 15).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '74b6409fc720d143_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70070a13-b651-441e-8344-7a7181a2a648', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 15).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1380b73747ee1066_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('094fce13-0e6a-4112-8514-23ebfdb9be2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 15).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '856a676a1d754b16_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('401d40e5-8d18-41ee-96cb-79eef89350e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 15).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c95091ad8d550d88_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('522284f8-9f42-46f2-b566-bc12dfd080e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 15).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '65eb816afc347878_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d239aba7-7739-4159-a66a-b65b9b4b2767', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 15).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 15).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '756608e2d94347c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3602eb0-be38-45c5-a4ed-d8cca072371c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 16).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '65f1d23a79030342_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e29eb246-3696-4075-922d-b218a6569a79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 16).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 16).', '{}', 'Networking Fundamentals', 14.0, '2d2be590d7c3c732_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b461b96-d8c6-4bdc-91f7-5c13cedaa388', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 16).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 16).', '{}', 'Networking Fundamentals', 14.0, 'd64413c01f620f1e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('062b94bc-7c5c-423f-8b77-fc9f6f712d50', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 16).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 16).', '{}', 'Networking Fundamentals', 12.0, 'b5636b2b9e9be694_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b643407-1a69-4c38-936d-4c09e215eac9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 16).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 16).', '{}', 'Networking Fundamentals', 14.0, '574dfa30e8efc56e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f3a50c7-af87-4ed0-9717-97ed3ce96493', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 16).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f2f5519280ea2e06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53fb61b7-b504-41cd-a48d-b70042bc4257', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 16).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '76c87a7a44fbd2ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('627d0a84-e08e-4381-b0ff-ce518cbd036c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 16).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f20d48d5cd2fed8b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb3b4f23-54f3-41f7-b7ac-d5a50da80f1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 16).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9f8da523543cfaf9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('011fb749-a53d-4eb3-8125-578e54eae5b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 16).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '003441c188deca44_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba44a568-3bf5-4112-a727-9e5b41a9d4f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 16).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f29bf1bc7efd0699_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea9ab172-50cf-45a3-b3f0-daa0146991f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 16).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '776aed56ebd50721_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15ea173b-84bd-4272-b2c2-ef8a702659bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 16).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '23a8d02cf5202a68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2800106-f560-47fa-8421-9ee97998d76a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 16).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9d243454800386c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3eadce90-95a3-4bff-95f5-5c72a003c089', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 16).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ce4147b832eb18ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c7e6ba1-8329-4b8e-854b-5e3d8a34911d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 16).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f4edf7c01015c32d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1e8ecd2-3ccf-4eba-a6e0-134e03e7c445', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 16).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '819e29be1e1a66aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb1f8407-f832-4c96-ba45-a556d95020dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 16).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '5ed9f30e780966e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8723a2fd-6470-42ce-ad7f-4403c1b34547', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 16).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '123842c74eb8e213_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('854a2640-f190-4200-b994-0bce09f6723e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 16).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'dd4c27a54cfe43f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ad630af-feaf-4c85-9333-1292db35d627', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 16).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '83093dbd504ee5a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f49f10b2-26fa-4f15-a3f1-c444074cd650', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 16).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '163f6dd79d624ad5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14faa7e9-08fe-43df-a72c-48254de249e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 16).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c02b3b451f69d23a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d740669b-5fb0-4f97-be95-42dc1630cd02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 16).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'b3c4329390ecf932_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7a4ad9e-45ba-4832-a9af-845765ee0ca1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 16).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e4a253eb88705662_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac0fc7f2-5345-4905-a9a9-acd8c7f92234', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 16).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'db21a597fb4a39ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d0e6e95-b3a2-4d28-9d32-1a6496372e07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 16).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0136689c8af78aae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40185096-6b97-4dee-a085-32234984968e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 16).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6a6ef16e9bf2001d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53e6d0c4-7f2e-46f3-a1e5-e84422f4dbe1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 16).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f1fc82730027418f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d7e6f45-1df8-40e2-82a7-e19972c62baa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 16).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 16).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd395c0147cf7ed7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('440985e2-7cba-4e8b-b0ed-43d135f6232a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 17).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6e06fa1dba988332_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0033fc29-2cdd-4885-b04a-30b3c65b6720', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 17).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 17).', '{}', 'Networking Fundamentals', 14.0, '3c535d6120ca5ea1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9edbcdd1-3dec-45cc-bf1c-cef14063dbfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 17).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 17).', '{}', 'Networking Fundamentals', 14.0, 'b96bbd3522f7c2c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd135ed0-2793-45ea-9836-c0162bc3cef5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 17).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 17).', '{}', 'Networking Fundamentals', 12.0, '6e30a3811b855186_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d46e0454-08a2-4214-aef8-b4c9a28c3d56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 17).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 17).', '{}', 'Networking Fundamentals', 14.0, '3b06ce564ffeabc3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('996c5684-c638-4f32-9002-569ba44319bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 17).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b7661018dfd4fdaf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ed48778-eaaa-41b8-a89c-85892fed8479', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 17).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1af0c10cd6ae8ef4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36e2a74f-9388-4ddb-87d5-aa32ade7cdac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 17).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fd4acfc66b2208a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80833f6e-7044-4781-b689-ffdc134296f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 17).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7905a3a6208a50b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc479a7c-9397-4f88-b0a0-ec6f1bec4e05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 17).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '38abd6ab7b6fbb0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf15c2a9-0d4f-4fa8-bea3-00740fedf3ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 17).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e63eea976468758b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35b0d416-e700-4082-a653-bd7d408fde51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 17).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0f21cd8904d1482a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7695edd1-35b6-4729-a171-a921417a07fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 17).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0b36437497cae770_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce96fffd-71f2-4c9f-9253-9c31c9ce8d44', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 17).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd4530bb9b48ac6dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaaff9cd-e45d-4fb5-a52a-b74e645f478d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 17).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7185fe9b1fb2ef0b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a54f3b0-ad7b-41f2-ae1a-0c796ac30ff5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 17).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '27949c414dc443c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f63a15fe-41fb-4e10-94ff-1621c66a4fab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 17).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'dc4238efe291709e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33b806be-ee0e-49c0-a738-2605bb9abc02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 17).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6e325d2c9109b8c2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a0b4a44-205a-4795-95ee-2276c30e0c7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 17).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7f03625241c5c970_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baf6d55a-c6fb-4727-bc90-65f3af3acb87', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 17).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '55867ece295b7c4c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae89a2aa-20f9-4044-bd61-bf31fdca5ac0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 17).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ba1fcf6983378ad5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad21884e-9d69-4ff9-adb8-3d41cccabb72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 17).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3f0cb3399fa8b7f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d60d915d-4983-4d3c-b096-5c0862121770', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 17).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '20a97c60aa54bc9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('339c66bc-41b0-4f15-afa3-e16d9cb166fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 17).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'edc5ba0a10bce8f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e03d8909-852f-45c0-b463-c097c597c91d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 17).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cd43d92f4268e867_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13fac7a4-0ba3-4230-8689-c4705f94530c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 17).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '40bb3542c0b9bfde_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb16928b-862f-4a8b-816b-201aa5bac874', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 17).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '62657d8fa7f76a5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('444109a2-3fed-4d8c-83b3-3a54ab77dcfb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 17).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'dd055f9d428778c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('052904ac-6d94-4c7a-a768-10ee20b7f823', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 17).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '96c4dbeb511b7a70_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86e5037c-53cc-4932-af6d-9b00f151d419', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 17).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 17).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '85bc954eea30b218_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de71af0e-9bdf-4085-bb45-cdc57427d03a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 18).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '9d0faa54e5db6e81_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c8ae9a7-4f04-4011-b0df-52cb62322fe6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 18).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 18).', '{}', 'Networking Fundamentals', 14.0, '2b7feecac95b9ac2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('617cc050-8cd3-46e4-80fc-8664557cc1b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 18).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 18).', '{}', 'Networking Fundamentals', 14.0, '3044a3fce5f5c240_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab9b078b-9388-4186-bdd8-1a8c92373031', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 18).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 18).', '{}', 'Networking Fundamentals', 12.0, '1d052938895c2a25_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('798abefa-8f20-4d3d-a8a0-e866ad39c92b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 18).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 18).', '{}', 'Networking Fundamentals', 14.0, '5796c683dc07b4fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('617d2d7c-a192-461f-9299-c9aa843f088b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 18).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1f9919fd96a76e62_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c0f8313-99ab-4041-a330-3bae89723c4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 18).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2c9b51b0288abe69_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3e3e78c-705c-4a92-a4b7-13b1f790ca88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 18).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a19fb1e85b2caa05_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adf33d9d-65c2-4657-ab2e-3911ad6d7aa7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 18).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '16af794ba2158673_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5f90d6f-8c9f-4e41-874d-5dc9331ec508', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 18).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e161ab940eda1b15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2573fef5-b21f-461b-af68-7ab595674be3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 18).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1ad82cae6d9ecea4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b34752c6-a351-4597-b27c-519214fded61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 18).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bfec20d8a895a36e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36408a8a-76cd-42d9-a976-abd60ad78271', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 18).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f2c76b69f1810488_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbe04248-03be-4fc2-8a02-123caeb9e713', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 18).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '88cfccd1f6ecee02_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d0ee0b7-2673-4adb-b3d3-3370f5f99616', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 18).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a913ea3df119b118_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc201a24-66bd-47a8-b4b3-65a19e9a2b77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 18).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'afd4472a2c708c57_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fb543d2-f1bc-4d0b-8fe2-77856c4621be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 18).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a47bf7e87de8c39c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ee607e7-54c0-4b86-a4b5-ad99a98ad37f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 18).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '34f927bc6a08e5d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b51762e0-86ca-4624-8581-d6e9c753cc90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 18).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3b4916e144383a7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('241285ea-b495-4063-b1aa-629bbe78c215', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 18).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bb327f44d3fe7c11_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce8b470e-3128-4aa4-9814-52ed5166e1d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 18).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '73136d7899d2833a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a3dfde4-a5f3-4acf-a3af-1505d2c313aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 18).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b295ab8ac554582c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cdc7966-a665-408f-b2ac-f881c8ab2090', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 18).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '61b2b492b23691d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14b72313-e1c0-4990-a5d7-a9c8ad22ad6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 18).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '9adeeceb13715fc9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e335dbde-83d3-48d6-ae31-0739de167e2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 18).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6a1351d143afba4c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d58a129b-a522-46de-84e2-6dabcdfe8dca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 18).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0f7323b69d527687_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fc2b07b-40b1-454c-a66b-04fcd5afb224', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 18).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ba14f268308a702f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f86b330-8ff4-47be-9da4-e5e4dbdb51f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 18).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '28fdab5867f9cbde_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('244f45ca-f782-493a-959f-4cefa9457e19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 18).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f427cea6596d9668_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('516afdeb-1e2b-40d5-99d4-f005a0e88a11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 18).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e9e2c7fe900ca70f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bebee012-c4b7-442b-8836-6dd6e0fd0e63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 19).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2212a4da41f26ea6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9523027e-1882-44bf-b318-d3cc095cddf5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 19).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 19).', '{}', 'Networking Fundamentals', 14.0, 'd35eb58324cfe0c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb0cbce1-1a85-4801-9ac6-002ca947bc60', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 19).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 19).', '{}', 'Networking Fundamentals', 14.0, '592ebdd593300ad9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('875298a8-1fef-4eb7-b775-651df0d5a511', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 19).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 19).', '{}', 'Networking Fundamentals', 12.0, '0bcc5b7c92752fb1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f82f96d-033f-4830-9223-dd6fe2c7be16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 19).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 19).', '{}', 'Networking Fundamentals', 14.0, '07bfda2d91744e20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0968a89-5092-4ff0-bd6c-c8894a39c41c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 19).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '29a384d51615a16d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('923df03b-d7f1-4d3a-8dc9-72c1531e682e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 19).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '136ec0709e547d82_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f1bf194-e1f1-43cd-85f3-ada810d58ed6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 19).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2eea421722ec1083_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c3827d3-0a92-40a1-980c-03c817a8d8d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 19).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9c5d126858ab8847_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7a3df6f-8fc4-4a24-8d6e-23f3095a1912', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 19).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b0fe7fe1d6560688_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a02f0e4-f10a-4ad5-8258-9e35861b1b30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 19).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8e33e224093951df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d171e62-8e3d-44a9-b663-77639635b604', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 19).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '078a1ad17ff89e3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b76f0298-2f56-4e6c-89fc-240eaed22c6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 19).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0126a34c965d731a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b88e10b-75cc-446c-8137-2b83cea07795', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 19).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3e7e2fb4b6782785_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea953174-6e52-458c-9b4d-b49f94301b02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 19).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8ff5d30f0b483cdf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38eadaf7-5dda-4c5b-bf57-b416d501c351', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 19).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e3764f0789eaa491_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('391d5248-9e9f-4cc9-8bcb-ef32d4a70eab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 19).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1f222eb1b209b7bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('024adcca-58b8-4a37-9785-681c6c41413c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 19).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'b42b52c4e5d16532_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67c52fd1-e125-49ce-a590-6e190d0db830', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 19).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e7bb79a4d137db69_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9bfbf76-5fef-4450-96ad-7dd6978c06de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 19).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'dd9d9c9589874f3b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a446e76d-b2c4-4f1e-b057-1c42933bac04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 19).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bf196e2e249b0f38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77a0b20f-ea0d-4504-b782-3582aac662ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 19).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8b0ca98ca37054b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f7a7f8a-3b6b-407d-b921-9ce1918fef08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 19).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a850b7dd8b278ab5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5088104-7945-4d78-8a30-af33490b3f76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 19).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6b85fbc0122e9409_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7f3e9e6-ece0-4c3b-ae52-1b88158c3b99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 19).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b5487404d2ed5636_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c372d328-31ad-41c1-ac96-54a3214ac297', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 19).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ba88ec1281e97007_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c15b5c3a-3a22-44a9-b2d8-5ad48e1ee8ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 19).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '015613fb108a4c50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e6fa7c2-abe1-4ddc-a033-dace53f53439', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 19).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'fff23f814b5134a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be15e03b-8187-4c61-abb5-7b703f27d2b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 19).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '073b1055e29c9426_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70b7bf72-47a2-45fd-871c-154630658034', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 19).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'dea90baa7375b592_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae89f80f-8385-428d-826d-653f18924ba4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 20).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '572a5ac37f0300c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11ab3f32-5ebf-4fac-84d3-1c7bd6ec2627', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 20).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 20).', '{}', 'Networking Fundamentals', 14.0, '6349ad792d863aa4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd1cbfcd-7f31-43bd-a1a5-90af4d390c48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 20).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 20).', '{}', 'Networking Fundamentals', 14.0, 'c363b7ebb94d7b56_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c18ca989-7ea3-4145-8d79-2cb9d840b736', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 20).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 20).', '{}', 'Networking Fundamentals', 12.0, 'be678d0dd77e6db1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2ee58d2-4069-4c12-8ae1-44b15491488e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 20).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 20).', '{}', 'Networking Fundamentals', 14.0, '55f9424358b19445_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('030e548e-6b49-4337-a62f-3074493bdc80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 20).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3589dff25ec62006_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c588b54-53b3-413e-936f-04fbbfc4c48f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 20).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5546ff3f5022bb29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34cc83f8-1035-464b-b89c-f429d4165b11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 20).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bf3fb0e5ca6e0ca4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24450f0a-49e4-4d4e-97c0-f44a2aacdb41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 20).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '317d749bdc54a7f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f542f1aa-c355-4c0e-b81b-c477ab80b799', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 20).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'feec8cd4e2e9e9e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e662940-6ee0-4956-a003-d37ce0f7e19e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 20).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4ee2bc32378e3b4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c38a9de-d8c5-45c0-973b-cdd24ed433b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 20).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7e614c8581b4dabe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f144b16-b3ab-41f6-933e-561b5a73ab82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 20).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '06770db8ef907362_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9bbd834-dc6e-4207-b973-adc3827ca501', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 20).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '535fab47c7673dac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8aeea18b-3d10-4902-81f5-e7362b55ffef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 20).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ed3776e71719aede_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a018733d-1422-4230-81ce-700cd33783fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 20).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4043cecf31918257_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('472968bf-aa95-4753-8f2e-87eb6f06463c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 20).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4677db9933f478a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e26a794-1694-4991-b531-eb0d54c996ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 20).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '7855af7263e2ceac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b99ad307-8d69-4ffd-bd1b-4ff97a462816', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 20).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9fbc30fe30ab7a9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('942e89c6-d9aa-4b55-8f26-4d263f7bdb76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 20).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '425a3fa138a887fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c60642c-b60f-4007-96c2-7300c45b05b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 20).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '93bd9ffbe2c81c52_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cdd8d8b-e6b9-4991-bb06-83e5417dd3ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 20).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '457b72c6bb685d20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e95445d5-9bc3-42f1-ae6f-49f301096eb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 20).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bbcbb4624f593c35_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed0dc91f-393f-41dc-9cb8-adafb9139ac1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 20).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '79afb1fa68f1b4f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f244083-65fa-4019-9996-c5e38b3ac0c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 20).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3b8c6edf81c4ddc7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ce64861-298d-42d6-96db-be5a8b688119', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 20).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '04e45144924a991f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebce37e8-b6ae-4454-a7e0-ee1fcb4a30af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 20).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '60eea8cfd2e151f5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67ae07e2-b3a3-46d4-9b30-af0bceb7688b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 20).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a832dab2d0ade2f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10aac84c-cf63-494b-b883-ef8f0ed18c55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 20).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '343ef09e989711c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e035695-e2fe-4d9d-b390-75aff2fdb79d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 20).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '34c2e09aa9e3284d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b5639ec-83b4-4e6b-9f45-93fe2fa3122b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 21).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1cd24256632d1aa0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7208830e-c9cc-4890-8bf1-69a0c392b821', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 21).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 21).', '{}', 'Networking Fundamentals', 14.0, '72157446d0ca832d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0261aca-3e5b-41e9-98fb-83c942c4e45d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 21).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 21).', '{}', 'Networking Fundamentals', 14.0, 'eacb09e6d139a7fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58b1f133-e53d-4588-8f64-f0a9f44ab284', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 21).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 21).', '{}', 'Networking Fundamentals', 12.0, '1c0655de3f95b5f5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59f7a8d9-5b86-4b21-8dc1-0133f83e7170', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 21).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 21).', '{}', 'Networking Fundamentals', 14.0, '8a9229f17d12e00b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e93abc4-7c91-4c3b-b36d-e2d490dcf4ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 21).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '058eddd9668cc2cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2061d35-6954-4c3d-aa43-b0fb2483d57c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 21).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '664551a8c54565c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('006c58b0-0223-4a1e-b3a0-0f216ff0a248', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 21).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '44c33573cef98337_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1d19fca-4f6e-401f-bb78-463a549cd364', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 21).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8838c2787d878885_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('beccffc8-7c07-4720-9fcc-21dc8b89d96f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 21).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'aaa4717b702f7281_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b340581-1403-47cf-af0e-6d17ae9d6e51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 21).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7cff95123c4b6adf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8f57833-d8a5-4660-961b-b0964ab5d022', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 21).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'dd879a0c5bab15b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdaf880c-d9f5-4e1a-9c95-f1fd0320becb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 21).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '71b1894f94b0542e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3395687c-cac5-4ef3-ade1-f1eaba22ea63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 21).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd4ebc9ef2ee8932e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7808447-ee17-4440-833f-642660c9f87a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 21).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '63cf077628b37a8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae472355-e0e5-41e5-88d8-970917f438fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 21).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7c27d5a61bfafe3e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af34e198-f7bc-4424-a4a7-da7397be27a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 21).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '39dedfbd715320a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('040dc815-422a-4254-93bc-1bcceef49574', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 21).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4ba6e555dc0e4eb4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('872e5dcf-9e7f-4623-a835-8aa74e8c8eb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 21).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5eed59b506d692f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5f5b04a-9ee2-4c4e-9183-50f11e7da4d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 21).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6d2b4befc8f18348_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e177576-42b2-42ed-9696-426cdc8953f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 21).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '96478c137a001a85_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('528ba1f4-fc63-410d-9e20-67b9e20ffdd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 21).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '80060ea3fcfb779c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e2d0f5a-5de7-4a4b-bcce-0bcea391640a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 21).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '048a452ac1d164d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b86b7110-7156-4014-bab3-1264324b3fb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 21).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e51ec727ef11a972_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('841af0f2-6f32-44d9-ba0e-42612afb8771', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 21).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ff01daebb2982fe3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ba95371-e9c0-4fd6-b535-9c5807fd23a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 21).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '265e4443c5329928_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('233d82ab-f810-4589-831c-958019dfa19c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 21).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '887a9e24b6855c6e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69b62439-add5-404c-bde7-5166e54872fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 21).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a3a95392700fa936_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80aa8e7a-96ab-4346-b112-d4334930448e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 21).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '48a6c69f42964666_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8b7a6ad-f98c-4fa2-b86e-d29bb957beb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 21).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'cb78d1875a8968b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36e0b53d-97db-4914-9b7b-d5a5112fc5b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 22).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '723b81b1c4c6786f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21d3a36b-a592-472d-9a32-a608edbc710f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 22).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 22).', '{}', 'Networking Fundamentals', 14.0, 'd781969c9da2914d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b401c5a-a6a2-44a7-95f3-5263004c2bcb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 22).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 22).', '{}', 'Networking Fundamentals', 14.0, 'b78cb12aac479c24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1344fc61-b965-4def-a703-7e837ccad7d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 22).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 22).', '{}', 'Networking Fundamentals', 12.0, 'a935be019e0f4f40_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fc3329d-a51a-4422-9cdc-ac0c6582e075', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 22).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 22).', '{}', 'Networking Fundamentals', 14.0, '20c1da3fd315ed39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef98ac9f-607b-4362-9ac2-b98787286c99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 22).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '91f4e8afddbe0800_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e3658bf-5061-44b8-88bd-8b955234735b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 22).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '96c6f451de1a9a59_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d356a28-a686-4c4a-a60b-7dd4b327973d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 22).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ecd357a137decfb4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('080f8474-7b5e-4d17-a8ff-59277543731e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 22).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f335dbd0ebb24d53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41ca9995-8427-44c5-bfda-c852d5c4387b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 22).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '558687a07cda58b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f05e5131-f751-420c-acaf-43401e036c73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 22).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'acd30c27b3b78722_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('faeeb283-84cc-4920-a2cb-2fc2bb717c40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 22).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9bc64ec1461c0d42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c42426ce-d303-4069-969f-907ec13d27de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 22).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '72a712d8f103391c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44a5b3d5-388d-4e1a-9b18-b4f0a92f71b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 22).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'dc03de3993018fb0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('895fe833-ea68-4888-a5a2-ee44588435b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 22).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7a18c3cfb030a397_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63829c20-07a4-4964-aada-c46eddabcd27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 22).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c3a0948127380099_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2e45c2b-13b8-40ba-8aec-d1d64e52e3af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 22).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '730bf3b16e1327f5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10e019b0-2817-42ce-ab33-a547345d7e50', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 22).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'bb039072ab5c8caa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('868b2ab5-3f47-4ddb-a953-2cb783ba2a91', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 22).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '036dc5aee5000141_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3e5c2dc-6916-4f6d-8fd9-5963cb7ef36a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 22).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a256aa9ad7b2cb25_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a90842c8-9396-4c41-90ef-96b1a1e8b628', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 22).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '772e07a885c5c9ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7671173c-815e-4b4f-8624-ca9edb8d8075', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 22).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e216379fd68a7d0d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60467dc5-3115-4c40-98e6-d851470192df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 22).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '539be9f0aa2442db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec7d3bb0-2d80-4ebd-80d6-947b8c269dec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 22).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '59fee57dad30ea64_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d048a000-1d46-47a1-bb00-634dfd73b3da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 22).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bae999d75b6daeb0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36cb2735-7afb-4497-b5a5-efdd4049d1be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 22).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ee0fa0124da66db0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08a14856-3a28-4448-8d93-52b2e162180f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 22).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '56a84f104e0a808b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37352a27-8b77-4758-96fb-645474302f35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 22).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8796bd1ecd88b969_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('159e33a9-e4b9-42d7-ba29-58d52e45dbdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 22).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '13ab9536547f5907_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33e9d3e9-732d-4689-925c-ab412ceed01a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 22).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 22).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '718ee70d6a210097_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13fe14db-5e6b-4b6e-9bb8-4ef129b971d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 23).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '508776fd73f9c7d6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9838780f-2731-4f0f-a7f7-e78cf9b7267a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 23).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 23).', '{}', 'Networking Fundamentals', 14.0, 'a31cb36abe2e3bfa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd6e93ce-ed1a-4ae5-a1d8-e016efd9d6fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 23).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 23).', '{}', 'Networking Fundamentals', 14.0, '1bc7a294d7c3dad0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52e25ebb-ee0e-46d9-8369-ce4002e34f49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 23).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 23).', '{}', 'Networking Fundamentals', 12.0, 'f52dbe8d8ee41d82_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f245630c-a12a-4cb8-9214-cff7876be4b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 23).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 23).', '{}', 'Networking Fundamentals', 14.0, '6990e27d5fa507c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76461867-d550-46b4-b245-6cf27bb04fb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 23).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b74b0d1f3f968b8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbfb7fec-4918-4d5b-926a-655fcc6804a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 23).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a475c11f2f7b0dff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71cd9e2d-b514-4ece-8375-d9bd2f028ed8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 23).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9825be5b978dc661_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22a802ea-dab1-4f59-90e0-286c5be4bff4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 23).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'af6177c3a8113f87_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1adbdfdd-a808-4ef7-a19d-40e63df44c74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 23).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '893e7b32e55dbf91_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6cc4388-f626-4500-b23f-447ee4be6d8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 23).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9b6f6073cfea88b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('675234fa-cf25-4188-a875-9bc0c2a9da41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 23).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '62aeb0a34e8e8900_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('811d8301-21af-4e13-9f68-eeea6d9aaf5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 23).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'bdc86b6561229bd6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee55ccd5-2b2e-4915-9eda-782965e28d69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 23).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cd0226baab03f9c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a73bec5-8e7b-4892-a9ef-f8f747b77780', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 23).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9479ba4e19ec82b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9ea4fb7-29c2-4100-a74a-27dcbf9867e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 23).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a091ba7f6f62e168_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('779f3792-c3e1-44bb-a5bb-43f01123063c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 23).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a2de619bb1a1bdf4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a7f7d2c-23fd-430f-8711-5600ad75cfb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 23).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'b700bcd7f5984cf5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33a04fb5-3e0d-4f1c-9177-6b9e0a4574bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 23).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ce746fd57328d535_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa530c11-963e-40f6-9c84-728757cbcf8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 23).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '960936b31142d206_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32dacebc-7f34-4482-9fd9-29489ce3668e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 23).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '165dcd8f8c249ede_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7aa47510-ddbb-4b30-aa51-d0a641a6e0ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 23).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f1483ddd7d76af71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ac4cbdf-d193-4011-af71-a4e0596c97b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 23).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '959eac7f32f8cfce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6ef4c78-e925-49fa-ac90-cbbde0c8e744', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 23).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '587e2b8454fe577b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8db0bca0-20b0-4664-842f-ff5d58113078', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 23).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '904338481fbe68e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64f8dc5c-bf2d-4f71-a300-d3a24cddd5d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 23).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '97ac3268cbb82fa8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56818132-a1c7-4b19-87f5-b63a9bebae16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 23).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '57872427f533f7f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53a8b9fd-b75c-4037-b355-67b5577529fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 23).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '87b177143c82aee9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03c46b02-8ca7-475c-98ed-c4f639334563', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 23).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '99b2fabb087292a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22b2563d-1186-47dd-b41a-98fe6084c95f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 23).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 23).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4d3f5d1f9cff73f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d041388b-8d90-4340-8e82-b11be9018a5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 24).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '73b3d3ef8001f20a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f21b6cee-2cb2-49d5-89bd-ee38bc3958e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 24).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 24).', '{}', 'Networking Fundamentals', 14.0, '91ab33bd2ca8f343_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('366db724-a9a3-4dd4-82a1-3ce7ee99f979', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 24).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 24).', '{}', 'Networking Fundamentals', 14.0, 'e561476578279125_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d222669f-5a8c-4b20-a00f-f0242abef90c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 24).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 24).', '{}', 'Networking Fundamentals', 12.0, '195d6dbb72240892_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cf50328-d9b1-42b3-b620-6f019c04dd8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 24).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 24).', '{}', 'Networking Fundamentals', 14.0, '7208d56b0654e280_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99c1d5ee-453f-4182-8394-d98ece9a4bdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 24).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e0a8e9628b84ca48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aa6f717-6481-4284-9d6b-6f5f0ab0655a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 24).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'df61e1cc70dac800_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fd36306-837b-4ca9-833a-a5e13b84b4dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 24).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2ef0c7959a3d9abb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aaa1e9f5-2f9e-40ab-8a7f-402ae9d9c555', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 24).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6ac5e3b22bcca32d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('688a032c-ebe1-43b8-857c-5cb0e1242628', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 24).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '61172ce7991475f7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c95adfc9-8594-4007-a277-b79efb35dedb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 24).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '62b22ab722183ab8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8043c3a-5f83-4efe-b6b5-6239def2b493', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 24).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f4101fd75f66d708_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8f7ca1f-7dd0-4ec5-b911-4e452d946dc5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 24).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '79fbca1241d82aca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b62e38c-5b7c-4bc6-aecd-df151a392653', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 24).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7e9025deca314e38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79b000b3-3861-41ec-a081-149cd717a884', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 24).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'eb76a030e39c8416_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e524750e-b311-46f7-a09e-17a14b7a45c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 24).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2807edbcbcd50a01_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95c8692d-9bd9-4083-a211-9b1254787e7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 24).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '47e7f2c6d5960c3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d516d3c-37e4-4865-83f4-64b3bde95112', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 24).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ff21d48d7b160f5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e998b42-62f6-44c3-a489-753bd9dd7a21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 24).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0da045611a1bf078_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c392034-64bd-4eae-851c-661cd3be6599', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 24).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9e3b59d065202f6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ea8cdc6-8cca-4146-bdba-8e45a768f178', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 24).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6b0f0ef691c42a3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a537b8a0-92f6-47d2-98a2-4c1577854fc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 24).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c70be2736db1d774_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b6ba2e2-c560-4a48-98c0-2bc4f397e300', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 24).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '594d9eeac7f4d459_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f65f132-81ab-4e4f-874e-1718116b81b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 24).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'aa422dcc1e0a6226_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13c51df4-2895-47c9-aa99-d62d0f30031f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 24).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e74fe75c3a8911ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37ae3734-ad13-454f-8eef-cac0d693fe14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 24).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '43a66aa22870cbb0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d37eb00-9712-42cc-9dcf-499ce0e5c463', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 24).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '79728e9dbec19460_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99923bd2-05e8-4870-a726-cef67994687d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 24).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '98a02ba44e8fc4eb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44c8b4b0-283b-4f80-b461-44cfe7d3179e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 24).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '41e59d9968d57af0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36ba4f0f-455c-4219-8133-531d9b7e00a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 24).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 24).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7d3678b9b321804f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a8c53e5-300a-4b52-825e-45e7271879f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 25).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'bf11ee7bde8b1abe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3955f071-3f81-4a5e-a7b6-55f7d01f3031', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 25).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 25).', '{}', 'Networking Fundamentals', 14.0, '411c7d4369cdafc1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a965830-290c-4cdd-9177-c0586481a1af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 25).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 25).', '{}', 'Networking Fundamentals', 14.0, 'ab0b577114c21a03_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5f5d107-950d-443b-af55-ea0c392b2b5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 25).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 25).', '{}', 'Networking Fundamentals', 12.0, 'f8e7507e305ddad0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfd5f23a-a88e-42ea-8d18-0fc9cf6553a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 25).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 25).', '{}', 'Networking Fundamentals', 14.0, 'aa6ef871e55d91fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70d364b3-318e-4fcc-a9c6-45a9a86c62f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 25).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '409f0de4c88814c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('848462e1-4640-4d0e-bbe1-a15dc0b64642', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 25).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1a708cc5f9e73e9f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('944e7768-7019-408c-a223-0342bdff3807', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 25).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0ec5a59931a8fffc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d70f5430-52e3-43a2-92f8-e272ed679915', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 25).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0e5b28b03cf0322b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b208040e-aeeb-409c-b6fc-2aa2fa31db27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 25).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '82c56fc8b3d3e6cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ab8f261-b296-4f46-b0e1-f53c6983a855', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 25).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '98c787968a3553ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('608a81a7-2ec5-4caa-89f4-452d893857d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 25).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ea7e4ea8aedbdb12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59a38cb7-09d5-41e3-9146-3a5de873797a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 25).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b40dded108f60b7c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0a59b29-a21d-43cf-a1bf-90ad4fbd72e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 25).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bfa53020043d825b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cbd4f1d-2c51-4420-be1d-ed859ef8d9e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 25).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6c0aa7b4d1f5b658_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f774755d-0216-4fc4-85c0-759963bba79f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 25).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6c1511d57bacd118_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aabf1abd-49d0-487d-a5d5-41ed2cc3a0eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 25).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '388ba446708e1f34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('125cb976-f2e2-436a-9eeb-d3bee3de2dcf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 25).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '304d1331eca612b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13ae87dc-f457-4180-a0ba-c97a5785757b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 25).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '472644f56f65fdf2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ca5d2d1-be4f-4ac6-9a53-10d84cc96378', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 25).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3745f1e7dfaf25dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d46d2b9b-5c0a-4f4d-a56a-3581c90011f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 25).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b8fd33213109838c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48fe426d-1537-4bf2-a439-112799471a87', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 25).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd22ead6d90a84ff5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fbbdc0c-7e86-4ca2-97c7-7655e1d06da5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 25).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a1ddcadf65291d1c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2979e4a-525a-4998-860e-c364b57c5687', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 25).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c42db42ffeee4b5a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b35671e7-de3f-49bb-b3ce-c0cc29b9acec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 25).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f441caf0354032cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cd1fcbf-0a4c-4e17-9607-be8e3943cb23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 25).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd98d71d15d3be2c2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1fc77aa-f403-48d3-b533-a8382a540962', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 25).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '2db15fcb5e66aeb9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4985bdc-a603-4a55-8314-a520d730ff86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 25).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '3e01f0a7336d6df9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a06056ce-e951-494e-af9b-1d313897894d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 25).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2ca59b590f111f75_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4d2e1f0-4261-4271-80ac-1d7c55d52b29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 25).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 25).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a0697d150b477484_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1359fb3b-f9de-4022-9203-b2c1ce6059bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 26).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2d9015a3de184d4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4ac0af9-f327-4c21-ba71-2a2ee495b4ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 26).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 26).', '{}', 'Networking Fundamentals', 14.0, '470f809ba86b19fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e926fa-10cd-4f48-8afc-8ccda578747f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 26).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 26).', '{}', 'Networking Fundamentals', 14.0, '99086855bd04105a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ae1d4a6-14ce-4c80-a374-382fd2bd97fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 26).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 26).', '{}', 'Networking Fundamentals', 12.0, '2de052ed7c00e10f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f5323f2-3fed-4ed3-b602-94dd65b4b88a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 26).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 26).', '{}', 'Networking Fundamentals', 14.0, '3bc46e49c8cdd54b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6191d5c-da9d-43b1-b415-008361610dd7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 26).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a573ab1744c7700d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('121547d5-4565-4896-a3cb-83024a6f0018', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 26).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '13ebd695e5e51220_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('197bb87d-d6c1-4393-94dd-9e32648f5578', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 26).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8b0db5efee441caa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e418b08-0951-42b4-9d9e-0c3e833b5ec2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 26).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '09de05f9813a5afa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9751deeb-6299-4dfd-a221-e5e768be0405', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 26).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f61227c7e7cc9c47_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d558ebd-2a7e-4bf7-bf32-5a5846916fb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 26).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '508f1a739b4f2a39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0737763c-6ca6-496f-9a1c-1f0e4d9aa6eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 26).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd3a454e6f0022310_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44c3952d-bea8-49b5-a2f8-710bbb5d43d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 26).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '78c108397fa5858f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6c9e2ce-254c-44ee-b088-afd52c652269', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 26).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '29d54007eb797a37_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcf6c45f-1092-41a2-9979-7b01637637a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 26).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '34079343c598639c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51d936c1-b4f3-4566-b04f-d94a7e376833', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 26).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e8649fa03d91193d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24100e75-479a-49a0-bc38-8c8e81ff1574', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 26).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e2fad305fab9a079_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2deafd55-1a3c-4044-a27b-7150217079bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 26).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e1586421363cfa6e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1888c035-574b-4ed3-9fd5-afd22301ab95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 26).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6a432f1c86b4abdf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdfdc421-b53a-40ab-bd2d-6ddcd79f56c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 26).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '531c9ec5cf6a51c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39dfb712-78fd-4847-92e7-d5d9b36fcf28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 26).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '26726abd2c8643d6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01a9cf01-c86f-4182-8aad-c5e62337b5f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 26).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3ebd7c9d80f3dc06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('964e1e83-fd6d-40e3-b430-49fa64b82a9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 26).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'abdc621b7aa04d34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed1dca7e-2a22-4abb-8592-ddeed6522c2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 26).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '89f144b1df1fba10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f5ff8a0-35e0-40a4-8a24-f876cdf9467b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 26).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7ab3c5b7fc2f8136_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bbb22ff-8884-4061-ac17-3db12ff17b12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 26).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dd59bd55ab4c18e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e7d0428-fe1f-4e13-95b2-fdd092946019', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 26).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'b3cca9ebfcca527e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a2a837d-3f37-45ad-b8df-2d06dd273282', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 26).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'eff6104d1c6ab859_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e709a83-dd88-43f1-86a7-719c572699d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 26).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'cf41db4b184d37a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9098765e-1eb5-4daf-b4dc-eb9a78af68ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 26).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 26).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6b80fe14a3e9e8da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bb4db06-ec07-4ed7-b14d-e3ca71313686', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 27).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1982623923d7cba9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5987f9f-9d2f-4e15-af05-51c45d97344e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 27).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 27).', '{}', 'Networking Fundamentals', 14.0, '31c1190432e7efb9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1cb1411-e856-4d10-a8e5-57fc1a385930', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 27).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 27).', '{}', 'Networking Fundamentals', 14.0, 'b1dad11ab20d5688_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad2909fe-0275-4286-87b1-dd9b5ff796c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 27).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 27).', '{}', 'Networking Fundamentals', 12.0, 'dcf2b744f7363a6a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fdd1e5e-6cf6-4527-bd6d-5d07820f30a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 27).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 27).', '{}', 'Networking Fundamentals', 14.0, '54286de41d95a730_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a38199e7-39f4-4fc0-af82-340856effb9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 27).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e05d1f0383bcd5cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9835761-b20d-47d5-b069-f63250aee1ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 27).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e641c716cbc5c251_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6533259-475f-4531-99ee-b587e9d1bae4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 27).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd0d39100e4308150_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('143c940c-e7d1-4ad9-9fda-2cca58a7afc6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 27).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0b51e9dc5ec5e861_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cae1a94-44d5-49b3-b9ed-367f1b7efb37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 27).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8b209d5d553dc509_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63314c9e-ac5d-4a38-87d3-3102564302cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 27).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b4f33c599f15a150_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da4265ef-f6c3-45f0-b9e6-2673a3929da1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 27).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'da40b6409b4a824b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5d4b879-2791-45df-a2d8-b48a6f40dfeb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 27).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '80b5e2dccae09a65_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c15ef4bf-9ef7-49cd-8311-db8e84ab2d4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 27).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '15977adad8b39a4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0a1eea2-43e9-4e23-a036-228aee1f0016', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 27).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ab436bf2be013652_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d223720a-5561-47b9-949e-0e2cc8e36483', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 27).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e21ef30865d59633_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00d2add5-64f8-4638-a56c-68c10b0be9b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 27).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd88e5016a59d2288_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8a62dbe-778d-40fc-81c9-3a47ce60e041', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 27).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '82a069a70cdd6e1d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c138b311-4f2d-4635-894b-01eb1c268d6d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 27).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a75566268d1e8e0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7217460-f4e4-495d-b3e3-2f8968594c2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 27).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '70d04fca8ef59441_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9079298b-ffae-45ec-967b-5958500ef82a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 27).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b9afaa7932be8f58_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f7cf82b-d55a-49f5-bb20-7d0b3822e963', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 27).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '53c56987dd1cc00e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('674dd4db-598e-4f9e-9f7c-8fd780a3d812', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 27).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '017eac532dbb4c09_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b041ebe3-f8d3-4bc6-8ad9-d08c2b98ade7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 27).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '1fe077e19bfe8fa7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd0cb2a4-224d-43d0-959f-a0b315be045b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 27).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1e7a6383a02c85e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a52125c3-6e9b-4e0a-bf31-172c099f1dc2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 27).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a00dd3ddf88d5f16_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('638b4643-bb89-4f05-81cb-e927c09a69f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 27).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '9679066ee758e827_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebaf9f39-939d-4a7e-a134-531bbbceda03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 27).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '258cfa729eeafd64_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35736b38-3453-4d10-8611-d67fb0538509', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 27).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '04d3d6428ea6f884_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('605345c7-7cdb-4b31-9c88-f789d5d0779d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 27).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 27).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ddf20bfb387a18b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f23e141-e71f-4805-8b33-0d6af52d042c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 28).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'cbf150a90842b66d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c49ca61-ef2f-484e-abd0-494c33af0b88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 28).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 28).', '{}', 'Networking Fundamentals', 14.0, '4f9178c76d43d328_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01559d41-abab-4f97-a128-adfb8a705980', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 28).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 28).', '{}', 'Networking Fundamentals', 14.0, 'ee200c822b601b88_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9fb8dfe-6b93-450d-a7fe-bc41df4ba269', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 28).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 28).', '{}', 'Networking Fundamentals', 12.0, '45d115e4df8d473d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baee881d-d1ad-4dab-965f-83036abb4547', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 28).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 28).', '{}', 'Networking Fundamentals', 14.0, '991077aa46fd98da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9d75ddb-8cbb-4026-b0dc-ee4ff026c8a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 28).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'eecc8331474754ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54f43912-8b92-4621-b8e5-ee20f896e3d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 28).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f69595412abd8f8e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bd34bd6-ab40-4e54-b4d0-0810634b0ecb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 28).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'da40848f6e643205_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a6c5f64-5baf-4568-bee5-4e705ef3c467', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 28).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '064b4b71ec72a5f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c520c53-b059-4c0a-b230-f3e5b433a0ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 28).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f5b835aea78445e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ed6ab54-7cf2-4846-b0ce-c7d325bd7cc4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 28).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd2ce5c633aeb1a35_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3b42010-51dd-46fc-8d21-f62a3524083c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 28).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8b5b2450c02ab6bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9672ebb8-6f9a-4769-b05b-1a89f4743645', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 28).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fc65916be6d8f354_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fff7008a-f36f-45ce-8927-d6a383d98082', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 28).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '16aab85df3192324_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d788da96-15bd-46f1-a339-7b632932cf0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 28).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2148c376e8ac1715_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67ee511b-ca05-44f1-94bd-7474aa45c7a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 28).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e4ced414709a41ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb782d28-5652-4c91-a95d-c6e013549da5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 28).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '32313b8ec783ca82_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbc993a0-85f7-4247-b681-d9a40a3b0c19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 28).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '2575bcd3e689f155_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d603d0ca-133e-4910-99ce-11de126a8d5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 28).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '08484fcb5c911ed2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8eb62ce-c993-4669-8d82-15c4fec05c15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 28).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5abdf57f092bdcf9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a607a80d-cfd9-4061-81fa-b94d4616abc9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 28).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '81e7174382767a16_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4536ba6-4352-4ce7-950c-4bdfc85c51a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 28).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e73d00e233fdac94_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc0be7b8-1eac-4638-b729-64fe741d4006', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 28).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '159fa2192917be0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c3a9931-87eb-415a-91c6-a22921663325', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 28).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4fd8ac166f9fe7b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88e5763e-6816-4f38-8f67-d30efde53649', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 28).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '430d92e765c743ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('590ffdb6-170e-4940-b869-f837378d2ffa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 28).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ff92ebefd050fc1e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef39b6f7-80ad-449e-9fb6-17b5f1829e50', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 28).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd3bad6b9296db252_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb0ab8aa-a94b-442b-8839-74801fd2a606', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 28).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '92f1364cd2e33f55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f8ae93a-6c32-4d05-9e88-f7c746e496df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 28).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6138eb3eaf97fcc5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21d2b26f-2aa6-4d48-b859-ff7d2f8e98f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 28).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '425fb7a7405c300e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8fefd3e-2ee2-495b-ba30-15f99e279dab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 29).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '91d938743db92252_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('317ffeee-18b3-4c11-961b-a2ca9abef748', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 29).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 29).', '{}', 'Networking Fundamentals', 14.0, '24e63dbe7a1fcb64_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa19df12-5662-4f86-b516-c2ec07a99d37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 29).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 29).', '{}', 'Networking Fundamentals', 14.0, 'c640c03864f6c976_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21f6bccf-8858-4657-a093-b96cb7664680', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 29).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 29).', '{}', 'Networking Fundamentals', 12.0, 'd0eb0092826dbd6e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08b18bd9-ed0f-4e6d-ab22-5e32e1d74275', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 29).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 29).', '{}', 'Networking Fundamentals', 14.0, '721c9d27a2bba079_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7854d57-9af7-446d-baa7-0e5960a18c14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 29).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b908520515f513ff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4a48998-fd0f-4a88-ae67-9fe2263ba1d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 29).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2d124a3f37cf9aea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7c6a0f2-2c6f-44cc-a291-e0c3dc97c04a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 29).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f0e6e2fd48f9f173_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe0f9835-e1b7-487a-a136-7a0946819ba5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 29).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6e2898245f683daf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('122e0cb2-0d14-48cc-a62a-42e4d8442d48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 29).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '452683281129309a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5951e8d-f245-41be-b05b-6b9891575aec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 29).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd12b2657306fda19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94bfa72f-b23d-4f21-95f2-2af541b53292', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 29).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '37c2f59c8acc3c3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ddb9266-73cd-4d41-8fe1-14535873229a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 29).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '32c704c897c093a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1378a05b-8d1c-41a9-9623-5bbd2515ab7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 29).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a11bfbdce87608e9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('914d9503-c625-492d-8359-5a4b286cd78e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 29).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3029bcfe538e3b7c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('665f35e4-8e16-42b9-88f9-19785168944f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 29).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'dd0d37fd09bd6448_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37be0dd8-9463-4931-9895-79d07855874b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 29).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'dda45d6f537b2a4b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb0c101f-902d-4af2-8b03-a8a4a5db16b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 29).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6fa7f2d834e438f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2574b27c-a072-43ee-9fae-1492f847add2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 29).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1d318447ff01a400_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40283d79-6c9f-4b16-9f4c-d48652b6d791', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 29).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'df194e478e24242b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aff9d5e-2347-4ae4-9ad6-da90913f4363', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 29).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b6b1138632a0b010_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb224c80-bc92-4ea1-8151-666a681d9dc3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 29).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '14db89db122c10a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e7f70ab-bff8-490e-a1aa-4b7caaf37d12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 29).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'db0b97c6e9c231f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3466fccf-94fb-4258-9635-5105b4e56040', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 29).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd4408804f57a86ff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3b8ff03-0a03-46d9-9a01-4f34f6b6437a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 29).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6f16bd15cfff21ff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a688fd1f-22df-497d-a80b-3e2f2cd1b9d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 29).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b66260e13a66053f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61ab8c10-eb51-4e67-a620-5695d67d9650', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 29).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '269131c2e13eacf9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d5ed74f-cac5-4100-9e46-aaa9a8b8c136', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 29).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd3c26b4d0b14087a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d6e94be-4c61-42a7-8845-1bb4e14795a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 29).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e50bd7cf62fd33e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a4699ba-b712-4b14-87e6-c6e21c8c1676', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 29).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8fd4e8fa681c4499_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39ed7d8c-c813-4eed-929b-26703e64bf06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 30).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'fa28d96c1722d007_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7260ff73-30a9-4cab-9140-ff695ffcd4a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 30).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 30).', '{}', 'Networking Fundamentals', 14.0, '29c0f85cc9af7662_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f403e003-1e5b-4078-800a-455eacdb7cc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 30).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 30).', '{}', 'Networking Fundamentals', 14.0, '973d32831ae395cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9783ca3c-f25f-41e2-9897-5ffe04ea6595', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 30).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 30).', '{}', 'Networking Fundamentals', 12.0, '3b0016421e04901a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0871c75e-ef49-4d48-b26d-b103f86fdc49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 30).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 30).', '{}', 'Networking Fundamentals', 14.0, '3396e422f7e3c4fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('839abd69-e80c-44c8-9107-16842ad56cfa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 30).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b8da96ea744448e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11eb3502-2476-47d7-a349-20779ac8a590', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 30).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '29d2d2cfc7d498e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd6dfaff-addd-436b-a759-1e69b570f2b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 30).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '874724115d47d131_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7034300a-bbe8-4672-bc19-3fd6a2ce6d9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 30).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '57d07b4786fbf25c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('086083d1-3f64-4fd1-bc20-66088365ec37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 30).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a4677f8dc13e7836_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49ebcfb7-a021-4a86-822c-4c0d40c883aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 30).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '32460f5cfcc823f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c887eaf3-e237-4b5e-a694-5ab1e112cc86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 30).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c09352986449eeec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9de1b95a-680c-4227-a6b4-db266c0aaf9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 30).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e7c36ed5ae93e5fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5581dc0-558b-461b-9974-32f54133a738', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 30).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7b3c4e408ccd1a93_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebdf6e22-2082-42ba-a848-905dd28981e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 30).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '163bcd792b8f2e92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e67ff1ee-9cfc-4f97-90dd-bc1129e610d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 30).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a2947de825712456_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae4e53dd-bea7-4335-bcbf-41dbe0eedf3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 30).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '73920392926ccb15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1519e6ff-80f3-4cff-966d-fd1abc9fee3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 30).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '15901ee7f369c676_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5915fd04-6ed6-4845-bcce-3ac01b0fc02e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 30).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '220e97ce25628ca1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab19668c-87d9-4ef5-a07d-ffc0fb6fbc30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 30).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0d051744a9e961a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88f6fa6d-81f2-4c5a-84f2-248c11fa8e35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 30).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '58e7306e2620ce34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd086d1d-55be-48b7-933b-c4ec8282202e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 30).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7c6a4bbf00fa24b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70074dc1-c70a-428b-82bd-f23d64ed70d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 30).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f0199e64d785ae53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42adefe8-7733-4207-beaa-bd707a5c51c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 30).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'b7873c939dd4284c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e87d2e66-c880-4d0b-9a4c-7dc5500840e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 30).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7faa0b1422071336_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78f5c7d2-854f-4193-ae11-536ecd85abb5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 30).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '191ab8018717c11d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd439381-9e33-405f-8b3d-5966d995d11c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 30).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '754b7c53bbc9a1a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95c34488-852a-42fe-99f8-cb92a3e324a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 30).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '56d89287c8ccb8bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11b4f873-f5ec-4931-b89a-bb3d7ceca8e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 30).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1dccba60ff5c3bd5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('713fda24-b0c8-48ef-b2d4-9c5fe86b8ed8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 30).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 30).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '24b9db7a3c2bdcac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d668ee53-5aa4-495b-a7a1-fe90ebbfc0e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 31).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '4d0dddab9cc9f34f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de63d4c0-0db8-412d-9b5a-0e48b7bb8698', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 31).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 31).', '{}', 'Networking Fundamentals', 14.0, '29ed456ea218aba1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8dc5acd-c07f-43d8-95cd-b7961dd5d90b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 31).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 31).', '{}', 'Networking Fundamentals', 14.0, 'f869852a62fc3f27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('684116ac-5e3f-4157-9a66-94f09e4b2af6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 31).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 31).', '{}', 'Networking Fundamentals', 12.0, '697d90d5aaf6f8e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fd19e94-18bb-40d0-a16d-dcc4bf418483', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 31).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 31).', '{}', 'Networking Fundamentals', 14.0, '29cc3fde51200feb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57332ef8-38c1-41be-913a-09282f418330', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 31).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '93d7cc353aca6b57_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6c084ea-6538-4136-9cd7-f32a15a71439', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 31).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1b847500ec9c39f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6586166c-89e0-41f3-b78b-ac22bb4451ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 31).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd1f8b0f696542f51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5ec7c54-6e88-4a69-b0ca-1b1dfcea6c2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 31).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8b402fda454ee082_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb1c2921-0b74-4265-9d95-93c3a159c204', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 31).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd2f7b35a90f791ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bfbbc90-151f-4821-a6bb-dc2e5e4a3bdf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 31).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '953741186ae4fac6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd911024-6c09-4cb5-9f28-35bf004c2326', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 31).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8aea12a0cf77b806_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8829c3bd-4904-4ca2-87ac-2b2e6667bb76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 31).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f965ac89173da3cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e8fb55-9e65-4d38-bbab-7f43674c4294', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 31).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3fc3c2480edeaceb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2c69138-f612-430a-83a7-027c8cb1337d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 31).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b74dd23d60aec1ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7c60683-c4cd-4662-bfc1-6c29b53c6805', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 31).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '62d31f5942311ca3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf38c39f-017e-46a9-8add-be63c618e047', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 31).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '982da2b1b4364b8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('991541c3-9c5b-4e21-9383-cecc57e37c90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 31).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '940dc6612945369f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24fe6b6d-a171-4a5c-b0ad-03f3d50e08f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 31).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '46d4bd68457c9466_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('532dece6-7c41-43e3-8695-23a83a398126', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 31).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a6e6e8b37a129beb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb5fb443-f6f4-48ed-b17e-c910e7d13718', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 31).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3efeea412440ffb0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('859ad575-6a4e-4ce8-a0bc-87ec4b37c44f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 31).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '750a1d7cf7e083d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('334b4381-fa62-4f1f-9b0e-196a9182e812', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 31).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '39ba6746b70f3bca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3134718b-79d5-471f-ab96-a1cf6b8b72e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 31).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '44868b1a15221fc9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4a82f0c-8295-46bf-86d2-d7d314ed7acc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 31).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd0e29abb7d079f01_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b94bfae6-6c80-4ad0-bc05-5b27808d1217', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 31).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1526bdc990cfe35e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d6d9ac0-9ca0-4513-9b03-7eeda82585b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 31).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5d9df6315a67ca68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43c2279d-959a-404d-a265-2de2a5f8772f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 31).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '462eb910d37cd953_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07019447-1d6e-4b33-90a7-0fe25cf2aff6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 31).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0782e951b674f575_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5da1ae9-436c-4325-b729-2ed64f16be7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 31).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 31).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd87016bdf33503c2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('957c696c-a3cf-4142-8d51-ac0753794326', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 32).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '27bd4d7f9ed68cb1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7c59d5a-ce1d-4540-8611-086e8fbb5b37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 32).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 32).', '{}', 'Networking Fundamentals', 14.0, '7d3ebf918bc0fcad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b35c0237-8e1e-41e9-b983-9d2e2d118f13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 32).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 32).', '{}', 'Networking Fundamentals', 14.0, 'ac6ab3470777a576_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ccee002-61f3-4f9a-8d1d-692cc74f5844', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 32).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 32).', '{}', 'Networking Fundamentals', 12.0, 'aacb0e38a2b3fc65_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ec2b985-4d72-4b3b-a779-8cc58ee29f5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 32).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 32).', '{}', 'Networking Fundamentals', 14.0, '5d5927ea96157855_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7b32894-d454-41de-88e8-570ec12cddb5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 32).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '871df677fb104e7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1eeb3345-a8e5-4c68-a2e4-11706a6a98cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 32).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c1fbec8d36ce666e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27a480bf-1f32-4446-a3f9-80614f64db93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 32).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f95592f258fa5019_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7061c5b6-4724-4934-976f-55647183f08e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 32).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9a83ea5d3a2864e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cbfde71-a122-4644-844c-20a87ce1f961', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 32).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c3e2f4282a746b2a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21763621-0e93-41c4-b364-ecf8d10eb211', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 32).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '07f67da991cd242e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('114f2cc3-0ffe-4f20-a702-821fb865e6e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 32).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '160c4d7ddfbabac8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c45e197d-de97-4773-969e-fba09f2f738e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 32).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ee81500793ab60e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c16dbd48-a828-4749-8d5e-f31936b6e973', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 32).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fc10c7962b9b53b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80608200-1e35-4a51-a40f-ad775a2c8530', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 32).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '07d5ccbc205198f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('324d5208-9cf2-421a-8bb3-75c1ba53b62c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 32).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bf8789faf13f7fd8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28f5e1c3-eae8-49d4-8174-55aab134badf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 32).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e653a6ab166dd9be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de2de124-bc16-4786-bae7-bb6dcf94b0e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 32).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '0fc555c7f0a8dc84_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c3a7ea2-830f-4853-957d-e74e100d313b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 32).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0bf344275efdd8fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4a44753-6f55-4c0a-83c4-a8f6b59996ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 32).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9c4d805087ef0333_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('258ef402-6c4e-42ed-8d71-7d2e613e3920', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 32).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd0d0f8033505ea7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d251833-ff9e-4a6c-8914-e24fbcfff04e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 32).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4ca425d5f6276f26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('162b4cbc-fac4-415e-8492-91751c5e0a0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 32).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '72a2fd40894aac1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('692686f2-ffbb-476b-9f32-dc3bd81ddda4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 32).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '5994dcc021a1e2a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79b6efa2-68d3-4959-85c8-b1124399728a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 32).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '640158f1b2e2123e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05431065-c283-412b-859b-30c3b2efa4e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 32).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '814096be3ba7d544_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e7b88ab-1b6c-4718-bf02-c5a0e0d2e6dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 32).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4e33d51cf4e9dfe5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90769318-c9d8-4d40-bc66-1bb54f178263', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 32).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '1f4a7f5aa0e4bc57_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22029461-1cbd-4406-ab0c-178f4e613311', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 32).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '72b1ca6be8c75776_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b039cd31-41a1-430a-81d1-a0a8fda06a78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 32).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 32).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b4cdaa2870fedcb8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9dbfcc0-696e-42ac-83b6-420ec625162f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 33).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f107052ad13e3d38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08b7d3e9-1f4f-419d-bce2-190e65996c63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 33).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 33).', '{}', 'Networking Fundamentals', 14.0, '051f594bcc00f878_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19367c14-9b46-4c43-941b-8ffa89b5719b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 33).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 33).', '{}', 'Networking Fundamentals', 14.0, '8c01782e479cc12d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4fa5ca8-02d6-460e-91a6-04f027daccec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 33).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 33).', '{}', 'Networking Fundamentals', 12.0, 'f357755a05d735fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cb50cbc-5923-49a0-ad0c-62abceb452a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 33).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 33).', '{}', 'Networking Fundamentals', 14.0, '75f721f8e96c2936_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2678a156-eb2d-4177-b2fd-c293ce2eaffc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 33).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'affd599cec2be79c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52b49a79-c998-44c6-8216-090c365ed6f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 33).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2e9b17a3ed65fe1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11db8930-8550-440e-9f67-8e157da09209', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 33).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e80ccecc51e61991_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86aa1621-b025-4426-9f82-65995b9dbc90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 33).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a9b03f000413fd14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6f4ccff-325a-41c9-9bd9-ccb1a75bc816', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 33).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8763dfa52ddcce64_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90580a13-fd94-4eab-94d2-2b198f907c55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 33).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '00b8fbec64884a34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a42c585-08c8-4898-a6a2-4e04dfe34488', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 33).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ed66aa704512248d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bc56480-eb24-48b8-9435-5796e4d18d05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 33).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6d33c7315831b14e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46640471-c07a-46dc-bc56-178eeb3a096d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 33).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4ed66848c58f6d2e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e846bdc3-b53f-4e98-baa2-67fd33cbf223', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 33).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '501462d8d147675b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99557437-7145-4de5-ae85-f1439d3d808c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 33).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fa733b06121ad8cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0711da5-0d42-4552-8f8f-bd4eb607dd8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 33).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '2cf341f9c80f7320_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a24111b9-0490-4872-9bca-08f6eb1d5d91', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 33).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '47543187d33c585c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed1a4bf2-3c29-4097-9d76-95f4f78cacd3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 33).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f9e2e324b072e61b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f39d2d2-ba09-42f8-a1f1-b32bab1409b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 33).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd86da50204431d9f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8066bf77-de15-475c-83d9-1af1468c4139', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 33).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a8ccb10c184e6a67_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59a559c2-6c6c-4299-b7b5-50ceed80dfe9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 33).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9d61f427b04da12b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb8fa058-c924-4a80-8017-d6cd56a31d19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 33).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f1958b27d460b651_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7256fbf-6703-4524-98e0-7b3103001234', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 33).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd55c1a70ca5ee7d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('284402af-4d4c-48e4-a31d-acedcd6dc79e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 33).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '11dd4f37c226bb44_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b133e9d6-b48f-4920-811b-0823aef6cb9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 33).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '78d822079de291bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4a91415-7615-48ab-9949-6a4e9ffce1b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 33).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f4c83b5f2d75a4d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8e2e2df-1d40-4fc4-9cc1-d3819c2faba4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 33).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b991ef1fd1923c80_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c0927f0-b340-44d7-8138-03f958843d67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 33).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ce488928a27a09a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25726bed-dc9c-4785-b4b6-bcdea10f84a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 33).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 33).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '737d38037ad0f2a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f411db86-10eb-4d7b-9ad4-1ccd96f88f2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 34).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '21be92c39db51211_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7711efed-ef04-457e-ac6d-18e1368e21c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 34).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 34).', '{}', 'Networking Fundamentals', 14.0, '8018769db7411bc9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41d47d1a-09b3-48fc-af0f-ec5a75a5b1b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 34).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 34).', '{}', 'Networking Fundamentals', 14.0, 'f0e97b21d7995c59_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9150d0bf-ff91-48d1-9d8a-2c5e9ef2f618', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 34).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 34).', '{}', 'Networking Fundamentals', 12.0, 'd80225c3568a9508_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c652d923-e4e6-4eaf-be5a-9edb0afd87fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 34).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 34).', '{}', 'Networking Fundamentals', 14.0, '3e69a7a707c97b51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b43b075-6d8e-40d8-91e5-6a9eed2b6dbd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 34).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '7b25c02c6ca546c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bda4487b-07a2-442d-aafb-35addf319eab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 34).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5d57eab3e0acb5b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc3235d3-f5ef-4e00-9278-994385388d0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 34).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8712c48b549d03b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10893999-7a41-4fcb-abfb-bc4d35545193', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 34).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd76332c3a18ba2c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e69bf88-34ca-455d-872c-5f2c7bfac02b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 34).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '80f4d57b1995f121_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8763bd4-c163-4d0a-a449-23ee1eaaad57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 34).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '808c965a82b60fd0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b58bac03-a569-446c-ae77-f43c85c8f31e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 34).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '807b52c4ca8e53b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcb4d063-3f72-41ae-85f2-d79f4eae8060', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 34).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7fe134c1b203878a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecd65638-484c-4d94-aa6f-51f20efebafb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 34).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '33cb83852592854c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a6b6cef-c410-4fec-bb95-580b19d00424', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 34).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '35ce7c888cec62b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08e3739e-1031-4159-97a2-d2babafc2fe6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 34).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8b53bea71edc626d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00f5b8cd-0d78-49da-93e8-aae50f2a820a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 34).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'adc90814f053089e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bddf4dee-dac3-4798-a613-830feb677718', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 34).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ce45d2fa3453b971_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0db4bad-497a-4529-88e2-c56594f8b120', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 34).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b2ce224823c379b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('195886bb-de17-4eed-b319-a88893f13613', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 34).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '14b8123351381ae4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1b0a375-cb9f-4daa-a9ab-f0fd417c988e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 34).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2b9ed1e796ac59bb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04e7444d-fe78-4f22-b572-31f02e22c573', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 34).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd6a2245afa82f2c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00d9f75d-b573-4c7b-a01c-790416dd9d78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 34).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e1c737e5e395388d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d249ebc7-6ef1-42d4-96f0-1afd9a6afd22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 34).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f5cd64a522e1b099_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbcbf8e6-84dc-434d-94a8-e39c0e36c9cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 34).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7e648740e7c7f89e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a0e4e0c-7ebe-403b-bbb7-4e634284a746', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 34).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'efdd7699fcc7a135_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a61ed0c-465d-421a-8584-032bc8dbea3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 34).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '22dda55e200e5db8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d1800bd-d749-4001-b07e-c3d4d86f77a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 34).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd6ce5ab1b4461e21_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5eacefbd-da70-4869-aa5f-eda5ea89156c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 34).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '39609a94da65e081_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bd84830-cde7-4c90-8b3f-2fbacecdb43c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 34).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 34).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'db4cb817f34288b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a43fecc-c888-4d01-82f3-9cac8887f337', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 35).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '229c357a1f44e3e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7f33abb-d4c8-4163-a504-8e1954b8644f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 35).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 35).', '{}', 'Networking Fundamentals', 14.0, '2f5ae675d0689740_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9685764-c0d2-4a52-99b5-351787ddd20f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 35).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 35).', '{}', 'Networking Fundamentals', 14.0, '32f4e89d9c775e9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e5d5fab-f4ae-4c47-a345-0dc7b721b897', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 35).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 35).', '{}', 'Networking Fundamentals', 12.0, 'e8b473f0eb40e344_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19a95f62-0e17-47e0-99ea-427102a384d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 35).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 35).', '{}', 'Networking Fundamentals', 14.0, '00b8952a842087e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91c2c82d-ce20-420f-84bc-152b6822c058', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 35).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6380ad747eb07902_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1410fcd-244a-4319-8f27-54cbda09097b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 35).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6f7bfad3ada2c581_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf02f2a4-c347-4964-9af9-ad13dafca4a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 35).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ae2e4c7822956632_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33e5ec52-fed7-48a3-9683-e393cf6a49ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 35).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '16984aff0a7d8eba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dd836ef-348b-4635-a578-b867d76608da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 35).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '62b808b785f76c41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2e8809b-83cc-4c29-bcae-0b3905b2b8aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 35).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '832928f527260ace_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a4cd9d0-6cfc-449d-8438-9eb888579ce1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 35).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'be9258331ba419c2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f98aca0c-b0c9-4f91-9d84-5aef0fa791ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 35).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e6893d98b3429ffc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a0395e0-853f-4915-a874-25211f0f904b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 35).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '69b73230d9dcc617_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51ddd7b4-26d0-490e-bdd7-1819d60a0c7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 35).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6b5aa6c4ac649a29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41e3b762-b169-41b2-856e-8e4255eeaa2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 35).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f1a0439b6fe27326_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('addef520-5685-496c-b571-ed708bc61ed6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 35).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a90691dde0c6dad7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36dc2635-d6d5-4cf7-bb4a-4af68b1cab19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 35).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '76874aa2579078d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad2f8406-afa4-4e4d-84e4-88c040a6ec78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 35).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '74c2229c4d72c468_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58ead991-cefa-44fe-98a6-91f3da8c41f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 35).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6ef69d0d709f31ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ada1279-d232-42a4-b1a8-2d5851d4d340', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 35).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '57c3b5387ee3cf5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de414166-9a62-4d75-be1c-665bba9767b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 35).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4c75d08cc029c839_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19efce98-5303-4a30-9d31-6bf183db0c23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 35).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '31e68384fe15aecb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2023e348-d7ac-4c01-aff8-998421408b81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 35).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '0d3c3e138c35814d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f611f4b2-75f6-4beb-a5c5-046c66dad53d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 35).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8388afaa37b1cea6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1366d463-46ad-41ef-9913-2f735ac58f1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 35).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cb0166e1779b25bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4ecf5f3-f79b-4c43-a8ea-39e5e9a694f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 35).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4546e5734fdd7662_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5303e9c6-71a5-443d-b816-ae9c7c0efdb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 35).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a2d9971abc58a8cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ac0c800-c940-46f0-ad32-2b997f79b6c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 35).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8b092151a169a5d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b878afd-57f5-4b8b-b4a3-cbee549c207a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 35).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 35).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fc3a8f13a6e75455_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15ec253d-0124-4c5b-909c-520ae4650770', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 36).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '721a28b0accb5d5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43d37f48-a58d-481e-bfef-b1e5bc1892b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 36).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 36).', '{}', 'Networking Fundamentals', 14.0, '0bd2c3ca53199279_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9156ecef-6862-4de2-af92-10452992f6df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 36).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 36).', '{}', 'Networking Fundamentals', 14.0, 'cecf9537e8726ac5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2b316c9-84c6-4a1a-a749-fc0030fe3ae5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 36).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 36).', '{}', 'Networking Fundamentals', 12.0, 'cb080788b550e0b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c22e6425-3f0e-4ec1-85ac-3035b362d6ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 36).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 36).', '{}', 'Networking Fundamentals', 14.0, '78897539bcfe969b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d2d5e2a-b2a6-4993-b304-beff99a39acf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 36).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '9526136e91ad2ccc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f84e33b6-810b-4cc0-98b9-36422511a841', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 36).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9612a0b79cfc03ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3396119-ee1d-48bd-af0e-5d3cebb991b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 36).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0dc691892f528e17_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b8b0952-6cfd-4bc0-ba45-87fbcb0714eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 36).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c7cb71fae111abc7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7470498c-4701-4f57-b722-98fb96207ee3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 36).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '89358b39c7f8d460_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78d1efc3-00a0-4673-9b92-963d3bc12712', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 36).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2e90a0155431105a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5a3f9ae-15b4-4615-b9fa-821aa0f75dba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 36).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9d7e615e9c7d7be2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('359099e9-4e5f-4d76-83ca-b0c099375e99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 36).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '85d6c94411f46b28_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31de0c15-d03a-4ce3-979e-7f104e49aa94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 36).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '759de1cdee5e0d73_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('732a4bba-8050-47a1-af01-91acd697faf3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 36).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '41263214f6b2c9eb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebd562ef-f7c3-4449-ad72-1815d7d20518', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 36).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7aa4dd69c9d4081b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a12d179-d23e-45d3-9561-aa22a78cbf66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 36).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6f098183864710b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7db1bc02-5bcf-4d17-a8c6-ce6d067e2010', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 36).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e822209948f4ba0b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7d88199-8a8a-4462-9f8a-1184bfce5023', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 36).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '39e7023997fea3ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d421cd37-58aa-4d3b-896d-aab928714a9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 36).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '34e1d92a0d467c1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ced442c2-6bea-444c-a4d0-5052e0896a3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 36).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '608c6f022d29ad8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a27147c-10d2-4b36-bac7-fe5b9064fd98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 36).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fbbb7284989fdb02_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abf8a82b-5552-4286-b42d-bf25b6482998', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 36).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fb7936a39c03845d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d3b657c-8ffd-444d-ad5b-b7bfece0b521', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 36).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '20d3c83d607c522f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('959aa123-e6f8-4169-b5cf-b2660b700b97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 36).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0d5661a2eb10d3dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c1a46ae-a145-4d08-a6c4-e9bba1cfbe69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 36).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '42cfbeb174589280_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bfbd9ee-3428-4b38-8636-4ecd363e239e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 36).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e1c1b058e7098443_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c601a339-8c22-4be3-bde0-8a6bad5cc7a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 36).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd8174eeaedde02da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5e4fce4-cd02-4d2f-988f-94b919731900', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 36).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'adda07e584fb41ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e15a2f4f-eabf-4108-a831-68403980255b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 36).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '05c7c4567e5f8e0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e4fbdc8-60b0-4308-85a9-01d6c650cae4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 37).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '437af869178ba19b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3816a5e6-4df1-4bd5-ac16-fc8bbfa6c23b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 37).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 37).', '{}', 'Networking Fundamentals', 14.0, '3fb64545a6d01e1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21eb0c41-5834-4f5a-a97f-c905080b5ee4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 37).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 37).', '{}', 'Networking Fundamentals', 14.0, '40958f77ef11f23b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7abe0d40-027d-46d7-9729-48e5e8c7737b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 37).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 37).', '{}', 'Networking Fundamentals', 12.0, '128f09d333f14d6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a38c6ecd-8a7f-4279-8adc-26069c3b4e5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 37).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 37).', '{}', 'Networking Fundamentals', 14.0, 'ef44575c9c302dcf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6b67dca-21f1-4484-8e69-c5acf1454194', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 37).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a42e243fd72f46d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc87dc0b-191e-455e-8388-bf8fc743e396', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 37).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '56630f06153a094d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f5c0301-dff8-43a0-bc7c-97140f0d52aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 37).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b369a52ddf6b4dfa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4155697a-f9c4-4068-8131-3ad2e2b00e9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 37).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'dfdc74f831a2974b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50621761-8252-4d83-a062-c1cba4e8115a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 37).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd65658c88c93b362_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9acf11f6-c6aa-4f5e-9b62-be3a50260aff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 37).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c6ff00a2ad7fbbac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('305215d8-75dc-4435-8cef-024fedaf5a2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 37).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9c2a9e75c4577a72_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d026fc5-e854-4f68-99bd-6702525e8f5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 37).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8a414c480dc67716_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7b24773-7594-4115-b31c-9780be65b85b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 37).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f3f00dccc2add8a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b81f07eb-4de9-4f5a-8560-6c616abaf3e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 37).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ea704c1312a3a9a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0305c343-d287-4362-9e03-36541da00326', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 37).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ad1b5b2e453af42b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31f0c634-5411-469e-8f70-850b99944652', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 37).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f77dd7061065b3fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae1681e6-e1e9-4b20-b6c1-828bad850f4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 37).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a1b712b7abe76842_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1c3305a-48e0-4c25-ba1d-a02464a761bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 37).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'bc44ea286c600653_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e47e9cf1-02d6-4ed7-b1bc-4828ed8a8e83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 37).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0174f3e1abd1a80e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45a57026-cca5-4737-b205-9ed5b45375c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 37).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2300a7a05942a6f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e84da699-6569-4064-be3f-8dd7a6de408a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 37).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '42e5f63c7475e155_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c8e8eec-54b4-4ed4-bf96-0698c355cc71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 37).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c2c693d0f8f1131d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67c3a8fd-bfa9-440a-99a2-3346b6e2daa7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 37).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7de67d79f01b9e5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('426c2228-ae9c-4ff5-8e18-5ae67369c762', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 37).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ad80f217165ec09b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed4c625f-eb3a-4c31-b83b-dab7915e1dc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 37).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'db2653073fbc3b44_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2085ffd7-45ae-4216-91fa-4a80e38803ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 37).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '3742f4e1fef1fed0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0681acc-54f4-415b-88e5-5a5a915e0b29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 37).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '01276412df6ab544_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08e0da8c-1c51-4298-a20a-11d7ced30867', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 37).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9229d106493a85e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('600faf94-1815-4a18-9eeb-88ddfc9715cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 37).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 37).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8c89df953db1e80e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('339c008e-a555-4981-b064-865b08aa2dda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 38).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b578d6dde933908a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('289ca6ce-f58c-4c79-a49b-19ec25561e53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 38).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 38).', '{}', 'Networking Fundamentals', 14.0, 'd4f4b5fba293b184_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f08e08c2-b4fa-47b7-a1ab-aecda4f2e593', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 38).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 38).', '{}', 'Networking Fundamentals', 14.0, 'e846c38d95d3f82f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e62fe765-d7dc-414f-a127-4cd5b58c6c14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 38).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 38).', '{}', 'Networking Fundamentals', 12.0, 'f46de7546b2687ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('066f645f-a067-4d34-a9c9-6b6ade600f46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 38).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 38).', '{}', 'Networking Fundamentals', 14.0, '43bf541350cba8a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a3f99e3-4bbd-40dd-8851-06d2a04b7927', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 38).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '8a7dde5867c1c074_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9653b696-cd45-4cb9-9788-332b46c438fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 38).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '05e531fa433dc463_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('692a0a8a-bb76-4914-a04c-b48d0eb41b15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 38).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0c2fb567b1d09ca4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31af0c01-b9e2-4803-9adb-fbfb9e49cea6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 38).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3b783fc3f73f7bc5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ce41af0-0b69-4c62-a139-b874622d94a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 38).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '80724e99f917aab4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e590cc65-5f8a-4f54-ac3b-b18906fa6629', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 38).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0a7c64ce9031689e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28c28f90-dcc0-4cba-a6a2-28f10620d8d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 38).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '66831ea0bafe8d5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af55e4d0-7432-46b7-9e23-c99e60da1d2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 38).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5fe192fbe93e77a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87b6fa8c-aeff-4d97-af78-ee21764f34c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 38).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1740c56ec6f5b03c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8fa40fa-4616-47c3-affb-73968e1d9bd7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 38).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c57a11aea2c36f85_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f925373a-146d-4ebc-a341-81c43048f414', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 38).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '816d99baf2a0c71a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e924ebd-4252-4924-9012-d69a06e9865e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 38).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4242c40b29838a40_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7035f7aa-e3be-401c-b578-e12e319f0d9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 38).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '3ce522dbf8e8543d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9ca28f4-d172-480d-bd2a-a35dab57bce4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 38).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e062477c8c39d53f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07bba988-6169-4820-ab34-4be08b610de0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 38).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a9ab5b9c8789f935_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('251f443f-6bf0-4946-9ecd-db599d334bfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 38).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'edb8c835233b6cf5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6ccd274-f2dc-4ef6-b10b-6b6f9d3ef9cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 38).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4ced4d39a27e52aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e37367ea-240e-49c0-990b-6c7bc482609e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 38).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '29ea88a2a5cf9057_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9de475da-5d16-4397-a445-f038b2ffe05a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 38).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '18fc894ed4d4c697_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1325e30-117e-4f50-91bb-372ffbc31296', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 38).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e15c94caa5ceca31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85dce430-b114-4364-8faf-217ec448e519', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 38).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0b93b291dfb84b12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b1e52ad-7872-4c7a-9c85-05751a5c0c12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 38).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c0d3406e276df385_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df6b790c-d0ef-4565-a533-ef88ffea28d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 38).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f4dec6a162725664_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fda5f802-a842-485a-b849-e4cef50ac399', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 38).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ddffc89a0d173120_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fef9f0d9-e1be-4264-8878-e4c60e27d1e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 38).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9f78753fe5a9c688_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e6f4a2f-aedd-4518-90e9-08f07943aa5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 39).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd12c44b8a77a78c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c773858-0b56-45af-9c12-2b2951a1bba5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 39).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 39).', '{}', 'Networking Fundamentals', 14.0, '1d28ffb21edffebd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b29962e1-eda2-4bab-a5f6-fe8485d072aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 39).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 39).', '{}', 'Networking Fundamentals', 14.0, '6ecc49b207fee93d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c17fbc5-2f12-4a10-ae49-3064f27ea071', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 39).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 39).', '{}', 'Networking Fundamentals', 12.0, '6034c91d6d42b4a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b27db5b-9fc5-4f2d-bf26-ed952da07310', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 39).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 39).', '{}', 'Networking Fundamentals', 14.0, '2360962624f043c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc89e04f-2a0a-4b3c-b0d7-5bacd6d31ebe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 39).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '740fba725e02a183_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95199821-c062-4e8d-8229-0f51bb18cd31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 39).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '400ca658b70bc44b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8036603d-040d-481e-abe6-a1c008155ad3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 39).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '077936efac7b4709_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e08cb0a7-febd-4a94-b79d-f39615025687', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 39).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e85ac17be76acc54_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60e541e4-6357-4585-b1ae-fdee0f81b8b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 39).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '240240a45089888a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eb129a2-7b8e-4e3a-a977-92746c07defa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 39).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '36eac855cb55d75d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('744c46b6-e898-45f5-978c-f43654d9db38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 39).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7c685a365b0d538b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('496f9a00-15ed-4faf-8f67-30d32cb4492e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 39).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '56c18786a6ba8c6a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61100e8d-22a0-4fe0-9410-98f841c09cab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 39).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6ae50f82cdd39bdc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4604fe55-19a1-4d8a-ad86-a0ae96ef1106', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 39).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7530eaf59de66b33_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e26e812-9c6d-4a77-a6f3-4cad4664f7f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 39).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c5d97398cdad4f2f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('156396ca-2bb7-4e6c-a8e5-b9e80c7abeea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 39).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '623bca17c32d5a96_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f4dd272-764c-4669-a78b-499b4a275e67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 39).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'daaaf5e8d9228d0d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56a0607b-4a1e-47d1-92e8-cc33e000093d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 39).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ffb3fe59e2ac95b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48f24746-23c2-4b42-b50e-2ef3bec4f1ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 39).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3c21264fb83dddbc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0750f4e6-6b32-43de-9cf0-cbaae0158458', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 39).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '862f60cd80ba569e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d38d677-ac28-4e95-8b8c-d45207e15de3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 39).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3f6f4f217f6d93ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54ca42d2-a24c-421d-a1a4-6f55e6f55151', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 39).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '704b8de543589aaa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('584c9dc3-341e-4ce8-b50d-c5c6fce0aa0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 39).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7b06d6c04969859a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('298eb90b-1d80-4b59-90c5-3dd50ec74e4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 39).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '86b580742d8f60c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43b12acd-b161-4cb9-a6f2-91d67b4b5025', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 39).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b16650cf0d005c10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf65f535-0be6-4bcf-a115-a1a9c2cce039', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 39).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c9120b131ad15878_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('931bff13-480f-493c-96e1-ea2bff61fe5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 39).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '728f753e2f24bcc1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eae8909-f94b-4960-85e7-58f5bd0e7ca8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 39).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd05460e44804ed5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23f0fa7c-e2b2-4bfb-927d-b69ec9670936', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 39).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5fd46fb9f1edd283_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23525498-4b06-4bbb-ba47-a83b720d450a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 40).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'bbfacc5e0441900a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a93b9e26-ee1b-49b0-af29-8919caca451c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 40).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 40).', '{}', 'Networking Fundamentals', 14.0, '21cf9180dd10d032_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e846d85-2f1d-4762-b1d4-ed575c0d0a61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 40).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 40).', '{}', 'Networking Fundamentals', 14.0, '9d53f6f80571acd5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('850ca3b8-75ac-42ea-b570-5f07a6953a24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 40).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 40).', '{}', 'Networking Fundamentals', 12.0, '3b12fccb590f9080_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fba95b08-9ac8-45ab-b0ff-14e9b7220f39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 40).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 40).', '{}', 'Networking Fundamentals', 14.0, '0cd26a70c09631b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d44cbc03-d2c6-4731-ad71-498041ff42de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 40).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '4bd599bd252abf8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99f4eea7-85ff-4ac5-b284-20a811f48a68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 40).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '327b5f865f906532_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2170b0d7-e775-460f-8cce-c63e10db571e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 40).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3ddf1150b45dc4a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6c83d48-9a3a-4a04-8dfb-0ac951ac16fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 40).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b84e08e66afdb761_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('079be994-34c8-47b9-a84b-057272723883', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 40).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3d3d524ed9e1cf45_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d97a8904-3d63-4003-9a7c-c294bd160225', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 40).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0cb7a410c16b01d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('471f95e7-d192-40c2-9ab5-3af0bef3e879', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 40).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8b9135a4bc039d36_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0da10e98-73fe-4bdf-9df4-61abc57a9592', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 40).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '16fd634b57738fb8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69de605b-c7bc-4f9b-964b-034c51f83b07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 40).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '67a1b38a541cd74c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b51dec8a-66f6-452a-9816-05312bbfac25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 40).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b9f5e020d83c37f5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fbdadf2-4216-4726-98cf-83a940a6186e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 40).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2321501e5c75ffff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78323685-c5ea-48f5-bbe1-12330e8b1322', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 40).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3dcead3fadfba1e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5371fa19-94de-4569-88f0-09192c37421e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 40).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6f91664790abcf46_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1e53499-414e-46db-b080-610513010dbf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 40).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '624d852110453436_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae2f757c-1871-405b-a149-1b9692542cd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 40).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '32c6864bb9f5b25d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25934996-ef05-411c-a006-a80ccf683579', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 40).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '344f60a1f7c13a5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de5edbef-6d07-48c2-958a-5bb97ed796a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 40).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3d5c6e0408843431_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de7f8f62-fede-4a84-8381-368b4bdcf71c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 40).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e22dc48ddb029388_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c1579e2-68b8-4c42-9085-5fe22e4a027c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 40).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '13195e3635917499_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('606e40c7-f771-47d1-a87d-6bcbcb3aebb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 40).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2a7945487a6e3cee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('904adb9c-b56a-4709-b311-2bc2afdbe637', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 40).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'eeb5f0ecf4af6188_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8cebecd-ad30-4e32-a094-ce842499348d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 40).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '3efaa66bc2c6384e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab2c6b98-9f87-478b-9887-e70bb3f085c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 40).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '150c49e31bc46d93_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5833c096-490c-4e4a-8e36-019823e07369', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 40).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9b81fb8a278b10c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d591258-eb8b-4979-9951-039b2a06a364', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 40).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 40).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '320bf62ecc8125a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07c5ab54-c2d4-438c-b142-e656efcb8631', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 41).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '300e6713a2f372f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc4291d7-949e-4dd2-8df4-86ec80782f99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 41).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 41).', '{}', 'Networking Fundamentals', 14.0, '5962c63b25f385f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63d5e005-34be-481b-804e-ab72bc91f092', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 41).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 41).', '{}', 'Networking Fundamentals', 14.0, '01384de1b542ad79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd6fd99e-c0a7-4350-abb4-361d54ebe35d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 41).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 41).', '{}', 'Networking Fundamentals', 12.0, '6dfd297e34360b1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcb914b5-c0d0-443d-b0db-429747631d2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 41).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 41).', '{}', 'Networking Fundamentals', 14.0, '76ce86183f5bd9cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efbe3d43-fc7f-443e-b1ca-3f00f009ebaf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 41).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3d2c06307e535db2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95728182-fbdb-46e7-967c-ffd1499125a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 41).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a2f25f72f52c78ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9737328b-1d8a-4a9a-88dd-076b30165599', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 41).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8afb9a96fc02922b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f2b6483-e63c-4a2f-ad11-37d95e67ede5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 41).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ed06db47177d50e9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('475c6211-2dd5-46fa-94d7-c71fa9ab57a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 41).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '15fcc6fc94b6b4ac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('000e8d1e-ec3a-496b-a380-6760e3202758', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 41).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ee137324309d07c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f160363-29d9-472e-823c-b14b0679930a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 41).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '23ca0e43da755838_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75d1f458-697f-4031-9e46-2022b31881f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 41).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '900084c7ab3d3b1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e8acb2b-3cdf-4ff5-81bd-cf640cf8439a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 41).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7f7396daa5656ae7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aaac7da-2d02-4820-a352-f9e32456870c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 41).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b2246ddd35b957ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efc1a153-a7a9-4804-81b7-753ad8bd164c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 41).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ece87cf60a7511ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b20ed88-b785-4e56-9733-791f1bc03d5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 41).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0f4e2687c04f5ab3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3d75acb-1c48-42cb-8d5a-eaec025a6a34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 41).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '0fa9b544f3eea328_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b591338-8fab-47fe-8dc9-4281195670bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 41).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9adf4c1e9266adb9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97ce41df-f45f-44e6-8a8f-ef6e31448162', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 41).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ca2ab3837b9a3b75_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e824cb25-fad4-41d1-b33b-d4992c4d835f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 41).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd91f9659c4d95089_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a730f0f6-2bad-4ace-9028-7cf48b44bf04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 41).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bdde359bd19f329d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3d0f32a-d92b-4d65-b5d2-117478712dad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 41).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '59f02aaf99d28c12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72439454-2976-4041-ae62-28b3d4f4db4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 41).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '20f4f8bb442e7d73_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9c34eaa-cf78-4e91-b0a4-777ae2ebec20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 41).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8f800dfa9e5ac7a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd733401-11aa-4411-bbfb-3aafb2654dc7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 41).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bcb12995a1aea753_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb89c459-3e10-4cbc-88d1-1f3fc3c2fe08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 41).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '1ffddc09cee873b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9aa4a3f4-fdba-49db-ba25-21480575b1e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 41).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0ba4a6cf0b0c6030_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e62858b6-ff0d-4612-9747-981223147a04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 41).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1bca0e902f89a2da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('217dfae2-7253-49ed-9f49-4bfa08c53b9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 41).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '23f90ac7d7f76b4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8d1966d-c53f-459c-9f56-6cbb117a583b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 42).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2bc6dd75614e32aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fd55c3b-5695-46ef-bbf4-ed0602c92405', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 42).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 42).', '{}', 'Networking Fundamentals', 14.0, 'df4a95982a8952ff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5edd12da-4002-4a92-be5e-59aed1a71f95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 42).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 42).', '{}', 'Networking Fundamentals', 14.0, '78c90d56ed85eb00_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8da66fe-9ac3-4163-932b-e44977e55525', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 42).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 42).', '{}', 'Networking Fundamentals', 12.0, '973f87b89ffe19b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74e81315-c2b3-4ed2-a6e2-f4e0922d47a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 42).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 42).', '{}', 'Networking Fundamentals', 14.0, '3ab38f21ccabc31c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35ef5705-ea80-4ff3-bbc8-9c05c069678b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 42).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '468eed9f169266cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bff6df46-9f32-49be-8337-848f9bf07962', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 42).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ef44fb16e8fce488_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f28f3cc3-8d96-423f-b0b4-58652050a429', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 42).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '84e7e52e10c5e74a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('376305e3-fe77-4b80-851d-eb7c26a640ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 42).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '84800024b5a56647_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92a334df-b491-4d99-86b1-1eff315887d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 42).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '96c62279c7e8c915_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('429b8bcb-500e-40c3-ba94-9203c5edc547', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 42).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '49863006ec1b08a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82457f21-913a-4a4c-a79f-7d3623bab033', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 42).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '28b3c7c2ff96ee0e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10f202dd-ece5-412b-873a-268643eda3ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 42).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8a60332d245d6a4c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bebcc0d-0a03-4687-bea4-a601522bfadb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 42).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'deb6d157d82cdbd9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcb5a1dd-a35d-4bb3-9fdc-e2a94a3ce84a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 42).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '12a138d0e4001f50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bdc4aef-27d9-4515-ae70-6adb26338681', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 42).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd645de61f2662785_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ada333d1-5a7d-4115-b903-84f999f88a26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 42).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f1a07797c3a22b98_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35c51aeb-85a5-4695-a2ae-8d6fb74f0b54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 42).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '83f7bc1d195d6df9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05f4e06d-d0cf-4485-8882-1448d48f1255', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 42).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3b9d60b4ea936bcc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('396aea2b-42c3-4c86-a225-7ee52b9f4c98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 42).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '27a292e6feeb5cd7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9410ec8-c9da-488e-b775-016f681ae25b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 42).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e902da8242217bdf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8bc32ac-d392-4407-b555-a82c17ef4f14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 42).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '72743b05d5f3e7f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed5e1eda-37e3-49be-86fd-cf5cc9537d5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 42).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '115de8aa9d5a4ac5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb408ca1-2ca0-430a-9277-6bf52b9ce33d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 42).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f06db8b769b0c263_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1037b421-c95c-41db-b9ca-306ab5e150c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 42).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b22e676dfd11f6ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80181c8d-7106-4ad9-8cd9-a2231bc15934', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 42).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1e76860bf8637c01_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f440242-a53c-489c-a583-1b909b636681', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 42).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4332cabd13b564a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6866017b-9288-414e-ae4b-1699b2b52ead', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 42).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '61e2c08f253635d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4663f5d-c50e-4952-818e-60bf22d17d0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 42).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '097f13c11421a0bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3f32510-31a5-4f0d-b886-3d0a098ecac4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 42).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd7ecc26f13f7998f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9db26216-d96c-4f9b-9860-d5e400d340ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 43).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd584a145434eab17_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4049de05-2fa7-4332-b2da-acd56087f00f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 43).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 43).', '{}', 'Networking Fundamentals', 14.0, 'eaeb6a4160b4d9b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('406deee4-fc94-4ea0-a8de-b4380672ef76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 43).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 43).', '{}', 'Networking Fundamentals', 14.0, '80cb5931694c0b18_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00e3a8ae-0ffd-4af5-a4f1-3bca3d402050', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 43).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 43).', '{}', 'Networking Fundamentals', 12.0, '5b7c5e9fe8016488_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a188605d-8c76-4b9d-9512-09ebd0c863a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 43).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 43).', '{}', 'Networking Fundamentals', 14.0, 'a6fb62c6052a1ad5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69a72b0d-4eec-413a-ae99-306b69663b24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 43).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '05952095c8d3a728_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50a68d7f-4429-4018-9d25-da1b5ab321d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 43).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2fe84dfd47e089ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fc7a726-1d6f-4985-809a-117810531e03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 43).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c8e955aa92b962a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e21ee80-b3af-4c55-ac6b-d1f49ba4648b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 43).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '81a97b4f3413705a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('137f1f53-88d1-4103-99e5-ec5b1770091c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 43).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'db7b6ee350dfdce1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee23e82c-149d-498f-9a00-7547e55a0185', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 43).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '926474b54cd77ada_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a02fee7-a9ef-499b-b38d-c50bccaa65a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 43).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '53879cedabe95f3c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de017aec-e357-4731-8cd3-fe014e5a4a83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 43).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9098b4f3a2156b10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8266e41d-94ec-4a21-bf55-2d9c564fbd93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 43).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '66d8bf8e32602e2a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5daae73-8dfb-435e-a7d6-974d0b11f258', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 43).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cee46b31491f6640_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d2010d3-a012-4548-bca1-e101e09b306f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 43).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fbca4eb3e25f24c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('329bb357-b46c-470e-8dfd-4fd5f6d1367c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 43).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '54ca69b9c42aa6c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7ea62bc-bae9-48af-b0c1-6a0a7a8cb9ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 43).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '87de126eab8af2a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05b0ef08-50fa-4650-b6b9-5906bb3cdaf6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 43).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1b84d89ada7aa99f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e24914df-173e-4802-9d8a-3e22d8f0d6ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 43).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '674793cc61c6e38f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ee376eb-2114-4223-ad98-b23f6767df9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 43).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '33037bf15fe15971_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('076d8638-1b27-4bac-97ab-37628f7e2277', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 43).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '67edc92567ea73d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52c70a0f-3ce6-47fc-8ace-4cd73a852065', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 43).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '51a619343209f65e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b31df3cd-5d5b-464f-ae8c-c354eecc786a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 43).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e64219e00f115b98_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca40af91-bb64-4fec-8d54-2054722268a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 43).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0a8ad46ea72a83b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46afd86f-51bf-4226-91a4-b41736d71c45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 43).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '72aaa9a7420b9786_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4a38e42-2225-490d-a339-244ae92810f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 43).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '551da5cfc8d8460a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e247b702-f32d-4f40-b0b1-7ceeb2213854', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 43).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f5a3e065b7023c79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef5922a5-f73f-4d0c-9a90-cf754662fc6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 43).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9c4bd9861352cc4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b51c9bbe-8207-4c69-b17b-8834a0015f26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 43).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 43).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b20fe8ee44933125_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99197720-bc32-4afa-b8d3-e5103360be83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 44).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3aa6430e44b5d0f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('521d50b6-113f-4f0c-bf9f-399017045bf0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 44).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 44).', '{}', 'Networking Fundamentals', 14.0, 'd417a172585ccfeb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c68cffd-4bbd-4bda-bf2d-4d5dddbb7244', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 44).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 44).', '{}', 'Networking Fundamentals', 14.0, '3a559223702db640_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee42107d-433b-4709-8e1e-e3f318bec87e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 44).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 44).', '{}', 'Networking Fundamentals', 12.0, '9c453bca56682d15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7ae70dc-12e2-4593-81cf-dce6e7bb6ee1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 44).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 44).', '{}', 'Networking Fundamentals', 14.0, '46e226ffbdf27d2f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a64525c-491d-4ff3-9c12-66781c004f04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 44).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '80e827d611fdd7d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0361171-e669-447d-873a-b3df390fc919', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 44).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9b1fd5e6179b99a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ead77ce-956a-4c6e-9224-24a4837e0740', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 44).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e2177aad09302900_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60721277-4ce6-4a84-a583-bef75698491e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 44).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '36a94ffd0612ea5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80e82ef3-9934-44c9-9461-47774d311103', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 44).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '1aa9510ebb4cb725_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f09c1e99-74be-421b-9c5d-6dd8b9539c55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 44).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0d436f2b8a8765a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7fb3b40-d7e2-4808-8405-e7a8a0d4ad54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 44).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '95c685dde3d5b862_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aca17457-bbdb-4518-925f-13de6d763fa1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 44).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'bd12f9a3a45f3693_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1da92a2f-cf9f-44b7-bf35-cd6e20aa305b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 44).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '45f64b7a60664708_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72c7add2-a5e1-4530-bccf-8f224de2c08f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 44).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f55a39639bd91df4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e98ee7e0-e8e2-4a14-9a59-9dbca8f71929', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 44).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6cab0baf1360fe2b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8014431-fd9c-4616-abcb-b62c9fb5c35f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 44).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ecfc84e60ecee4ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fdb0557-bc9a-4e11-a70e-bc3998e0faf6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 44).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f914a53b9d0308b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a17a0b15-e217-4f1b-b0e9-3624fda73f54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 44).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '663581e8f6827fab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db198e63-72b4-410e-983a-d32fadc83f62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 44).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8942a6da17a0b7cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('809d7a3a-7c44-47c4-a07b-519978b5c818', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 44).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ba6f94564fb5d11e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1426932d-0a20-4abc-ba33-fd3452daa229', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 44).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8457bbc3e63efd3e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('091e7fd5-b7d7-4680-9262-08f37a74c54d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 44).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '952fdc59e51e74a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19f62439-e2f8-4613-8969-16530d0f1aa5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 44).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '02f2cf16feec5b08_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c857dba9-bdc3-449a-a5d4-4fe4f391f615', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 44).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ee758721b9c61f42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd536e30-98f9-4cf8-9ab9-04be7369afd7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 44).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4b43562438db269a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea7bc3c2-2b38-48cb-977b-080c69e48b5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 44).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'baf086b4a75d2659_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('443eb44b-cf4b-4dca-8465-ab5a4b5abbf1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 44).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e21eeb085807abd7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ed0751d-4b7d-4514-b1c9-3e173adb8c0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 44).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '201a7f5de1ea7af5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17e7b842-90e7-4e2a-8115-8b6cb459ced9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 44).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 44).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '01cbf08cf5b9951f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a62356a1-5c0c-4925-9125-cc478a5e4d83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 45).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8d3d755cedcfb3c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e8a0f5a-ed8a-4e38-8b24-176739f28242', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 45).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 45).', '{}', 'Networking Fundamentals', 14.0, '367f417d3289488b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f3644f7-6560-4b3b-8c86-fdbec1734642', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 45).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 45).', '{}', 'Networking Fundamentals', 14.0, 'bd076e45f42fbe1d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f7c2a9c-d57e-4bd8-bfe1-6871c166101c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 45).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 45).', '{}', 'Networking Fundamentals', 12.0, '56fc5de41abda53e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82ab7c37-da7a-494a-92aa-a989b7bd7345', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 45).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 45).', '{}', 'Networking Fundamentals', 14.0, 'aa94dcc6ea53ad56_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('474ce705-8234-4614-aedd-5655e1605aaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 45).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'c71a20b2df5cece8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3863ba3b-8140-403c-b146-d272d2005c1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 45).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c039687e158eee7f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c100ddf8-7f95-4ae5-9737-19cd66519b9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 45).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8b78992cc1b8e2b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8491707a-f6aa-44f7-b6d3-ed83bbef4117', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 45).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '71474e4e29d01e76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61690733-7d95-4894-9f43-a9925356f0e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 45).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '5c4ab5793d16c6a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76ed37b5-cba4-48cc-b696-dc2a629f9947', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 45).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4eca4fe0bf7d5e45_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e93cd8c-e897-435f-9820-a9ecf1369164', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 45).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1332467e15676f88_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4bed905-f7e6-4051-81fd-f8ace75d79cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 45).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a2ed2a6325bcea51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dd762ff-7495-4f15-82e3-f48b2c674be4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 45).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2c53bbd53cd60b7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e64cc11c-7f94-4dd4-963a-8a5a9b1f42ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 45).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1a6e3ac89c37d268_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16f521de-3a9f-45c5-92ff-bb84e08a90d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 45).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bde100cb7f17eb7c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('081c17cc-4580-4185-aa98-9d9256205865', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 45).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1e3d02cefbbe279c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('161a9dce-5d5c-40b3-abab-f002bbd68ba3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 45).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '2f3b1278c8a6f542_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e7edc94-8070-448c-a7d2-74b7cec1aeb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 45).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a9930d86fae4be97_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('951efd61-4101-41d9-903d-201647229dbe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 45).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd86a10b33c8e9390_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddf27296-95db-41de-8522-bccc5958295b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 45).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2176466df37c58f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65d605db-7603-4aa5-a15e-7a354b80ff4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 45).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd5b67c4b3aa195eb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10ddeee6-8888-4ed1-bc62-712cb79b1be9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 45).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '443c2f5f99975cd1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71344780-bd71-49c9-a027-3c1d1546de07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 45).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c799e8b0a7898941_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2e286eb-8beb-4295-95bf-e32dd08404ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 45).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '22e7a75be798549f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae22d49b-65f1-4466-aee7-2c69bd350749', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 45).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '66c6c54eb8121664_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef2dfafa-d3dc-47ff-9b64-00504103b056', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 45).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '54483bded966c751_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a6f677e-0b4e-4ccc-a56a-819e847628fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 45).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a905f7933a45b178_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fb6d732-c6ea-40fe-a8ac-773cfd33072d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 45).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9c2acfadcc818ce3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('380e4ed4-4f91-4e14-a88b-e9e28ad6c585', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 45).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7160c6d292be373b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('373b2bb4-d019-40bc-aaaa-19ecdfea0655', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 46).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a0ed541d183b5a1e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb4cf550-3359-46cc-b948-17bbe520a32d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 46).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 46).', '{}', 'Networking Fundamentals', 14.0, '6669829b2a8218e9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c00af80-9fe2-4d9a-8efd-5c230513825c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 46).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 46).', '{}', 'Networking Fundamentals', 14.0, '11cf9fdea0ede261_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f573b263-ff22-4321-9d97-8c5b2719a8e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 46).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 46).', '{}', 'Networking Fundamentals', 12.0, 'bc5211801ce1e858_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cf425b0-2f7a-4fda-b121-299978be4887', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 46).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 46).', '{}', 'Networking Fundamentals', 14.0, '118b9c2fef96ddab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('450c0148-4c9d-495b-8493-d7e91311a5a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 46).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '849d051f348a12ac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03260af8-e27d-45dc-a170-ad99f704fa97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 46).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b70a73b4ad24cb3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04d667d0-9dd0-4420-854d-5b88137b469b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 46).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3b7fe05de660efcd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee5c2f25-8879-4a40-aa0a-7a9db5dc2568', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 46).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '70c3110652c5ae24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfa69852-ed8d-4c2a-886f-96d4f6e76b8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 46).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ec0dc8ecf807b634_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27e34455-19a4-47fe-bee2-9ae924e597c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 46).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '06dd58ad06f89871_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6400713-58e8-4112-aef8-12f68fe52399', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 46).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '240808c9335c4dab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af3edb26-5262-4b4d-a24e-e154e7aa11a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 46).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6a2f06c519bac6da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33353e49-ae28-4dec-a234-6e2f407c372a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 46).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b5e0086a8349a0fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cb4aaf6-d26a-4362-bed2-8c36ccefcb34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 46).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fa4b838fd2c7592d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de47b551-4d18-40fb-a320-5f5da1f63794', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 46).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1c7a6e60117266f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7117a41-0ed8-41ca-bc4b-d8d3dcfc3f6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 46).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cf7bdeb07f117736_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcfabd9e-944c-424b-abd8-52f0df0fc177', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 46).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c3ec1cc91f4f5de6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1151911-b581-464b-87ad-235321ae2a64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 46).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'bbb6aa7d0e4392f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85f245a1-fafd-45f2-aaf2-b1d693840002', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 46).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'be5b5c4685f509c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('889f9809-6099-4465-99f8-e62436166d53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 46).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '042d3c1e2320c44d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd05d551-6ead-492e-b914-1cfbf21e48a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 46).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5ecc4f009a9d4b68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90268982-c5b5-4490-8b64-9bcfd9abc1fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 46).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'eaec3b27e137359a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dde79c84-68f5-44b6-8e98-527ff99a93a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 46).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '8aee353b9d9d09b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2085a068-7a96-4c8e-b34f-545cf8c708bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 46).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1cfe1603805cec70_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7851a90-cebf-49a3-a83b-d6c38c6c6e32', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 46).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c02487f57761101b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5593307b-b33b-4509-8b03-6c7aa2a2c4f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 46).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '793892bea96071b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba4f074b-9004-4b76-9f9a-cc62a1a1661c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 46).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b15c1b5f0aec6efd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5454273c-88bd-4418-ac48-4c9ef621c83c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 46).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '90281ae1c766a18a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdad35a6-18cd-434b-800c-f218e0da7918', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 46).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'cbdc01b60a5dd999_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a6843a4-5160-4f8f-b1f5-88bdb2a2fc88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 47).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '262a749059a4dfac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adad107b-0cf5-41e7-9fdd-d56fae51d7e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 47).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 47).', '{}', 'Networking Fundamentals', 14.0, 'cd9239f557dacc53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68a08564-d166-4e58-b4b5-28618deeab4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 47).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 47).', '{}', 'Networking Fundamentals', 14.0, '03fa504a31a4d4a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8de35599-9cc5-48af-960c-c26b52be5a82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 47).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 47).', '{}', 'Networking Fundamentals', 12.0, 'bde085b21e69aa67_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20c28f92-9809-440d-8628-268e3b78aff5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 47).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 47).', '{}', 'Networking Fundamentals', 14.0, '7c2591e8e4dd53c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35c67e45-d605-461a-8b11-811aeba3356f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 47).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '138a1a45a3aab74b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95844d5a-ff4d-44c1-9dbc-1518b9d4b857', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 47).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ba0d70c15b8033da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20a62cf5-04a1-46b0-b793-8ad53ed7c296', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 47).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ec1b8385b704fd46_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9632372-22d4-42de-910f-e080a0b4289e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 47).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3733365ae78c0115_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('948613f7-1ac6-4d36-a256-07ea92529f04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 47).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '9f3a02c4db655788_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b66fbe6-328f-43ca-be6b-493f08da60b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 47).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '71db33df257f65af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b9386ac-f2e5-4de5-8723-84092c1f5b83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 47).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9906a91caa710ea2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b7449e1-4e75-44f4-ae97-f8f586eacb7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 47).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '19facfa90df1738e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18f8c9e6-28e2-40e0-9ced-a73ce5552996', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 47).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2bae8de9d4fbf31e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61f6dc45-941d-45eb-9be0-6eb7899e24b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 47).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '93280eee52ec814d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e532148-6777-4f1f-a563-b1676cffe750', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 47).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '20df2a9e9f76e5f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b3c7fc9-0805-4af2-a931-f88967203d7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 47).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '17d55e956ab0a391_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f759765-73e2-4aac-a13c-0331e2398fb5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 47).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f9ba92c3554621da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1906528-dd45-4265-9543-e75c3cba1bdc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 47).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a1e2d41efc75e716_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a9cc1c0-08a0-460b-9a06-c18837aede2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 47).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '59dbd5f021bcc7aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68aced10-58c4-422f-9d6c-6faa10c9a054', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 47).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b21b503eded5b59d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bc391c9-2049-425d-b21a-b7de10e62d16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 47).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '062ec6797cca8d23_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9079576-6f65-484e-81be-fa212ab9ca64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 47).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e5aeb541f2aeb4f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10effb12-149a-453a-9dd0-37feda0825ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 47).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '277deafab7c087be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d46285bf-db7e-4cf7-87f5-89addfdc81d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 47).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '42a876f4dee3cd1c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e909767b-6a3b-470b-ae3a-a4b0653c7726', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 47).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f48b32ac4a8aed41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd3d53e9-238d-4099-8ce5-b9dcb56f8d7e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 47).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'b31d1e1cfb68224b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cfdb5d1-9013-4b32-a8bb-40bc5e5effe3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 47).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '7bd3bbf2ba43df6e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('805f6892-46a2-4dbd-a8ac-a06f69440f54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 47).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2341571e2c760b09_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1230df4f-8d72-4a20-9b97-376efe27e1b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 47).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1dd9bbf8e68a8460_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2da88ee5-41db-4dd3-a72d-6f0c02c008e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 48).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ddcdb5b75e7b7d34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc305d57-30c9-440e-9ccd-411b11eec385', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 48).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 48).', '{}', 'Networking Fundamentals', 14.0, '1f8c9b1ac26a580b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bc81502-ad90-4e34-84bc-6d1019497554', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 48).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 48).', '{}', 'Networking Fundamentals', 14.0, '48fbbbd29290d2cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6ee33cc-cfe0-4148-8ab4-f003546391b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 48).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 48).', '{}', 'Networking Fundamentals', 12.0, 'b74a9e2b27baa127_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('369dde4e-b084-4955-863c-659c11a5e669', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 48).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 48).', '{}', 'Networking Fundamentals', 14.0, 'e5e8948e2033a5f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd26d472-47e7-400f-9984-6eaca1d883ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 48).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ce136269a6aec564_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aac5312-e5d0-4e45-8073-9f18256c85f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 48).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5e0ec70f8417921a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e282a23-3952-4c18-b701-4c103f3a7ffb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 48).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9cf2037155fe2922_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a8d200c-4c00-40c1-baee-2036996bf8d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 48).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0c3d57a69b309597_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6db5419-e751-4643-aecd-fef4d015c892', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 48).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '05972813317c43c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06bb8e49-5785-447b-9e23-a397b9bcd869', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 48).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c4ec0f54b3225015_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3b7b2cb-12ee-4806-8858-13836de956f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 48).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fb76278d932dde2d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8667b8a-c4c4-44d7-9141-001943e0e5e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 48).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1a26b9442feefb12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65d450c3-5736-4e80-b81f-99510dcb549e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 48).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '90c8b2385e330833_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5ca41c9-140a-4081-aab4-f9e9700b5940', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 48).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5dd683e0bed98cfd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9b482c6-4041-4ae3-803e-71487745ecef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 48).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9d07f4f8edb2fadf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('622aa242-2ab0-440f-91a7-ac1dace743fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 48).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'dc18b8a91073d58f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a09ab761-90a3-4b56-ac32-dad4b8a35ef3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 48).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'cb48ccc9c7ca9c8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b2f8edc-2004-4f0a-90c4-dc8d734d0ace', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 48).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a9d7922a2c4465e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c98da60-2e21-424b-92bf-97dfcb7b2449', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 48).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1d1a5df1c0e92d4b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5be602f-193d-4608-82e4-5eb1211f0723', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 48).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1c3b5b1755729a75_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c600a56a-4d07-48ce-911b-31639bbe3254', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 48).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '62f627ea33bcb42c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b22016b1-bd1f-4579-a5e4-15bb992a41b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 48).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0d5c46c78b2f8c1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e02d57b4-de2f-4b3f-bc5d-eac887e7a892', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 48).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '492aed5be20c7829_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6901bfc5-1842-43c6-8f82-a8088f0204cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 48).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f51eb6d51e76eff9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ade5703f-06dd-4482-93d3-53c2fc473d77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 48).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '40bfa4ae64fb578e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d87eb90f-203e-4582-bfe3-3e7b60fe04d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 48).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8df7501683024f7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8a4407f-c86c-4b5e-b34f-4bd9f28e9fe2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 48).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8f5b3d9c0986b6ff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ebcc6c9-9b83-4e41-b6e1-4667f4f3f02c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 48).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8d8909beba2d34ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('647d0f89-1745-4e3a-960b-dce9825142d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 48).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 48).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ecd722ed4dca5426_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5186734-acd1-4059-b27a-7399199c0dd2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 49).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '21998a91899307c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c893884-0ea8-49d5-b74b-c6fdede3eaad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 49).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 49).', '{}', 'Networking Fundamentals', 14.0, '172bbd997418c7a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e822433-dc19-414e-b420-ded700c8cd79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 49).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 49).', '{}', 'Networking Fundamentals', 14.0, '85da1a3161d3e325_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d170034e-ccbd-4529-911a-a82b382ce717', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 49).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 49).', '{}', 'Networking Fundamentals', 12.0, '20da100055d89398_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3acbfe21-822e-4126-90c8-54fbdd08f610', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 49).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 49).', '{}', 'Networking Fundamentals', 14.0, '0b1a37dc5e15c3cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2eafa7e-30cb-40e5-bbac-d6b2824db4a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 49).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '98b12ce54f90c166_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d037e3cc-a7c6-4734-9575-618be081e740', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 49).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c7bbe18796998efb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f52a088-2976-458f-8b76-d4804c2ac60d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 49).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '31c2722b61c1b27a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5869c4f5-32cd-48c3-883d-7435ef4650fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 49).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6752e8e7ed4548f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9838231b-a2aa-49b2-a015-7ecc8abe0d54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 49).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c3f963e8f09a1a2d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fec82d4f-fe61-494a-9e1e-9c3ebb59e1f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 49).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8be2ad51a6fb6aa0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9d34d16-68c8-4c71-822c-f6998a5212e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 49).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c4bf91d7fd066d06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d9f5823-0ba7-43dd-b4d3-d886d277873a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 49).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dbc5600520f5c13b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d059ea01-7970-45e3-9377-b63ea15d3f8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 49).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6aac90e8ccc6ae34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('367d54d7-76a3-4aaf-9263-c2b03094fbe9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 49).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '42077a69c06209b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('509bb986-7a70-497e-bf76-a790f27d36c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 49).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a5a227320831fb6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bc66a5b-bbc5-47b3-97e9-5ed54992b6ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 49).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ba2e0c3b05396b7b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7162f6da-5429-4830-bb45-60175619d53f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 49).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'cc4a7702f045b659_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddb8b5f8-b3f1-4f5a-880a-9b50d271dad1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 49).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '36fca0df7e842e93_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8aca820-aa2b-489b-bdbf-ce1752cd3d40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 49).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '83bdc581bc6a496b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fd17bba-069d-4864-a853-6ff8b1a1ffeb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 49).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd63bcbef910530c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11904552-234f-4492-86cb-73e12525ea93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 49).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '224af180ee4495a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34facbff-ea63-409b-94be-501e9cf5c72f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 49).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4e0b74efdb1b39bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f608b4fc-a353-42cc-ba4d-f8dd9dac8fd0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 49).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'baed5f4f0cba792d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf65cc4c-8c66-46f7-9ba7-8cef607aae96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 49).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '493cec45d73fe4a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76f4e393-5ce8-4411-b1c4-d44f5f4e135d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 49).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a921dec37023efee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00a33e25-2186-4538-bf7d-fac9babb9e52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 49).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '536b355026267ea1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ccbbebb-a86e-4f79-84ba-7e9c1b44a653', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 49).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd5a18c6ae4647ba2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4e39936-250b-4267-8f06-837b0c9f3ce6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 49).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f9941b35ca071493_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c587f525-8b70-44a7-9855-4444ed5af1c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 49).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 49).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4b941c74c6e3d277_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b143d45-fdfc-4b84-9a87-8f681bdc78c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 50).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b15564bdcaec34f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f16c3633-51ac-4d0d-a804-bdc6493f4283', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 50).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 50).', '{}', 'Networking Fundamentals', 14.0, '21a05dc20c44dc76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b83a79c5-434a-48cf-a117-fa7201f3286e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 50).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 50).', '{}', 'Networking Fundamentals', 14.0, 'f5ecb0aaba85a8e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4db2adfb-87ed-41cc-9a52-942162c27faa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 50).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 50).', '{}', 'Networking Fundamentals', 12.0, 'ca6cd89ab7d36185_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('374f6103-9d93-4f43-a51e-b90facfbc867', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 50).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 50).', '{}', 'Networking Fundamentals', 14.0, 'd59b70b485637729_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ee4e52f-7cec-4538-850d-2e3110176650', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 50).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e3ea5f91243d5976_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbf8042b-4713-466f-ab3e-07c6746d8e83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 50).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ee832aa663e2ac54_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e09c1979-4339-4480-8f9c-b6f8875d640b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 50).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '67b0a37f7e11709a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cbf9cf8-e50e-4ddb-9ee6-9918bd94f3a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 50).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e88b0050a1498970_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3e6e39a-5bd0-4ea8-a53b-64a7d964173a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 50).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e189f5eb48f3c3ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86c90bce-d3dc-4087-91cc-fd4b889cb655', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 50).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7594e70d91ba6e5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('247ed3f2-696d-4534-834a-45c3493479d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 50).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '896636dc27aa215a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2c8bd77-a037-41f0-8a2b-afb268dfff98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 50).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '42d793c72656b926_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92d713a9-fe9a-4f19-a803-30beeadc342d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 50).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '897be1a84f6f97cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe2cc4dd-4e00-4a00-9f0e-e44e9b0c3526', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 50).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c472c0504fb65bb1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ce8e9f8-8768-4c5a-901a-aac96803e2b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 50).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7dbd48fd8a79abe0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd452103-a0e8-4613-8189-206d1aa4bd37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 50).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b49c5c7c6c3affd1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71f2936d-331a-4309-b6d0-5175e434b33a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 50).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '15874615b890976b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41908eeb-778b-4b12-bfa5-eaaa5668364f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 50).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9a086afe5d6e876b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3d11470-e1d5-40de-9c99-5776c672cc2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 50).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3e0de612c5df77d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('158b1392-5d8d-4d8f-85d4-3ffe42ab0ee4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 50).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '46bbe24d0020b49b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82d854e6-ce84-4c56-bb09-3b12d014ef62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 50).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '15448f32425ff942_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('661b15aa-cfab-4c46-a728-9ece3dbb7cc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 50).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '33e52969aa356339_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('667fc661-f03a-4a6c-8c3d-56c2ed61c57a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 50).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '2dcb208f80f2c2c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a26082b-eb71-486e-9980-817e0d5ed781', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 50).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '647f4521d6db5a37_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('818f5176-1469-48a0-907d-d89257738343', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 50).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0e33fb7fa96cddc0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddd53f3f-ac1e-46ec-8f2c-0f779027e2ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 50).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a5df33f0d6fae2fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03322aaa-d382-4004-8a84-74f1a73ebe95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 50).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '602b83b38f327763_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('462d1a9d-9ed5-48c7-b90f-f167943527c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 50).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'cb82aa3bd9484872_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('151f39c7-5e25-4a6e-b6b3-a4751fbb01e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 50).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 50).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a39d2f4c9d01ced0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('807fa967-fc76-4580-b2b6-7c97c1e63395', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 51).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ec3de4cb30a4608c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dd84254-9635-4617-812f-33cd3b45f180', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 51).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 51).', '{}', 'Networking Fundamentals', 14.0, '3111055f909b4389_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c91851ff-ba73-42f0-8f16-2df63a8cde49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 51).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 51).', '{}', 'Networking Fundamentals', 14.0, '96c3e2672dbe012b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('376e8c0b-a1c0-49fa-876b-c69b2b6f9972', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 51).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 51).', '{}', 'Networking Fundamentals', 12.0, '0694730e6694246f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d10a59e-ffa5-4c17-8eeb-26f0608bfeb6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 51).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 51).', '{}', 'Networking Fundamentals', 14.0, 'aa5a2198047c2c8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28943dc2-4492-47cc-96a2-f02eff27cbb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 51).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '0c0d077e84f66cd9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ebef796-d970-4c5e-beb6-0b8e0dd28758', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 51).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '58d9f6d0a9520d67_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ca170f4-1a04-4351-948b-a1a974971897', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 51).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '479d09679ace9bc1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40ac2afe-13fe-49f4-ad40-b3d5240851af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 51).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9344d55a6c483ca7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2647e7f2-7165-4156-a770-3dce0a3f50e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 51).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '4bdc0214c4458cb2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33107d10-11b5-4696-985f-18a8d5161945', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 51).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0b0be08b3c13cbf3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a293e675-896f-4bc2-9d0e-0276831cefa8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 51).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'eae44935923d2f9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0acb8c60-e731-406e-98e7-f438eee49ef7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 51).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8a612db0a5a3f03c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0096b319-ba65-450e-a84c-0b8ac9fb96dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 51).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '63f4e8664d6aa472_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2352221c-5bb0-4a67-880a-e06082bbab13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 51).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '494029e2a2a33b44_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('476aaf84-1541-4d49-97f7-dca2cd9926b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 51).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6119be775b1eb1f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b7ca415-4197-4bfa-aa3a-fd38144eb5b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 51).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ab59b76787ebe223_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d899bc3d-a0b9-4003-a4fb-2278f747e3c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 51).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'd2b58a0f63bc9886_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f816834-6d03-4111-8092-d5decf8f32fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 51).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '10ee920f5e7b8797_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f0c23a1-de85-4307-a0da-16e5a1c8ea46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 51).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6cab894e1fbf57dd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa68f2d9-5510-477c-9724-14b3bf29aac7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 51).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '78f2c846aa5a95e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61797f25-a304-498d-bd99-8dfd2d75edad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 51).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fdc0ff05af7142af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee94d0ae-5d4d-4cb8-80a7-487afb4666f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 51).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '677ecdf789734f02_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('640b4793-916b-4e0f-8be1-ae9d6b29f0b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 51).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '06bea4ace91769cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c24137ab-25bc-43a2-a629-ae3caa1a2fa3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 51).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '93bd80ca1b554ab3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('063ba930-f8d0-4bbb-8cbc-f8f4593db676', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 51).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2320e166911254c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9754045a-656d-469f-ba6a-221a9eb7dcf1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 51).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5b69bcc4e1cc4fbe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c26e19c3-5df1-4941-b918-eecd0935f617', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 51).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '65840201a19f6611_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcad8266-89d4-4ffe-ba1a-f709fef6b3e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 51).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '510c7b2256681112_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a05aa5a0-71fd-4503-9d31-cd39959b83dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 51).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 51).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '70aa5e999d08aa76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30d479cd-f7a6-4b1f-8e11-d13bb28df094', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 52).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'bfc5a69f9b247f8e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16042dea-8445-4b7c-affe-8d78c964ffd0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 52).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 52).', '{}', 'Networking Fundamentals', 14.0, '5f25225ee4c94108_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b035ba0c-f7f8-4d3c-bc41-5c8d9a0a38d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 52).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 52).', '{}', 'Networking Fundamentals', 14.0, '679f44739c26f606_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aebdc572-54af-473e-859f-3bb073c83cfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 52).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 52).', '{}', 'Networking Fundamentals', 12.0, '2719b8a36d2570ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32062b96-1b79-45e2-900d-227330ab249d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 52).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 52).', '{}', 'Networking Fundamentals', 14.0, '9c66c2d6a767ce3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1daab0bc-4d56-4957-8e59-9361d8223809', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 52).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'bf21bff64a587010_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('541b8269-79bc-43d1-a2ec-4c264a2377da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 52).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd01612665b3a5a6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c01e74cb-3189-440d-a9a0-75aeb8c2dacc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 52).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0da1320dfe10bfaa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ebb7fd0-e399-4cec-84dd-7f98d90c8be8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 52).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3a9d3f91bd3860a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd246529-50f9-404b-ac69-1e42bee94498', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 52).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '710d9bab0acf26d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2af20ccd-fd99-41a9-b2c6-1566729df89c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 52).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cc7989f99e73d8f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d92f95b-d5f7-4c98-b457-88d33265aee6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 52).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0db5e31daedd98ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09cffc60-0002-404f-85ad-577b6302f60f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 52).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fbb448197718625f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7d01f47-0a97-4470-b5f1-de85c0305339', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 52).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ff8e94874d11c3f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('138dae93-0322-4889-bed6-d4ccb10c5821', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 52).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8d709a20823a362d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('903b4f59-8e58-4235-b21e-590f6a11f7ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 52).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '578590677de9ad27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b582913-ec54-4fb2-b281-e9a8171ae47f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 52).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f438a967335f0a92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e026d8c2-ee52-48e1-8224-bae4fc1aa98e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 52).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e659b2a4046de347_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fd170f9-b406-4ccd-b827-6e43c3f6298f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 52).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3baf0e4d30bf7ceb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('681352ea-98d8-4350-9ea0-c27605fe9caa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 52).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2af194b9e4f01f86_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fc14ac9-5159-4ebc-87b6-09aa455827a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 52).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1403c9ba043e8e4a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c91fc42-ba2c-4b51-ae34-f19e0477084c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 52).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c05e40d49abbe2cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3187d6b6-c5b3-47e0-962f-7f59457da085', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 52).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ef98faa0b7a23872_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec55ac6d-cfa3-4721-8475-2e4a9e667feb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 52).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '761dc171da89a50e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f926051-396e-4887-8718-aa535972c1d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 52).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'eb1b102b963137f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfd76e70-d87d-4107-9217-b7e5fb845b1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 52).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b59b16c8916cbcbb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('494f65dc-1d59-496d-8c75-4e841707e2f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 52).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e7ff81b66e4c49a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6e844d2-8b0f-4c92-8cd4-67ef850d5df6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 52).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '2cf2e3ec7abb2d92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7350f06-9a60-4fd2-88f0-debaf9fb0afe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 52).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd88bc9877e61052e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('439598c3-a3e9-4807-bf41-73bfb394c1bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 52).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 52).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a91660953fe2937f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17d00cd0-599d-42ce-8200-e8eb582520ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 53).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a8628dcc8beba06e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d099f655-e1f8-4e1f-8b62-21540a6c49d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 53).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 53).', '{}', 'Networking Fundamentals', 14.0, '7e46ec3adf5404c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90373532-6e76-412d-867a-ec3754d597b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 53).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 53).', '{}', 'Networking Fundamentals', 14.0, '0b1cdc8ad6b8987b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6a9b522-3a2b-41a8-b39a-a2c19b1b68fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 53).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 53).', '{}', 'Networking Fundamentals', 12.0, '4c674cc6d27d19d9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88ba51d3-f2bb-483b-9a00-5e6cdd21f466', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 53).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 53).', '{}', 'Networking Fundamentals', 14.0, 'a66dff674d79eed0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb77ece7-f9fa-4fdb-aa82-43cf4be78dc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 53).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '4c1a3e3aaade3f67_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a584df8c-f1e4-4f6b-80ea-bd7d45d0f190', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 53).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0adf977c26308923_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2cdc3fb-4fbb-422a-9ecf-b9b288ae89fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 53).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '414993463a32b7aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec048068-05b6-4d2c-9232-5cce5db2de51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 53).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6d92bdbe6a879656_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1454593d-4f02-4511-b51a-5245c50d6f22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 53).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b1b08a3a97529139_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fa33184-d3e2-41b5-b9a1-340129192635', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 53).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd6015bfdda267d10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('199c3670-4fb0-4c21-a9a3-a6559264b42b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 53).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e705e7feeb502b14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96337ad5-30d3-49f7-a02e-d995d655a964', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 53).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3f6189f024e6cd30_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5006256-f326-4d12-9d23-761055bcce88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 53).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8a8903a654a2e669_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdf93759-12ae-4da0-8925-43b83e715328', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 53).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f47e650024798681_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('709de066-512b-494a-ae5d-ed9204e8e015', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 53).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '71a1de9f1fa70940_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4880373-e352-4456-ae4a-ddec22db5ac3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 53).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '48dd36679ab19371_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f235e24-8ca5-4ac4-ad26-b3648a97772c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 53).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'dbfe0471bdfecd21_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6f70875-df62-4786-948f-2aab33efb55b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 53).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ba441ba159a73dce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d89eced4-475b-4032-8327-bab387396241', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 53).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ce9efd0500069547_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ddbb4fe-5b61-4490-9421-91fc594abc60', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 53).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b681106aff28a763_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10f98608-df2c-42d3-a5ca-55c583e1091f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 53).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '03878adda1710d1e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('279d26a7-4344-4e06-93d1-f6da6623c8ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 53).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd71c218f540d3afd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('250362cc-bfae-486f-a80f-8e087cef4da2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 53).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'a281cdc4ac62754c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b05a9cc6-31ac-495f-9789-ee4a40170aca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 53).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dc1eaa0756d60774_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3966435-348d-43a4-ad6c-3063eeeb9251', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 53).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f1e388137201725b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3374a7a5-dc1d-46b2-ac82-464a6a423248', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 53).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '09aba5ee24c10e27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d5bc87b-42eb-460c-bd5e-b9e6c780e93c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 53).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'aaf46853dc57ff31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70efdc4b-9d9c-4ef3-9774-b59cac74a458', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 53).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ea9fe24f59ee660b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5544b3b-4641-49a2-91f2-98fcf947c026', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 53).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 53).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b044aa719d5d25aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('087b92d3-6b50-4631-ad6f-e8b3964b7171', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 54).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '486ce78af4077e13_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4376a47e-9ac9-4451-8980-abd00cf10d48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 54).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 54).', '{}', 'Networking Fundamentals', 14.0, '2969c37d300cee49_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aaa9cec5-3d33-42fc-bfd2-3b5ce1d02612', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 54).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 54).', '{}', 'Networking Fundamentals', 14.0, '569640d85224bfcf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29a6070c-b9d8-437b-b3e4-3eabe96e6f5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 54).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 54).', '{}', 'Networking Fundamentals', 12.0, '78da12dbda21a21b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2194d9db-166e-4174-b11c-c719c8a02487', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 54).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 54).', '{}', 'Networking Fundamentals', 14.0, '8c524c24c99841b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9019a531-23a0-4f40-969f-21c1db924888', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 54).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3a2e00b66ee8cedd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d44c03c0-0c51-42dd-a861-6aa41f2561d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 54).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2de9983819840276_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5abf6dfc-512c-4413-b244-15d6bdf2ab1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 54).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd3eaf5320968eafb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eaee3c0-4a8a-4ed5-9f48-41ee0f99e261', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 54).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '34ddb39ee71b9dfa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a746b0c7-9268-4cfc-af86-f6d1d5b43bb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 54).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '2dbbd12d8ac66b4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9199ed34-6418-4ae4-9fbd-e9470a1dd364', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 54).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c94e9fb73cd97062_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d487a8a7-c228-4ebd-8a34-b070ca9490d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 54).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ff759a79cdcc17ac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48a39a90-f7de-4291-9043-1a9569b0755b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 54).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2ec626f1146be99d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68a03f37-8947-4211-a4b5-fc265efb19a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 54).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0cf2e769101c3e07_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34460871-bd9c-4c53-b10f-4ba08e1487a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 54).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2ac394e6ade8c132_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8c260ab-b006-49e5-9683-9caef2a52d65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 54).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2ee61f85d380244c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a9ba71c-9987-41b8-8791-766f218c4790', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 54).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3205aaa767a251a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('683de06f-17ff-42ae-bbb5-f2c2bbde483a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 54).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c3f070768a8517b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e683ced7-e6d1-433d-869b-42b421dbd745', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 54).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '63c0c5b4663543fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3837c07-8a03-4442-b625-0d0ea6c88d5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 54).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6089f1d38fb8ecb8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94f63606-5114-4b8b-8ade-2303afcb865e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 54).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '60b9aa4ebd029c79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acbe8b4c-bc88-4864-a1ce-efe6bf83da3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 54).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '66afb966ee278008_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3d5322f-8f46-4eef-94df-f44c8b682066', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 54).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '17d9e593b793c6bb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0595c7b5-8cfe-4deb-bcdc-5d523632ee4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 54).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '8df5cfeb00e6ea0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('625ef64d-e3a4-49c4-8ed2-05f143c7736e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 54).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bc413ee9e61027d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1413d778-3fda-4306-b634-619b67dd5176', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 54).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3bc9ac50eb6e3741_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aefd42ba-130a-4be4-b4c9-21dc3a3dd862', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 54).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd2fc1f153d34e0a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('997d7996-d21c-4744-bfd4-668acc2c896d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 54).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c26cf6ae66688087_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81f15b5d-ea44-4604-9bad-6fa36b8eb61b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 54).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b9f951ceb3b3f120_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('887f26de-21ad-4c5a-bd29-cacdb009d1c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 54).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 54).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '072de3e46812b028_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('704683b0-55a7-4f6d-8d5d-20803e89d763', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 55).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'e0281049eb492d0b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b108437f-3c92-43e0-81da-1ddb7fee5854', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 55).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 55).', '{}', 'Networking Fundamentals', 14.0, '04dcb7a9c27e1ecd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50ba4a58-312f-42d0-ba5b-dd6e2851a353', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 55).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 55).', '{}', 'Networking Fundamentals', 14.0, 'acaf4a087f6c81ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9db9d25-9de7-4fef-bfe2-eca33d38b47c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 55).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 55).', '{}', 'Networking Fundamentals', 12.0, '04bff4777c4bcdd0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25458441-02f8-44a0-9a0b-2528d240e795', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 55).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 55).', '{}', 'Networking Fundamentals', 14.0, 'ed68ea681954c7d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af39fb25-60b8-45ce-bfce-413deba86ccf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 55).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'c9de2eea7e3ef845_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8815e00-fc5e-4876-9926-f66e53a2e39a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 55).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1042db17c1fd1ef8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08f6c0e4-2461-4bb8-8437-014a66808eeb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 55).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '967832d0c9e8cd76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2ab88ae-ef55-4f3c-9d27-48a74a96a4f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 55).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b3a476cbc8032edc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1d8568f-d2a2-465f-9a5b-8fc42e14fdab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 55).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ca39013606dfc090_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c41f98e9-c24d-4657-b5a0-287211df4a97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 55).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2ea7c13ec2b81e65_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d45f238e-4796-40ec-a061-10f0c3c956f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 55).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '028ae18a84e6b3aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7419aed-ba4b-4138-8615-604e6fef59c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 55).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0ae30f537a0695b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('154b57f2-e433-4069-a95a-dfc17be0f6c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 55).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ca1b078f45874c53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e4a204d-5dfa-41cc-a7e0-27049dcfdcee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 55).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'dbb7362dfbfb1632_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6165dd2-3ea0-44cb-831b-b268f47a3037', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 55).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd2537b2043ad7121_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0965ba52-ee72-49cc-bbdf-6338b96cca9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 55).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '8c3f1b2fede0ddd1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71c53096-846b-422d-b1c8-c97f96accc6d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 55).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '9112a469145be38f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6da5be9e-20cc-4307-927a-8df21e926c65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 55).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0b80e1c221b5cabe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78b7e2e2-c10e-4e16-a029-faeb7a32326c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 55).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7744fa5f2bfe51ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fb61cea-d726-421c-a892-4680decb2b54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 55).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd77a5b5a08094eb8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('534b4714-736e-4130-a8b2-bf2cfac6bc81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 55).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4ee9dbc6fcb78b2e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57ddc2d0-85df-44b4-be9f-c771f36659bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 55).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3da3a7ee9ce7cc49_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5217a0b1-7b5d-4b53-aca6-300df4a945b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 55).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '32e90a068f82026c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b84473c3-08f4-4673-a5c0-8e62a1b7c742', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 55).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '69c15ef9cd592662_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80bbfe9f-70e0-43af-b5d7-e25e911a2486', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 55).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '966c966b536f1e97_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22b8e88a-36ec-4f97-a24a-fcccd53b72e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 55).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '15d74d4449d34d33_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41d469d6-4390-4039-8df5-35310b76f384', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 55).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'cb9649beb32a5721_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4331fd91-c1f2-4645-a545-0221924e8f9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 55).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3ef6ab653d17f191_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f5e2eb0-2c26-4341-bace-ddc846c965fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 55).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c75c9886bc11f71c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66d19808-0923-4018-83a1-a4bd3df4cfa4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 56).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd1d81268b03b5238_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c0ffa20-ccc1-47d9-9882-43939644e152', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 56).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 56).', '{}', 'Networking Fundamentals', 14.0, '23610b538d46b14d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91ee926f-5b2d-4297-bbc5-6bbd6cb4e837', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 56).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 56).', '{}', 'Networking Fundamentals', 14.0, '989409fd13a55a8b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a32c9bce-a9c4-4471-8eaa-ee0c4cb45130', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 56).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 56).', '{}', 'Networking Fundamentals', 12.0, 'fc8698cb36ec8498_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebb254fd-1677-455e-9cc1-fce83ce8b26d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 56).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 56).', '{}', 'Networking Fundamentals', 14.0, '3e7e55424e4ff476_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf31c1ae-7dc1-4f40-a987-1851cc0e1901', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 56).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '78feeaf7d54421d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('104f5c2b-dcf4-44bf-a341-cb9bce20a534', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 56).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '28a409e36e91988d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03b4f791-9c81-4816-b961-fe671f1596a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 56).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c72b3784c6a10500_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04e34b8c-a35f-41a2-ac1d-f7ec2b5d5b40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 56).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f9a84551e882e812_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6827ff4-ca51-4f96-aaac-1506794996e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 56).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'fbba3f3150cbdc41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82654424-8c15-4ac9-abee-a2eb1a0e8b6d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 56).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fb09c137d2f1b8f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1134e16-846d-4e3c-bb07-00a02878a21c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 56).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c8da02e1ac3dcb67_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2646108-b8c9-4867-81ed-3e24a25ec238', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 56).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e24cbcd9ad96c358_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3baeabcb-d144-40b7-8df8-15f327d5027b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 56).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '530ae82ab0902d3f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96704194-5ee8-4e8a-8da9-30e66564ed21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 56).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6a98f99cc94431ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9af23e5c-2e34-4cd1-a7d9-8314ed628bfc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 56).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f665f7c5b2960c24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf7f66d2-0595-477e-b9e5-8ce8d9339d81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 56).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '420f09a676029160_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73a090c9-b7f2-48a7-a0a6-6d696f72a762', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 56).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '5bc8bab3b2e0255e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2df5ea3-0aa4-459b-ab74-e26105b33e26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 56).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '383cfd22fd61ad75_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba634ba3-9a5f-49da-b8de-478992a64700', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 56).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'afabdce866c531b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4023db11-d75a-4fd7-816f-991aedee6e39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 56).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'df7cda7d771e50c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('858fd40c-e9d6-48fc-8f38-d98423177907', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 56).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '44591ff9eccaabfa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('108dbb97-a1e7-46e2-a592-ed50231cfc45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 56).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '33e57ab9eb7ae81e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('524487f9-af8a-4262-8a14-0232cb2eb4ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 56).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'b6fa3cd57b5bd0e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a5d1a90-b711-4e1a-bf8f-9ba03fe8aa5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 56).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6dfb35fc87ae40b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aee6d550-16c6-4492-9b36-b9526aae210d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 56).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b3712eed389c9224_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('117ee25c-afb6-431c-a771-91d4fca74dc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 56).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e82a196bfc4519bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('929c82a5-fd30-4641-96f5-1f637ce84894', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 56).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b886f823a48e7cda_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('824e0d24-c4fb-4dac-a40f-a1b7624198dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 56).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1d78afaa250f0dd7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bdac381-7668-49ea-865a-57229c18de35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 56).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 56).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8ae05f4d66878557_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f74084c6-1195-4c70-8900-861674a4368a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 57).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '36018348c6e9fb0e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb9cc2ea-0700-46c1-8670-22374c5635ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 57).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 57).', '{}', 'Networking Fundamentals', 14.0, 'd4ca1a812136fc5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47ec2e84-bc8f-412f-a4f0-aad371639489', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 57).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 57).', '{}', 'Networking Fundamentals', 14.0, '5da212f89075e8c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('794e5821-e193-4385-8e0b-a3d3093b2e89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 57).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 57).', '{}', 'Networking Fundamentals', 12.0, '747605c2676bb6a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d914fcc1-f561-4abc-ba5b-ae573009fb5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 57).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 57).', '{}', 'Networking Fundamentals', 14.0, '5ffe7b950fbab073_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e133d7a5-bb36-4535-b620-6908d363356f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 57).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'c7c4057423e2cf18_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66fd2893-b515-4555-8578-a1e8477c0afd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 57).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ba3842d8618be581_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4a0feec-b234-4a62-b403-8b99f5e40268', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 57).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a423413873353717_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c403c3df-afde-4262-a94a-7acf5c84c5d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 57).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fe5a3b3f36237da7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2286aea1-ed0b-4cdd-a9ce-3c6eebcbc48f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 57).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'af04e03d914eb933_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1261d9fd-d4be-4248-93be-b455b54f851d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 57).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '601fbf407b0c52a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68a2427e-381a-45f6-ba9d-c5e78c8c1904', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 57).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9696dc84b1dce748_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c5faa20-87a0-4138-be19-6952cc84fc57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 57).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a1e9e46d58833ac0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4df4480-99bd-4501-af06-06eaca8e06a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 57).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1fadc48684825a32_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f13dde6a-c8af-46fd-a0c1-06ce2cef5774', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 57).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd6f24adbbb026267_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6093c7c2-5d48-44a4-9190-ef5ddd7b1649', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 57).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8a1b47eb4251b018_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24b4cd42-945e-44f9-bed1-d323b3fd9a3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 57).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'acb4ddbca63cdfca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16d43942-71f0-45be-8dc2-ff189cf70ce5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 57).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '5164c9a4d33bce38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dec1a69f-2858-4b7a-b964-d8efc3348a06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 57).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '10cbde33beba1fce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d1873c0-d178-4648-a2c3-0dd737ef5b03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 57).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '64d6e5c6e62bc6dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d117b29c-ef8c-415c-8eac-32498b97f4f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 57).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f3c8b02d435fa177_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9982d6c1-71f1-468e-9919-b1dffc689ee0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 57).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b67d192d923590e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('558137d9-7316-49d8-a9ab-cdc93bc21648', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 57).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '74b44b88bebf1011_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bd23b5b-ad46-4ca4-8540-0b6270d23db1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 57).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ba4a2cb558d015e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e15bfe6-be55-4c58-bc98-0c31db47c10d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 57).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b21e4d343567f9af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('532868e2-df86-4f94-b1df-83fc1221d71c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 57).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '56bfaddc13da18b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30017c8f-0ffc-4610-a266-8fcc47e1207a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 57).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'dba9a574c1247041_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7c1a11a-4f37-46dc-871f-7a0bfc48d3e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 57).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '93395410cecbe325_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5c18d78-6ded-4c47-bfdc-0897c5f7cb59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 57).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '97e1d582c153577b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f517d37-e920-42c4-9883-8cab6a79cb18', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 57).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 57).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f1f1fd28dc10b232_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ffbfdc5-b3cb-4a00-a395-2f70b32fa108', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 58).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1f537b6800304ada_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e832422-b97d-4232-916c-70b8b1b918b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 58).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 58).', '{}', 'Networking Fundamentals', 14.0, 'b8eba4192d70676a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07d897f2-9799-408e-9ca6-1e1100a58e93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 58).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 58).', '{}', 'Networking Fundamentals', 14.0, '847c51d3ace7bc43_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d5bd02b-4bb7-4b7e-a95e-80c0d783d2b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 58).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 58).', '{}', 'Networking Fundamentals', 12.0, 'aee7684225cf62fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26b97ecf-7520-4780-9841-a047c79e0bdc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 58).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 58).', '{}', 'Networking Fundamentals', 14.0, 'a42a6ba5bf33850a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a23a097-22a8-48f1-8f1e-047ea8591104', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 58).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd0df1dc592357ec0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2a1354a-8dc9-4211-8097-f0990ccf8fa0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 58).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a06269094c2dc6c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ba1b4c6-e783-406a-9f74-d81b05ec97d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 58).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c24ffaf76d40e233_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ed97212-bd5f-4d2c-a201-75ef0f645b49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 58).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '12c4cd2136150546_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c26fced8-9207-400c-a892-8dcc4999898f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 58).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '9df0ca3eee07bc0e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ecf7428-6903-4837-8684-af1b5bf34db4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 58).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0cc40a76d39031a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('824dea2a-4b65-4ec0-9bab-a2cb50400caa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 58).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4f9d2a455f98b8a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db8cbe74-8a96-462f-ade3-dfde7ba73a50', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 58).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd863a6a1325e46d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9306d8d7-74e8-40da-89d8-5d827f4da52c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 58).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ee8c2209277e5a1a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3d7867e-9cae-4f8a-811c-477df11cc744', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 58).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1a3bf6ec8a809660_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('559b30a5-8169-4b47-a263-9c81281157cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 58).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '68c4241f48ccadcf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f93a4c64-069f-4551-9cf9-677e9859aa55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 58).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e620f24932f98ce7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75b0bff7-c64d-454d-97a7-65452b85085d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 58).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8c469582f2f7e80d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('654e39c4-60da-4f6c-a652-b2841266a02d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 58).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '151e411498832617_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('881d6671-2594-446c-8cf0-f5af4bd7e6e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 58).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '01beed707470bb98_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e36c7e7-c589-4370-b96b-13c614680979', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 58).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5c20e2c8b741d7e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ea3470e-3e14-4f99-a42f-8ad2df041f31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 58).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '708845da91ce47c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79aec07d-ed4a-40c9-a9f6-30fb228f87ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 58).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '997b600306cfbd7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bd5973a-1956-4f23-aa6f-2967dda97a9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 58).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e7bfed596b1f5c5a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98e991f3-733d-4267-9744-e90df20c111f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 58).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f2d20e6c47c45a52_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('836270ac-50f3-4e09-ab5a-0a807ca09b7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 58).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7f87486e93e30ec5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc5c8c18-8e50-4a34-967a-d8c0283188c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 58).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8ed97ff897ad9611_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6f1dfd5-bb41-4bb2-af83-f30c07dd57d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 58).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '955cccc95c8ec3bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2199cd15-bd17-4a2d-a9ef-d284f7fb8556', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 58).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '880c7b76f852dc90_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35b50087-81e3-4eff-b4e2-8fe4e6fd926d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 58).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 58).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8fc8f22a0e24c134_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e210096-0688-4e65-ace8-7de03273addb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 59).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f52e57ff5068e6ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf21657b-e507-4f7a-b414-fa200fea5163', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 59).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 59).', '{}', 'Networking Fundamentals', 14.0, '7318433b67fa3176_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44e18642-d574-4365-ab0e-e6b8ba92a6fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 59).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 59).', '{}', 'Networking Fundamentals', 14.0, '874cbc6c96c30f8b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5625337-f401-4c88-8774-a2cf361d51cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 59).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 59).', '{}', 'Networking Fundamentals', 12.0, '6368fa5fefaf4c25_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0224e622-8eab-4fc5-bea4-93aeee19639d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 59).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 59).', '{}', 'Networking Fundamentals', 14.0, '2908d328f63d356a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('407c6651-d14f-4dd2-b3d1-e80234e90636', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 59).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '24d8859479f46820_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('718b0f0a-67f7-4184-80e2-aaf97e6abf8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 59).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a576951c15dd2c8d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34d61813-a731-4da4-b764-cb563d9ceaf7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 59).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '79e7b397cb1f6393_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8013695c-3585-4d07-9082-d33cbf8062b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 59).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6a663354311e2f71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59b6b3e7-2043-41ed-be13-55724263f7ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 59).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3b74b7d8cd0f555b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8311094-a4c6-4b37-b73a-090c75df6c32', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 59).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '938f5175f42d0fda_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c902b637-b525-4581-a5e3-8ffb93ac6223', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 59).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1f68a749dbc86d18_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba4536d7-4f95-49d4-8bd5-27b33d7e3014', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 59).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '43f12bd85cadc9f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a71f56f2-55c7-4797-bd1b-4c581022b7b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 59).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0bd1c35d25341c28_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b20b2a6c-cfd6-457e-a146-d95d2ecf661a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 59).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '58e6a6e8bf6351b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e435a71-daec-4712-9858-87a76f1e9f63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 59).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a313aead8ebf77e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5661f8d4-5a1e-406a-9a83-e16214dc468c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 59).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '351a440d5046db45_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4d06bf3-b202-4ddd-a910-1169288184c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 59).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'eb5d05965c109916_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83d3dbaa-2ad3-42c5-9ba4-21ffb3febeeb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 59).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'bae8ec529e4c03a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97fec9d7-64e2-4aa4-9d52-7a7d77fc5bf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 59).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1e72e28c11a45f28_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85bb175a-917d-4669-93e4-56462879f2d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 59).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0857657d4a9f4441_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e2cca98-265b-46d7-a61c-6b02308226f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 59).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '44cf06ff1698ecb8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('445c4d15-6a06-4582-a8b2-8645b74793ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 59).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '35ceef1dfbe6b780_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55d630a6-afc0-4d0e-8e91-368e664ca468', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 59).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '20b5554a766344da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10d40140-1d2c-4d75-bf70-0b2b0e27241a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 59).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a477a57a328a3488_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0c43aa9-c4a9-4ada-ac4b-1e225ed5f784', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 59).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8d58522122ee996f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45efe8c5-08f0-4835-9de5-c90ecb267db3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 59).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'bfe33098636e2348_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62c7754e-4a57-4944-8955-40009165b840', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 59).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c3db422197f81071_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fee60e4b-88e6-43aa-b8a2-b472d7a48952', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 59).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e5695205cd171eec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0f7db56-2c1e-48ad-9a20-6fac1c21312b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 59).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 59).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4cac1c073599a994_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9931bcda-782c-4daa-a811-287b7d4f200f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 60).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'e8094be0f83187d9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5921811-686d-48a2-86bc-0e054dad0c3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 60).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 60).', '{}', 'Networking Fundamentals', 14.0, '6a6cd68e206e4f2b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f13cd55-66da-4b3a-812f-62d7e086d50c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 60).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 60).', '{}', 'Networking Fundamentals', 14.0, '44c8692104656313_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a9825ac-944c-4571-b425-e9ee98b9db25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 60).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 60).', '{}', 'Networking Fundamentals', 12.0, '258e19cff851bc3e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05b54a23-2696-49ae-955e-53815a355de5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 60).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 60).', '{}', 'Networking Fundamentals', 14.0, '6a5e3c0c6fbc720c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afaa50db-3664-46bf-b560-9c89b8c5cc4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 60).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'cb9654d2a9964433_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6f32de9-39b1-4a0a-9d94-8ccccbfb8d1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 60).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9bfbefbe298abf8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2cdf1c0-3f2d-4de1-9aab-eea5ddc48e7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 60).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '23bf9fe4c79cb61b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e4ec2a9-43db-4a29-bf5b-f66c79b09bc9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 60).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4b1828678481091f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05dd911f-c368-415d-85f4-64eddd71637a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 60).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '575964461deb2901_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eba64e5-e0b7-4c13-9f8c-bd73d8567e62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 60).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '08ec73ad5c76db10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebf0bceb-1f67-4931-99cc-457709a8a1d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 60).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3d02c9b940c78a5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17251011-49b0-4ef8-8ab8-eba99a7aee6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 60).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'bcbb3b65e91056ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81942e58-2b94-4285-b6bf-4e21596b84ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 60).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cb485f25f902301c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('331454a4-bb94-4069-b600-95b2e100d10e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 60).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2272b3057400a4ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('484e730b-fa26-4e5e-82ca-1c0a47f9daa9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 60).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7a8e389462be3091_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f627b8ac-d1d8-4806-9809-2026ccf0d49c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 60).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd15bab64d3fdeebe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bc03ef0-195c-4ecd-b950-e61efb962dfd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 60).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4fe3e30c221e3cd0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eba1bad7-088a-4578-9a1d-8cf6349e1d77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 60).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5685044f6d8a7276_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b316e043-e475-4980-b5e1-5d29ed679998', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 60).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fbc6473f27b5653d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fcea520-fcb9-4b5f-bfe5-54d4f4b83f0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 60).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5761f7eafe8c23ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e801938-47c3-4385-a64f-35ba5f2bbffb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 60).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '73c872c1028deccf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0322c31-e8e8-481b-83ea-2c1a31fa32ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 60).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'eb6457c10c6685f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb8a1ef8-caeb-430a-9d80-89cbc3457df1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 60).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '79b8955276fb837f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('777e7ddf-d605-404b-a54f-055b81432e51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 60).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e44b74d9a4e7e595_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab8511a6-4f20-45ad-bc9f-54248d184d0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 60).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '52dc81fba8253c79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e443083-89e1-4cd9-a6c5-7162fa24e3b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 60).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '53c2176d2479dcd4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b09d2dfc-f5df-4a55-889a-cbb2dac7d2d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 60).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '320e27e4e4d8979b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f39b0f67-811f-4e17-a808-be3fc6b5aea9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 60).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9076336e920f965d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4619780-acdb-4bd6-8cca-05331abc713c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 60).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 60).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4447b134d41dcf57_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfa1b329-e204-466d-a2a8-1a8ba2f174d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 61).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'bd7326516c007c7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('352dec9b-9cff-4c83-93ff-370571ee97c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 61).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 61).', '{}', 'Networking Fundamentals', 14.0, '74dce9de46666d41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65a653c5-2c40-4c7d-a1b9-d3398adc1f63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 61).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 61).', '{}', 'Networking Fundamentals', 14.0, '8cc84337622b5694_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15364a4e-0373-4541-af56-4219502555f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 61).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 61).', '{}', 'Networking Fundamentals', 12.0, '8452e2f1179f0235_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4cd1a34-b45b-475c-8707-402e38d73156', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 61).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 61).', '{}', 'Networking Fundamentals', 14.0, 'db9111e5de0917b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31b27d24-a0c5-4182-b4fe-c2bd9256bef6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 61).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2107f4db4a5a20d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96601cd1-6c1d-4245-a763-fff439ef0ecf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 61).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4dc49a77eff99b0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ec53edc-2523-405c-9f7f-65e4913d49bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 61).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7deb5654d424d1d6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e7b3305-8062-4866-8319-f5ffcb0a2b44', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 61).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e2561e6652f76b52_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8bc7a57-cde1-4a89-9060-44a6011d457b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 61).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7e61468ed3bb6847_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10e5ff4f-901f-4b32-b803-8b4c9a59b382', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 61).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e282a5950a662cf2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67dd2558-4e11-474b-b814-37941fb89565', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 61).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '01b5084ee22e46e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d86575bc-58f8-4c21-be59-44eb647f1058', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 61).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4663bfac5e89b205_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22eb1986-24ba-4fb1-81c1-f6c575f55528', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 61).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '935261ff559821bb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efa41b97-f2ca-4bea-861c-4ebd864f1543', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 61).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9da12964bb650379_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a980d0bd-a316-4e79-a473-de773aa228ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 61).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4117344429b611e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eda3226a-fb47-4324-9c69-f6fc6bff2d61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 61).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e9451b39b5382c21_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeaf6087-e617-421e-a887-45c9ca5d7360', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 61).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '19f28979df1c351d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a05004b-cc53-4dd4-8ca5-edc7f673f3ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 61).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'fb10f88c7c714059_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a1a4890-d1c0-4a4d-94ce-e89a41f9aa24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 61).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '32121067d5f6795c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1e14e4d-c910-4f55-bc73-5af8a1f8cd08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 61).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3159eac900ec62d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfe3ac9e-b88e-4cd1-84e6-56d63a0336ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 61).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e677777b8af47786_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd00e12b-4f38-460c-98ed-e2e3a54c287c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 61).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7acf8a5be98d9398_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c558945-75ee-4e11-8fa7-5c7492ecb3cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 61).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '766414e9877dc3ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0cf299a-be99-4698-a6a5-b64fbd6fd1de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 61).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6cd2e7544eeb5123_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3d05018-e4b6-40ae-bab9-ae59c64ec109', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 61).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '23c46a01a79759ac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e07c966-2001-480c-ba2e-ae65c6325376', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 61).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '2537fd3aaf78dc08_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c683deb-2b9a-4188-b9aa-7204a0b415ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 61).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0e88baa0c73603ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('831f989a-d384-48c6-846e-67dc5bd581eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 61).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '104b9e1f3bcea2bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24b9b663-8d58-4cbc-943d-7f9f689c0be3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 61).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 61).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '47ea61703768af5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d055ae4e-c7a4-4773-b2ea-e015e5634d2e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 62).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '054178f9605a3edc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b72834e-7730-4cbf-aa07-96d222df117b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 62).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 62).', '{}', 'Networking Fundamentals', 14.0, '358a72220c2ada25_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ab63c7e-6a7a-4653-811a-3c73ce1f0eba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 62).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 62).', '{}', 'Networking Fundamentals', 14.0, 'd06db4bc98b90378_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52729971-923f-4f59-a9e6-3ca0e9e1528e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 62).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 62).', '{}', 'Networking Fundamentals', 12.0, '98910ee7adcda923_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21fe6b12-ca84-43e1-969b-3a534d9bd0b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 62).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 62).', '{}', 'Networking Fundamentals', 14.0, 'ff0b76a07d1e56ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('870525aa-4796-4796-9b06-2f987bf75dd9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 62).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6a4d8fa9e8344b7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d4617cd-ab57-4848-b62d-c9410763b435', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 62).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b36046cb28170d74_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('241b6acc-c4de-4c7b-887a-b3180607ad6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 62).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9b9e90237d8df72a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04627cde-19b5-463c-9a47-9568e3360aed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 62).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8c1813203e103817_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abc12257-15e1-468e-8d44-3487e32d2995', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 62).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ce6f0b9d6b84f6fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('142a0f91-b808-4cca-952d-b739fe460539', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 62).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd10b16cf1b0c8d9d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38506278-1109-4a43-9a5e-4a548b44ded3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 62).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c3b0c977d006d310_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3346d88-0f06-4155-936a-ab598ffebee0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 62).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd3533c2c4bc43816_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('306f149e-15ee-49e1-b89a-cd4ff44bdd91', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 62).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8a13f45b3af25a5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83273f07-9b58-478a-9294-f487abe9e729', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 62).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3e10c77687a45c15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1691da3-20b9-4451-9d5e-07d566a7ae9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 62).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '95b35f9f88582e48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd549bbf-46be-4fc1-a249-58ef3bf0bb42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 62).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '63b9ffa3d749c866_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c775e083-d5d8-4af0-81b2-cefaf3a918b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 62).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c5a4acff73a054e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75ff7b64-482e-4f46-abb3-f57fcdbe8153', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 62).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a109f605daca3a8e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94f958e6-30f8-4e93-b5ef-f77b7af6b043', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 62).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '604689d0b81b6770_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea2fcb02-8b61-4015-9292-8e496ec2352e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 62).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c3a31315b31ff81a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9835ba6a-fa98-421f-a095-05b910f9b59f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 62).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd5a7c4a550413d32_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09631264-b466-43c4-9708-962753d1d27a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 62).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '074ffdf261f76d01_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bd9bf51-fad2-4dd3-aade-5c21ca10fc2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 62).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fac4dd13a38f02d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f09cb20c-801f-43fc-b41d-fe5053c8f631', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 62).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '398e7178f3e7e0ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6747ae79-1a8d-4717-8114-43ba1debd177', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 62).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '58fe634de0d68f70_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54638922-d3f9-40bd-8cba-1895132d3343', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 62).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '84749333cd032653_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80d5318a-3020-4437-9872-76b3266cde61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 62).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0e4f8b2b7a7c15c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd3f7d19-35ec-4380-bceb-252567467c46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 62).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '74670ceb552e0290_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33ef067f-8088-49a5-a99c-3d6fcf4f0cb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 62).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6749b48855cae663_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f949b81-799b-4f42-a9a6-205675e811d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 63).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '090beb490114b751_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fcfe167-d3ea-4040-a7db-71bb270c0b30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 63).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 63).', '{}', 'Networking Fundamentals', 14.0, '3aefe0a31c74d4d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('807a6b84-bf09-4e87-a0c5-cc17d2519863', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 63).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 63).', '{}', 'Networking Fundamentals', 14.0, 'bcffe229458ff30a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f432eff0-92eb-49be-902d-d8c2b29b992d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 63).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 63).', '{}', 'Networking Fundamentals', 12.0, '8aa143420b9835c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('213fe0ef-a15a-4947-9b1d-abd4186b776d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 63).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 63).', '{}', 'Networking Fundamentals', 14.0, '2b48403dca324b5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff47c1a5-5b03-498e-8c95-4ef282f2f9a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 63).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '53509613fd9198bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d2ce379-f68c-4b19-8730-f496d8e6a206', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 63).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'dec3d34c36f9afe0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55a797ec-6751-4275-ab41-9b057dbc20f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 63).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c8fa785db7ad6218_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('326d54f8-8d49-4f95-bfb6-6d3dcd661d9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 63).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '68861172fb04a09d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('858e7fdb-4599-461f-8cc0-910d2178c772', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 63).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '6c98efc4c03543f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ba79624-85c1-4b21-a814-d1ac7e683208', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 63).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '12bc12db656d137b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81b2af53-2358-4a18-8d06-6b41cb31fabd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 63).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '02494236fdf5b0bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3565e69b-4cc8-474a-9465-f152fb755c0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 63).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '890ab3b5ec8b6040_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1be250c7-def2-437e-80d2-a028ded704be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 63).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7b04d9e32c1e8217_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('460b91ee-0816-4fb4-adc5-dade94521fbe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 63).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bd1ec85c0c9af5ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef7f097b-493f-44a8-bb6c-5fd32dbffedd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 63).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '19cc52af48f25f24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29f37208-e5c3-4334-8da0-4865d6ba249e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 63).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'da359f879dfc052b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac8989cf-b331-4f5f-a064-c31af5c61ee9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 63).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'b12f14b02f0195f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5df3dd4b-8b79-4fb2-aeb3-a526dcccad4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 63).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd9b31618a83bf681_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c28dc28f-b23a-47df-aa06-4fdcc1561637', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 63).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e8173cbb2a5be2f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba2867e8-6fbd-4be6-9429-98ea2b65aa7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 63).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '68fed18b45c96de1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6daff382-0653-4a06-8bdb-f563e15900e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 63).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '48c820568cdb65f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5519c059-247b-4dda-859c-8d54bab36b3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 63).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7f90c8d6c7d9663e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66e4117b-c68e-4dec-a0f4-f6e4fb3c9744', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 63).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '99b3398364fef136_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b5b13e1-a264-44d5-a110-cfcf4c681899', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 63).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '73cc77bcabbefcda_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('111565bd-c224-4832-83e5-3edcf6e2746b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 63).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a5258b3a07b02ae3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06876db8-6834-402f-9ede-f50dd9414d01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 63).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c308baabacea36e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8582eb3-4321-4ae5-ab52-83f848383f15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 63).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '76db00fc58e2a1ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ce27078-8786-400a-acf9-0dc67d83bed4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 63).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e602273f80acb234_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdcd7abe-ef93-493e-912f-4f6e579155c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 63).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '25c3bac751cc2d9e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('529b9321-9bfb-4b09-8121-f3d8564f4feb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 64).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3a0b363773a8f396_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce882020-78f5-4c97-9c6e-549eaf6c6e1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 64).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 64).', '{}', 'Networking Fundamentals', 14.0, '4d4e54dc1ed587c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3798b1fc-cd20-4c37-a28e-0de6b3e7de08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 64).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 64).', '{}', 'Networking Fundamentals', 14.0, '8eddd56a029e8f62_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b9f851c-eac8-40d9-bbff-40d1d9c222c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 64).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 64).', '{}', 'Networking Fundamentals', 12.0, 'b3eda548a2fb7cd5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d20cd0e3-f5ae-406e-98e0-72a5950eed08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 64).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 64).', '{}', 'Networking Fundamentals', 14.0, 'ddadb4d1913eaa5a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23c106ca-56f5-455c-b859-dbf2f40efbf4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 64).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e7a57268d4dbcefa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f49c636-5ab4-4043-b2ea-e0af2b215fae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 64).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'aac59fd9547a06d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('321a252f-fbf6-4d7e-a094-7625bbff3343', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 64).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6bff417b8c971d19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b03ae8e5-7ec4-4bcd-bfb8-a199ec841606', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 64).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ed96af9cd4b88264_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c22ce387-84bd-4482-a178-d8150a0f5418', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 64).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f9316eace89c5046_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('282910a3-0ecd-4645-9d50-b8989c1942c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 64).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4bae8660ff8f9431_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f3ba63e-9ef7-4f81-b7fb-9943c607f7ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 64).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e1bcf5046da6a6d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee32a5ba-78c6-48f7-a722-5c0ff4158e24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 64).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd004be22cf25244c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aa410dd-1573-4180-868c-f8c555490fc2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 64).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ae0a51b8095c8ee4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3c81e2b-fbef-43d8-8ff6-300602df4e9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 64).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '34020a868ff0fe19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4605a6f5-5745-4d91-ba4c-94c639c308f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 64).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6d4ec3679906a1db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbdd8180-166a-45ec-b2c9-620fc8c05be1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 64).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '64ae6dd944c4b62f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6dc2552-d80d-4b35-924c-79a6617e7088', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 64).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'bc5271bdae637df9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3f9a475-ed08-43e1-8d69-66272b2ad9da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 64).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9fece928f5c90f8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d007c97-601d-4e97-a17a-fb87217a6159', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 64).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9c851c3fc4d19628_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69974dcd-dd1a-4f25-8fd1-1b33ff9f89fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 64).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c4ba4d5906ff6d0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acea52e5-95a3-4ebe-8a2e-c85041dd0c1c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 64).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '71094884dcdb7976_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88b55fc0-2839-4f09-9c3b-15e29683c040', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 64).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'da46d3278eba57eb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d698dfc-3960-4b09-b002-4d56b33de88b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 64).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '56ec3e3d4c808a40_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32ba8d4d-d502-41fd-ae78-4d686825269b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 64).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4268cbd1a5e56d0b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd8f508d-c6e0-417c-9b67-406320c01d62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 64).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '321bb873af73462d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4332f355-1f42-43f0-8ad7-93b135d314ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 64).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '005b3783ded089d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87cc2df1-4d26-4e1d-b27b-100ce4980ed8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 64).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'bfd4859bc6a6a2ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5486e91-a169-4ccb-89fe-2255eeced10c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 64).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '45df19de9459e39d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc2e13b9-f8c7-4a88-a41e-c03f8230f06d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 64).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 64).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd1c0e1baeaa0b7bb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d41afff4-7789-4338-9497-d1df84e5003f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 65).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8b9cf62bd945f440_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('249dd8f4-7847-42c7-a1d9-433cefa6070d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 65).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 65).', '{}', 'Networking Fundamentals', 14.0, '501b6e3d8dc5f890_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0c26985-50e6-42c6-84e5-edbbcc8134ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 65).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 65).', '{}', 'Networking Fundamentals', 14.0, 'cd43f45f780df51a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52dabbaf-6b59-4209-9c48-ad91866d4e62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 65).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 65).', '{}', 'Networking Fundamentals', 12.0, '09be4243baf0f328_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57110b10-e83a-4c67-a444-eaa4abc31cec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 65).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 65).', '{}', 'Networking Fundamentals', 14.0, '5046eb00cee98d84_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32fcbd9f-4d20-43b5-9b07-0ba9b58b2b0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 65).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a94ac9fc2285c2b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c31c3482-b20d-433a-894a-6fa837b2f093', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 65).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '23bf7898e46273f5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1676d774-ef7a-45ef-9d42-acf57ac4c713', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 65).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '10b322f6117f3795_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce17e2e3-307c-418f-902c-12de93fb2474', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 65).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b32a9d551e4818c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8f837cd-fea9-4a27-a959-204dfd98d13b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 65).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c92ec2719b914941_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0562e69-b461-4668-a09b-300cfcfea706', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 65).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '465ac61995548a2d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ee2b4c8-8162-4598-a21b-fdca3f9492ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 65).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b30001b0175e00b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dde8b303-8b0a-44d7-bd96-571b297cefcd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 65).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1a0c1f7a00d6b263_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a61e347b-0f88-4ccd-a012-2104f484d39d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 65).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bf1afd55e95cc54b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cc67ebb-0088-4dcf-8165-652471d4e277', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 65).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e9457f7f01f34ae4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39c119d7-ab98-40c0-bb48-987f25a54173', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 65).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '52aad92117c59c19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43c7a36f-0be5-4b24-9c7f-2368d3016dc3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 65).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ad91cf14385ab5e9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae8169f6-9694-4ab3-8de4-7403646d1906', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 65).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '31b91c84797dfe02_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c811f8c-ccad-4109-a120-c36dc1989fb8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 65).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '825c604b408b5d3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef31330d-ab66-4a5d-9492-b00d6c51cf86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 65).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a685d68cc486865c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fb34509-0e6d-44cf-ae9e-67af17852db9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 65).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a548431e9d59a625_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e324fa3c-f97e-439d-83f1-88f672090b36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 65).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f4e2d8d0350151a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26cb31bd-0980-4975-aec6-c24a23c32f48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 65).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1135c8783fe525d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f70c8a41-e220-41e6-ab61-aaceca84cf79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 65).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fd3795f2f9f20dbe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5676a1e9-bf97-40af-b13f-14aaa2fa26bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 65).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6f92b41e25d8255e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b02a0d4f-d263-4bac-93ba-e6aae646db25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 65).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '03b9d567491ec5b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8da0e016-06b0-496c-b478-6351134c6c27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 65).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f20d7c57088d59d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ab7cf8e-3eed-4a80-a4e6-431678e0a79b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 65).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '75d62ab43f5111ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ae89dc1-953a-4604-a784-10128b2dfe15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 65).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2164d6a8bba893a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('965bcd71-43a8-480a-b9e1-bfbec1075eaf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 65).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 65).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ab47bb9fc074aee3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19875dd7-f889-48be-a6ed-6249146c2c61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 66).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '41ee75c0cc65a022_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59673f74-7e50-46fb-8ca1-25b29b49a734', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 66).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 66).', '{}', 'Networking Fundamentals', 14.0, '50cc4c7c58c309e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9c76da6-ed55-4885-a3f3-37440ad47a70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 66).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 66).', '{}', 'Networking Fundamentals', 14.0, 'e38b7db85cb34de2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcb621a9-8c16-4e1b-938f-f69a022c4aa2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 66).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 66).', '{}', 'Networking Fundamentals', 12.0, '49f96718071eca1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5933db7-dba4-4fdb-a4a6-fe71b9579d22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 66).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 66).', '{}', 'Networking Fundamentals', 14.0, 'f0b153b61b98c494_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cbc3925-ac68-4670-9825-56120a7cce80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 66).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '40113963a044605d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43dc0b94-cce7-42dd-a82c-a69e171318c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 66).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '49774145697f28fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4731f4bd-11a0-4b54-84ec-d47f64f8bfe8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 66).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '03b0618249b38ff8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7962c9ba-e90e-44c4-81c3-feec58849bb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 66).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3b38075f51445017_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('803d5f21-b9f4-45ea-aa38-0b853d3b8881', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 66).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '0fed56847e6216ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38d0bbb9-bc3d-4673-ae70-ba2490058c51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 66).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '82ef4ccee35dbb2d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff0f06bb-3297-46ba-a3c0-2bd5125ce843', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 66).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '87a81303fd4649b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af64a275-6da1-481e-8fb6-23e812496819', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 66).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '05b6dd3c9ab16b51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18d048a8-7114-405a-823c-f38fb6c1dfdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 66).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5720434fd6bd5c6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3a3f638-9d1c-45ab-adb2-49ddcaeb1cb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 66).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e88d701dbce0a377_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50f04f5f-4c6e-42f9-a740-2eb3392b94e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 66).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6411b9e3712b2b8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67172482-460c-41fc-b8a6-7e1c9c8bc98b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 66).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '26c44a02e77b46c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('374fc39c-3c85-42e0-8bda-29448acef561', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 66).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '5632c6b57fe37818_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('048e7786-c7a4-450e-807c-399f261bc264', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 66).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6327274effc77cc9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6922a62f-94aa-496a-99db-8aea95cf7a4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 66).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'dc49c7095691c6c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89935b3e-5bbd-4ca6-a532-8b6caeb6258e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 66).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '98b6550dc279ad69_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35f9de78-0339-4d75-805a-b6308397b3fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 66).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5646928db63e6484_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bd0abc7-47d0-4d0b-a4c8-b36099b02c0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 66).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1b0075d9d71aec95_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9897c427-49c9-4354-a397-fbcced911d79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 66).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'bc97cc8ab5b19eee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8359adfd-4042-4398-9883-a26eb8cff883', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 66).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b68bc85a35eadc6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6c7aa2b-ed17-4b66-b8cf-3c5280035e6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 66).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f656a5a8535dfe1a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1707d5ae-d959-4f08-9309-a3f4b7f34fb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 66).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e75d6848c1240404_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('116be5cc-2d15-4fa1-ae0d-11e77ed30249', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 66).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '200ae571c7865213_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c66bb25-51a9-4474-9333-055a702d2c54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 66).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'decda2076a5f2b6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1257ecb0-6db4-41d6-9ca5-ae387f16301d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 66).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 66).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c2fb9b9cf37b1832_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d45fa3d-7655-4d3d-8ac3-2ff6e472eaed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 67).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5ee7c8afd695a2a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('675ded8c-839f-435b-bb35-fb69c12413de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 67).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 67).', '{}', 'Networking Fundamentals', 14.0, '00cb4b06285bbeba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aaa9311-f6ec-4314-8ede-99464cc66984', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 67).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 67).', '{}', 'Networking Fundamentals', 14.0, '9f04e9819ee1194d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02dd6f99-d181-445f-8110-5bdd12c07c9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 67).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 67).', '{}', 'Networking Fundamentals', 12.0, '5b227631fdc49a0e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e1dbb29-be93-4e04-a017-2958a673e812', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 67).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 67).', '{}', 'Networking Fundamentals', 14.0, 'cb94f80cf15ff742_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69e11d3c-5699-44e6-86f0-bfa493e6e4b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 67).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '710a52b94c377f39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33f548c3-76f0-43ce-8f83-c881757417ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 67).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'dbf29f665d6d14d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b3f662b-3065-404e-a7b0-df9f603fe4be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 67).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f10031032a32448d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('984cf901-570c-49d0-abe8-71e56c9807a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 67).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c175c6e8ff536069_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a07962c3-76fc-436a-aa40-7b148e4c6bca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 67).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '961c17186c3c7f9a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6081cc40-51c8-44ec-9975-5397c4178261', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 67).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1f095efee837932a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b294355-b116-426d-8a6d-158b07ed1a94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 67).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e0fc651760a35981_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ad2c23d-d6b3-4963-8e6e-b348530a49ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 67).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4be70d117edc75ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd89e0df-2420-4224-b4ee-dad3d29077b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 67).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '49d531dcff49fa2f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3db98a25-d0e4-477c-b760-5030d437cd98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 67).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '246ab6395f506b80_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95654645-3935-479d-8a5b-3de037b1ad89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 67).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4f6a1aeefa6f18fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11f10d7a-6a63-4a9d-bf93-9249d8be2b61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 67).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a149df441290f7b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6317b9ee-44b7-4418-933a-198b224b3212', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 67).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '233122a8c62972fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c4d7aff-b644-4e3d-a77e-fef9bf6c52ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 67).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b9179815df0f9a90_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b392664a-9b91-49ab-aa92-058c1ad741e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 67).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5332a2293ce555e1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('000a5637-518f-4ddd-9209-fbcafafe7f90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 67).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7b701ba1a0b911e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56be5ba4-45e0-4a3e-882d-93dd5f31d8fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 67).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ba3d103a4259663f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5a7c20f-3e40-4aab-b195-f2494c7e7f34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 67).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '21e73933ec54e87a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb194c2b-349b-469e-b7c8-b4b0da3ce061', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 67).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4aab2b93160f8c53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f29a5540-6573-4494-b818-09a818f44521', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 67).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ef1d5c738236d5e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fac6b8e8-ebc5-4614-b7ff-8b29f7a9a03b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 67).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f73c09dcd1463f03_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a04c42ff-ced5-4e75-9b4d-0101fc38a221', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 67).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a5c92da0cdc232dd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbb37136-3992-4192-93e6-933511ddea3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 67).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'bcb506a183806a04_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('befc2679-33ab-4cb0-ad45-1a8efb526c89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 67).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5dfe8b93c2f87577_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e60ed5c1-7711-4932-8c11-5baedcce1f65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 67).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 67).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1c5fd4a8ddd95eae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df8fe1cc-75ac-4852-b5d8-b881cdd2d440', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 68).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ff2e4f3fcb75bc7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60318759-1188-4efd-8f90-1b2666f2dc88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 68).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 68).', '{}', 'Networking Fundamentals', 14.0, '6829e633abead042_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a957af83-0e93-4284-8b3a-8c39c49447ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 68).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 68).', '{}', 'Networking Fundamentals', 14.0, '8fb6e102110bf6b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('664e84f4-30fa-47fe-90a0-f7765901e98e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 68).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 68).', '{}', 'Networking Fundamentals', 12.0, '392c4a84250d07fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9a32d5f-478d-4bf4-9bec-7ea9b8b1558d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 68).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 68).', '{}', 'Networking Fundamentals', 14.0, 'd87c1298c648085b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4d42623-a26f-4a7e-bc30-ea441eb8a351', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 68).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1f8c7f7a4eb83971_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('958d33b2-7635-4f44-adb8-4c2e9b529071', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 68).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd740983a1699575a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5a620f9-dde2-4a46-a457-044a7aa31f35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 68).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '52bc3f67e5b21fa4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2211c889-5f92-4266-b180-ffae7039aa3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 68).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '637734d7f9ff77b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2899457-f93c-4ee8-83d6-aba9cf4c519c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 68).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f5acb87d02431e69_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10797377-8e53-44f2-83ea-812985dbb057', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 68).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '90075e0e9a82717d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e386ed12-2214-438f-9b9d-8ee9b5b684b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 68).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '36ffa8e95ab75031_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70c716df-675c-409f-919b-86b4094e1a47', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 68).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1fdb39e37e1b90d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0475ef4-3d90-4063-918d-34c426ccbadb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 68).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6fde76e211d0c2da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31579669-e621-47a0-a1c9-e000af9fc908', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 68).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '90966e3dcfa2aa5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c41c3647-945f-4b65-a95b-3b67f1ef9d4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 68).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '000404bbf30f7abb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6d79d4e-a467-496e-91e9-5b19b62831d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 68).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'feda8f7b049ab662_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d670e09-0ad9-4958-9fd9-cea805ec2bf3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 68).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a488d2d9bf5fe15d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a59bf91a-3796-4ffb-a070-2a0950c9e0e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 68).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '8bbe0f2350f24a6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b672386-f037-47d9-bbe4-9def076fe84d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 68).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7da08e0dc5863f8b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65bb50a8-c934-4beb-bed4-509465ffae9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 68).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9a9efebbaf954b1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64c89eba-c69f-4a49-9360-d8fe2420a85b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 68).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fd39c59f3b1b5a6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e80b20e0-cad1-4b72-a31a-0848e8950a2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 68).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0e875030d22a73c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe42b8e2-765a-4ee5-8818-c7ba245217c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 68).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'a510bf5e12c0a9df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2f6a003-8dbc-4941-bab9-8bd09099ef8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 68).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e1e27f98d07898ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('586aece2-4295-42bb-8249-5ec1d3c8987a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 68).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '62e12921910fd89c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f90ee4f5-3886-4ccb-96d1-adaf00e5d6ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 68).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '1aaf8e798895c3e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c41b7682-29ba-4577-bd17-57980780559e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 68).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b04c7a647b1d32a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b245e00-fb36-43fc-93d0-c23a22ba5d7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 68).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'df16a97ca2a4c395_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5c4dfbc-cbd9-467d-aa09-e16f147bc985', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 68).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 68).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '96d74d497eff845a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9849ce0c-437d-4395-8ca9-4cc9d8e56fa3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 69).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '7e425e503fcf3c86_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6e63407-9373-4433-aa04-693143e095f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 69).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 69).', '{}', 'Networking Fundamentals', 14.0, '09ff35b1f401ae9a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73e70301-dfb7-4d50-b523-821f2701166f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 69).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 69).', '{}', 'Networking Fundamentals', 14.0, '9d00df0227738575_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0420fe58-9525-4f7f-99cb-93ab8f3b5e7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 69).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 69).', '{}', 'Networking Fundamentals', 12.0, '5875236ac767994d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22576d24-cf45-4267-a21d-58b8ab0a931f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 69).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 69).', '{}', 'Networking Fundamentals', 14.0, '9c4f872dd26b8403_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3449bb45-28f5-461b-85bc-26ca67e7bed3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 69).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'baa6d095363cdf34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80d73ddf-fcdf-4710-bb4b-55e0ced5c789', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 69).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b51e396c7d464320_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4b60add-9c17-4f5b-bf84-bdc2585c5b0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 69).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8de7f4fda110bcde_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f36d3d87-d753-4b01-906b-364063bde5af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 69).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f4090d38ea6a4e84_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7efc3862-5997-44cd-a6c4-7611ce2cb85d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 69).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'deb94faebfe3de33_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('395433d5-c052-4663-9a43-d7f255ad6eaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 69).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3038843fe0754a05_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d54d3c8-27e0-484a-89aa-bc77d1a46391', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 69).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3ce636266b96b018_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e6c57d1-e500-4ded-bb1a-94ad7a03c654', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 69).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c955526da1a3550c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2010149b-8841-4689-999f-89fabd09c092', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 69).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '041b62d680928e81_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67bf5ddd-c6fa-4cc0-b6d6-1f916e2bbd1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 69).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '26c4e7f521e1c993_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c4730c6-74dc-4bb8-968a-70abb15a9f2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 69).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '705014e8d0f25a04_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f31577df-920d-4885-8ca4-4c66ec133937', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 69).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b883688818125941_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89e7ddf0-ccf3-4d26-820d-f78cff821a0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 69).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '9ac8d69c1fd23c56_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61af4feb-ce21-457c-9422-8e5462926492', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 69).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4207037546f2481b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d98bba4d-09f6-45ec-a4dc-99e6d1a634da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 69).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0b8c7b97b7099ffd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3886cdc-b69e-47be-8e05-571017544d29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 69).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '65d52ad59528c510_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d88cd99-d4cb-425e-9d26-fb257ce45724', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 69).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f7d43a017f8c7a80_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3f81eb4-a551-46a9-a006-01a5705d88b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 69).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '56b0bf34a1caf714_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb053aea-9799-428e-9c2c-4b7ccd058803', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 69).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '16e7e33b46720248_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30f480a6-cfa6-423b-aecb-8a0a1ed9fc31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 69).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8d7271c8be03d16d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('429b641d-fae0-48ab-9ec9-069560b98d86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 69).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a21acb22e8cc5b25_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f45c8785-04ea-4f3b-accf-be63edeed8d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 69).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '34eff7abfc8f3d2c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ed85a4a-db4d-4ea0-ad81-593ccc4c72c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 69).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'dc2d5d684d090754_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b398837a-c5ae-4802-926f-a829e8114e63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 69).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '72d237b42740fae9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fda6e31b-ca18-4edb-bc52-b334d75f9cc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 69).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 69).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '17b78d8c824a31a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9351496a-3668-4e65-b3d4-450f7c490b55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 70).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3a0d9391c27a0162_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d77be2ba-f391-41c4-865c-3721a13bb453', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 70).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 70).', '{}', 'Networking Fundamentals', 14.0, 'fca349dad64468f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16c2ff0b-1454-45a8-ba43-355538cbd4a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 70).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 70).', '{}', 'Networking Fundamentals', 14.0, 'd610c8611e796508_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bee34c93-dad9-44db-a7d7-94e32b30de4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 70).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 70).', '{}', 'Networking Fundamentals', 12.0, '840fecf5f43e028a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b88c0d9-82d9-4ae1-80e0-d2b8fb0c9208', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 70).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 70).', '{}', 'Networking Fundamentals', 14.0, '7108af766073bb5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2949c547-a2a2-41a8-97dc-03845bf2c741', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 70).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '0122295de7d0e73a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9123840f-a685-4bee-9170-0207bec0ac81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 70).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2cf3aecf89f42c4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e415a821-9f9d-404f-890c-feb032318044', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 70).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '792a153107b0de0f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b34f848d-368a-4a1d-b99b-634445875725', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 70).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '41ea383f013879fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cfeebf9-df6f-4eb4-83ad-8833c42dd661', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 70).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '4a0a013ae0ef20d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7967a9a9-0711-4ae5-adb2-bae59255cd93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 70).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '578d6aa0abeb3308_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4978ab4-82ff-43dc-b8e3-5999e9e977cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 70).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b666bc5573807e49_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddaea317-7a2a-43b6-9e23-868d8ea29146', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 70).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7da5db639369db0f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9aa86afc-a9c5-4e03-88c4-2761c2a90113', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 70).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b7049af618d908c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f705b417-b238-424b-98c5-aedd757eb515', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 70).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8d616ff6c27e5b26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f203ef4a-569b-4ccc-a153-f239c8f2827b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 70).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6a75f82e27bf5e20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aee73768-32b9-4e32-8da4-d0380bbe36d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 70).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '75cf414ee433ce0f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de7f3f48-ebe8-436a-acbf-ba9b86f260ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 70).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '9a86412d6e50a698_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e3a2259-7a52-4f7b-8669-13af706ed6f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 70).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '12d7e59618fbb33a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e5da952-3ef4-4610-ade6-b6a803ee2b7e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 70).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '26d87988535f7e90_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6163488-73ef-4428-9188-b577bc857393', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 70).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '58bf02d451c0f05b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('842f4de8-7e49-41bf-b275-f6e01a0d75ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 70).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a0503ad0e9f36517_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af248e6d-99d0-4f71-aac4-f5f8cb04d534', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 70).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e7297bbe3b16bdd9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7712d558-a708-4612-86b9-a3b0cc112ede', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 70).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ddc7fa8e4b0f6388_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25226ed3-ebb5-484a-910f-156f4afe290d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 70).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a76c99bcd5a7c013_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fac9cd70-91d2-498e-80ea-5b8d4cb6188e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 70).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '38416e485ba70c8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eee0f232-7c3c-4e48-93f4-36a52506e9ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 70).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0f51acc8b38f24b6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2931713-c4b6-40da-a1b1-f6a533edf61a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 70).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '61ea5db0cb98b0d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9ac8f2c-2720-47a3-aadb-0a1ea2a24194', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 70).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '62a0dffa9dda0c71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd89fdbe-5125-473b-8a01-8f753a9be519', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 70).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 70).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1814ed017e4d9af6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6884d460-8f00-4a4b-9cca-71926c415e18', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 71).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1ae0caeaa9a68568_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba25b19a-6661-40b5-a633-51ee139c0bdd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 71).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 71).', '{}', 'Networking Fundamentals', 14.0, 'b8cd6f548babce3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('168dadf3-b6d4-4446-a7c1-3ce15478de93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 71).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 71).', '{}', 'Networking Fundamentals', 14.0, '7f00be1d8bf20cdf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8b3254c-8ccc-4003-bf4d-98df0be5f9bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 71).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 71).', '{}', 'Networking Fundamentals', 12.0, 'f99a21e9cdacb61d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42e095b7-3b8b-4d37-93e4-fc8ccd0df3d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 71).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 71).', '{}', 'Networking Fundamentals', 14.0, '794300255b442070_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e43893a-1938-441c-83c7-0921744bbd2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 71).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f87af82d6a4cf836_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0361e7d6-e4f2-4476-af0e-e9d02b7688ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 71).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '555d58034c36dbfe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9fcb210-16c5-41a5-a22c-27823d37f056', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 71).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '889a452a1decc59e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d80e2e9-f914-4d4b-82e6-2369570f5332', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 71).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e8f4da2385ee42b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('040fa84d-e46b-4a45-9d77-b890ea9128d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 71).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ae77561c179e4e34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9940839-1626-42c4-9810-d0b9d9db83f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 71).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7c5bfa45a4c68668_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1497c209-7121-436b-97e2-1b5253267f6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 71).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3dd40c55d07fbd9a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f07c0e5-50fc-4ea2-8600-6b257034ab76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 71).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a1b418d28d22486f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('755fdb0b-ec4c-44ba-af65-d26cec03a92b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 71).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2114c14378dd7087_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c7bd5ce-dda0-4c0e-8100-a95c8f2a084e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 71).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0c641eed38f80cf2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d0f2043-860d-47f0-9c09-d44be6bc61f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 71).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c8ce035636c97ebd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff4953ec-4034-46b2-9cc6-950dc3020571', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 71).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'dee7680e607a224c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c83414f-3736-4e62-808e-0c14139e599a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 71).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '956a0e136a30c5a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd589027-16ef-4a48-9a2b-bbb01327de1c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 71).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '479b3810ddc60d34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('518879e7-93ae-45ae-8a3a-b66e568e4dc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 71).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ddb1a42ef6631011_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b94e6bc-f112-4c2c-b211-90b8b0826012', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 71).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bdea9385c75b7b98_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72ff2029-755a-4573-be74-94322f9d469a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 71).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '83f98684262a9365_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c17f6541-e7d7-4dc4-aa74-41760fcdef8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 71).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '693b31b94547b02f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8ac676f-7889-49d0-8713-6397faab628f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 71).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '2ea3b43d7dbe7df9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89bb35ba-4e25-4058-af6b-4bd29edc661b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 71).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fe47221a12be208c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44d54845-6063-43a1-86fa-0d7c48a3fa7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 71).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'de3001bb0655ad55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e405eec-2565-44a9-9b56-0429deff23a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 71).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '303a78582f883301_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('692b0e40-0193-4928-8de9-1df5dc49504c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 71).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b84fb2d9e722564a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38468cdf-1cdd-4e5c-b16b-1ad4b4d521d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 71).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e0c5789f56c86ff1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17d00300-3f1c-44f6-a391-ad7cfc711cfa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 71).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 71).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9e737263ca1c59bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('284e7f1b-819c-4f19-9137-7aa8c3281113', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 72).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'dcf47d85cdf636d6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa680986-1313-4e4e-a6fb-86517bfb4a8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 72).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 72).', '{}', 'Networking Fundamentals', 14.0, '6b14b10208986cee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0411eaba-3888-4c74-9aa2-85e1f8ae60b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 72).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 72).', '{}', 'Networking Fundamentals', 14.0, '176545e15e5ab068_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('352c55c8-99a2-41cc-bd9d-28b06500ba30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 72).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 72).', '{}', 'Networking Fundamentals', 12.0, '07bfb61c0dfe1fc4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('775561fa-ff50-4d9b-936e-5fd16f67b969', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 72).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 72).', '{}', 'Networking Fundamentals', 14.0, 'dc7497fa114e7149_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90687842-50e4-4f8e-8037-2fd9597d8e09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 72).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'eef23a1d7fe6e3c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2219c505-9d72-43a1-9c7f-97fa31928673', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 72).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '353d280dc7381ca9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3586469a-164a-4e4f-89ad-0275460b34e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 72).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a60073eaade2ddbe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d4839a1-9aec-4200-8bb6-f07419a3c09b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 72).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '28e569b761c45b28_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8e7e971-c3f2-40d5-9569-9d1610b5b07b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 72).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e6ae941e8bf7287c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2f32c4b-c1b3-407d-9807-c7f57c2259e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 72).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7cf44cc9edb58ebd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('843b0ea5-81fe-4cdb-bf58-cbcd806ef127', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 72).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a5089640dce5f5cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e757a47-bd69-4bb6-ab27-7db0ab956c6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 72).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '75745af4e52472ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a771af6-d3cd-4ec3-85c3-c4760ad15f20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 72).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f809c8c34cbfe9b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62ddd171-62d0-457b-a438-1cbf74ed7080', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 72).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '404685b2d32b4e45_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a775367-d04a-4b98-9e32-2ddb89f6518f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 72).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a253a1f4a55f603a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9fc4b9a-8264-46ff-8f9b-1aa719c512b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 72).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b114cc2b172f03e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f905a3fa-cae8-4b18-95af-9a1d58e5c43d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 72).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '0ce352db11e12c70_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52942944-f636-4ada-b65f-5c0e6983acc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 72).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '388ba2213f5d5ce5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('554e236e-1345-4426-819e-76b3980de61c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 72).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bf5be9532b7b15aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11e05e97-aadf-44ca-b995-0f572fe7505d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 72).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fd473a54e39b103a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('389b08c0-4e5e-470a-a829-4f635ae66218', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 72).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3ca7e63a334a9d06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc198a28-dc8e-4d0f-8b7e-7c3e738f9ea9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 72).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '75c0e6caf7a54d35_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ede174a4-9e32-4963-81ba-005a0f364ea1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 72).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'bcce7f74e5871ee0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eefcc1fb-e55f-4688-a88f-b40b8041d24e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 72).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5007d3240d94130a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b646823-c2a1-4872-bf8f-3cd7996b8e0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 72).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd260a35a6695f6d6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b373a6a-1643-4dcc-a594-82ba8549ffd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 72).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '481e6db689564a51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c7bf600-f275-435a-8fdc-dbc1dbf33a13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 72).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '797a918aeaf93f26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19ef4133-16c1-47bc-913b-2b27eafe21cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 72).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ac715c83a65c772d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e602683c-1e00-4378-b3dc-b91593a76006', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 72).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2b8aef47e0a3b85e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc750c99-0250-49bf-9702-2939be3ed3e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 73).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'dc3132170f35676f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8a62708-d131-4893-9a35-da677b90ccbf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 73).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 73).', '{}', 'Networking Fundamentals', 14.0, 'f84d2f0badd62365_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db5d2f90-dda2-4fde-b8c5-272c15b524dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 73).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 73).', '{}', 'Networking Fundamentals', 14.0, '7cb33825f74080bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c375b45e-37d8-4420-8c89-77a464cffcb6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 73).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 73).', '{}', 'Networking Fundamentals', 12.0, '53fff7fda91cfca5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b10dd71-8738-482e-996b-451e339e1e61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 73).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 73).', '{}', 'Networking Fundamentals', 14.0, '393d6bf6e7d0b90d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba682658-9381-4f08-a1a9-c477b8154df4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 73).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b816bc8a729e4b38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02b53deb-557c-4467-ae05-26f6c2ea9ee6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 73).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f834aea1baeed708_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c07972a-0b65-468b-8d65-738c4d9766e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 73).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '32ccee19c2903fb3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf1b4eab-385f-405d-8422-1e488b774579', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 73).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2a20d21cff11a19f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f199a739-bb34-400c-9e20-0d11b3566b01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 73).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd6eb26eb0752ea0f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47e49efa-ca9b-40e4-ad53-2352180f69e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 73).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '17291ba45ba2b23c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6364bd56-39f3-4a67-9e9a-86d4fd1e34b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 73).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6bf9895c44fe0b81_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d132a5c1-d0ae-4c6b-a5c0-231e00a5316d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 73).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0856ba39bc8b4cdf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6c40e1b-8d88-41e4-b2e4-509084c981d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 73).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4e56e9483d2dbd89_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57168b1e-fc95-4473-a8bc-8bd846febecf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 73).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6abc16b0076916bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67f5d517-3c66-4499-9e47-a78cea947e51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 73).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7dd60bc1f55ce4be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cda6e229-fa65-409b-ac12-ae9a54ce74aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 73).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c29acfe98b372fff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f1c8387-3db5-453a-8389-5a0605c31a9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 73).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '917254b6760a87d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c30722a-c4fc-43c6-a8ad-c6044e92d9b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 73).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '12e9e876a29f0852_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f6fa790-f3d5-48a0-8f84-f30ca29e5c80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 73).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0713b7b729da4a15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60cc3633-9839-46ce-8c0d-3be8b6f58c21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 73).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fc992f52f5705536_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e69ba60-4515-4946-8fad-3a79eff2c343', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 73).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6a8de344eca7cab2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dd5214d-be2b-4f79-8ebb-63289582baa5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 73).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fc6c83a04fbb2e0f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9959994f-e6d8-4b0e-aef1-fd69d95c3b6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 73).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '32fb02ff8139a05c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52cff62f-62f0-4726-a59a-576831be902a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 73).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '77d9ba992ddf78e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2d3b2e9-2bc9-4f4f-8296-249c18635e76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 73).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1ef2a4d0d9fd6998_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b528e2c-269a-4779-9f64-941b1963a6fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 73).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '3cc94bf1d802d0ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43ba02b0-086e-4490-82ed-715ccc09b190', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 73).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a08634a083beb64e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73cca096-2e16-4942-afac-b23cde491cbe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 73).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a47215d11503a7e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b919a7ba-bde3-4faa-afbd-dd64928f0458', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 73).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7ebc469c8d252067_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f67b6c79-0ad5-48b5-89d6-c963a424a3b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 74).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '99b15cec64e2ba53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7467c5f5-f2da-4b86-bab3-d54adbef2cfd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 74).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 74).', '{}', 'Networking Fundamentals', 14.0, 'c1f3cbbe1356dc17_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a37ecd8b-da0e-4fd0-a392-8d75730e1ac0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 74).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 74).', '{}', 'Networking Fundamentals', 14.0, '3978686d09166b4b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfe24188-ece8-4d4f-85bd-76bf8ec18c7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 74).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 74).', '{}', 'Networking Fundamentals', 12.0, '5e7b6f3997acb229_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('334b2f4d-eda8-4836-ac5e-75185ce1330f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 74).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 74).', '{}', 'Networking Fundamentals', 14.0, '1d0525d2cd968597_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97c9a373-0643-4cf5-9028-4291f190bd1c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 74).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '4b185da783febe56_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af7a44f1-89b9-4974-a7c6-2a4aad806441', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 74).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd733c227010f4bfe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba29ed97-0c59-49bd-8ca1-6700ec107960', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 74).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0b85f497d1b0345c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e603dfde-07e3-4634-8669-38c307b499a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 74).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ce19c407c66ba016_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e59c2b6f-4966-4ea1-824c-2c783f18066c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 74).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8c9c1df3e926d058_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f38b0346-9665-4e47-9dd1-99a248b44788', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 74).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a1d3b57c70dab204_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('443b8cc7-5d94-4a9b-b1ba-6d2550dc4325', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 74).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'de1bee57a129ec2c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ea1b335-29f5-4a07-ab37-9494350b8d9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 74).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '75f7f16919a4aab8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0af9d6e9-9e1d-4e7c-95ba-8472d861a278', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 74).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '271cef6166f1fbed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a326ed78-bf7d-40ba-b068-3fa39aec1eda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 74).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '648e52bcfa3c444e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7220cda6-9ec7-47e6-882c-28f294d147da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 74).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '14ed2f16cd4a1ab5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('464aac31-5bfc-4f92-be16-032bb4d68bf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 74).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3acd2e85f02f7f27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bee7e9cc-0b22-4fd2-a255-f2536a659c16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 74).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4dd9765850453a3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('131ab6de-8435-4c63-8117-88bf709ace01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 74).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '49201635b1203014_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('215198d1-4684-446b-b6e8-b129f7db2e15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 74).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '04cef67ae2ebbc30_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca286f67-b83e-4b64-80db-d0cf81572729', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 74).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '02c88462311bd683_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('430b88cd-4bd8-4179-aff4-88c6770e0bd5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 74).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '118533a7c18d91c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('425fc918-8521-49fb-bbfa-587abaf46ff7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 74).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1b794151165c6f59_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('594351b4-da0f-482b-a03f-c9fd71d22458', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 74).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '23c4714393ccf984_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('360844ec-ddc5-495f-a071-e5f99b5cd95e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 74).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '96ece4583a5b0418_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f02a5c6d-c0c3-4b2b-9508-3d32d0953545', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 74).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a9d34e594e7963f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2c494fe-e119-4934-ae91-7f53e186ec54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 74).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0a8e3a5d55411991_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27408d39-8308-46e0-bc4e-d46e22618e70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 74).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '19ba20b0a6e598fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9f7af21-c6db-4f44-961d-20fc0852edb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 74).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5413e20979e8e4f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6031b76d-ab3a-46c9-bfc9-06ab05a42e3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 74).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 74).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5f7543dc5421d3c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37b4428c-4fa6-4911-b0ed-e31fd17fc6bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 75).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd36a60d7d4358870_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d61ca5e1-0419-46dc-8baf-3a6fb814e7b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 75).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 75).', '{}', 'Networking Fundamentals', 14.0, '1231f626da2c1e88_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6874e9ea-f3d8-4afc-846a-918c1d8382c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 75).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 75).', '{}', 'Networking Fundamentals', 14.0, '7425e2d1fe31f398_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adc5e2f9-6b7f-449a-9881-5f07b934b200', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 75).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 75).', '{}', 'Networking Fundamentals', 12.0, '25d443a7fb59e522_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1085a97-a420-420a-bd33-94e303b9ced1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 75).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 75).', '{}', 'Networking Fundamentals', 14.0, '28329ddb6a8c3d4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e5bc5da-62eb-49cc-a814-9d9f34f007bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 75).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '0ad3a8934177b8ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ce09550-75ef-4e9b-81d9-1c47fe982e97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 75).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6fc3957dc9b6a795_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40d4d5d3-f1e4-4148-8ec1-dbedd080bf09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 75).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f62b30e59deb5ca4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('054f6a17-f892-4fbb-aa3b-d85777c390f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 75).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0747b62dab3269a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bddfff22-3953-4aa4-b68d-75faf1d9ee40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 75).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a34c78a6238f0448_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b062eaa-8f99-4c99-b0af-c8178097a2b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 75).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd5eb19f0005002f7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('517fe776-17ce-481a-aad6-0bb30340ae41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 75).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '15bfb9a4d53fd485_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0eba8cb-0beb-4ccc-903a-fd20fa4976d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 75).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '70e1d332825cb80e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5425ee0-5b5c-4dc8-ba37-1be5f37404fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 75).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '92651a7ab0a67a63_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8f55ac8-e0e3-4ee4-a3f4-0c6a330ff871', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 75).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '70bf4e055cce97e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02a02959-8839-4d63-93ea-2b1f542c0293', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 75).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5a38e2bd1dd03b91_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8221a18-33da-40e8-b125-8e455c131919', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 75).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'af1954259491bbc7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d50329fa-2e93-47f2-8e48-19bc400f9079', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 75).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f5eca24f668fd3fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f228dc8a-5f65-4561-9433-400a16780876', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 75).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '8ed56c597efee99d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8dc7771-572b-4904-b4c8-8d81c82b2050', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 75).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '372fc43a9f790d6f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c31b7a78-d364-4e2e-ba57-660c400de243', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 75).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ef2eb3650e847952_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7873df59-94a2-43ab-b49e-27a139c62a2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 75).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '52b23cc688ef19d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('988c0243-293e-4286-8452-88758c1fd881', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 75).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bb19f7d1bfd74e2d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ad50272-0bcb-4703-9d6b-c903eae206d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 75).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e2caf49a984eda5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f7ba87e-22d7-4a93-a283-ff4e42d3c278', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 75).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2577c923677c72fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('273f6739-2de9-43bf-90a4-852a91082c3b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 75).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2ae04f5bae8b8bd3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('698a3c7e-299f-4138-9ae3-9b355e95f368', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 75).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '569a30d5b208126d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('416c8c53-1103-4485-b40d-8e9a09bf0b46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 75).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '067edcd297de4635_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ed420c4-8e60-49fe-9b87-ffc72b56e9ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 75).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '83a8f5879908e736_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f41d573-2836-421c-a401-0cc051268a89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 75).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 75).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c3ab10290a1ce12e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbc7d942-dd49-4867-a3f7-cd6f6ca84332', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 76).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '61bda38914de3a48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5288d85-e4d2-48cc-a44a-f1dbb926f326', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 76).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 76).', '{}', 'Networking Fundamentals', 14.0, '2f74d94592a41adc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f01c5820-9329-41d1-b238-cd0a26a824ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 76).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 76).', '{}', 'Networking Fundamentals', 14.0, 'ad3a6e59ea2fd2d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46b6f5bf-c0d7-4ec8-991b-4d3c7666b352', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 76).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 76).', '{}', 'Networking Fundamentals', 12.0, '9a012b4f3e9a3057_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('633490c6-f87d-4e04-a357-99090023f596', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 76).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 76).', '{}', 'Networking Fundamentals', 14.0, '720b76200b68e998_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1221c8f0-c897-486e-9bff-565650b9c7b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 76).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'de3b6c35fb540a06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e26478c-210a-4b1d-89c5-c8df941b23a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 76).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '55f179ad22797ef7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f04d6f21-3281-4434-86c7-1e915121d4c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 76).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1a9fd67cfdf4a726_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7550276f-3790-4b11-b1e9-5feda28d143b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 76).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c1e79a6283739fc0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80e47d51-ea34-4d5c-9c5f-78ecbac71bd2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 76).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '443d07dc5077faa3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0f91fe8-8619-4d09-ba3a-f9e3cff498e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 76).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '71441cf3e9c08154_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0222f75-b329-43f6-8a41-49cc9b3c244c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 76).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ecf1fe4c8aba87a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aef5f3e-7402-407a-bb7c-7d543a334759', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 76).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a532d637e95bae84_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4e4e8c4-6c5c-4532-9104-4b3a6d055429', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 76).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b09a1f9b6b7c03e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23a820b3-d268-478b-8ed4-efb2e5500583', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 76).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '504f784e7f508499_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8151edc-ea16-40ab-85bd-d597384c4bea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 76).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '895ddebc67f98f0b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4fd2ccc-4a91-4c0a-b462-f9985d60d517', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 76).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '95a29185635a6e66_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7b0a7eb-5321-4cd0-ac02-804627df4cb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 76).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '3310a7cc2b560da0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e46553e0-3390-4f6c-89bf-1b9ce7e99786', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 76).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '562fd21699a80a9d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac903664-f267-4fc5-9002-c19110d84c17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 76).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a0de03a0d1d6d230_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b932c6ba-2489-4487-bfe5-0639095f995b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 76).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c7aaa8780dabfbb0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9551f8b-ffb9-4b96-a1fd-93c8f85c7c4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 76).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bfcaa6ca02918009_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31681930-50fe-44d2-9d59-9ae5869f7315', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 76).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e0496427a19e48ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1b37688-4b5e-4a8a-bfbc-0b0397ffbbd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 76).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6cfeaa51df5cbd78_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b32883c1-8234-4255-a50c-bdfd125385b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 76).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '70e4fc3feb44b198_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74e41a73-ed57-41ba-9fbb-adf3fdc81883', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 76).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '739da91998e5be7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e63b833a-50ed-4554-addb-a03a42722466', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 76).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f24c8ad13830c135_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2b125b9-dabc-4186-8fbd-7b199ac978a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 76).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6258389f3b9237c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90c508c7-8544-4340-86ee-af0c38a0315a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 76).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a817790983433c35_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56494f16-8f5a-4994-ab7c-74d33a712993', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 76).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 76).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8dbb00e494b531ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('736ea6ff-a909-436e-a987-2ecf07caf1f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 77).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '33f0fed32207e188_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b6e0d5f-ab18-4055-8aee-e9b28f31a34e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 77).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 77).', '{}', 'Networking Fundamentals', 14.0, '58a626153db50f0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b1bc317-6b5e-4199-bcfd-f78c20766f9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 77).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 77).', '{}', 'Networking Fundamentals', 14.0, 'bedbd355a356f63b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6cc65c2-2bc8-4c45-984c-10c706fb8a30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 77).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 77).', '{}', 'Networking Fundamentals', 12.0, '359d6e32f4753d63_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d002329-804b-4032-8ebe-733b83c20949', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 77).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 77).', '{}', 'Networking Fundamentals', 14.0, 'dca268496ea908fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06642092-0ff6-4787-b051-a74a791f2255', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 77).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd280498d6c294ebc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bf17da7-f997-4e77-80fe-52da33932f1c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 77).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '213ec245901bd8f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1e67abb-2bda-487f-a0b7-907f02432ad4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 77).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ecf89f27c6578364_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2efcd380-e444-42bf-b698-31d9fbc96b66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 77).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd5ed4c2a73acdbc9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('078c9dbc-79ec-4a10-b0cc-43f0058e5b10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 77).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f95abc15ed1e3420_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49fe0baa-a593-40de-be17-e2976e9653b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 77).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4d56e8633d4b613a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f503958-0349-41b6-9d35-9dc095a84dcc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 77).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '338ade2322c7959c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1aa7f6e3-25bd-4ecd-b7bb-341a29f1feda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 77).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8cca7741934e09c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ad8fc19-ab17-4427-84bb-4c3547d08252', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 77).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a80b97c52c554c4a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4e415b0-ea2f-48ef-accc-a3789c24c191', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 77).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '89901e79c29fb43c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('842860a1-3d82-480f-af5e-1debc55b9736', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 77).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b850209507b8daf4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07f2b239-09c6-469c-95db-5385a73b2532', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 77).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '422e3edfc211657a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed7ebba7-e870-4b1c-b70f-a25afde65cd2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 77).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1cef6f37119623d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81ce7a3d-0974-4d6b-991a-bbae9f6c8e2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 77).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4cdd08b76daf44e9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97ba8be3-4640-4d6b-a903-ae177965c125', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 77).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5a7e55d6aefd152c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1c43665-83a2-478d-aecd-54c04e5a37a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 77).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '69be03c63989d79d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37ff6a64-553f-487c-b825-f34f24b333e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 77).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8f9ac20522b3dfc8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cf0a735-d61a-42ea-9dad-9533837646c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 77).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5e109b5b72bb3970_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb6ae5c0-ec84-4997-9daa-1feea9f7ff4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 77).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '5e81d35110935210_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25fb9f5d-10c5-4a49-8d07-a1e006bf02a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 77).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7755774575dc0915_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c029a7e-1d93-4111-9411-4e6c26c9352d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 77).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e8fd7f47ddf1c7cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('711dabc4-4265-4d87-9c3e-98e008de8cf7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 77).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ad2c78bafbf0a722_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58c1ee71-ebbe-4f02-802f-c68b4be911f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 77).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c82dfe94c1a62a23_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45d89e91-ea9e-4c14-9341-cc2cb8cb6c26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 77).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'dc2b004470e57365_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58d6a761-4925-474f-a3ee-d0137d33c597', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 77).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 77).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '82ff0625a0a02d6a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a5e7268-a968-41a2-ad4d-f63e117cd3e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 78).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd8c4a612dcc8ef37_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0e15b5c-7208-45a3-a623-d517e1bcb2a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 78).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 78).', '{}', 'Networking Fundamentals', 14.0, '6898afd0adaaf582_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5925326-d498-4cd7-823b-59a639e00c04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 78).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 78).', '{}', 'Networking Fundamentals', 14.0, 'acda4a2e76ba7d79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a83f884-b2fd-47ab-b673-4d25142146ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 78).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 78).', '{}', 'Networking Fundamentals', 12.0, 'f3ec781970547fce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cc600a4-b69a-42d2-8a5f-4254cdc4e516', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 78).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 78).', '{}', 'Networking Fundamentals', 14.0, 'df018ed2d7b0b8b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d32b99e-7e17-42a3-8d76-be07c33c717c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 78).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '64b8f08ef520a517_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90239a4a-9236-4fa7-91d5-66839fcfd01c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 78).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5fc4309fa962bd66_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca2f2f12-bea1-4551-9a45-9ef7aa115177', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 78).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '34fa12d5618f6ba2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc651b5b-b548-4ee9-9886-4b7117ba8535', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 78).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fedf74bc17e38acb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d08d54e-3b78-42e3-94a1-278cf08cd0db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 78).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '67041eab50fd46f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98bf0e1b-3518-41da-aeb1-7d9eeabd1192', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 78).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c9a0332cbec88675_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8523a99-d6b5-43d0-afa8-0bf55ea499af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 78).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3fff2534e8cd5758_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ce5a811-7a26-4cdc-9518-30306067dd3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 78).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '23ff6a3eea27db66_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc419853-6f8d-4195-afc3-27942149f535', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 78).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b028748f2a8f13c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('407244aa-ea4f-4398-b54f-38c5c55f68cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 78).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f2724a40aa8db607_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6395d3a-c47d-48f4-967b-3f4572d40527', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 78).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd4473088ed7431cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aee7a70-b94b-4df0-952b-766035bb6c9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 78).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '60d9910440679073_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e150bc6b-b48a-46d9-a4b3-94c243534f79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 78).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e031fc6840560019_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70f2eff3-c4d9-473f-b828-ae6c06c0232c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 78).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6c268884e6f5e4a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29ae64c6-08ee-4f15-8164-3d4ec13b2829', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 78).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7943edc97b9633cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ed8390f-ff53-405a-9310-f73be64c223c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 78).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5aae755e02b79f2d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c20ddb95-95d6-483b-a7df-a6f98610d87d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 78).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4514aa4bfc5a3544_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('421b4b3a-1c8c-4809-bce9-55adf8cc7b07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 78).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5496d30106f04de8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2850832-8c20-44c9-81aa-afb5ea0c755f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 78).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '1372887a50505030_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4df26fe8-677c-4467-86c0-45e4c09efc3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 78).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5946584f66b0cd2c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46b672d2-2032-4123-8f1e-902c8455947c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 78).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7e86d9052b0239a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88837644-d3eb-42ae-bb65-f895f19bb6b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 78).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c10e30888eb3c33c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d737188-db45-4899-9236-1c598f403f01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 78).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'ac35f9c95352a140_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eea3c77b-a5dd-45f5-9322-b1ea8ad1e806', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 78).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '48f94d9e499e78c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7100278b-4bb2-4ad1-a967-8903c4024db9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 78).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '895ffe65ad74f05c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b528280-f46f-41c2-b15f-d3ea5bed13c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 79).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a1e3ab1c36fb0e2f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14f811d7-9f1c-41e7-8cd1-3ae4cbbcacfc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 79).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 79).', '{}', 'Networking Fundamentals', 14.0, '76cc50019c98ef07_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63fedc23-7001-4762-89d1-affa807f1f25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 79).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 79).', '{}', 'Networking Fundamentals', 14.0, '9ecdf4e09a649c43_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16cc4b6f-b012-4def-a25c-a2dd6296a20a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 79).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 79).', '{}', 'Networking Fundamentals', 12.0, '97e4803bf6989da4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('486ebe94-e9de-4d14-90b4-475ebe6094d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 79).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 79).', '{}', 'Networking Fundamentals', 14.0, 'd061fd9f261d2900_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64f038cb-9fee-4a6a-bf4d-dac573be9b00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 79).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b86aaf5bf8806de7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1f19eb0-ade1-49e8-98ef-980bfa7778ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 79).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bb8f4c29366edfaa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ace6c19-1bb3-43ca-993e-c1a69b38b5d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 79).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '16e503e50831792e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6db7cbad-7830-4281-89d4-46429a9ca314', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 79).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8a56bd3cecd22ce4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8000786d-268a-4b2e-a584-f7e0f42a2521', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 79).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd823230933349833_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca1f3b71-a057-47c5-a0b6-285e72b3bfa0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 79).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9686105021a6f62d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2f9df15-87f9-42df-89b4-2c9482161aa1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 79).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3a19266890a1208b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16a29090-111c-4072-8897-0b8624907072', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 79).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '49196710f10fc50c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa8113e2-35ec-48b3-85ae-60cd984c005b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 79).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c42f2b979d1b79d9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('feeaa4af-32fa-4e0e-8dce-ba0de2a11685', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 79).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5e0a58cb97ed0549_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5018d4f-4148-4c9f-8b25-96afd759bed1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 79).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fc33d561e49af7f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c65b497-5c6c-4841-bff5-cb2d3f4e0db7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 79).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '157fcf0855e25b54_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bbd885f-a233-4c78-a4e5-5261934141f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 79).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a92a4082510efe8d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab533403-8417-4f77-a18b-f05b73726792', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 79).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9f7f3c48f29438cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37f48efe-a523-4af6-9199-d31ad7e533cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 79).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd6e107abee9a3c12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d474ed0-bd78-4ba9-a8b0-3e33d95bccb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 79).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '864da90c97bd3a75_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adca064b-b2c7-489a-a672-41483504cae8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 79).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fa56dda26d5a1c9e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79138f18-184b-4c5a-876d-54577bc1fa9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 79).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '539e455db3b1924c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b81e6ca-ecb2-47a6-a101-ca30227fdb41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 79).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '0e6df035fbf7216e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7fc9bce-7c3e-4cb5-89d5-2f5c5f3139c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 79).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '15a85361a35fe376_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e813343-932a-4dfd-b94a-5c2b23bb431b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 79).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '329f85faf07f3ca5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46626ec5-defd-438f-92b3-0f1719763ba0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 79).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '50ffa0c0acccf2f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce0701bd-c857-452c-9202-648550d4c009', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 79).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0c506d0dfa5b432e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f33f33d6-05d6-43fd-a8c2-ed7c8a81c1c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 79).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'caadd623a912aed2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e35a0de-b2c6-4a2a-a90f-b6a62d56def8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 79).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f62af251d178e66a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d549b2c2-fd13-4a60-af62-a45b4db79941', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 80).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '187188926669032a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a9d5627-6bc9-4c31-861b-d6df9469edb5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 80).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 80).', '{}', 'Networking Fundamentals', 14.0, 'dd90ca6b339cae4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('688af759-e0e1-4201-96d5-90ef01eeded1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 80).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 80).', '{}', 'Networking Fundamentals', 14.0, 'aa556f5772179f94_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd4937b2-bc98-4f22-90e9-81d640306e6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 80).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 80).', '{}', 'Networking Fundamentals', 12.0, '5b9a6a6f19de841d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f80dffd6-8fd5-457e-8a46-8ab8c913861a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 80).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 80).', '{}', 'Networking Fundamentals', 14.0, 'ed5cd236c644ee17_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('923b6bdd-dc5b-4622-90c6-a022242b6439', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 80).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '224f68cb2d622064_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d342b49-d73a-4c93-9e5c-9046bb02a6c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 80).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b250c8936d747246_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2a97856-aa46-4a74-a4d1-bd3289f1761a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 80).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f5c62705cb94d343_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ca66be8-c758-42bd-8fae-a71c99aa9f74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 80).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6bc00ccc08acad4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe311e07-9e92-40e0-85c0-9ee9b4fd0e85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 80).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a58282c693325aa0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5539bbfc-93ae-428a-aaff-c6a453865b6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 80).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '774eb5a485d904bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04ad9963-2891-489f-87a2-d7d0a2b383c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 80).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c5f37ba7661ec772_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea4a9836-8729-4ec8-b068-6a3a1f0a5f5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 80).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '513a9a4f07c5fd53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cabbdee-2779-43c9-b159-16ef9e3a80e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 80).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7aca811ee89ca99c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08f37f7e-1eb6-41b9-9c09-bafa2414e13e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 80).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c550a4fb65afcd99_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75e0d150-919c-481d-950f-826fbc02099d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 80).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '08fb31f87b846685_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e90900c-174f-41a9-a371-c91747106def', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 80).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c77727bab8f4d39a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b6f7b20-a3d4-4ec9-bb0b-44703602204e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 80).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e6f0427b6012aef6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87f0632e-81ba-4259-a3ae-d27f8d2340ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 80).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '05986e9e42aa84ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f42a38c8-da73-4818-9fdd-1bbecf9f6a57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 80).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3a097157c03cb3fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7535e96d-7abc-449a-923d-b56609fa89b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 80).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6e7ead30f894cc7f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51bafef2-a965-4d67-b848-a5c008a9a077', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 80).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9aaf0143ca10a066_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d040cf7f-b2fe-49d5-9303-b1150f8f2e7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 80).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '07b1ba7bedea483b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0c977ae-f0af-4b18-a66c-b903baa15cf0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 80).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6b237bf07badb9b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37eb6975-bef6-49e4-8599-de5e6490d48a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 80).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7f9b246a159fba79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2e5cb96-691d-4f5d-a20d-8a248bbb7fc5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 80).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e5c3ba201a7eff50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8373e77-a1ca-495f-bf5a-82dd68bc103f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 80).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '69cb889a2e9b1e13_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67de39fa-70dd-4b48-9354-627fb676b155', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 80).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '3d40cc136b234dad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff145377-1b16-47d9-9065-00843dd3ce2e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 80).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '64b390cf1ff447f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3042a7d7-2c98-4457-9cc1-30921e2e340c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 80).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 80).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e93cb13391a0df51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f75d2a0b-042d-4324-8b4a-c297e6f98d44', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 81).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a02546803b6cd427_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c5b6869-80c1-4fa2-854a-d178d4381d21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 81).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 81).', '{}', 'Networking Fundamentals', 14.0, '4a16764117c9b25a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('025b2ba4-2094-43f1-9318-6956e2c57e80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 81).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 81).', '{}', 'Networking Fundamentals', 14.0, 'b6b3b0749909b590_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33417e7d-e6c9-4626-8989-d2dad20dde42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 81).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 81).', '{}', 'Networking Fundamentals', 12.0, 'ef1b25010b4bf89e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82435cbf-2015-47fb-ab40-5bd6b1168b16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 81).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 81).', '{}', 'Networking Fundamentals', 14.0, 'daa33f4748b75881_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4d3ce9a-0aa2-484b-8c81-f5d572c0ef39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 81).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd97a6206474115e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e41fe88d-21aa-4266-b6cd-5f91cc4aa46f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 81).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '521357160acae525_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcb9b6e6-26f8-4e79-8102-f097db802d1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 81).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e1cbcc06cf7a544d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc40b3dc-f6d2-47bb-9648-13b28c19b1c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 81).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e0232271c8d7868d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7672a6a-ce04-41de-8b15-5ebf698fac96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 81).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'af5fdde9eb94c239_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('150d68ed-fd4e-484e-badb-27c686ce7c02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 81).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '18b38907615954da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('635a307b-a8c4-450a-8db2-5505f322f410', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 81).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6bed3aaa96fc8e55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42af1121-a32b-4da4-b130-4f76e8d92993', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 81).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '45abb7bc089dd091_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45fdae21-587f-4322-bbc2-ddcee32e46c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 81).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7d2fd82081ab4e13_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dab0a339-42ef-4429-a1ee-ebf675f7172c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 81).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8b9d1c20f85af80c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0808d5bb-80de-433e-a653-17989670967d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 81).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2b59b2a9e05c1c80_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('457f8d0e-b672-4584-8c10-dc4623d1cfff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 81).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd1428ba2475a76dd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdcba4cd-e47d-441c-b8c8-6590e6e7da27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 81).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '799a0866362a3de5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e83fb0f-040b-46f8-876a-e34b0724e661', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 81).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd2f9244c976a3b6e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e3966c1-255d-4b24-b72d-31dc33731513', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 81).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '54a132d00a2bb4c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c7095aa-4d07-46c4-a223-a37fcdb44b56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 81).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bd20dd58fff9c3c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dad9db2-5631-4a25-bf56-cb73310eedb8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 81).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1867726ac981fd26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6798ca24-0f64-4278-85c3-e2a758aa4e75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 81).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4bf4b88fb3725c33_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e4c31e6-44e9-401a-add3-78c91846d653', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 81).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '020e3b34dfb95e05_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae383a4b-fa29-4f38-a589-b2ce4e960579', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 81).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '81a7203584f9f9d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f45ef90-0a79-4efe-b8d1-b7ae52255e60', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 81).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '682681bd4241939a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d837c76-6772-4f8c-842e-c74416924250', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 81).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '813814f2ed92ffb0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('857c0291-e6e2-4e88-a1d5-77f6f7e7642d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 81).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '20005cdeabf20a42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d13d7ac-ea72-456c-a9c1-2586f48f0077', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 81).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3969db2d282e8050_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('338fe485-167a-48df-9b26-04063ad8aff9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 81).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 81).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '488dbc6243916a4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('737dc207-fa1e-47b0-8418-22745762529b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 82).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a2af669c5f92bfe2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6a89468-836c-4c6b-9ba4-ac43ef558454', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 82).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 82).', '{}', 'Networking Fundamentals', 14.0, 'ee3872f4157999ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db06d75c-5ca0-4348-8d0a-1988761618ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 82).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 82).', '{}', 'Networking Fundamentals', 14.0, 'ca6b811d21384311_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb6aa827-de92-424e-9bde-ca667e4d1b0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 82).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 82).', '{}', 'Networking Fundamentals', 12.0, 'f03b149e24e2e0e9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7c565dd-ba83-4e8e-a6bd-6900617d196b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 82).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 82).', '{}', 'Networking Fundamentals', 14.0, '5227ecde4119678f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d718ebaa-4e48-48c5-a49d-af998fe0f07e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 82).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '4d4d5e54dabb6b4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b6b4e71-685d-4f9c-8cc8-10803908190a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 82).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c056df777ceace5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdb6e1c1-9bcb-4e91-b3d3-eb5263173b4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 82).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a34dcacf24a940f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ad1bf38-dd2f-4910-b69b-250fb9d7f3b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 82).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fa4ce32b6b34a917_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0355417b-14f3-4895-b31f-0b5bf3878ed7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 82).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '0843a9632995a059_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f471920-4ea3-44bc-983c-42b43773b80b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 82).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '791daf834b3c8a23_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('359f1027-237d-44a9-861b-66fa34b46cb6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 82).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '962feb6d1e2be7af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('787e0d9a-a5aa-4ad7-8fe5-e6ffd5948447', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 82).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '95b06c4d1dfca6ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82b85162-1104-43bb-bb72-aa3b2b52c5ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 82).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f46b08d86cfbd5da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cc0fc50-ac18-450a-beda-618c81a34c40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 82).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7ff3d8a2c189d40c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8728a12-4db0-4ec1-934e-f1ee96a79128', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 82).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '203d111f0b18f94b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bba4354-8420-4c7d-8b1b-09531d2fc444', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 82).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c34e90d19e26c648_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f177587-06db-468a-87fb-3987ebb400db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 82).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '47ddaa700da0eeab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f9d152c-bb15-461a-96ed-750c649ff00c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 82).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '00829c5296d53bb5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56a6985c-18ef-41f6-8e4f-abc61d3bc1ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 82).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f15de63aa0670f86_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0afc8a85-9aef-4fc1-ac17-109c96d0e89f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 82).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '766972d7acc0ffe1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c156ef91-af89-4e08-8f10-d237762202d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 82).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '599bd2ec3ba97c69_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08917921-45af-4a16-bc1d-9f313240eb9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 82).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6404cf13afa6a9e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f751629-7d8f-4f17-8e87-7c79fa054dd8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 82).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '0e72981047bd6950_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaf99d75-9169-4d6d-90d6-31e23f0c809e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 82).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4fff7eb0f3100099_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed9f6dca-6b6a-46a6-ba93-f769fd9f80cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 82).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7c05145eb77a41b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f2885df-fb63-4a4d-bd6f-1c1b98866625', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 82).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '76baab9bdb376830_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62d55780-2d3d-4f36-9d86-f488085178f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 82).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd5ab7cc759697481_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5360b4c-2c82-4288-904d-906ee413dcb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 82).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8fa3457ebbb44bf9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f32fa0d-1421-4f87-8658-a32fbb76a5a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 82).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 82).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5879393ab3735467_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6133b7e-6146-4bd4-b5aa-e909931d5869', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 83).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd53cc03e87a4d295_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb9b8f81-1737-4c8c-ae5a-3421b99e41c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 83).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 83).', '{}', 'Networking Fundamentals', 14.0, '37595a5c62798c45_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ff8e429-8ea0-4486-b66a-d4411303faf6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 83).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 83).', '{}', 'Networking Fundamentals', 14.0, '656516171c460ccd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff1beba3-1fc2-4142-9b6a-4b7212cda635', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 83).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 83).', '{}', 'Networking Fundamentals', 12.0, '5ccfffee103d112c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de1dee44-38bc-489d-a99a-c092a8028c9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 83).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 83).', '{}', 'Networking Fundamentals', 14.0, 'd7e1c8409766a8dd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d595d3ee-edf6-4e86-a36a-50d6eb87b985', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 83).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '7ecf0b6c3e29fc69_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cf7f99c-031a-4471-af05-c1cde981aa20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 83).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '53aa8367b7e562b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('932a2d29-03b5-48d9-bee3-69a1baf980b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 83).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6b0c85f52201c3e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('211e8c70-cc24-413e-b125-303bcd52d664', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 83).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '157bc50f30d7b1d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26bc4be9-d405-45d8-a6ba-659835d14b9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 83).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '6b5f8467d19305be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5933b1ae-568e-4f88-8e81-26d2664ba54d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 83).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1a99082b621ef0bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('680198b2-0b56-4562-8e55-93356f9554d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 83).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fb05bdffd761043f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13626aa5-1396-48be-93e9-0bbf83c64edb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 83).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '960cc0f8759a9376_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8cdf3f7-5cfc-404a-a047-b29085b4562e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 83).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '943778848d3c7309_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff597f07-b80d-4765-824c-826f4a99f42c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 83).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8e0e4d19d646b953_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4e1662c-9b91-43f1-b2fc-5ecea3281652', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 83).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1a434c9720a84bf5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6b541b0-cba9-48c2-ad74-7d9534298582', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 83).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7ae841cb087c26da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5370064-5e4a-4f38-81eb-5fef9cfe183c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 83).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ae505c32fdcfffab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a698df14-3060-4363-be22-e021e1bfe541', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 83).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '2d0f600eecc4976a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71e839d7-f4b3-442a-a434-5e148c3944ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 83).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8bf0c60d7861fee8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66a721e3-3cbd-4eaf-93fd-f009598941d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 83).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0f12e3c4b8c8ed43_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51d07b14-9d99-4d45-b285-36c46a225471', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 83).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '09676799c3018a9a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a811800-c732-4d05-904c-bfe55e01fe54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 83).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '43fc1a9caaf9bb9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('994db55b-e2e1-45ae-87f8-ee8cfbe889fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 83).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6fceced5e2ff14f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8b86ac5-da6e-49ed-a551-8bff533a5d88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 83).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1ceb00a6ae6147f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18815c8a-fd61-4ede-94c1-6cd0d9445993', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 83).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f10264d1e3aa5ae4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b64f7df5-e10a-4e20-b40e-74298d38c993', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 83).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c10454f3694a01bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e1f3747-9dd5-4bcf-a366-62c3a29adead', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 83).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '91aef18b650bc776_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba9b9e3e-550a-4301-8a40-0202b6a0a159', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 83).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '90530fc7cc72e81b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3dc9cede-73be-44da-a951-e32d80391fe9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 83).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 83).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '887a82d09803ea7b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02f25538-497e-4998-9039-26b60f5583c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 84).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'e6d2c12d294f1434_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69d52d10-597e-411b-9bde-f643ea90719f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 84).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 84).', '{}', 'Networking Fundamentals', 14.0, 'da0bbe78534427e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2345e72-b296-465b-a218-5c61f7fe3c9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 84).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 84).', '{}', 'Networking Fundamentals', 14.0, '5c53c6d715eaaf79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4081189f-85a3-40e7-8120-f52e93ba3b20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 84).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 84).', '{}', 'Networking Fundamentals', 12.0, '3de055eaa39bfcf3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49273d27-f823-4b34-834e-c5c15d32c21a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 84).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 84).', '{}', 'Networking Fundamentals', 14.0, '893cdd5c82313de7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b669265-fcd2-45ea-9bff-d5f94931fa75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 84).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f2b9e73408c01497_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9be0bc23-4fe2-4f59-bcf8-66ffd37d1170', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 84).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5e46b97652ba73af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38e325bb-b139-45bd-87d9-12f372264fa8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 84).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9a7ab332d738ab56_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1049fc81-e110-443e-9479-3ff08eab2dbf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 84).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5da7db736408095c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7dc571d-3db8-454d-ab66-4c012b45c874', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 84).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'fe91c35928829375_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22cf8e70-6e2e-42b0-be87-69b64b063f6a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 84).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ecfe78d117c30b6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19c3c6c2-0ca6-4f70-8c93-d348ae628504', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 84).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bfa4c45767bbc178_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5eece031-bf75-4d21-a1ee-44ad77a54d94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 84).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '746e708ebfb6bff2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b50617ea-24b9-4165-bcb8-17c084f045b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 84).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c090ae917846214a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a44437b-8de9-4db8-8234-5fca0006b897', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 84).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '001ad7a5ff9d0116_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1933828f-77ee-419f-a339-87ede271ba97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 84).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e6bf54d2789a4dcd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5d89807-782d-4969-b34f-fbec8755a559', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 84).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd3e029de0c1d8f9d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1265cdd-ae1a-4b58-896e-9fe0b11a33c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 84).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4a49983dba807ef3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('089f68a5-c313-48f0-aea3-91bb6758d2e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 84).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '522174c2f5632da3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c80a624-7ce6-4aa3-879a-065236154624', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 84).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3986647d59d7f5ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96db2228-b3b9-49cc-aec4-78d84c5c151d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 84).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '59a54c1fb75b1a55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('769ec93f-1d09-4013-a003-2f621860dead', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 84).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3b2c9afebe8c27e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b75ab79d-dbd8-473a-bd52-40dcd6f68316', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 84).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '164d17415e4e69ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21403ebd-5ae7-40fe-a198-310104a8d5af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 84).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7a09614c8e513d86_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0f0c512-a2f6-4161-990a-236b5a76aa09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 84).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a79ae601bc8c646b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d98400b9-4996-4f53-88f9-89b250647ec3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 84).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '9b6a0e8c3a0c22b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2d17c0a-17d4-447e-88a7-0d309b2aa3cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 84).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8ff46c6e296f4000_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36c4c20e-d38b-43a0-9844-66c4b3b0e678', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 84).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '90a02ee534e1ae2b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c6aba00-2ee0-41a8-9e00-21e143b95629', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 84).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '83269fad91d87c57_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eecd56f-1638-41ee-9519-6abaecac2a7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 84).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 84).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fe05d94a9ca18a97_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('486a208e-ca75-463f-87d9-6787a550de9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 85).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '9cbefff7057f9176_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd632c5f-63fe-4850-976f-4c4dfc33922e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 85).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 85).', '{}', 'Networking Fundamentals', 14.0, 'b101182e781e8d1c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c84b6928-cd57-4a46-8c04-5bc3149917a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 85).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 85).', '{}', 'Networking Fundamentals', 14.0, '5391fdcfac924bf6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1046eee-8a5f-4fcc-8043-03b1a86ff9d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 85).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 85).', '{}', 'Networking Fundamentals', 12.0, '9320d330cd2c1999_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e15d635-c957-4837-b32b-0416c86561ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 85).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 85).', '{}', 'Networking Fundamentals', 14.0, 'eb51beb4b8c47e9f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37fa5ca3-4125-4d24-a6e0-f6f8cfbcf421', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 85).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e649837951c6a064_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e650018-d765-4fb2-accd-562a489fb717', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 85).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0cf02dc52398eabc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b75f2b97-315c-45cc-a986-9c0ca4f9b050', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 85).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '10cf88d9d8c2ea34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c785f90-8eef-4f5b-80d8-befa34ed5b0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 85).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2afe0f576e6cf493_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18a922c3-46ba-4389-a1f4-6c363dd81143', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 85).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '473218dd3d162338_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bf4dfbc-a71d-423d-b039-65a583039c42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 85).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b426f7218af38a10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f64889d4-1103-4197-9ee6-4445c1d5ebbf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 85).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ea4712bcfd5b161d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b959977-9c06-4b0a-af24-8482c5bd534a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 85).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '74ef0ba200e7ef53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cc221ce-bbd2-4647-b2fb-b2dbec3acd1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 85).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '490ea4913bc8ecc3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('896b26d6-1a95-4571-94d4-08f00317860c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 85).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd067821f945902e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0338ccfe-bd60-4626-9947-07fb74085071', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 85).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2e3308ea2a14a4eb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7ca9ae4-1308-4be5-be3a-b7ef4ff9599b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 85).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'fc5b18a07855bb20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1b57412-193e-4bea-b3e4-af6234da5452', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 85).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '2b7b49af680a0a21_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d743332-d9c9-4bfe-a178-37cd6d994ff6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 85).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '929f8dec2e61782d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('980bd5cf-8648-4afe-8354-ae9203d082ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 85).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '39c3ec4391d96aee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bfd4fdf-72cd-49d5-90a8-b5107fc28727', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 85).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a09303e34a95ecd3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0b8fb44-53d4-4e75-a4b8-da9040351c9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 85).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd9e691b39791cf92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fdc87d0-d7eb-4b19-9604-9fef939c668d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 85).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd2252371fe67402f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1cb1e4c-f99c-4459-868e-9e318774a43d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 85).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ab8cfac1cc68ecd3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95453ac5-a5a6-4cfc-a937-deb6069a494b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 85).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '884e9da664126c12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3555ac1-53dd-4c09-9bda-28b91c662e32', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 85).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '34c5b72a13b1e217_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e93647f-5142-4a2d-82fc-f7f8b756f1e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 85).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '040516d5996468cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bb52f40-1d06-4b74-bf10-00ddacfdef96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 85).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '22b92547b4c7b219_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeece999-6fe1-4226-84f7-365b1f8fe87a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 85).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '18a39fb458b88265_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8b3cecd-2953-40d5-ad6f-8068d1b4bec5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 85).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 85).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4d810efd577db8f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3b2de63-d0e9-4964-ad58-a61827a62a51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 86).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6d55e5e3861f8693_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f99f0411-54f8-479d-ae05-12f2c7eeddb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 86).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 86).', '{}', 'Networking Fundamentals', 14.0, '26d26ba2cf292d6e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2ed2a7a-e4c0-44ab-9dc4-8bad2f4640a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 86).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 86).', '{}', 'Networking Fundamentals', 14.0, '02696924f66f5e1d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b51d03b1-158d-447e-9f8d-1fd2b5080d5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 86).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 86).', '{}', 'Networking Fundamentals', 12.0, '84210b893b0fa47d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39ace101-c968-4d3b-b55b-d2b08beb6dc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 86).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 86).', '{}', 'Networking Fundamentals', 14.0, '48f1f2d0cca694c2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('329bc81c-56c9-4366-a498-90646d7ca4f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 86).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e1b5859eb29ccdff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59e82a67-d0b4-42be-9e0b-37a6f179c020', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 86).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '44f56d951e526da6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('227f4195-d175-448f-b96c-56c17ed95752', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 86).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '82829c18d87639d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66c5a666-3db6-4588-9a08-6d1d8894d767', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 86).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '072f9160bf92c622_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b38c1dba-cbfb-47ec-a098-302a0d99db2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 86).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '103f4c156909d72a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e32e2a0-8bbd-4142-8ad2-29dd51ef0226', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 86).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dae981044d57e3ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a382ce01-455a-46a1-a471-49a5bc58b9f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 86).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '546feecddf9f1af3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('418f305f-cb74-4c90-a0d6-6a70cce241f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 86).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7c8ff2b7290e0764_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b38bb0c4-17e2-466e-bfac-8eab4232293b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 86).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e3e19af251f26af5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c31839cf-31b9-4e1e-9ab1-b3e015072bcf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 86).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '54fa3287e30a1712_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09b8f3e5-107a-425a-8f27-252c2dacd163', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 86).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c1302a81c386920d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db14f889-8479-4939-91eb-ebd9a9ded337', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 86).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4f5c27ff02def611_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('290cf9ba-129e-4ca4-9ec1-5525153f3aa3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 86).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e727181962c208a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('019f514b-2f02-4967-984a-a7c148619ca4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 86).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9c03968f4049ac76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('233dcf19-aad2-4fc6-ad37-cf46c81f74ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 86).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7232c844c39fd3fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfd28274-54f8-49b6-ba38-61f8df2a96a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 86).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '051a3c10d4c12d6a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('342b496c-d4e3-482d-bec8-dc6074820f6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 86).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'caa97d41402b8370_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09e093d0-8c0a-418b-a9cf-29d04daf9bab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 86).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8985348c931803fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1ffea39-d773-45b9-b1d3-f7da5a97073e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 86).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '0a9282a8eed50b9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca2fd7ae-741b-486d-91e3-4a8bf5db8ee0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 86).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f28267dd068cbae7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fe0e652-1455-41c9-af0f-80badb065e70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 86).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c712404d0ce66fd7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a5fa73b-41f1-4ee4-a7ec-01f72dce13b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 86).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'aab66218b88d484a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ac76b21-eab9-462b-a92d-4a8e36d3e3be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 86).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '985a8654edc4c0c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b0723c9-22fc-4546-9237-f94e4ed7e51a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 86).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0543e8175ccb1132_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ed1d412-ad99-4556-9fc9-496df5734079', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 86).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 86).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '393625420917a27a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dab42dc-4e28-4b66-abd8-7ab206d82831', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 87).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '964fd5737644ae5a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a103040-b64a-4aba-af85-df1c45060fa2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 87).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 87).', '{}', 'Networking Fundamentals', 14.0, '53e3b5dc8188ee4b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('107ba62c-8a48-427d-86bb-d51c2a997947', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 87).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 87).', '{}', 'Networking Fundamentals', 14.0, 'bcaf700c60b79fa0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78f9183e-61bc-463a-9a50-5cdac4898fd9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 87).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 87).', '{}', 'Networking Fundamentals', 12.0, 'f3ec2a70af235e67_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52733567-1c3b-47fe-90da-69b3d9dc2d9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 87).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 87).', '{}', 'Networking Fundamentals', 14.0, 'e7d1f8029d73a8b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a843adb9-80bf-4f36-80ac-a1f5bced17d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 87).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '0a19fa1f87848b7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f988225d-49fc-454e-8850-0f5909c67fc5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 87).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8af45db398f874d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('623a74d1-55a5-47c5-a20c-7c4dc52c6e6a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 87).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8baa81d2a1ea5f08_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba51f46f-18e3-4c78-a19b-4ce7276ca560', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 87).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9e527466a33c9a12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f16c628-6aa1-428f-b0c0-563fd750ede0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 87).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '9c2dded8ce964db3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5365a2c9-f68c-4268-8fa2-5784607364e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 87).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e24126ee0960fbad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('597fff29-3e28-4fd2-ae78-7f81f0acfbe0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 87).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '416b001026c629bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f9eaf00-10bb-4ba3-9331-d9dff08a1d48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 87).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fd46d0d08cb7ea27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5c3b3c9-a7f7-4900-b16d-0ab18d3ba63f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 87).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '54e034954bfb10f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1ce8f80-fa96-417c-8947-cad713219076', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 87).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '73a0143f7ac9ccf6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc050ef8-9a94-4374-bf28-e61f80eca406', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 87).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '742523d8c5be4abc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22c0f9c6-bdba-4448-85a9-39da60c4945e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 87).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e6e1689beb7de38b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3ac5a9e-e156-48cf-955f-accf5a68d06b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 87).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f03c0a5e86dba1a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41c5f6c1-592e-4cbb-973b-10c71e8cb793', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 87).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c241170b1ac44065_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('464b6ebe-da74-4a21-ae7d-d44cd3fb92e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 87).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c2721df121959c30_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3ebadf3-cc6f-4c0e-b093-c07864720e61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 87).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '999f3574d6216987_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cb92007-b058-49dd-a020-3a708f5e741d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 87).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8cccc97c2da385f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef127a70-8ec1-4dd9-a3da-a4ab0a4fd5a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 87).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd226c852033974ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0ba672d-ed7f-41a6-9b87-bdb92c9f1cf0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 87).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '98dffd25d1534ee2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48f5e826-8eeb-4e3f-b4bf-bbc2749664a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 87).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '97eca515d14850d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('035b9fa9-7a58-44cd-8303-de8897935d04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 87).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '05d2e93d1e88d9b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4beed9b2-0477-46a5-acf3-c2e1646dccaf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 87).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8f90df4154ad2f13_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d5e23cc-ed57-47c2-ac4b-4f0e79d23a58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 87).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f0e4567b6fed3a72_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcf1bb28-579e-41c7-8cd4-9735b3e22471', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 87).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c4db81cf262e40e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a69595e7-2be3-4b5d-b8a5-59512e923f35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 87).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 87).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '37f828b25de3819e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f3d7083-3a95-4bc3-82a6-62212371771d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 88).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd0c92f93b087b0ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb9f79c0-b8b8-424b-b8ba-ac3481b6096d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 88).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 88).', '{}', 'Networking Fundamentals', 14.0, '0f8ca956e65e2353_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d932029-0d49-43ca-9340-240213a4222c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 88).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 88).', '{}', 'Networking Fundamentals', 14.0, '1bc3e9d61ea4e375_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebea0b4c-d247-42ea-a7ab-a9e0d6bd8dcf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 88).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 88).', '{}', 'Networking Fundamentals', 12.0, 'e56954c3ea78d4f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3985479f-2941-4c5b-ae96-6350f47c0607', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 88).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 88).', '{}', 'Networking Fundamentals', 14.0, '66ebd10fa3aadf31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60cf727e-c125-4983-9860-fc88ea56b25a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 88).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '11b432a34d01596e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db00c547-4404-4558-be56-87b0137cd4b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 88).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'eec6651c992c1d14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d70b93b-ee1c-47ee-8473-3a6f223e5ba9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 88).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '059a4ff7cc2887f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c1c518e-0018-4736-955f-4776443f7887', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 88).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cf58033071fb8460_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f28bcbef-5e73-4087-bcb7-f7ebcfcb9835', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 88).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '1c6c7acb1be7a43e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('679444a6-1608-4bc0-886a-690c09f7548b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 88).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd8624a975a70b35d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c9126af-3951-432e-8de4-950be4b1124d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 88).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a504f65357aa1ca3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdd306d9-f0cd-4e73-8428-788219ca64ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 88).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4d6b2532abece701_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb48b27f-dd68-4d61-8232-df4bb412bafc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 88).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6c50ee1264002fc3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9edefc7d-7807-475a-a7fa-a5c93a72d0db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 88).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0d5c192c8fefe39f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ce650d8-7988-492f-88ae-d82373a098d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 88).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '23f0f6abd8574f36_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a001784e-0061-435b-97dd-580608c399d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 88).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '8fef08d8b5e0c9f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddc4a0f0-6373-430f-95d6-3f06ca45f1c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 88).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '7941698a4c63e6f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf2e0f0c-e950-4d8a-ae23-8e538c4d1822', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 88).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1aec9c7b942edc3e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe792dbf-4c44-44c2-ba35-3b195fc40614', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 88).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'dd2017fe86d0126e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b27148c2-9e72-4ff1-a944-78d2aa2d8c1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 88).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9449c45a12277cc7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78e7eb6b-89fd-4f6e-bd3b-11d18379f4a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 88).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8c68cd249b833580_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26123966-67f2-486f-9973-ec8ac489b15e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 88).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '861e7e7e8cf5a465_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe2f8ec1-22e2-4717-9c64-16fe5baa773d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 88).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f7a08f2067da7f66_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7506338-4c99-4139-872c-f3dfaa5815ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 88).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f6581419a7c94db1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('babd7c2f-943a-4530-9ee7-ee1080778771', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 88).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b9d09340b2e4ad2c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f047521-c85b-4a2d-868a-4edec5ce2684', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 88).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '1d954671d8c976cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7699d66-c578-4784-bd04-75c811269a4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 88).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '03db63a40db5022b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('678161e6-2129-4e8a-9515-0d0fa6968c96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 88).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0c249ae3bc1600e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ad25a9b-ead4-4484-a74a-64da8812067a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 88).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 88).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '368d30aec7ebf8ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('306b5fba-c2ed-4e44-adab-67dc67a12942', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 89).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '35767d7ef993fa85_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cec6286-52c5-47b3-bf9a-3efa91e45b8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 89).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 89).', '{}', 'Networking Fundamentals', 14.0, '53a6ea9c08d9b295_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d477d01c-6f18-4121-a6f5-e2abd028335b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 89).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 89).', '{}', 'Networking Fundamentals', 14.0, 'e5d8fad81751fb5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c6e182e-bfd9-4527-8594-3f668c541eec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 89).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 89).', '{}', 'Networking Fundamentals', 12.0, 'c48c663b2f134675_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d91283e-4b32-4bdb-aae7-50773bb5b0c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 89).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 89).', '{}', 'Networking Fundamentals', 14.0, 'dbbcbc46233ae72d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d89d41a5-4019-41f8-b394-4d0c0b3de51c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 89).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '5a3a196cd284674b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be808a37-47b7-42d3-920c-0d6387fb51bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 89).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fccc4a00759c4be4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9adf9d7-d846-4d65-af39-eadda3d66efa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 89).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cbd9b82bdadda941_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec64584d-7f11-49a3-a1cb-faca1cdaaea7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 89).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b454d271e249d08f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed5d3ae9-f2ad-4c1b-9d9d-3a96dc142b10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 89).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7e9e3dc3514f5ccf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('596383f0-5e2b-4e23-beab-ceb68256e1ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 89).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ca45bb626dfe75e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7279ab6c-3848-4966-a5ba-a30f0558b302', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 89).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0dbe1b5b4f165b7f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9093023a-27b6-4171-ac89-aa257b943959', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 89).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ffc6a59d70c80b61_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff7b3490-b8ed-4402-a128-4675439557f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 89).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8bf4c4c6bd32d9ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bbe67af-a971-4cb6-a1cd-39ce7cf34071', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 89).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ca0a2f4b30b3f20f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49929610-6c20-487e-99ed-db21cf8e4745', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 89).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fc23f6160028bf66_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f12deb8-948f-456c-8ee9-3a40599b4af9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 89).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ad07f23c5aa89f1c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0a5a5a7-3659-4d94-8beb-e309d4d52bf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 89).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4361dfa71d196533_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('424a0c5f-93e8-46ad-b690-07e93fee3217', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 89).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '8b998386e3ef1284_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfc0f19e-8d6e-4eef-8cdd-76be5d74daf2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 89).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fa7471a9f00f3b48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1c6cac2-eced-432b-8e48-4420a75c02aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 89).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5d758c9063a92b6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81548622-dd8d-4c56-8f6a-e5d6eab87cba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 89).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0e716aacd223c337_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5437a9aa-88f0-4d0d-b897-aed656eefc43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 89).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e3bb260b2f38c6ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9998c2d1-e87d-46fe-81d3-8bc086b59c62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 89).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '04ba33216369a281_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c0dccc0-b682-4d37-a36f-36cccddffea0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 89).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '805de2096d3f8b84_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b8e5536-d046-498a-aa7d-9ca53394b51f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 89).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'eaaeb59577f2bedc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e96ea03f-990d-4aff-b00d-7e6761853e24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 89).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5a028669023cfa7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69638521-8bbd-4fca-a9e3-837103af4f0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 89).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '54908df34229cff2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ef8c9e6-8776-414c-956b-8ff4b0333562', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 89).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f2fe9a55eac98028_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8c663be-f1b2-4b7d-af7a-ed92c0c47090', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 89).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 89).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c2385bdffff0a5b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('394ec641-ba59-48a1-843b-4adda15c630d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 90).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '868146166ed68c4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b08c26e-a008-47fa-88c1-bd6003909e94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 90).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 90).', '{}', 'Networking Fundamentals', 14.0, '46646d6a90531acf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ddaf775-6976-4a02-9aaf-ab09303cbe83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 90).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 90).', '{}', 'Networking Fundamentals', 14.0, 'db1ea56979a39c4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de72b76b-3e3e-4868-8f92-0d88fa41f390', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 90).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 90).', '{}', 'Networking Fundamentals', 12.0, 'e0c812307952578b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aed0ba20-4962-4811-a813-916170f28dd8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 90).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 90).', '{}', 'Networking Fundamentals', 14.0, '8c5817cbe4e4220e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2acc381-9424-4bf1-bb5a-0541320f94f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 90).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '98e390e05bc6efc5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90e2a12f-1485-4aff-852f-e46ecd5ff114', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 90).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'faae10ce37593a43_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e4c326e-b90d-4865-8ae1-74ce779e1639', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 90).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4bd03814ad94acd0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('447eea3f-5bb5-40da-b1ef-0fe815f696ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 90).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9589ac4f7701784a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce0d8a1e-ef97-4cac-8702-8a7733513e51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 90).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '4dfa72e7679389c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70bf2430-9ac0-4845-b30e-75f0a157d8c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 90).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ff220af8575cc230_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d115d1d-50e1-4ef7-bfff-b5c8c1a2afc2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 90).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c498eef7a30f3d11_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e14440b1-0155-41b1-ad30-721ec718685c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 90).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f509c19961077f90_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b0d25df-9717-4452-b4c8-2a0accacc2ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 90).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2f96ac8c5a454bbe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae2e889a-fe97-4736-bf2a-d35765689a51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 90).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c2d6862f3f3a2315_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('224e9231-2b92-4057-9385-ce9c72e70d84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 90).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'dfbde43ed61e0d99_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7f430a9-89b6-4f3a-80ee-c8b8d25c3997', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 90).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '36570d738a5e90e9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ffa3290-f256-4ba5-9cfe-bd6beb346aa4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 90).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '43b53ed532bd71bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5148e2c7-3b50-45b6-ae47-0c1aeafc6a84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 90).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '20edd82c8059807a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba8ff260-bf97-4d9b-9898-252c44fdd1f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 90).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0889ab7be8412e52_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('131350fd-fc30-4875-a89f-445559d464b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 90).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4a96cdbef52d3416_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54b07165-dfca-4a66-ab31-6d17953d3719', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 90).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b3a6a42a037094f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6722e774-b6ef-4406-8abd-0af82bf48685', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 90).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c8594e1817084653_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4674e43-1b23-4d7f-be7b-fff838a49831', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 90).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '581740cf3380a95d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cfc01a1-373e-4f1b-9021-68ca10c98de4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 90).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd837f752110b195c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3658194-92a1-4988-921b-33cb4a229fe8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 90).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3f36a049c9d0f1f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae1347fa-f6a7-42a0-b109-ab8f9e858956', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 90).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'fcab71b30f2fe5a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('518fc293-3527-4de5-9df0-1d9db9af3ffa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 90).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f18919eac30f3936_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c339355d-9485-48e0-bdf6-2b21d9058ae2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 90).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6ff82b79cc7fb27b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a3bc523-1735-457a-9733-57b794ace8c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 90).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 90).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5e9412f9e0119ba2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e60de736-7b2c-48da-ab62-f0815b0b4f2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 91).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '0735714ff8f9283e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dc28d65-390d-40d2-9513-44db4387213f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 91).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 91).', '{}', 'Networking Fundamentals', 14.0, '452fd8dbaf127a0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92da05cc-6f5b-496d-9e70-fe6f770357ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 91).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 91).', '{}', 'Networking Fundamentals', 14.0, '9215c2324b787c87_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08e8c664-49c3-4c8f-b9da-19ef7f5e6ddf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 91).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 91).', '{}', 'Networking Fundamentals', 12.0, '82ee3e9ffae9d7aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4fb5362-b571-486f-b44a-9524314bebe4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 91).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 91).', '{}', 'Networking Fundamentals', 14.0, 'e9c303b13b9b56e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50404528-16b7-4740-b600-31c2c8ea66de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 91).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '9dbc76a2e56e1f27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60df4f27-ce5c-401a-95fc-44ff160ef48e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 91).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '188b9802b7a2eba3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f3d1e26-490a-4aa4-a596-273deef94e43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 91).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '557696f770facbcb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e98f269-e43b-4815-8da2-df1cbb0b1bfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 91).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0b2622f5a48649a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6992c5a-f6a8-483e-9e0b-61e6484832cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 91).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'af7cee6b3919802f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f04c940-3db0-4188-8d51-dd435e453b36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 91).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e91dbc6be2b70136_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d80a78e8-d30a-477e-94ae-c59cafcf2702', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 91).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '14847af8a0f93898_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1873d71f-014a-416c-8469-47c79657c95c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 91).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '43081537683be3f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ec672b3-efd1-497f-b345-4a6792e85348', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 91).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4a8ffda992995537_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7873b859-6668-4d04-9be1-361d58738e93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 91).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c7add1aa3fb68809_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0ab7e2e-7740-4e4b-8f20-0b73098913ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 91).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bdd9a58e409f5d48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3426244-69c8-4462-9ca0-5ad6d35d39b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 91).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '2f2243ddb92f21d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9fcaa62-b552-45ad-a334-d289b43bf7ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 91).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c09e3b2e844827f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40a8bdc5-241c-4eeb-9119-dfefd9fc26c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 91).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f42a546094ac6914_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('031f53ba-68ce-4dca-bde2-be18b3eb153d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 91).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c68f433273ecbf39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f208d245-77de-42ba-baca-698558be2483', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 91).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '920444203ad2a35c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c7f8fe0-c81c-4dea-8979-dc5539e7fb10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 91).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9d70789b488b5c0e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0da4221a-5315-418a-89fa-0e4d18c099ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 91).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0c3da97c8888f4cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79e1fd85-0928-4503-9bc4-7605b5f0a854', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 91).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '9de817b5f06d96ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a9807f6-7d93-4ebf-9712-f72110da0721', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 91).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0e4a6e608e86d1c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c03b2d59-18b5-471d-b413-588456426032', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 91).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5d762df5c7d41d7c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a87c8d3-458f-4ded-9d2d-c08f127c5b6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 91).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e51b28d3de0d794f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbdba18d-304b-41ba-b2ca-65668fb4122e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 91).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'dca3e48505a933aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd8d99cc-416a-4995-9487-df60107fe752', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 91).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '63d2651e18321923_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c7a9ac4-1f68-409f-9ac1-b2e445a6c281', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 91).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 91).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '38dd1c00d5f7ca15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65ffaeb5-1925-4029-b443-9dd5fcb0f40b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 92).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ec620cb84a199760_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('933a7017-8dae-4d05-9594-9db58707fc16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 92).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 92).', '{}', 'Networking Fundamentals', 14.0, '5b5f73ccada9f1d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ab74966-3425-49f4-993a-81ca90c3c6de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 92).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 92).', '{}', 'Networking Fundamentals', 14.0, 'e4a5b9e555d51077_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b709d75b-b061-4f16-a8e4-32dd3d96d4dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 92).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 92).', '{}', 'Networking Fundamentals', 12.0, 'f42f88492fd48b43_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4de1e3b8-fd56-4e34-b6b3-8ed10e768bf1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 92).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 92).', '{}', 'Networking Fundamentals', 14.0, 'fb2e39cecf7bc0ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('566f965d-eb56-43f3-8b51-1a6b05fd1c00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 92).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'fe259d7811e2dd16_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d339a06c-ec66-464c-88a1-1676b0936594', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 92).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '805e0a7e6cf5055b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03cf7b09-418f-4fe6-ac7e-3e9e84f6483b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 92).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2bf8b1dec00ec0fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44499f38-0ece-4efd-84dd-495b74c50c8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 92).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5146ee2cc20b13aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bfe1524-0a25-41cb-8615-725fa7668d3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 92).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3aff7a33fb185176_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bc51f7d-44a3-4119-bda6-cc558bd62d30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 92).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c58aa005ffde5320_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('deeb1e00-828c-4623-a4a9-1389b8621918', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 92).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6691aadf83659c83_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0660239e-5020-4d13-b980-6eae503e1896', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 92).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '76528cd53425b981_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cde0d17b-ae50-4ab9-b175-283c944576a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 92).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '24b921084d28892b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dbf37c0-5df5-438f-9235-6d10f7ad449b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 92).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '068e73f2f324fc39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b428e223-9bee-4f9a-8156-f17bfed8e3ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 92).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1bda3ca12603511c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0364cf65-fd7b-46a8-9eef-95214f81ce1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 92).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'df11d50b22716352_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8daeff2-d875-4087-89bd-672408655063', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 92).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e6e7b430aa2818b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('051635be-f860-4d71-98ec-a2e89e8c8996', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 92).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd616c0821419c9ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6d6c009-bb34-4258-a647-9030a70591d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 92).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e9b93e5be2a917f7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('610714af-8cf5-4b49-85a2-22b30e202d33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 92).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0eba47c31b149ae3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03b9dfce-574f-49a8-9add-0b7ff0fc57cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 92).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '77173bb2e2ec40fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c09cee4-ac76-46d5-8740-8b853ac51039', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 92).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c6e133a233e37676_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eb2d613-c61e-4bac-9ef5-fd1e2e1c4725', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 92).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fad4953c004bdf55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec73c3b2-4c78-4681-b005-8dd7a0f29735', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 92).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c9318218f83e5003_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7554dc0a-e203-47ff-91de-8e8bfbe75107', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 92).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '076af6a00861fb7c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e602fa71-b125-45c3-8ee8-eb618fdb9dcf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 92).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'dacf8777c93b507b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ab00990-2163-4ad6-b26f-036892f49768', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 92).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'fa03294577462368_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a26f34a-91fe-434b-bd9e-97c103ae9f29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 92).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd7234475e4ae13cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('431166ad-0928-435f-9be2-208cf8ba76a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 92).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 92).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a8159d83431f1f6a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bc0f4d2-4f5f-452a-91a7-9f0560cea307', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 93).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '39141b37bbf6d85c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0d7c725-4045-4c5d-94b1-caf124c4e88e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 93).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 93).', '{}', 'Networking Fundamentals', 14.0, '60c27627f22863f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1de1ebec-e5c1-43b2-b973-03e9bf953caf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 93).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 93).', '{}', 'Networking Fundamentals', 14.0, '37a8288ca0ce1cac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ff3faa0-3a18-42b5-94a9-3af27e64aaba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 93).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 93).', '{}', 'Networking Fundamentals', 12.0, 'a1fda4074661a9d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a71273eb-c22f-4ad0-8d13-5a883de56968', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 93).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 93).', '{}', 'Networking Fundamentals', 14.0, 'a98f5ea820c43495_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('feea9536-068d-45f4-bca3-d9617ac943c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 93).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '57edabb3cc376d1c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dff5245-47a0-43d1-8b55-dd9b6e2ea0e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 93).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '759f78c5e5516aa2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78bdae37-cdee-420e-a68f-42534973c065', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 93).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '60ef4d4add2a22fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22923674-c0b9-482e-b7dc-18aefc87f476', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 93).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a93a3be36cecfac6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e6f7017-e858-42bf-8d8c-e1c4a206ab85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 93).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '52239085ec89693a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bd907ae-3f68-40d8-b963-078a3a78b4e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 93).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ed13e763ece6be91_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('484ddc96-75a7-45a1-9ff2-6e1e6ca39925', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 93).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3048d0a604dacecf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88ce7985-2fc6-4bcc-bc9b-f478e19ee4ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 93).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'de542b62bc7b01dd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f15110f-4415-4f86-be56-4c5273d5d0f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 93).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '98af642a757ca44a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa76c4ec-5aea-4cc3-8cc3-d133b817abc4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 93).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ba6acff074387528_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5c20d9a-613f-4ead-a4a8-0c5fe0b59a53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 93).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8e58bea9c592787c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4c0778c-c637-4a48-a886-100a863f5f4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 93).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '87155570fdd4595b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('443a5bde-2b35-488f-ba01-a05172a90a4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 93).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '43d44f08c417a34b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('160239cf-0be2-4725-a788-28ef5cff3a25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 93).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f6f471fa4e91110f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a94790a6-9e9e-468b-8202-07d25cc328d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 93).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f2a1c44724856e5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('608adc4f-f34c-4509-be8f-85b35296e855', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 93).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0bb72121571c43b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad3c40eb-0424-4e86-989d-d5848e3c1480', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 93).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '751841dddcd255dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d6c689f-51d9-49c0-b8c3-b71f447ae82e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 93).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'eb99da0341e1e5f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87b123d4-76f6-4af5-85f9-5d2c6bf0b520', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 93).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'a90d129531980c5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10d35ab7-ebaa-42b6-9e01-d4f0d4a7a7bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 93).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '93f789b341749e79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72bf8893-b2d6-4830-a9d2-eac2e25e1723', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 93).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ccfbb6b0bbb21b1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('768767b1-db13-4529-a283-97ad5b88a557', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 93).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'fdbbe9f6cae44f64_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ab4f705-e8b2-4881-9084-930e80d6a710', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 93).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '312df24ffe412788_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30c01018-ca75-4a4d-adb0-30a5f3618d7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 93).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a225b70fc2fb5344_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('492c87f0-2f54-4768-9702-08f361d10776', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 93).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 93).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'aadac91b8f312f93_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e42f6f96-b383-414b-982e-37a4b4852148', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 94).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3bab314e7fd8bbe1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4362b259-37cb-48d9-9e0e-4f8dc489707b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 94).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 94).', '{}', 'Networking Fundamentals', 14.0, 'c70cb7e03c49dc0b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8deee1d-105b-4127-bea1-4a3f30df156e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 94).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 94).', '{}', 'Networking Fundamentals', 14.0, '34a43d69d65c2c2a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8db6ac4b-7851-4fb1-8f35-9e6d12561332', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 94).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 94).', '{}', 'Networking Fundamentals', 12.0, '39b399cf384593f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dea7ee0d-8774-43f4-9356-4445154124fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 94).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 94).', '{}', 'Networking Fundamentals', 14.0, 'bae36fbf5f99dcc5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc06ddb6-3be3-4050-b2ab-533c6d934608', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 94).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b436a3679e4fec16_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3dd7093-03f2-4e20-affc-06a1716e0350', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 94).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a3d95773419cbb9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('deda829f-201a-43c7-96d9-0faa7afe7a5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 94).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4fb68c937cae7b86_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c95d1d7a-44dc-4a66-bdb0-37ccc3ac4238', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 94).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4d3756ee3e128264_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e48984a8-8ace-4deb-a14a-a0e1ac17801e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 94).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '558445ff1a008682_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dabcef8-45c3-49fe-ae43-4565044ba437', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 94).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4bf0491d4e69d24b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7014f15-bf6b-4b92-9bd4-56cfdacc5905', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 94).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e1eeec016d8a8e27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47ceae82-c0a7-463f-bce3-10bc5590b56c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 94).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'bcf09e853738642c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e70d8cf9-a7ac-48aa-82df-c7410f2389d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 94).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5886026787a0fdb9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30c31c42-dc71-43ce-b629-96b4e60a5f91', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 94).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '126a5a4ad4468357_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9ea59fb-b3c7-440e-8571-220df34ce647', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 94).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3c6f8fd1138454f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd731695-5eb9-4f62-970c-7e0ea1c45762', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 94).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '45c0849346d430db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbd9f13f-3646-489b-9da6-91cea3c29757', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 94).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '364d7f0333dfae9d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91f9f611-810a-421f-83ea-8fdc2cfc8473', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 94).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'fb8e9729e3329c35_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf0cd24e-f43e-4c0e-80d2-4ef2a4501f77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 94).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e57d97fc8a69ea55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9400f53-098e-44ad-8324-5d76aa7c7347', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 94).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8a41f6d327546507_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('567b25d1-36bd-4b95-a54e-ebdbb93480f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 94).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'cb9004632273ed15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a2c0210-5d2b-44fe-b06a-77d6d44c4528', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 94).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '119725cad6641fda_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19030aa2-4325-4fd2-840b-711bc531a290', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 94).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c79739b1074ba101_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0431cae-8a8a-4ad4-b5a1-756b5e8de499', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 94).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '029c7acbd10e4c8c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bc306fc-22c8-4485-8aa2-56873c88ef19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 94).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a1b26a0c2e0f64c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('643c3fce-83c4-4842-b109-3f80f69b18c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 94).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'dbea1f3b5eac181b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1052b94b-88a6-4cd3-9cd9-3e124a24995d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 94).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '431985aef046ca1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0030dbfb-704a-4f8f-872a-f00914f7b770', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 94).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3355cbb8cfc1fe12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e63e2c88-892e-47a3-aa3e-ac726cc323f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 94).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 94).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0326e7ee7e0b5c39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70c1877b-9004-4a37-9d57-350a85f06e8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 95).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '165a9879dae931c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01056892-b1f5-4a21-ba85-a3bf5914bb3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 95).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 95).', '{}', 'Networking Fundamentals', 14.0, '4013379c697a4f31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7131278-7fda-43a4-bcf2-f2d3059f7c6d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 95).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 95).', '{}', 'Networking Fundamentals', 14.0, '349eabb8a21da87e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f332d71-703c-406e-8057-99a77e759820', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 95).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 95).', '{}', 'Networking Fundamentals', 12.0, 'f1fa6efcd85bc8d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2b93272-01f9-4d15-a079-40afddc92f66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 95).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 95).', '{}', 'Networking Fundamentals', 14.0, 'dab029c1bbec6a12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e71af92-b60a-4039-8b2c-3d121eaeef61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 95).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '7510727b04239fe5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84325b01-7ff3-476e-b4d2-d7ee6e856a12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 95).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd10aa70e0a58cb20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7f0d870-38c6-4437-992d-212650f85884', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 95).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4dc73ef6ea16114e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2403e258-60e0-4ba2-a79d-3145bd12e61c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 95).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '74e5cc1fe97898d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebb47871-065d-46bb-b024-12be2e553975', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 95).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '362ee06cff50f539_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de2c5c1f-715a-4946-b752-3b6c5d92c571', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 95).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6588e422e8b219ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b84b604-b394-4550-85b8-9595895f30f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 95).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '238fcc134e67aa0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b315ea8e-59aa-442d-ad7c-346c72545b6d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 95).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd3a446459b732752_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c86fbd7-7e1a-4b7e-b840-664e843a04fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 95).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e66599d49adfff46_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ccbcefa-7b2a-463b-b4c0-8e971be80277', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 95).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '11745a91e25f78d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('359f5c49-9330-49b8-a048-de6333790668', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 95).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9b58914f3c44e7a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e0d1560-f10b-423a-8d8b-1ae110ebf9fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 95).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ca8a9c180fb004de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0656f77e-2c0d-48a3-96b5-bd0af08892e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 95).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '2b9bfe7452ccd5a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4277c36-5c82-448e-9ce5-e8f50e9cfc72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 95).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3c46a75a64b9a481_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c75d028d-595f-4831-a06b-c8d11bb2e3f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 95).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f9da8a55349104ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be0a163b-14ef-4494-b80c-c03d140b1969', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 95).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '839ec6a409f13bab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d4473e3-6b37-481b-8a4c-2bc3d32c65db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 95).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '373ca9dc71ae30e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('049fc1ab-1577-4eee-ae08-8a9a60db48b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 95).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bedbd224b4402f47_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9eb50c3-493f-4b22-b174-a227c576b9d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 95).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4105e3d667664ffb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd0cf21a-dce6-484c-a514-2a06feabd9bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 95).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '391585d52d0a04ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77145bbb-63fe-4157-b28c-0c38eb642c64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 95).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '109c8a1872bd35b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfaeb8bc-6ea5-42e7-a4ee-cc5659758596', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 95).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a558b77bc37c4e4f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6ed4dbe-3622-46c3-bd4d-2178a22a03f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 95).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6865ee6b36c9616a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e05fdd11-7c24-4885-a7f9-3e4550a877ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 95).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9d7dde097cad3b0e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3825372c-f6d5-440d-83eb-f24197863914', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 95).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 95).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '218935620192160f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('759ab2d8-1f7e-4d9f-a6da-a537dbefea09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 96).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a605a09bf3992c7f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20ef5675-f06a-48bc-a1de-e9d8b4d1275e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 96).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 96).', '{}', 'Networking Fundamentals', 14.0, '5eaebc79080c032b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f28f54f-4342-46df-8415-29ef25a62e5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 96).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 96).', '{}', 'Networking Fundamentals', 14.0, '32a9f60a8a637f0f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3f272e8-113a-4b96-b24b-63e633283057', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 96).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 96).', '{}', 'Networking Fundamentals', 12.0, 'b2bee76c24a910de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('875442f7-7418-4527-98f6-3fe5d54af3a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 96).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 96).', '{}', 'Networking Fundamentals', 14.0, '8c79f71501b916bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f8dc4fd-65f8-4301-a921-56ffc02b514f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 96).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1478d311433995a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c70d2859-71d2-412e-964d-f5f64bdd9e22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 96).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '82dd7cb71d65b263_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a0f8a87-0127-4833-ab1c-fced02e54b64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 96).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '242fc98f00e67d11_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4aa7f564-f967-4e0f-bc6d-ece0eaf20a48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 96).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c237559a0d528784_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8deb6f7c-7f19-4efa-b5d0-e607898852cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 96).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '14ce98c2dcb4502a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e9ae119-5453-48ac-97d7-0ad74469a9cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 96).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7b769e92a2abcd85_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a74b7266-d265-4ff8-90bb-289bd541c9b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 96).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c42019e8e9980cf3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74e18fff-3332-47da-a73b-d952382b2a09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 96).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3c672ae3bbc34d7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a0fd06c-677c-4995-b7a4-069b41ad520a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 96).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2ffc9c93a708fcde_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fa665e9-2905-496e-91b0-8a4a4e4bad16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 96).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4b76637d075c23ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e118865-ef6f-4640-83f1-55205fc5c4b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 96).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '497b7ab7aa4b59b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24243c99-86fb-4c34-ab41-4917b287bb14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 96).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd1075037183d2132_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fc2b9fc-718e-4793-b18e-65d7d87ceb1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 96).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4775f2aaa582407c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0aae956-7225-43f1-9861-5d38b4704ca7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 96).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c783b66bc1652a44_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3e4f412-a92e-4802-adba-794865ab1cf3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 96).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '077da3e6e8fcc268_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('685cd7b4-9915-43f1-a915-513c7e1952a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 96).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '748e04f7274beb45_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01a73b1c-5c21-4c34-a0f1-cdb3f42e8e93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 96).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '699a51292f359055_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cc2ff4a-e2e5-4571-92b9-7bc27e856a24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 96).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e85e7a93c1502d81_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b91e14db-1917-4b50-ab98-e5f88db44b27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 96).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ff6f6ecf6356c305_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbca2067-b3da-42fe-aaa2-811e33b64d78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 96).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cf2e39547587e818_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29c7b98c-b261-4d5b-ae1f-f0f3ecf38f67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 96).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b57af918553bdeda_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fe8fda7-c74a-43cd-a4e3-96978f73b8ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 96).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '6b291ad8b06277ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cae7c4d9-712e-4ad9-b613-ed6a6af442c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 96).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '4c2e03015fa30125_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e47430aa-7fda-435d-8a56-80bbbf6e3276', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 96).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1bc534474488299c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50f0c32a-f2d7-4f29-845f-9904cf2adaf7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 96).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 96).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2162f5e65323db6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b4b0e03-f84b-43ff-a5d8-b9c97eb5a49c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 97).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'c58910df8b448d99_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fbdd04c-f6be-435c-9720-68106e5ab5d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 97).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 97).', '{}', 'Networking Fundamentals', 14.0, '2674eb64fd79fdf4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b547790-88c9-4eec-bb6a-0d8edb918858', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 97).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 97).', '{}', 'Networking Fundamentals', 14.0, '19142ae11670b572_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d09a8fb6-ed92-454b-8924-dea859fe9a1d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 97).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 97).', '{}', 'Networking Fundamentals', 12.0, '42cdc1b7118bcfab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76948900-247e-43cd-be15-b7d699c0c3ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 97).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 97).', '{}', 'Networking Fundamentals', 14.0, '59a65a54c43a90d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84ca4dbc-a8f0-47f5-97b3-b769b69bc5df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 97).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '0d28f17e0c00ed42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0e91ecd-b34c-476a-ac11-be3ed60c053a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 97).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f9910e5b03d2f485_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7714954b-c8dc-47b3-8ee2-471ffa5425fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 97).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '430f37106b58c832_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be763be1-0546-4db7-b637-f3717d57fd42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 97).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'eb3ebf3549633784_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85daad6e-0678-45d6-a270-12ef1b4b613d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 97).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'bc97cf71d703c818_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9229ac53-8833-4926-abc7-8b290d0d7dfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 97).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd4c4f7a0e2434d06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88cf6f8f-7b68-49f7-9bc4-2d08d659b1e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 97).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fc5473e279accb14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2766aeec-0f29-4333-aaa5-d803a725f6c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 97).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '64991503154178a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24bc92a1-7b9d-49cc-a450-9f90535a48b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 97).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0359b8724887a919_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1c57a79-199c-4176-9476-45920af37289', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 97).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5f7645e056e66f6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('358c4b56-b7ca-4381-b2a6-b36e23a2dba7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 97).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd5283e8aaf798b6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b60581aa-02bb-4999-8dec-10d12a9ab23c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 97).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'bbe7d67e3ff62f8b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16108605-ba8c-4c43-98e0-92faf8740449', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 97).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c98fe53785bec4de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d145cb8-7c53-4a1c-b53c-4e2caeccbe4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 97).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7f9495553b660356_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e5de8dc-10ab-4bc4-8c69-fe7f769625cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 97).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4ff56e5308daa89e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32599039-0781-431d-9a6e-77b2ef680bbe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 97).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4e1f7e73b01546f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('844e86e1-96c6-4b85-8743-29ef6c7209ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 97).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '725526caf11726d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdbd7c47-84e0-4b00-a409-59b409f45031', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 97).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '15c81db9982c73ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60becaa4-5729-434f-b777-f9cd7c26d45f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 97).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'cc3e533e64a84885_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('283ac4f9-3601-47e6-9eaf-577f6c3794fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 97).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bc35258f277e9815_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('770b4eed-a9d2-4cb0-9ac9-d616e517867c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 97).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a26f27c57de922dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0f2c6f2-0af0-4007-bb89-23e3de961c6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 97).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '61451e956dd0f2f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb45aa2b-6e68-4394-b88a-ff7ef2faf0fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 97).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '3438c5e353364c2e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad95163f-dfeb-48a5-ac9a-67b2fe963cf2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 97).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b29d96a049b2fdf9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f8becb2-5413-4540-9ab7-4755f2364ae5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 97).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 97).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '45ef70df350baf2e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28d0f0a3-4669-405c-9d78-d94132b5bba8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 98).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'bd437390f28f7ea8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('739a664b-ac16-43c6-af94-7c7180d631f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 98).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 98).', '{}', 'Networking Fundamentals', 14.0, 'a935086ad3b73afd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79b3d2ce-4b56-487e-a5e3-cf122439ea89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 98).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 98).', '{}', 'Networking Fundamentals', 14.0, 'a94fd1c98377a1f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd2d5d3a-61c5-4fb8-be71-2927c4a60f64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 98).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 98).', '{}', 'Networking Fundamentals', 12.0, '2c1391464a4efb92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('514f0276-9344-424d-b24b-bd69af9250ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 98).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 98).', '{}', 'Networking Fundamentals', 14.0, 'f851a1266de05c54_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ac42f6a-f3cc-4cd5-874d-170f4d968b28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 98).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd88239755cac9759_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb37bef2-5d65-4a48-a0ad-1adcef4b8d01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 98).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b7d0ba2cbb0b8fc2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('338538cf-6eb7-4c15-af56-53107d50f76e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 98).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '802b7e24297f3499_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64b1ee02-9524-4146-ae17-f43c3e4554e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 98).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '53017a302ea2f02e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c3887ba-3346-498c-99a9-73f3c377148f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 98).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '856036582d93fc48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21b29496-ba4c-43be-96e2-27dfd1a83ed1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 98).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a28713ede74c7b9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50c762e3-268b-40ac-8809-ea8825540aac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 98).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '40b2e14544444881_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2f09e57-5641-4258-a8d8-81a764000cdf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 98).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a17304d589a26d00_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1848f960-370b-483e-9f4a-f735d2873e15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 98).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3bd7f4449f28e23c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78dfabd4-60b8-4c68-9764-945433ac9667', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 98).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a4245dc041b5ae33_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed103c70-38c1-4727-8761-07ee2bb8188d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 98).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0d4b7eed702de0c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c23694bc-b7f5-48c8-ac84-2a9d28080702', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 98).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '21e604f14d39e3fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fd224b3-6eb6-439f-9f0f-bce299830161', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 98).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'cfed9278170bb15b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ae8d870-d8ee-459e-8ead-6c0ab190df2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 98).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '575546db3f25975f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3caddbcc-ff0a-4981-b9bc-09e11f82076a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 98).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6c6815bd790b4539_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('407e3caf-6423-4161-aa29-c588497b9c82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 98).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd780af5e72bbe04f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3af92c95-7c9f-4c65-8c09-0c709a2ebbb0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 98).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b10a3d001bce773e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14d70e1d-18af-41bf-903b-4b92cda8b2ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 98).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd72f6e9533dcdca1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d348170-6dbd-496f-9802-9dca7f0ac7c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 98).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'acb791163c0a34e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e0567dc-e3d1-4f30-9527-cd323ac52ab2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 98).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bcbf32d4c2a5bcef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('517eaa7c-f2d4-4866-b59e-8841d22b46f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 98).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4f376b071264c556_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bdc36ad-6a86-4dac-b4d6-c4790a1b83f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 98).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e8879f3df1e9a46b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aeaee901-3f4d-4fa9-8e54-6b417f7b1d92', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 98).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6d240795e1f8ed03_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea91c363-f4bc-4783-aa6b-4ff9d5dead72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 98).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0bc1e2f42784b760_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5665c2a6-93e4-4ce6-9b8d-d78665b9a835', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 98).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 98).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5f756a14fbf233a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be838c01-df04-41c7-bc94-fc2193b7ed02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 99).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '59623e8ebc73e5af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('608c623c-2308-4138-b9ea-a6f3b9c26985', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 99).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 99).', '{}', 'Networking Fundamentals', 14.0, '362084ba77ae84b6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6155a5a4-1749-4019-b46d-0bad92037449', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 99).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 99).', '{}', 'Networking Fundamentals', 14.0, 'dbd322fa3b075f41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dba393a-b666-4177-b9f4-f112b774fa74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 99).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 99).', '{}', 'Networking Fundamentals', 12.0, '06104b6b12312395_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7370b5dd-fad6-4d15-8881-66973afb6825', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 99).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 99).', '{}', 'Networking Fundamentals', 14.0, '846fc11ae6b27b4f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea64d7a1-4b6f-4eda-9b23-b1c9a357f5a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 99).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b7a5ed870c230d2e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a77ed412-0dcb-4768-87a6-378b966faff9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 99).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '78d1c3286acf72a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('922f7ee3-4662-466e-906c-8cca7edc6505', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 99).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ae21aa78b8b74520_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c746818f-8ca1-4b55-a960-005a276de562', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 99).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd93e0a9aaea697ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f865d8c8-b934-4dd9-8124-f0ba352c686a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 99).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '6e2c16fa6e4047ff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07d31b35-e7ff-4c19-a564-528470b28b7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 99).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e975db8755e0633e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27b8431d-cad1-47f2-a7dd-3c2da0470342', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 99).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '815afc7b40a9dc5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75f3ff3f-9f53-408e-82f4-bef33bdfbbc7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 99).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7a32755a5e17e505_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b43b7a3c-5d3e-4911-a58d-8bed88fa181c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 99).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'de8cc12e372f1860_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c89b4c85-b097-48e9-9c27-7dcc888f2f09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 99).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '98c224d7dae26fa4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c882027-ff04-4821-bfcb-f02142c4cc5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 99).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0f6cdf848e806350_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cf83c48-e92b-4991-8e34-faa86c92ae15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 99).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9dd3dc49f31c83a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0159fc06-3101-46f1-8ded-64ed0119da35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 99).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f6defd75231e332e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('accfbeac-1dcf-4fb5-aa17-fab92c1d5d30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 99).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '47ea88ec6148be5a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51102c74-1ae2-45c7-94b1-4da184611e8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 99).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3fb0bc0daf0208cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61dc2286-4298-4d74-bd7c-9b5059af6e0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 99).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '23ce2fca5d2a5117_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b42d3702-5de5-4e7d-bdea-e60d3ffe5cfa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 99).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2c2a64fb98e1ea10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c88f384f-5fc6-4eaa-8861-ff99b8f7ef67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 99).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0bd817bb9c60a0df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce6f34bf-a101-423b-93a5-504ebb17025f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 99).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4f18c7ca1338e817_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c55f1cd0-0926-4fa3-beb0-7b32dc212842', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 99).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3db0d136e86187a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2255397-d526-4d15-b66d-b567a8b50269', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 99).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'aaab46d4117b63b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d05f65b0-84c1-4f7a-8724-8bf28b54bda0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 99).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '3d72f2df055c2fb4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccf06ee3-6d9a-427c-bb16-a6b9562a6b5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 99).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '1bc277753a756e18_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ee689c6-ef9f-470e-bb00-812f4f2dc4e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 99).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd735de713d1644d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d449c8c-016a-4eac-9aa5-85f857eb38a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 99).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 99).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7ad689b701dbc00b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60a857b2-37b5-4b4e-a958-5c18c38527a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 100).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b91dcfa4e74d5d4f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('273268eb-4844-498f-8552-6ef497c6bfa3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 100).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses (Variant 100).', '{}', 'Networking Fundamentals', 14.0, '9ba4a0fc45c038b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a08fe62d-5289-4c63-9862-6997997d1926', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 100).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses (Variant 100).', '{}', 'Networking Fundamentals', 14.0, '85d545c9cdb4ad7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9130451-229e-4238-8eb5-ea3cd7c98675', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 100).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs (Variant 100).', '{}', 'Networking Fundamentals', 12.0, '400ce8228e078106_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7606b01b-8375-484b-ad08-8a3fb084dc07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 100).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment (Variant 100).', '{}', 'Networking Fundamentals', 14.0, '72658bfc7f18c4af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c8e1e38-4b37-4f97-b7a8-3e53a3ff42b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 100).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '617f76fde55a9af0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d26e6d53-62c9-4e0e-8490-8819c23da2ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 100).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b2212478ecfa54d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad3d47ac-755a-4d73-9afa-1f393eeafba6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 100).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f716ff8964aa8bfb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aba8d78-b3df-4e26-ae1b-ffdf0a3a0bf7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 100).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a2115274ba1f824f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0d3ff16-1125-4325-b8a0-3778197ba6e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 100).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '4127f2bbea015ac4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d52422ba-743f-4032-870e-6f8cf2cb9e1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 100).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '02f39ff4ff3b1eef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96faf736-2937-4c31-9165-84eb22944387', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 100).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1771f7be5743aea9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bcd7339-57c9-4afd-a3f5-f7785e00b7c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 100).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1312b9f939d6f586_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06722009-eb2e-402b-97c5-fd37f4d889ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 100).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9871abc9235f6d2f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de01323a-999b-41c9-b767-b918be4d8ffb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 100).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e16db19637b21553_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c509f10-02be-42b0-beb1-eca81c323434', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 100).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '979398b97508b711_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a06ba606-69a1-40fc-bebc-0aa80dc3fcf0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user account with an authentication method on Junos (variant 100).', '[{"id": "A", "text": "set system login user bob class super-user authentication plain-text-password", "is_correct": true}, {"id": "B", "text": "set user bob password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user bob password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.) (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd58ab0959ea644c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('056ff515-214a-4646-868d-534ec4b3090b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 100).', '[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.0.0.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.0.0.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.0.0.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.0.0.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix> (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '98f0be673bc76233_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('559f46f5-8af5-4e66-823f-373a84636d61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 100).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b40776c56a7a2f1a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5a13174-d6bc-4f04-9770-6c7b15e0a3e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 100).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f8eb61a240f9b23b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff5840a5-7464-4095-8ba8-042785785004', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 100).', '[{"id": "A", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '03937fce0e907518_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af997bae-5311-422f-9889-e2cb2d783df5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 100).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fda74123356610b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('321aea85-1d61-48de-a126-f7ff6bbe0a81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 100).', '[{"id": "A", "text": "Boot into single-user mode by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user mode to reset the password (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '84899b102118fbb7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d2db0c7-bd7d-45ef-9f5e-31062d046f31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 100).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '1d7259b8f40a873f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98034790-3aaa-4f21-bf91-bd829606c3bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 100).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fe5c758c13e585c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cd6d72c-7470-436e-a3b7-5750ea6d6251', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.168.1.0/24 via next-hop 10.0.0.1 on Junos (variant 100).', '[{"id": "A", "text": "set routing-options static route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": true}, {"id": "B", "text": "set static route 192.168.1.0/24 gateway 10.0.0.1", "is_correct": false}, {"id": "C", "text": "set route 192.168.1.0/24 next-hop 10.0.0.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.168.1.0 255.255.255.0 10.0.0.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '42d522391bed2441_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d98488c4-283b-4247-88c2-c532e7208772', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 100).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '74abd208963cd996_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3171c19f-c9ee-49c2-a9cb-057dee848718', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 100).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '41e8fcdc95c7f65d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04b7ebf6-6ac9-4108-a030-8068c1f7cac8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 100).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3e8112d2999d31e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('819f1db2-7796-448c-9c74-a52233231e3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 100).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing (Variant 100).', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ecaef61f729c0523_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1cea480-f5f0-4b0a-ac0b-b2a8cdde0f8e', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos?', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '32286407c224344d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc602141-b69a-42e8-af1c-bf6d18003032', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos?', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '6e10b3d7d19e99d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a982fae-b1b3-405c-b5f7-58f380b4c0f2', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0)?', '[{"id": "A", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "It is used for OAM operations", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, 'b504e82e3c55014f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1daa82c7-1c8d-4cc6-bd6e-703a899e84b5', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP?', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, 'c603a912294b7770_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f99da6c-5b36-4261-9023-3f47969ec424', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP?', '[{"id": "A", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'd642ad095439d56a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fba47c4e-74fd-49c2-9a77-745ecee559d0', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 2).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '75ab0f14f8128d50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88a094c9-b27d-4662-bbea-5932de737605', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 2).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '28574955dd9cdfc4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('266bcedd-98dd-4dda-987c-7e2fc3b36de6', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 2).', '[{"id": "A", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "It is used for OAM operations", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, 'd488a8cc9c11e32e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26faeec2-bb9a-4699-b884-e8252a956b04', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 2).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, 'e6c8084a2b625fdb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37ce5c53-035a-4db9-bf43-afb6c87e7fb4', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 2).', '[{"id": "A", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '7334e151c7b57fba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2e11cf6-3c32-49f6-ac0b-731361733d00', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 3).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'bd41de7bc911116c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a39cb1e2-99f5-4d21-940e-083504d8bb84', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 3).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, 'dea66cc1b6938803_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4887bed9-f1ca-4ff0-a35c-ab389035dbf9', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 3).', '[{"id": "A", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "It is used for OAM operations", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, 'b04c6af5a3b57d1b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dcb550f-90fe-4929-9748-5da2cf3db9a3', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 3).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, 'f7d4aa1294e69c09_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('128ac791-15b2-4987-9e8f-fb048a2fafe2', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 3).', '[{"id": "A", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'b3b1acb452c0820d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
