INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ab224c1-08e9-439d-a4cf-d8ef0a77a0b2', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 7).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '3c209477bae997f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3042f35b-cc2f-471c-bd9c-e8dbb72c7b94', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 7).', '[{"id": "A", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'fe0da6fc64ef1f44_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27b42f48-a1fe-4326-914a-5b36a76b1926', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 8).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'e6ea2e47a0d351ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8d3d2df-08d8-43c3-b212-1fc1555d7da0', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 8).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs (Variant 8).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '916d4619630c90fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
