INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('126a9165-f42f-48f6-9491-8a522c955dbf', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 20).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '9f2b29ef02596a48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('420ada3c-285d-4f62-b4d7-c9613fbeb555', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 20).', '[{"id": "A", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "It is used for OAM operations", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, 'a0332d06f5842d38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1c41664-1705-4894-aba0-0f765b1da86c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 20).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, 'd49622f1069f03e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
