INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e04d472b-bdbf-473e-ba49-88022cc242c5', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 45).', '[{"id": "A", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "It is used for OAM operations", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '43233fc2197f2b1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14d4fb21-87ec-48ba-b96b-3dce9437f209', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 45).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '5e60d5688e4a6ee4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f439e0f8-46b4-4dc3-8fd3-dc73f19e6ce8', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 45).', '[{"id": "A", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router (Variant 45).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'f9d07d9d585f6f1d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcbbce7d-ea03-4d46-bd8e-7551ecc543cf', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 46).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '91cafb26d55eb832_gen_v3', true) ON CONFLICT (id) DO NOTHING;
