INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4798009c-76c6-4a4c-83cd-5a70aefe979e', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 79).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '0c08f3ec557cf3cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f60dd57-6056-47a8-b8ff-6b983af8cebf', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 79).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, 'dd79da23e88e5fd2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('728255b3-ccdf-4750-8056-4841ebd2a753', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 79).', '[{"id": "A", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "It is used for OAM operations", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '676629921647b2ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2f5c9ee-eedd-4c3d-9e8e-5e84143c2694', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 79).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress (Variant 79).', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '6db00d2b9ab757a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
