INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de5c408e-a975-450a-9b3c-cf3ba06cb5c9', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 2).', '[{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32", "is_correct": true}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '8da74f88c6cd72c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
