INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('807732ee-1dfb-4cab-ba04-a9f59a169bc9', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 20).', '[{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32", "is_correct": true}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '854db368e044749a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('879dbbae-50fe-4717-b1c0-7380a1657ddf', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 21).', '[{"id": "A", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "B", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '1b55cbbc88427b68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72ccd84b-fbf4-4f6f-81b4-9cc2ce919160', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 21).', '[{"id": "A", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "B", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "C", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "D", "text": "Log and permit", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, 'a4b5096122573531_gen_v3', true) ON CONFLICT (id) DO NOTHING;
