INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('213a19d8-2eb0-4f1e-ac91-2407dc1fb92d', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 38).', '[{"id": "A", "text": "Tunnel mode", "is_correct": true}, {"id": "B", "text": "Transport mode", "is_correct": false}, {"id": "C", "text": "AH mode", "is_correct": false}, {"id": "D", "text": "ESP mode", "is_correct": false}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, '9edd898f5bf8d894_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c723d5a9-ff83-4a58-babd-3e4e28310855', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 38).', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A physical security domain on the device", "is_correct": false}, {"id": "C", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "D", "text": "A VLAN segment for guest networks", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, 'ae34c95286cb3491_gen_v3', true) ON CONFLICT (id) DO NOTHING;
