INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73d168fd-aea5-46ac-8c1e-25727dcd5cdb', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 47).', '[{"id": "A", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "B", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "C", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "D", "text": "Log and permit", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '94ea82d216176e9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49c37cdb-cdb6-4a60-8254-9f918a85fb8f', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 47).', '[{"id": "A", "text": "Tunnel mode", "is_correct": true}, {"id": "B", "text": "Transport mode", "is_correct": false}, {"id": "C", "text": "AH mode", "is_correct": false}, {"id": "D", "text": "ESP mode", "is_correct": false}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, '806a3b847d4dc29c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('082ed2c7-5827-4977-ae95-062b5e6f09c4', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 47).', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A physical security domain on the device", "is_correct": false}, {"id": "C", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "D", "text": "A VLAN segment for guest networks", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, 'dfef108549a2425a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
