INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe1fd8e9-6d00-46bc-a8ad-352f119e3be5', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 73).', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A physical security domain on the device", "is_correct": false}, {"id": "C", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "D", "text": "A VLAN segment for guest networks", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, '0c14e93997cc6d6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ccce649-9a93-454b-b814-0685bfd3ba00', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 73).', '[{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32", "is_correct": true}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '621b21781abad4b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
