INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('553a5a2a-5e9d-4385-a2c4-1d29285805f7', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 78).', '[{"id": "A", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "B", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '7ac4a0063303b061_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dab2d9ad-74ba-4a64-b775-fdf5c6f3f9ff', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 78).', '[{"id": "A", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "B", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "C", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "D", "text": "Log and permit", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '06065de2cbee83a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64cc093f-99f6-4850-8bd1-f6d10f9c6f2f', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 78).', '[{"id": "A", "text": "Tunnel mode", "is_correct": true}, {"id": "B", "text": "Transport mode", "is_correct": false}, {"id": "C", "text": "AH mode", "is_correct": false}, {"id": "D", "text": "ESP mode", "is_correct": false}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload (Variant 78).', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, '9e37bd3ebfd32850_gen_v3', true) ON CONFLICT (id) DO NOTHING;
