INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8da3fbe8-bfd3-42bd-b299-87bcdd9ab3d6', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics?', '[{"id": "A", "text": "VXLAN", "is_correct": true}, {"id": "B", "text": "GRE", "is_correct": false}, {"id": "C", "text": "IP-IP", "is_correct": false}, {"id": "D", "text": "MPLS", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, '424c1f959acd2417_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abd095cf-3b39-4d19-8fa0-28e5cf7dbc82', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'In Juniper EVPN-VXLAN, what is the role of the VTEP?', '[{"id": "A", "text": "VXLAN Tunnel End Point - encapsulates/decapsulates VXLAN traffic", "is_correct": true}, {"id": "B", "text": "Virtual Tenant End Point - manages tenant routing", "is_correct": false}, {"id": "C", "text": "VXLAN Traffic Engineering Path", "is_correct": false}, {"id": "D", "text": "Virtual Topology Entry Point", "is_correct": false}]', 'VTEP is the device that performs VXLAN encapsulation (adding UDP+VXLAN header) and decapsulation. Leaf switches typically act as VTEPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN', 14.0, '75657979f02e990d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f59d6941-3d1a-4559-a93b-56ddd8bbf4c0', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'What is a QFX5110 Virtual Chassis Fabric (VCF)?', '[{"id": "A", "text": "Multiple QFX switches operating as a single logical switch", "is_correct": true}, {"id": "B", "text": "A physical chassis with multiple line cards", "is_correct": false}, {"id": "C", "text": "A virtual router instance", "is_correct": false}, {"id": "D", "text": "An MX series virtual router", "is_correct": false}]', 'VCF allows multiple QFX switches to be interconnected via VCP (Virtual Chassis Ports) to form a single logical switch with unified management.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis', 14.0, '9e8b2f045cede30b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54b29526-4994-48f7-aff9-ebd107523317', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 1, 'remember', 'What is the spine-leaf topology commonly used in modern data centers?', '[{"id": "A", "text": "A two-tier topology where leaf switches connect to all spine switches in a full mesh", "is_correct": true}, {"id": "B", "text": "A three-tier topology with core, aggregation, and access layers", "is_correct": false}, {"id": "C", "text": "A ring topology connecting all switches", "is_correct": false}, {"id": "D", "text": "A bus topology with a single backbone", "is_correct": false}]', 'Spine-leaf (clos) topology provides predictable latency by ensuring every leaf connects to every spine with equal hop count.', '{"https://www.juniper.net/documentation/us/en/software/junos/data-center/"}', 'Data Center Architecture', 12.0, 'e385c23b7efd372b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0724a9c-4518-4fb1-9c1c-3fd3233350d6', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics (variant 2).', '[{"id": "A", "text": "VXLAN", "is_correct": true}, {"id": "B", "text": "GRE", "is_correct": false}, {"id": "C", "text": "IP-IP", "is_correct": false}, {"id": "D", "text": "MPLS", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, 'eb040d58a808d0ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd775c57-7b14-4225-b9f9-af23054be94d', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'In Juniper EVPN-VXLAN, what is the role of the VTEP (variant 2).', '[{"id": "A", "text": "VXLAN Tunnel End Point - encapsulates/decapsulates VXLAN traffic", "is_correct": true}, {"id": "B", "text": "Virtual Tenant End Point - manages tenant routing", "is_correct": false}, {"id": "C", "text": "VXLAN Traffic Engineering Path", "is_correct": false}, {"id": "D", "text": "Virtual Topology Entry Point", "is_correct": false}]', 'VTEP is the device that performs VXLAN encapsulation (adding UDP+VXLAN header) and decapsulation. Leaf switches typically act as VTEPs (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN', 14.0, '0c3d6ed20f0a5bc3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('438622da-90a6-482f-be26-3dc09e452492', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'What is a QFX5110 Virtual Chassis Fabric (VCF) (variant 2).', '[{"id": "A", "text": "Multiple QFX switches operating as a single logical switch", "is_correct": true}, {"id": "B", "text": "A physical chassis with multiple line cards", "is_correct": false}, {"id": "C", "text": "A virtual router instance", "is_correct": false}, {"id": "D", "text": "An MX series virtual router", "is_correct": false}]', 'VCF allows multiple QFX switches to be interconnected via VCP (Virtual Chassis Ports) to form a single logical switch with unified management (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis', 14.0, 'cd96b7a53ba4c9af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2af7a355-9be7-4374-b593-4c9c49ed2987', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 1, 'remember', 'What is the spine-leaf topology commonly used in modern data centers (variant 2).', '[{"id": "A", "text": "A two-tier topology where leaf switches connect to all spine switches in a full mesh", "is_correct": true}, {"id": "B", "text": "A three-tier topology with core, aggregation, and access layers", "is_correct": false}, {"id": "C", "text": "A ring topology connecting all switches", "is_correct": false}, {"id": "D", "text": "A bus topology with a single backbone", "is_correct": false}]', 'Spine-leaf (clos) topology provides predictable latency by ensuring every leaf connects to every spine with equal hop count (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/data-center/"}', 'Data Center Architecture', 12.0, 'd5783730eaaf6c39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
