INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd48db71-62a0-4e3f-83d8-190c00fae772', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'In Juniper EVPN-VXLAN, what is the role of the VTEP (variant 18).', '[{"id": "A", "text": "VXLAN Tunnel End Point - encapsulates/decapsulates VXLAN traffic", "is_correct": true}, {"id": "B", "text": "Virtual Tenant End Point - manages tenant routing", "is_correct": false}, {"id": "C", "text": "VXLAN Traffic Engineering Path", "is_correct": false}, {"id": "D", "text": "Virtual Topology Entry Point", "is_correct": false}]', 'VTEP is the device that performs VXLAN encapsulation (adding UDP+VXLAN header) and decapsulation. Leaf switches typically act as VTEPs (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN', 14.0, 'ccc2cffd6da6f32a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aae4d2af-5748-4bca-8b28-453110bd2cbc', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'What is a QFX5110 Virtual Chassis Fabric (VCF) (variant 18).', '[{"id": "A", "text": "Multiple QFX switches operating as a single logical switch", "is_correct": true}, {"id": "B", "text": "A physical chassis with multiple line cards", "is_correct": false}, {"id": "C", "text": "A virtual router instance", "is_correct": false}, {"id": "D", "text": "An MX series virtual router", "is_correct": false}]', 'VCF allows multiple QFX switches to be interconnected via VCP (Virtual Chassis Ports) to form a single logical switch with unified management (Variant 18).', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis', 14.0, '3f6622929d985703_gen_v3', true) ON CONFLICT (id) DO NOTHING;
