INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d154d71e-7fed-4d8c-86e8-e4b596e9fd8c', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 1, 'remember', 'What is the spine-leaf topology commonly used in modern data centers (variant 28).', '[{"id": "A", "text": "A two-tier topology where leaf switches connect to all spine switches in a full mesh", "is_correct": true}, {"id": "B", "text": "A three-tier topology with core, aggregation, and access layers", "is_correct": false}, {"id": "C", "text": "A ring topology connecting all switches", "is_correct": false}, {"id": "D", "text": "A bus topology with a single backbone", "is_correct": false}]', 'Spine-leaf (clos) topology provides predictable latency by ensuring every leaf connects to every spine with equal hop count (Variant 28).', '{"https://www.juniper.net/documentation/us/en/software/junos/data-center/"}', 'Data Center Architecture', 12.0, '085a801448117d35_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e644460-7fc5-40ea-8099-ed33536e634d', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics (variant 29).', '[{"id": "A", "text": "VXLAN", "is_correct": true}, {"id": "B", "text": "GRE", "is_correct": false}, {"id": "C", "text": "IP-IP", "is_correct": false}, {"id": "D", "text": "MPLS", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments (Variant 29).', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, '607235e38e89fff3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
