INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82652e45-c6c4-484c-aa12-a51d77b27723', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics (variant 55).', '[{"id": "A", "text": "VXLAN", "is_correct": true}, {"id": "B", "text": "GRE", "is_correct": false}, {"id": "C", "text": "IP-IP", "is_correct": false}, {"id": "D", "text": "MPLS", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, '0deaad4a7d3b12a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3580a73-9963-462b-a45b-6273a525938d', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'In Juniper EVPN-VXLAN, what is the role of the VTEP (variant 55).', '[{"id": "A", "text": "VXLAN Tunnel End Point - encapsulates/decapsulates VXLAN traffic", "is_correct": true}, {"id": "B", "text": "Virtual Tenant End Point - manages tenant routing", "is_correct": false}, {"id": "C", "text": "VXLAN Traffic Engineering Path", "is_correct": false}, {"id": "D", "text": "Virtual Topology Entry Point", "is_correct": false}]', 'VTEP is the device that performs VXLAN encapsulation (adding UDP+VXLAN header) and decapsulation. Leaf switches typically act as VTEPs (Variant 55).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN', 14.0, 'b572ebfb30ee8781_gen_v3', true) ON CONFLICT (id) DO NOTHING;
