INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('438fc8d6-5174-47f8-a9b7-74048233d392', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'remember', 'Which Python library is commonly used to interact with Junos devices via NETCONF?', '[{"id": "A", "text": "PyEZ", "is_correct": true}, {"id": "B", "text": "Paramiko", "is_correct": false}, {"id": "C", "text": "Netmiko", "is_correct": false}, {"id": "D", "text": "NAPALM", "is_correct": false}]', 'PyEZ (junos-pyez) is Juniper''s official Python library for automating Junos devices via NETCONF. It provides Device class, configuration management, and RPC calls.', '{"https://www.juniper.net/documentation/us/en/software/junos/pyez/"}', 'Junos Automation', 16.0, '61beae370184994b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fb5e4cc-3298-4804-92b5-25b9968f6b78', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 1, 'remember', 'What is the default NETCONF port for Junos devices?', '[{"id": "A", "text": "830", "is_correct": true}, {"id": "B", "text": "22", "is_correct": false}, {"id": "C", "text": "443", "is_correct": false}, {"id": "D", "text": "8080", "is_correct": false}]', 'NETCONF uses TCP port 830 by default on Junos devices. It must be enabled with ''set system services netconf ssh''.', '{"https://www.juniper.net/documentation/us/en/software/junos/netconf/"}', 'NETCONF', 14.0, 'b41d3dfa98783293_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8210ae0d-b997-4926-a232-bb9fb8504f8f', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'In Junos automation, what is an SLAX script?', '[{"id": "A", "text": "A script written in SLAX, an XML-based language for Junos op/commit scripts", "is_correct": true}, {"id": "B", "text": "A Python automation script", "is_correct": false}, {"id": "C", "text": "A shell script for Junos", "is_correct": false}, {"id": "D", "text": "A YAML configuration file", "is_correct": false}]', 'SLAX is a scripting language based on XSLT, used for Junos op scripts, commit scripts, and event scripts. It processes XML data from Junos.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Junos Automation Scripts', 14.0, '14a44a3444a3d0e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95f89182-8eab-4068-ad3a-f8697777cb0c', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 1, 'apply', 'Which Junos command applies a configuration from a file using the CLI?', '[{"id": "A", "text": "load merge /var/tmp/config.conf", "is_correct": true}, {"id": "B", "text": "apply-config /var/tmp/config.conf", "is_correct": false}, {"id": "C", "text": "import config /var/tmp/config.conf", "is_correct": false}, {"id": "D", "text": "set config-file /var/tmp/config.conf", "is_correct": false}]', '''load merge'' reads a configuration file and merges it with the current candidate config. Other load options include ''override'', ''replace'', and ''patch''.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Junos Configuration', 14.0, '53a45dd22ff0f4fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
