INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08fbc560-1ade-4cf6-911a-fc2ff1119424', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery?', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '623fc900a03dc05b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e485646a-696e-489c-abdb-26507aba3c5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix?', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '82604dceeffd14bb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3e0e90e-8de4-4ada-960e-18f933c08688', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network?', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '76ab1e627fe7b234_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71995b90-12d1-4733-8139-18fe1b9ca6d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD?', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '17ccb31069c55ee2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87724118-6d79-431b-b0ad-705c15e23200', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch?', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bb3c88d5dae963af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84d801da-093c-49b5-9430-45ecfcd04578', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk?', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1bbe17d4cbc77587_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11c19645-a05b-4530-8e0d-45523630d1f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning?', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '30445553418b0289_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e151898b-2c7e-4155-b0c9-9a4906c2c037', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive''?', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '41fc0170c43fa869_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e0f6a1a-77c7-451b-98d8-636998d2b526', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network?', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '20440459bce458ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('954de37c-a784-4901-ac3d-ffc1e8d83393', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route?', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '66e270c8e6d5bd2f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('915b9e74-c37a-4e7d-946e-9c83cb0993d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses?', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6a8d8e4fe64ed030_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0305324c-8d0f-4222-bbb0-0657c05c6fe3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol?', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '46e414abbb85613f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('964e2500-601c-47e4-ac12-0739df52a55b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent?', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9f3623acfeeefe3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df971ee8-0a0c-4119-9172-fc86c1114878', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address?', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e08887b7c9c12889_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0950b99b-72f1-4280-b362-1aad47b4f8ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server?', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'dcd69893f08fa2f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da670042-f1fc-4ad4-9a38-d483ccc944cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network?', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '459e11f6fc39c230_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ca9b170-cd7f-4ef7-a624-30b95b06ea3d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device?', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '4579a3f145cf99b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03ad73f7-f6a8-4371-8d53-e36dfaa27ce6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch?', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'dfb580d2851f9ae7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df307a05-d80a-4b61-87f4-58d22d564844', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management?', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'cb226142338929aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c87bcb02-6eee-421e-a7d2-2c01859ae25f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation?', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '49f44edcd980b465_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed99ae13-6f60-49a5-b544-e33a7292b5bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 2).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd7a96c0aacd20b0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('773a5123-ca23-496e-93a9-cc21bcd9495f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 2).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '728ee3f320bb830b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb981c31-14fe-4707-8a80-8efb22b38b2b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 2).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 2).', '{}', 'Network Fundamentals', 12.0, '9eff8cc3c0efd48d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e5d9b35-8cc8-4f85-a60d-b8d0609603d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 2).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 2).', '{}', 'Network Fundamentals', 12.0, '8d5c60155ce6ae85_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99216e6e-c7e1-471d-b683-b102c57d1270', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 2).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6e74358579784b0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('945de0cb-0781-44d2-802b-c800eea65133', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 2).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3cb91bce17df842a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4566ed7-e109-4261-a30a-354a3fa63466', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 2).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cb49259c10100b1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fff6f97-6efe-4586-a808-e0a0a85b948d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 2).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6c62d803098100df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffa15e0a-c803-4d39-87a0-539f346c0934', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 2).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3f2b221eb874fa80_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91aae4be-b926-4dd4-9ffe-87a6c1ca7864', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 2).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '930378ef93bb35dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6e575ba-1b6f-4576-bf87-b34bb562a62a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 2).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'e4f09ed158cac5c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcb7ed08-1eeb-4e81-bd60-cc94c7220625', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 2).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 2).', '{}', 'IP Connectivity', 12.0, 'd6ec258476197fe1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4f0aa57-f6ab-441a-8b51-3946e0daa729', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 2).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2c463e703a77aa1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceba9bae-d6b9-4095-b059-6e7d736308ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 2).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '13c5af4d52f53ab9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0142d1b8-1113-4ebc-b931-a99b7ce7c9d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 2).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '51310f862808f6ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52ffd0dc-6191-4501-b713-47fc1b86ef9a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 2).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '53512a32595fc295_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96627137-ad1c-4bbc-b581-d8bea6c86a33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 2).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9823a896820e99ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f74575f1-e4e6-410a-8dcc-49fb4385c4a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 2).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0a23141a9c446a08_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b2fb17b-0efd-4451-bdfa-8a3729798603', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 2).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '4fb0df365d778e24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0a8f250-7f12-46fd-8a2c-dfba8adb4584', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 2).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 2).', '{}', 'Automation', 10.0, 'ba5dc46640c72765_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('604518c0-9fa3-4a09-9aee-f6eb1ad23cb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 3).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1306799b51543cd2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3750570e-2396-46fe-b52c-09251417b345', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 3).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3fd15d9588398930_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d459a192-ecab-4b11-8321-c21a34b2265e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 3).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 3).', '{}', 'Network Fundamentals', 12.0, 'a638d0fcf29f3c2c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46af32df-38ea-475c-830e-51e197b78015', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 3).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 3).', '{}', 'Network Fundamentals', 12.0, '93e6f9f30a679025_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61eeb3ab-40e7-477b-9246-6f7817c7877c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 3).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0186d158d82ac8cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de20c19a-c6ca-4d98-a18b-9efe7141953a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 3).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5ef22391e32f8ab5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afb663fd-dc69-44d1-9595-0fd41050b322', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 3).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a4c7105d6d41fb83_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca6fb5a2-b08e-4d74-8986-472d8b934980', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 3).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd6fb45e5e227bed1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd70e165-1900-47f2-9dc8-7ff3ff1d642e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 3).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '95c5aceb0c7fc575_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88fd822b-d205-4bc9-9542-f241c5b7161a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 3).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '30c7d9ddc7fa2840_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2805f03-02be-4beb-9699-c7dc75268ece', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 3).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'b2f199f0c58ae52c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68445d03-658a-480e-a2fe-e73eeaed8c39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 3).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 3).', '{}', 'IP Connectivity', 12.0, 'e34986a8270a433d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9766b1d-979e-43aa-9757-1e9d43271836', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 3).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '48925bd8daa34297_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71c262cd-3942-4ae6-8ce8-e4ce32da802d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 3).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5d233695a5ce8fc6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61efe9e7-4276-444e-b8d6-1062e6c1595e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 3).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e902534fa8013d6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edd0985e-8aec-40ec-8091-24ed21e22732', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 3).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6cb04d80ab31518b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f55f3b6-6b47-4a2d-87d1-f2e529068c8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 3).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '83a8d1e15cd66012_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6433c9af-804d-4e37-9ea3-a5f9078bd4ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 3).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4e33bdce6f77e2da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e735ded2-d2e3-4a5c-bcc9-89c40e6c8d51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 3).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b39d1d66d0fd5d85_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6317723-d0ae-4878-a3ee-2aefcb209e9a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 3).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 3).', '{}', 'Automation', 10.0, '2907d1168a846373_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8899602-765b-4e34-ad80-263ec37ba888', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 4).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9e87973038ebdb06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09c725be-1d15-4368-b1d3-32fa619a4f69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 4).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '963d6e527afa1f4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('918121ad-2d7f-4b19-af42-fac6e3c8e953', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 4).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 4).', '{}', 'Network Fundamentals', 12.0, 'd7bec515936f4b16_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9620a73-fd56-48e9-93fc-a3741115dd1a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 4).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 4).', '{}', 'Network Fundamentals', 12.0, '52e31eae4d399517_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb94977e-d32c-4099-93c8-1493829b6185', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 4).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f79066bf9423678c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db1372b8-fc45-48c7-8d4e-40ed468bf74c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 4).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fc0ce565d91768c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86538e7d-e123-4ce2-9bd5-7730383f4d81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 4).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'aff4f36333adafde_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c048767c-8bfd-4d07-8bc0-25e50b21e48a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 4).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '454f4005a39bf6f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ce83596-e1a0-4b79-83f1-4cef708a77bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 4).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '194e387e11c9f1c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f727b54f-e382-42e1-b1c5-a961c89d0fa3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 4).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '428b58492f326629_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcd93158-7966-42f1-a97b-ab360f0dcbfc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 4).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '084be57762c0f5be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8df83410-3aec-4338-8e95-bbde12a9e1f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 4).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 4).', '{}', 'IP Connectivity', 12.0, 'a1745f942ef7c508_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a73d9516-a78b-490e-a850-9538a8b475e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 4).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ad7ef62a05fbc4df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4407189e-ff20-458c-ba69-ce380318fe85', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 4).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0fbdec05edc6474b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5156cf93-922f-4f95-a243-4bfcce779bed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 4).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7e832abed7f6d863_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b31ba00c-a357-427a-af07-f9bc3f6655fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 4).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9edff143bd58ab15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8388f10a-eb04-493a-beda-90f10b64e5c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 4).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '3d4e83c8c27cbb31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a62195cc-a6b9-489c-be3c-159f74361401', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 4).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1c6e48bb5f349ab8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26abcf07-c175-41b7-b47a-2f5aed8a1079', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 4).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 4).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '372b8fc17609877a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7af60f2-2d40-4a27-80d0-479c14bf750c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 4).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 4).', '{}', 'Automation', 10.0, 'b62802fbf4d21143_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c968385-52fa-43de-b25b-773b2409b1f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 5).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a1013c5f6c5acaf8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87e2fcb2-ef46-4975-8b9f-3e92369edb91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 5).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4d2968395401ed03_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e77e006c-2957-4b52-8497-aff55f2458f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 5).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 5).', '{}', 'Network Fundamentals', 12.0, '07d14287bd6ed1cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8d255a2-905e-4f42-a76a-4aecfc94a32c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 5).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 5).', '{}', 'Network Fundamentals', 12.0, 'c6cb9931b93ee610_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6657107f-f356-4206-89d8-f7d4e125d0bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 5).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cc9693816dc54fa0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acb5961a-6baa-431b-8c2c-b5d93b723aed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 5).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '89e81799b7f09ca6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94c75fe2-c789-411f-91dd-3f4ddaace979', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 5).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd83a2cd64dbbff5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d64caaa1-ff90-49ba-a937-1543d8368a00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 5).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f10a7f1ed4e4633d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7411baeb-865e-4a1a-b6e6-07e094bb27ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 5).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c5ebf4fd1daefffb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('038ca97d-aa6d-4146-a5ef-3c5abcc773a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 5).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e1101e2d056d9bd1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f8b14d3-38c8-4768-8149-41ec59ab4c6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 5).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '7b1588deecbeccb0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b0048ff-5bdf-49ac-8ba4-4fd0cfc36253', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 5).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 5).', '{}', 'IP Connectivity', 12.0, 'eac12516d05d9a50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e0373eb-9383-4d26-a592-f37c5a5d0236', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 5).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '902c7c241aed1810_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5488b9ea-7ca8-48fa-b5e4-ceaf17c278e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 5).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '38eb7cb49d16508f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3de6aba-52c3-4713-ae2f-9fc2f2c64e87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 5).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '963321ffc7a839a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64edad84-d396-4510-a997-a8e5b58566d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 5).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '89f091dd246d1f8a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('136d9ac0-30a8-4ae5-8b54-8dfa83b323dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 5).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6bdddb4d1115dd46_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18d7e88e-2ae0-4be2-84d1-15ae4f6f5085', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 5).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5efc188793143ef6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bb8c79a-15dc-4176-ba32-8382dd41b1ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 5).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 5).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '8ec4f554bf802bcb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c8942ae-d57d-42fc-922a-028bc6d7872a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 5).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 5).', '{}', 'Automation', 10.0, '501e13b72783a008_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c2acb31-58b5-40e1-a2a8-1704a7e66321', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 6).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'beb5dce29f839750_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0eb87d4f-5270-4ff8-9449-7d797429fc19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 6).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6aacd0d17fc4d00f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e6648ab-8c11-4352-84b6-b4e57db69dca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 6).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 6).', '{}', 'Network Fundamentals', 12.0, 'c3164ba23167f28a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7297e8f0-cae5-40fb-b3f8-8043c163f5a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 6).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 6).', '{}', 'Network Fundamentals', 12.0, '0d6e6af2708f58d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16961fe2-8cdf-42eb-9585-5c16cf31a1ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 6).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ec13ce9d8725b257_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f14406da-3785-44fb-a8ba-89d018366e2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 6).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd7bdfe3822757c31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7de33613-d8cf-402f-810e-1039cd2f8169', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 6).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8c5c14d640157725_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b46aa400-bfe4-4d23-8b13-9595fcc28041', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 6).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f7e188c1dcbec0b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d9990b8-9dfe-48ec-a3a5-85c32e284be5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 6).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'f24d4a4d580ada84_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4de44d97-6b88-4478-809c-d1b2aebbe6ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 6).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0a9bffcc624c7e2a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31588b70-c156-493e-8a5d-6cbc5def802f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 6).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ffca825472e53b31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24f8f0b5-848f-49bb-acf7-5c28aed74ce1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 6).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 6).', '{}', 'IP Connectivity', 12.0, 'b7b645170e0183f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31ad439f-e699-44aa-afcb-60b194788846', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 6).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3964f10af907582e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d932e9a1-1016-4d06-bf4d-5c38649b7cc3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 6).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bd709e017a8c7371_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb8cbf83-208d-452d-9c6d-bcb1a40cbc88', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 6).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b8c80542f4fe2fd6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('682a5381-8a8a-4cd8-99cc-c79233949bd7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 6).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2d83f1dab517212b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('961b8b59-ee9b-4d1f-8aee-6d499f16b68b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 6).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8c0b782bca9b2c5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('600838dc-b42f-4321-88cb-0bf2a0c1fd40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 6).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '099f16ce4ca72d60_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('321985ce-a585-4277-a6c2-accab6ee7035', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 6).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 6).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '5fc5e5fc51d43804_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da1dfb7f-42d2-4ec7-84e3-8f5d4691ec47', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 6).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 6).', '{}', 'Automation', 10.0, '03450c0b51bcfd39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc91d812-9135-4fe5-9d91-c160c45b5c5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 7).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0d4c6b94d767556e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('744ed32f-8b78-42dc-8eb5-2d41a35fa29b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 7).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '66d90452aa191745_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d94aad2-2213-475c-935e-55b50377ef37', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 7).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 7).', '{}', 'Network Fundamentals', 12.0, '62aaafae20ba7bab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5d9543c-ad69-4849-a080-8a5d49f26cd8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 7).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 7).', '{}', 'Network Fundamentals', 12.0, 'bf019572d46443c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29c5a50a-fbfb-44ec-b7a0-948af4e8754a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 7).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dcad76d6c5312ff7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67158ec3-4ede-4372-9c1f-5327c73ae0e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 7).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4838b81a7b56a45d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9d01ba4-e233-4081-95c5-cf188f7ec88d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 7).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '21a7f94017016c00_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('372ea3c5-1cc3-4390-8067-27076ea3ab89', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 7).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3de79d1507a75348_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1b9bada-dd05-4358-85c0-0ea95080e3af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 7).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '9fdf0850d95801fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba38f2c4-ec48-46a0-9f94-6409798f15b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 7).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1b5cd0492046e19a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98a29c28-6ef5-4f10-8d65-4a7dd50f02e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 7).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '3843c7932bc54ef9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26e734a9-8777-45cc-b836-5132356316c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 7).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 7).', '{}', 'IP Connectivity', 12.0, '70acc8e567ba5151_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab05b237-e44f-452b-8881-8db5fb6af8ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 7).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '92e7cdd81a714c42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7210c91-b7eb-4c17-93a1-030661fab26c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 7).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7853771f873023cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee1d5db8-4e39-4ebf-b763-db31b29d560a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 7).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e781817850397e89_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a96ed683-d809-4825-85f4-38fba647f36d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 7).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'da21f8bd108dc134_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d26cb8f-d1f3-4ffc-9310-422583542ce0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 7).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f2ceb9661a3ef576_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64b43f98-a886-4a37-9525-42e7cba11cdf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 7).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '304e6975e8adfc99_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13b1de05-6e3a-4e47-a543-c2dad1e443aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 7).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 7).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e898500a0d51914b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6c6ae12-59a8-4648-bde9-81d53ab54623', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 7).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 7).', '{}', 'Automation', 10.0, '1325187b3f006ed5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6f76f92-cfa1-44f7-abb0-1ba4f870f72c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 8).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '85d2dadf5cce0c8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cedb2ae-37b7-4d7e-b576-0e3d01986d5e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 8).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4a73d77ae75afc9f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3ae6771-3110-4f4b-99f5-9e2a6cb73b75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 8).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 8).', '{}', 'Network Fundamentals', 12.0, 'd1e96b56a9abc39f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('757e78e8-d0bc-4ad3-9696-a400ab586c51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 8).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 8).', '{}', 'Network Fundamentals', 12.0, '039e7ec1534e255b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('214c1324-16aa-4655-9074-44b92b765f8b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 8).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ab7bb398a71b3741_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6eab3e09-8cab-467a-8ca9-220914cdadb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 8).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '099173e45165e6cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73b658bc-8703-4b40-8d1a-9cc18531f7e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 8).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '38cbf1240a1fa0f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('862d1624-fec8-42fe-8124-d2c0426a176f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 8).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e4d6c5c65d79fd6f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91054eb1-6060-4a06-87bf-283edbeb8cb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 8).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '2d0d5ba5256c1c20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b22a0270-9a34-4140-93c0-75cbbbe54246', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 8).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'bf1c1855881f7802_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a352b07d-f13e-4859-9183-57df61406a3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 8).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '216145fe5fa34a9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef29dad8-c04c-4ef7-a4f0-a9166d9c9dc7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 8).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 8).', '{}', 'IP Connectivity', 12.0, 'ad49542fd386b698_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c76d18a9-de63-4505-aca6-eeb8624a8234', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 8).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4149b1a41e308a3b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27631f23-f4db-47bd-9b3f-53722e7ed860', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 8).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b1a416448325b2e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('341773ec-12b1-4e8a-9018-c581878453e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 8).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8592236c010825c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('818c4f54-4288-4bdb-920a-c3ea1bc6bc2f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 8).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5a7c770a215018d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf5dc024-6e50-4033-80b0-55bcaf5f462e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 8).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '723070e29b1853e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16901a92-d61f-4695-9521-95ef048eced0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 8).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f3728da76a0c651b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a97a8d0d-be20-4ba0-9191-b02a325464e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 8).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 8).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0c028db402cfaa6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e960f74-5324-407c-9109-2d63d4ecb7b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 8).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 8).', '{}', 'Automation', 10.0, '52f78475ad8e8cf6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6efa19b-c4d8-472f-9645-79cf688869fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 9).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '976d85e64ae0ba37_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e649e899-7aa9-4ee3-82a7-cb878046b5be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 9).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '17e4c1e0b477a1f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e22500e-6899-49cb-b056-8eebaef0362e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 9).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 9).', '{}', 'Network Fundamentals', 12.0, '4e173673b9f41f60_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae4e1d00-cd75-4d5c-8703-8d360f499a4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 9).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 9).', '{}', 'Network Fundamentals', 12.0, '16abd9f99e04ca50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30731f59-0f54-456d-9996-d129f8f43c20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 9).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6e0bc8e99d36ff84_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51a63248-9651-4bf3-b23a-9f50bfd15c6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 9).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cf7cda53f9dfa0a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1bb5671-34a0-426e-8c45-3bd1982ccfd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 9).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f827657b97cfc70d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2f90e79-ae3d-4dd8-ad58-c2820584c57d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 9).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '89c236bd36c1206f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3733898d-41a1-4303-9e51-c564d9879c50', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 9).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'f9a301c77d3bb732_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('128dac14-a4c5-4afb-a862-92082fcb3e9a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 9).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5ad660fa6c1d13a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('943b1047-72c7-4f5a-8b9b-a5cd40c9cb6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 9).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '02d2ebbbec2e0778_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29e5f993-6164-4dcf-8bc1-114f2f87cb1a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 9).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 9).', '{}', 'IP Connectivity', 12.0, '56f346eaf987c656_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae98beb9-3e25-4414-b53b-b49848a187a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 9).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ddff3d67d0243606_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('550cf369-5f0b-434a-871e-6040579de43a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 9).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ecce17f3d3e4a508_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b58a1d4b-9e5a-47e7-b8e3-233b1a5f9463', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 9).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2db324cb82b555cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac5e12c4-dbf0-47e2-96f8-f4d49d5b564f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 9).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9c4b69911f6730a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1862b64f-5c90-4a3a-a949-01bd752154c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 9).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '736f90d0d7fa6c19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7018fb8-313f-4b23-8013-ca21d626fab9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 9).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5a5a48d18e32ad7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02652d14-e642-470e-8e52-059112384a96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 9).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 9).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b94805c716c380c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6d40d79-939f-4beb-9afb-4744d8f40ffa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 9).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 9).', '{}', 'Automation', 10.0, 'b916686a5d1aeac3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c3b5c59-be88-4a84-a81b-9f5a284e5eb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 10).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b950607122c7ba6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74ed3053-ab49-4c90-8637-aeba3cf05292', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 10).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd779a85472fb4ddf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2ae0802-7bca-4549-b147-7d4ff40c83ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 10).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 10).', '{}', 'Network Fundamentals', 12.0, 'a7d9856fa8fede4c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('125deb9e-144a-4dbd-a505-3ed28dd76f30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 10).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 10).', '{}', 'Network Fundamentals', 12.0, '41311f16b2d97e0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0205f620-5a94-4c45-b29d-1f5320481494', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 10).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '23e1a5549f9eee06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4b6cddc-8d6d-4f93-834f-6180e2338d18', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 10).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c55ac8277dfd337a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd235091-8b73-4d35-8c37-7c25c5f8d40b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 10).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '78c0d1870429ec56_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1996fa94-fd3e-4b37-af99-442168e5bac9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 10).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bdfddbb08c28dc92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48cd57ad-7e89-49c9-9946-29a6716bd836', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 10).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '6f56ba223a35a9e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d85c2526-4675-4c78-bcf6-a4f354af0e05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 10).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1462725fe75ef13f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1275af4a-47f3-4609-befc-8e3a9e779e9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 10).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0c09c75171421bd7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e45742a5-40b5-4c50-9476-fab5ff233203', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 10).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 10).', '{}', 'IP Connectivity', 12.0, 'e73fd4891a256c5a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc8348aa-98ff-4b4d-a64e-62c9a1c61a39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 10).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2796498f7043d95b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4468dd3c-f68b-4713-a40f-49629161b621', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 10).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '56df006f7a4d71e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9adf4c03-709d-4102-ad4b-d6813cf213de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 10).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '68ff3d8e7025d142_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a882ca6-b7fa-4966-89df-42d78e4a9755', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 10).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c4f0579b8dad66aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f73ed07-9763-4875-bbc2-58f749deaf8b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 10).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c7e54a0e27fd841e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b167d43-af9f-4534-8284-b4cb3630337c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 10).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1c2c533522783d0f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c43c1af7-36d9-4585-9bcf-d4b8c0089565', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 10).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 10).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '67cb71638466f590_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d948072f-7560-44d1-987c-5adb8a4579c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 10).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 10).', '{}', 'Automation', 10.0, '64436c7ece15328b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57baf6b0-e335-407a-b907-0c51d4e857f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 11).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c06b99e18c641bdd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e84a4bf4-a9f8-4b0a-95ed-844e0dbf107d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 11).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '46320a3dfdbea259_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22a43967-3484-4fbb-a1ea-68f26c36674d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 11).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 11).', '{}', 'Network Fundamentals', 12.0, 'c5242df939bc546d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5def2b07-64f5-4869-b430-75a4d7a670f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 11).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 11).', '{}', 'Network Fundamentals', 12.0, '516d57f584ffffd3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec48d185-c8a4-4b5b-b68b-0c09c6e45361', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 11).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a07f8355fb8ec932_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7681c339-0fe2-46c4-bfd9-3014ec0f483f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 11).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '11c208459459e719_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a29550e8-6168-437c-b334-88ec4fa86f58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 11).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '745b0556e2adbe92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6f27ee3-3df0-4f4a-bbc1-3e765da1ae20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 11).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2236f9e4020a4bb8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ed08425-1b26-46c5-8edd-503c917dd41d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 11).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8539d55c86f1cdca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('798d78e2-cb26-4624-8379-3376806be657', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 11).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd1ed53c866a909c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a705e6a4-e2b7-4d2f-aeb6-1840e7b6c9ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 11).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ecf27965fe470a71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0f61a47-de65-45d4-ba2f-7999dae33e70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 11).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 11).', '{}', 'IP Connectivity', 12.0, 'fe7fdb0c47cb84db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60dd2acd-2eb6-4a97-b642-fc1588336af0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 11).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7ba0936ccd64bebc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('540f3d52-9d44-46d3-8e5a-2004a4fc6759', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 11).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6214810e4075e61f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4168d26-e7d9-46c0-a3f0-1285d2b633c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 11).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ee216cb069ad30ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a05f8ba8-3faf-4ea3-8b90-abe025ed3eda', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 11).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a16b6d1a9bbaa399_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c28d7de4-f7d5-4d11-8ead-9ae9fd2ac825', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 11).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9f9c0d2b8f8d3997_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2155493a-6c8c-4d0a-ad02-30deed76b7ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 11).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ed599bb5482bd7fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f49e626e-bda2-4d2f-bc99-3849e3ce0583', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 11).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 11).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0bc63f6b685ca750_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bca8ec68-b222-406d-a6f7-086171b3114b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 11).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 11).', '{}', 'Automation', 10.0, 'c17879e9a0c58ad0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f0fb883-8b0e-4924-97f5-3adfe4dc33fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 12).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '963955b79f75e061_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc703c4e-911e-4654-b865-d1852470e17e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 12).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'eddadeb8776e38e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cae9523-813d-4482-80f0-b600adb3457c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 12).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 12).', '{}', 'Network Fundamentals', 12.0, 'f374d82c7f62a02f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('180b3373-9d7a-43d7-afe1-8de2cd433928', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 12).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 12).', '{}', 'Network Fundamentals', 12.0, '38810fd590e7fb9f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dd59c2c-7081-4184-8c95-fde09c0e9410', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 12).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '25a3484b385ee8a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1df9fadc-769d-457d-85ae-8a8677381ea3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 12).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dab64e034d421c20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('327d6139-6249-4211-9c62-fa13bca40e35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 12).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cb2741c1e52259a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e880c726-35a3-4626-b6cc-e3e5160a8596', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 12).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'df735b8eeb844e1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d7952c3-8ebf-4a2d-a12a-e49598384f3a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 12).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'edbcc7985c0b10f7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d677287-6b82-4f00-8046-dd7de8ca52df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 12).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '657f18f677646804_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84019da6-e15d-46d2-98cd-b19148036174', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 12).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6442dff1b0eb218f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('968bb21b-abb1-4986-9382-4eeeea7ca7c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 12).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 12).', '{}', 'IP Connectivity', 12.0, '1df8bef9db28320c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e6c789f-8ac5-4be3-a76c-feb6d89e8a65', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 12).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e58fa9c416916cd2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca772222-d4d6-4a8d-9ee4-194d80aa8891', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 12).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5732934347838996_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6355de0-8405-4036-9964-6166f71be198', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 12).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1c970002941b3540_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4597d0b7-cee4-4464-a19a-b43f02872e45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 12).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '04c65bfa8544b952_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1b07047-667c-4a1f-96c5-fce23bd4fa73', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 12).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '49913fa950409749_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c79cb014-64d0-456f-a8a2-dade301b213e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 12).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '313664214170c972_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f771a634-ba9e-4ba9-8334-a2d862f6101b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 12).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 12).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '783daa87924d0306_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab2bf00d-d4df-4b09-bbf8-d091c60458b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 12).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 12).', '{}', 'Automation', 10.0, '7b30a7e9c5e26e17_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e52591-5ef5-4001-9bb7-285bc47fb34f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 13).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e866236084a40cd9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11025694-e0d4-46f2-852a-72b0d99e5ece', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 13).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1ee5568bde909a41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('782dfdfe-57ec-4431-b48a-2d33eb17d0dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 13).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 13).', '{}', 'Network Fundamentals', 12.0, '969fe0088ed95f3b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ff6072a-3f25-4895-b2aa-7be36303f0a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 13).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 13).', '{}', 'Network Fundamentals', 12.0, '6b8071629816f02a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('422b71c3-adf5-4c4e-b070-85b496daf2a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 13).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7b5bb6ed692f1280_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0ee13fe-0b36-4101-8219-1fe1bf1f2af4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 13).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'df571cb20e54b455_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a972e57-915d-46fe-a193-b087cb9e3107', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 13).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c082e643984acf42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ead3064-261f-4642-ae92-ff8d2c0e3c83', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 13).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '007d1fadbb2c19a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2189ba0-95d3-426d-93cc-b652bada132e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 13).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '313fcf6dfd73fc29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4682411f-e1ee-4b39-b512-d4fed3a07b5e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 13).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ef78e8a3c7ddf79f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac702f3f-d87f-4802-90d0-9df18b030750', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 13).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '5046b28a34619fd5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f9ad5c5-4d0b-431c-b39f-f9562d315a17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 13).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 13).', '{}', 'IP Connectivity', 12.0, 'fe16f73a3d685055_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17dd551a-5af2-48d9-af2f-deecb955a3fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 13).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fe09f0c9b96d2631_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('084bcd4a-1f11-4512-969f-b0344d640ead', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 13).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b2bb3be122efb7c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3687ca7-c580-49cb-95cc-004cdc38a5cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 13).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '998219e56e06be36_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54a76fd5-182e-47ac-8a1d-78b2c90da2bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 13).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a238747f8473c943_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88a0c337-28df-487f-895e-07a174779f7d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 13).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '4494062a1651f012_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e21b87f-5d04-4bca-8399-2650fbd535d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 13).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e44be8f3f25efbbc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9396b18-2f32-425f-ac88-588087c53b9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 13).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 13).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '5b0c18d70fbcbddc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e530272-e820-47d7-8045-71e6dedecc35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 13).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 13).', '{}', 'Automation', 10.0, '35d8c309edbe3a76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('691c9ba4-3d76-4026-8ea1-8683f4a4a60a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 14).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ba5bfee3b4d729a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b193fd2f-9d8a-4dd3-b297-98eff27e46f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 14).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e9305b7fa9dbed3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('792675d6-63a2-4159-a7b1-739f2349d00d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 14).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 14).', '{}', 'Network Fundamentals', 12.0, '1dafd1f94e9b6409_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('541312be-aadf-428a-81d8-108185b23ef9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 14).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 14).', '{}', 'Network Fundamentals', 12.0, '34f9eb24e6b1196f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f563205c-5338-4430-bd45-44ce45cadcf0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 14).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '25947910298e6b2c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3cba552-ec28-4a94-b6ee-d0decdb426e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 14).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '55c2431d25032921_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62c57927-1fd1-42b3-bcd1-c416fd1995b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 14).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a9a5842da82b1ae0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbb6fe53-da39-49e3-99f8-b3c1ca17ee1d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 14).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2350522de96c029e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee125ab2-b989-4b5e-a829-4877a992a594', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 14).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7e115e85d65c922e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a272d0da-e8bc-41ca-ac29-cac7175f4983', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 14).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'a8355f836a9c5b20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d1cb679-82c9-465b-84a7-756e81098449', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 14).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'e1b91be97b6bb3bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a12a9308-b9f8-46f6-9a3c-18e6b8a1e298', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 14).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 14).', '{}', 'IP Connectivity', 12.0, 'f7d1ac401ab78b7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99abad93-9089-4a2d-8c1e-e1b924663bdd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 14).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '57a2e96baa18d2f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bb7f65c-bd79-413c-b82b-4ea5cf79ee9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 14).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3199a1a3af480e09_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b19ac23-3761-48a8-83a7-02eb242ffe51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 14).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c7267dcd86633f0b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7dda192-480c-4cd4-9288-a784cbfa5702', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 14).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '022d8ab5a9f13ab1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('151faf90-5bf1-4979-9f44-ee114bd2dfbb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 14).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '26ccc40cf177596d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d567bd8-3f83-4f2d-9a7b-546178b6f1a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 14).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5d3cb84c60c1cd79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8586d052-e72e-48a7-93c8-3db3f1199c8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 14).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 14).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6e53d27c82af478f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d47c8b46-774f-4e7b-b9c8-814a647e04b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 14).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 14).', '{}', 'Automation', 10.0, '1837ec2e2ef1ec39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa2206b0-2e1a-4e1a-ba6b-3a0d0d1dc9d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 15).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9d97aa88aaa084c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdaabc8a-9c10-4e11-83b5-d751791a674e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 15).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6debc34674ce7efd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6553ac6a-a4d4-4d50-9b69-83926d51e1b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 15).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 15).', '{}', 'Network Fundamentals', 12.0, 'c3bd9fbe8a1dcb4b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f454ea70-e50a-4cba-bd36-22102fca656d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 15).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 15).', '{}', 'Network Fundamentals', 12.0, '375a5e70d5f1fb3e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30940736-c52e-46e2-a217-99cffc839402', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 15).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8f0ed7a4ea8b8446_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa060c91-744d-4bd9-9667-8ba50fdf5ecc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 15).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6d805227968cc727_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6b6ad00-7678-4318-8b90-73877c53df40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 15).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '30628ae712ffc782_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a101572-f197-4eac-bd9d-36ab851b58f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 15).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1ef8876c8c1fbed2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f0b6266-70d1-477f-9885-cc679f2dc0ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 15).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'cd124d8614c08da7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10b1e59d-b528-4eb4-ab46-fab4672183e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 15).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '60a5899464520633_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e94e269d-e744-4ac0-8b9e-6a1e509e3467', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 15).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ac021248cae1f054_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e3b97c0-e770-4261-9c9b-693d80cc77a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 15).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 15).', '{}', 'IP Connectivity', 12.0, '37058cba5ab19a33_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b1f452b-9266-4279-b5e5-39fe1d30788c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 15).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '99f34341cf7dcb4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37bbd659-bb1d-46eb-866d-058cb03517f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 15).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6b37766473be2759_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caa16a37-1223-454b-bf73-8c5d55442da9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 15).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '55cae454a8d817d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce83fdb1-b55f-438a-b78a-ed70a8102bb0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 15).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0f3e688f3fa71687_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('589e3464-71c8-4dfb-b759-92055eb161cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 15).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '4dd4a780a419eae0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e8491ea-69e7-4161-83fd-37d205174460', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 15).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6255d84c3010404f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('477a5f0b-62c4-46ab-97ba-d674650d69b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 15).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 15).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '8399a9c25e2e51ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5df942a7-d374-465a-84e9-35ef5dff218a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 15).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 15).', '{}', 'Automation', 10.0, 'd0e3eea0ce8bc39a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55b7c074-1688-4d6f-9b93-7e0417978795', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 16).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'af9500b1cc8c4588_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('856e710f-59b4-498d-937d-3fda35a0d3de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 16).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'fc9e49a1301a16a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9831aaef-f9be-4d57-88f9-c628d0fca2a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 16).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 16).', '{}', 'Network Fundamentals', 12.0, '83b9d9aa74a74a9d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de5caff9-108e-447e-abca-8502e130029f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 16).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 16).', '{}', 'Network Fundamentals', 12.0, 'a4ea7e79411cc21d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e936aa5-1c03-4421-80db-7bf2313aeb5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 16).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c2b2b76840c3279d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f02342c-b4fe-405d-89b7-25970b5515f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 16).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8239f5ed4bd04f74_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75b73636-d3c0-4f8e-ba18-11faaac9cb8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 16).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5cea911670b2a6a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95da5ee2-7276-4d9f-ab90-1c53c3db33a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 16).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ea62a1b817f92462_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca58be86-901c-4051-af31-5e0a83df1ad7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 16).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a791f0e77e6d5e5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c97eb60-ea5f-44a8-950b-031ecf92c106', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 16).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '7e55aaf2c0e644b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c27d7cdf-f7ef-4e33-a1da-45aa686ddb12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 16).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f807b1a882e9ebbb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ed06835-78a9-4e8b-8a6b-cc164c226ed0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 16).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 16).', '{}', 'IP Connectivity', 12.0, 'd1ce8757f8c183c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a74f068c-be9d-4658-936f-abd65d27e99f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 16).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fe86de8e47e9ffb3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('309ebd68-e6db-4b48-9859-3fb8bf3d9184', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 16).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1c160d805a758edb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecbc9277-a717-41b7-817a-3c21e4c58304', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 16).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '397cae37ee595c44_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4b7f4cc-7ac2-4642-af81-fe77059c6928', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 16).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7e337e7d1167b4fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64d0ac75-8383-4918-af23-c372b3f57571', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 16).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'fe52664ebdf36cb6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04c89d30-fe6d-45c9-b7f0-172afbce05da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 16).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3874f88ee38afaea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9906c9e9-914f-4b49-b8fa-35c2eebb2a0f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 16).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 16).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2ec7f529dd2f65d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf87fce9-9f4d-453b-8628-1cf6acbd2c17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 16).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 16).', '{}', 'Automation', 10.0, '359a59b167118b61_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0db9666b-4bed-40f7-bd12-f86ecdc0c390', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 17).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd768f7141abb5ae1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d56f7aba-af05-48c7-a7b1-4d5f2738da04', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 17).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6af81703f950aaff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29b1a75c-c82f-4c0f-b0f0-5e251de2a865', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 17).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 17).', '{}', 'Network Fundamentals', 12.0, 'd51199d277fe1646_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4afae684-7a26-45bf-a051-a00efa08c1a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 17).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 17).', '{}', 'Network Fundamentals', 12.0, 'cb7aae9acfb73703_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2624838c-bfe4-4d4f-9a63-f5c6ebc93f38', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 17).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '253b4a076358911b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d883432-0e94-438c-9a7a-9a5e0179c5da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 17).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fbfba7df7fa668e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0088e327-beb9-4026-9850-b63cb9020f51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 17).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '767f7651d4e2dd14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12cf544f-eb46-4abd-aa20-43e2cb2149d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 17).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '926d1c9cde460ae7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff263bc1-627b-48b8-a417-ff04c50e5726', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 17).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'aa11c0bbbb587468_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ec9c936-b38f-4bed-9f82-16b9c5584422', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 17).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5f3ed9d9d42ee84e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02fe0eed-178a-4e7a-9968-cedb412507d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 17).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '3084336334898b37_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1036e0e-ba74-4102-97be-451e456df3e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 17).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 17).', '{}', 'IP Connectivity', 12.0, '5790bd72b935d33b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45c61823-52a7-4812-b6d4-002bf5bc2db5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 17).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3cb58077019f97a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c22520b6-0e58-4ce5-8f50-3f1138b2e3df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 17).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fe4e125163478008_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5405fef9-7e04-4fba-8419-1cdccfcf5480', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 17).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '3e579d3c8b92528d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a303bd18-e040-4ad5-ae37-486cead68b8b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 17).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'bfa4ecc013bac27e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b7f4f69-96d5-4ce4-892c-a2d5a2f78946', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 17).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e1482a1c1967e1f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cadbe501-6c08-4091-93b6-98c3da7e4b03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 17).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8e29b55a3488fe02_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba45de82-0f30-4701-9074-be3ec286fdbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 17).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 17).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6a0808a3fbec9029_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51105c38-57c1-4eec-84cd-76fb782979b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 17).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 17).', '{}', 'Automation', 10.0, '90904306bd9b135a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2525c837-ac38-40ba-94f3-0ea6a6c764fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 18).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '832abfd0d3dfc134_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fca83652-a33f-47af-a26a-8129e23835bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 18).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c7a8d4a72e48659d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07ca7305-dc5b-41bf-9438-be20d4fe7d98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 18).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 18).', '{}', 'Network Fundamentals', 12.0, 'b2d4a4ce4f4a77c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('677d2b97-6318-4e04-992e-eebc03f1a58c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 18).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 18).', '{}', 'Network Fundamentals', 12.0, 'a371af94653ce4ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('201153fd-3d85-461c-a444-447299f4ce11', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 18).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4d81ac142764375d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b37b8920-17ad-46ea-ab97-0aba6623fc6a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 18).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd2391f427c6252e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c8dabc1-e5ef-4137-b83b-a052be43148b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 18).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '31146378d5b90ffe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bdb7c70-78c9-4e41-a2f8-b5c20cacfef5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 18).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0f4bbc26f49852a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ea10db4-908c-4e82-a0ca-1b3c00a441cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 18).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c5b2fa18a1e6be94_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c354aca-2ff8-4dcc-b6fe-70efa9f905c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 18).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '019c277a888c8323_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('931177d7-8b33-42e5-8d2d-bf1b15eae03e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 18).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a9dca4a3d5836932_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c8c2d38-07ae-4d3b-9436-8844a27fa162', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 18).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 18).', '{}', 'IP Connectivity', 12.0, '2b5e6425a0334c2b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f93c30ba-c12f-4a5e-9bfe-b904e1bf5018', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 18).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '733f1a9abeddd24b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8ffcde3-b941-46f4-9839-37f2e1295f44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 18).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9eb00b350c0d6290_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f89719f2-364f-49b8-81de-d9b8e3ccf93c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 18).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e0d65e592dbff613_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c85415ba-5f6a-44ae-992b-019c22d5fb3d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 18).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b54eb981d6281978_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4994d23-1f89-4430-bfef-a47315173ff5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 18).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0ce29e6b969905b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb5042ab-2b03-4f3d-b612-de242963287e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 18).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c42112e65d0e2584_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c95802d-b176-4b17-9712-87ece3dcabb5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 18).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 18).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e8fe9ee21b7a78fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86315036-da5b-44fc-9c9e-dab4fcffa860', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 18).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 18).', '{}', 'Automation', 10.0, 'acd154b05c2d10ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a696f3ee-1876-485b-ba23-42ae6cb13523', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 19).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5a352fec0d779479_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af76a2b9-6e93-47c8-9480-8934b0c88793', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 19).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4296abef700c0e74_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('125d75f4-753f-4752-98b3-1189923f4e37', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 19).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 19).', '{}', 'Network Fundamentals', 12.0, 'e611808878138dc1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b742c02-6cd8-4e80-96b7-0f25fc3e8d94', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 19).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 19).', '{}', 'Network Fundamentals', 12.0, 'd8d53ce541fbada8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4867832b-a8e4-42d1-b1b4-289c810f8b6a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 19).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7aabcb9302d7ae4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc9cffac-84e9-4489-a9a9-57c3ecae9cc4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 19).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '90f4efc7c337d506_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a011ae17-7c86-4d3e-8a5e-06cbf2be49d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 19).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '388e256308d4d4a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e5c4b06-6d13-4c49-ba9c-db776f24b2f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 19).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '374f7249fe54963f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5905ce4a-9453-4012-8a1b-a1ee234a3dc7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 19).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'f77dc18f754f877f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38e7d9a0-353a-4f9c-bfba-3da7b89d722d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 19).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'aa99dd692bd51cd2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b171d620-05f6-4bc8-94ab-134e3239b1f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 19).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '87714abed4809280_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('869dd73f-bc60-411b-972f-afd3ac9cd6a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 19).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 19).', '{}', 'IP Connectivity', 12.0, 'af57e460af061c6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7b50a88-c586-41fe-8579-c28b1eca8a72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 19).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '663dc7a5373243df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4afd4d7-095a-470a-b729-5a5b3098233c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 19).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b03cf179e7e95408_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c59403c4-ae00-47f4-8b18-72453a7369e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 19).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8a0bf12e7daf04e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f48e6df-82d8-445b-bad9-d5247c247316', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 19).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '597756e6f1f6c57c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a139256e-cca2-461b-b6c6-e6af297ac106', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 19).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '3c16cb0747abdcde_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1f56297-f251-491a-8099-de89a80be248', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 19).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8b332625a51fc53d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d97a719b-24fe-480a-9fc7-8ef68b6baa44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 19).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 19).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b2d6e899b23208f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9de329b6-5f7a-481f-af87-a2646cd69e62', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 19).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 19).', '{}', 'Automation', 10.0, 'ab85dce09f261b4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f33f0e00-88f0-4714-a24f-20bb8d7444fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 20).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '63d2ea99f0cfa3aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7eebe54-0e51-480a-bbce-e66688e9f9ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 20).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'efd8addd40985d77_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee318252-7f87-42d6-ba51-338eb548dfea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 20).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 20).', '{}', 'Network Fundamentals', 12.0, '0f8145b2acb44c71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48f40133-7619-42d5-848e-1b4ae47d86f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 20).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 20).', '{}', 'Network Fundamentals', 12.0, '1cf294938cee20bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c2d7c64-f354-46cf-b4ea-35e55b088a1d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 20).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b39d670db01ac0ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ab700c5-76fc-47ad-a98c-d80e9901982f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 20).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '893a29695c113ca9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('194da071-8273-44f5-810c-e7567c91390a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 20).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e4acd5139a44fc82_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc5128af-d1a1-4e7a-a9fc-d483c85bd253', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 20).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5d2e9f24ade45d5a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03a563ec-5caf-46d2-87be-11bb761eee73', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 20).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '680006b9bf50258c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3138974-988e-445c-99d9-f604c06d5817', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 20).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd47b7f967e2650a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d203a12-a9d7-4b51-ba58-04817f0a2b9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 20).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'bc1b1dcecab41cf7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bd80646-4b21-4845-9872-24e6d1afc9c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 20).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 20).', '{}', 'IP Connectivity', 12.0, '32af494d8cb08ea9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f46cd8e-53f2-4958-9831-7cc66719b626', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 20).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1d2eef5895eb3bed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05f8e725-f4f3-40bf-8cb0-ad1e62a67ed1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 20).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '01c9e63966344ad8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('366cdf6b-73e1-4aa0-993f-aadb0e08051d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 20).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e9781c8af020e5df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a97ddb3f-ed9f-4cb0-b5c0-15f2cfcdbaf6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 20).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c94bedb1b3631c21_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('141707cf-48d7-4bce-90c0-8b59a27597e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 20).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '85c1055744e3ea34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cc9bf87-e199-4306-abde-f4c514a463a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 20).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '706f9b64894fa238_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01544417-74e6-420c-a828-86aaeff42b8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 20).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 20).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '991a8d5a7d566bc2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f63f22c6-aa5c-4cae-9083-92d3dde152e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 20).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 20).', '{}', 'Automation', 10.0, 'de1a36114388ff8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('140448fa-ddbb-4815-a3da-bcd5f5859c1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 21).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '05cda8886f99edc3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d23cea6d-be5a-4f10-a928-da9cfcee1a41', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 21).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '14d53bc0b460e83c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f774fe67-a1c6-42e5-b2df-edb4cd6a3bd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 21).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 21).', '{}', 'Network Fundamentals', 12.0, 'fca792df2d510c98_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03861d76-d4d9-4cdf-a541-d93aaa1b2a4d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 21).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 21).', '{}', 'Network Fundamentals', 12.0, 'e3147f2853bab035_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f941a9d2-8728-437a-9ade-317b8649e2c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 21).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a211c024d95bbf0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d92638a-483c-4321-a0cb-a010cba9fdb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 21).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6e96dfb2bcc98372_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1f66149-94af-434c-93fe-19090bdd6e0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 21).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '84634bb68e958ba1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f499dff-b8aa-441d-888b-444fdc498b3b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 21).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '64d128501adc7f48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('063f50cb-017e-4478-b478-626da4ee5b09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 21).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'cb0419df13a4b556_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f30a7f1-e3ef-4529-8717-9288c2668f45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 21).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd4fef6b9c9345a51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e44b7b6a-97e3-443f-8b25-31378330d61d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 21).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '66d14f932065310c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d313c1d-f71e-4ff8-9e72-11293ec3f271', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 21).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 21).', '{}', 'IP Connectivity', 12.0, 'e0f2a405ab292b7b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3febdad-fbdb-4172-98cf-d24c067cfcd0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 21).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '75d93c4923180d28_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('204f8aad-7f9d-438f-a8eb-8362e78314fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 21).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1ad7eccdbe62b95d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a32aa67c-41ac-467e-834b-b76edbdeda5f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 21).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'bef960f2c7479efd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('079cb882-ec5a-4c2a-9f0f-53fe93be9525', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 21).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd57cace5f8d1d891_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08fe353e-3620-42f8-b109-5ea3d3133526', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 21).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9b9989b13f479797_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3b7ab7d-a713-4627-aac4-8cc7a9f6eaf8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 21).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5086d892737a5802_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1878aed6-c358-4012-abbb-a825b6c2285a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 21).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 21).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c47c2e652eeefb17_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c658a785-6385-4989-aab0-69add4d0e9e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 21).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 21).', '{}', 'Automation', 10.0, 'b8a6dcc914cd41fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e63b7314-7128-4702-b8f8-9fbbfbcbfb98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 22).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4e261603633a953d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0c99250-c19e-48f8-bb89-724886866ba7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 22).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '46c1b563bd030225_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c0ed446-3d9a-4b20-9817-85d23a1e3635', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 22).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 22).', '{}', 'Network Fundamentals', 12.0, 'b9cc268c788c5160_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bb83c51-4768-42de-a6a8-cfe7ce3e129d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 22).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 22).', '{}', 'Network Fundamentals', 12.0, 'f33460b676f434a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef308e2d-1e98-476c-b2f9-5c76ce30662b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 22).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5babb5cc4d19e062_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bb99174-8c57-4873-9ca9-3b14f37da707', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 22).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '174f38093a10ded1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1ac760c-9b5c-4437-84bd-9a1ebd53d669', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 22).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ec7d4e3939a89c34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc7da032-b77e-404d-9d3a-5da0c34eac82', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 22).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ada03136b5b7f3fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb83d701-429b-4d71-8138-dfa0ea9e166f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 22).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e4652bd369ad38c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65bde593-602d-4f29-a01f-2378cd6674e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 22).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5e57f5d2e28f4d38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43d1cd6d-ce88-4827-b022-3624c9957d8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 22).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9ac809cc6ccb5a88_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a0eb4c5-1ea6-45ba-be1b-fb365bc4d711', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 22).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 22).', '{}', 'IP Connectivity', 12.0, '13cdeffd883ba4f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd6f3dbe-6afd-428e-8b2d-0d5f4556275e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 22).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2640a67db9326dc3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('097e0eff-1340-4062-a97a-df5b3eee80d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 22).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9b6163d0bc534346_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0909361f-248e-42a0-9697-acaa360a0cb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 22).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '3d95014ba6aaca92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e3c8ddb-9f64-403b-a9f6-bc9a2728369b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 22).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a7dc556960a65947_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2d6c362-61c7-4be7-b008-c32e1b548d39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 22).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '685fd1f3b5828207_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76b106a6-aa8f-4153-8b2e-36ef74be82e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 22).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd2f04d1d23a092d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fef41ecb-3547-435e-b192-26d3b1715015', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 22).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 22).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '25ef6abb9a08888c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0150e041-84df-43d9-9bf4-b962ddad9ade', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 22).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 22).', '{}', 'Automation', 10.0, '766d3c93818f4232_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c927402-f722-4731-b8a4-925c2ca7b882', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 23).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '673ead89da87292f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cfdf8bd-a0e9-4b84-8a30-357ef9308bdc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 23).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7f53f54e4b66f94a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36147259-1b04-44d5-a5a3-e640efb78600', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 23).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 23).', '{}', 'Network Fundamentals', 12.0, '8979f5c629411261_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44173bbe-3149-46b7-a137-ef5e376296fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 23).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 23).', '{}', 'Network Fundamentals', 12.0, 'd29f3c28aeb16df0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bf8f8d0-0b5e-49da-bf0b-bb9cf79e7697', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 23).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2ae53bbc3a82a952_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5b089dd-9a69-4364-9231-689fb4d81d2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 23).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b63876641e633314_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1a7e7ce-3463-4330-8c76-b17b45519997', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 23).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b9853f7e1ff66776_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85b349e8-5bb4-4113-a3bc-03b34621e1aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 23).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '94c72d6640af4dff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad364945-0c27-4552-95d1-0f67d6e9947f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 23).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '601359c7835d9d74_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('756378f3-d491-4250-9aba-126feadb0cb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 23).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '3296651ddb634bc1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48dd57f0-4717-415d-8469-89adcc43f31b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 23).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f5ff1b99d310cd89_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f13c29a-fd56-467b-92c6-620650da62ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 23).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 23).', '{}', 'IP Connectivity', 12.0, 'b90cf89cd03eb148_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7f58209-a732-4a33-b231-f80c8ccf3511', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 23).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '66e56706db7c84c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54cead2a-ecd2-4cbd-9cdc-a2c4130efaaa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 23).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '15349eb784490453_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b04d19a-7c6c-4d40-be11-dacb23c9fae3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 23).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'a8c41563184238aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d34dde24-19f6-4fcb-9c76-4149963095d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 23).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '88359169747c797b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca69c397-7abc-4dcb-bb72-1db771f3d03a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 23).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9a577b9dc5353338_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('411b524b-cbf7-4942-9291-1177ad18f47e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 23).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e493d9f08b0986c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b79d381-93cf-4e1e-813a-8eae18119639', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 23).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 23).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '467dd5f4885534bb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ed0b172-4b35-4e3f-b226-dbf505a21640', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 23).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 23).', '{}', 'Automation', 10.0, '1dc94dd68dba8806_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e9e13ab-9507-4340-b638-9ac62b9d9054', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 24).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '38956230b185917c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e062496e-74ac-4c30-bbe2-9bc183d3131b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 24).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'fb66df69891b2bea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdb499f8-8320-45af-962c-36e2d4814521', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 24).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 24).', '{}', 'Network Fundamentals', 12.0, 'a0ddc0b1afdb611e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40c69586-5f29-4e53-a75c-d8c172404c1e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 24).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 24).', '{}', 'Network Fundamentals', 12.0, '22db1de620d323ac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73b6b687-68e1-40c1-9e72-0dea7f5106f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 24).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c8d69edcdf767d26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b90e77e9-93e3-4b3d-835a-e62ffec6ae7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 24).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b87a768c310303e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4e052dc-13a5-41a6-b65a-ca624b864a52', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 24).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eb5ceb46eab1f34d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a433c8e4-0169-44c9-a243-ae47d358e0e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 24).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '35cf7f20550cce18_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65850268-305b-41c3-a1d8-ec9285d91757', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 24).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b19bc76ae0be6ce8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aad5c0d8-306d-4a84-99a2-e88c4f333d81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 24).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd652adf38000d32e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06287fc1-f52a-405e-a9f4-3f96e493e572', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 24).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '3742ddae495385c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edba1a1d-0bb8-499a-b340-f30bdeba77ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 24).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 24).', '{}', 'IP Connectivity', 12.0, 'c8f8e2d03b86cf28_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d65bba2-0f54-4824-8929-e90601e6a51e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 24).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ed8e8e248c377aa2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1588de2-acec-475b-9e0a-c06f5a937e3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 24).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '082f661f950a6ccd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68abbb4a-cbe4-47e2-af1d-402a1dc532cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 24).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '31648068b575507c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd7b5cef-a28c-4da2-92f2-be3c4fe7d519', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 24).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a6d3241d4455eaa7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddde38a3-7110-462d-9f2f-bc2ff5a81975', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 24).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '1fc9096798ae0a4c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e5d71b2-7e24-4f2f-9bc5-7bdd73415b21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 24).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6a725dc67a92df7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df18fe3a-829c-4829-b1cd-2eabb5ede681', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 24).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 24).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '062e45e241139ded_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49b168c4-cc18-4aac-8c65-c780987d8736', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 24).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 24).', '{}', 'Automation', 10.0, 'bf423fdf98dd6ee7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('670c68b7-3dae-4a5c-bffb-0cf0d4470d48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 25).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '725b5ca63cb089b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47e971f1-9a5b-49ca-a29e-c645985db4c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 25).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f083fe9b5f1b0469_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a084e37-e801-4aeb-9f94-571a43b8336f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 25).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 25).', '{}', 'Network Fundamentals', 12.0, '9f42979a050a1937_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddcafc44-bb5a-40fe-8eeb-b87851e94f3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 25).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 25).', '{}', 'Network Fundamentals', 12.0, '1a0f91807973775a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37a87d34-715e-4ede-96e9-fd5c1b22eb15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 25).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '205871f689f7541c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('890529c0-578f-41d4-b3a0-660a361af15f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 25).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3ff838ec624a8319_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0506fe9c-3b5d-4889-8b63-50eadf9bac41', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 25).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '66c2e16feccd69f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cae8017-bd2b-486b-aebf-2ab51ba75ab4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 25).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e1e02ea7cc1a1c1d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2db4c101-a40a-4b19-a776-e881818d103b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 25).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c921682ca2c3dd3e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4671a6a-3c5d-4ca9-833b-8ba3442e697f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 25).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0364846eca7656c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7373d7d-1a94-4f95-9c26-7ae1fb206864', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 25).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6fb14286b435a1fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85212249-5869-4231-bc78-fc02f34eb9d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 25).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 25).', '{}', 'IP Connectivity', 12.0, '77e7a7369ac30ad0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69e3cb8c-c35f-418f-8d21-d5ef505fcdbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 25).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0c587002b4a5bd7f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9668bace-98f4-49b1-9681-216e9350b8c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 25).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd742a1a8bc0077a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9117fa00-6739-434a-833d-2105b7336b99', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 25).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '3b6428684864bff8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63bd38d1-f9ae-41bd-9367-df91b648a8b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 25).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c2b79d4bb441eeea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94f5fd40-45b0-4e22-8e09-a75646572252', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 25).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'd8ee378a75ca511f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db6f9b8f-8587-41f8-b8fd-9b81d6dee0c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 25).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c944bdf18add2ca7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39a73535-10af-478c-9aa5-7b6143b59056', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 25).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 25).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '12ea8089653673d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a26f4c0e-aa2b-4075-aeb6-8cdc1e205c10', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 25).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 25).', '{}', 'Automation', 10.0, '10001d25070e8aac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5c9c815-0a79-47c6-bb1e-8521a9efe74b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 26).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c2f084a0d572b8f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ce5f9cf-f853-4a8b-8f2b-8b39a470685c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 26).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '33894efca97a3c92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3976e6a-7609-4a58-aaf8-81a7d846744a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 26).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 26).', '{}', 'Network Fundamentals', 12.0, '7d585bc129a88f8e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad07b451-bfbe-45b5-82ed-b95e243cf728', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 26).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 26).', '{}', 'Network Fundamentals', 12.0, '06bd23610fc9a559_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4a9144b-7317-481a-ba14-ce6b3c98cf68', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 26).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3755f932e43c4a59_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4061fc97-fb60-4bfe-884b-507f57595c95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 26).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '93d534a0e4f92ccb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac08260e-3765-4528-94de-e439973821fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 26).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e395a059b3f6c343_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cff9a7c7-58bd-40b2-aa93-5c271aca4016', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 26).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '75b3c25a5c8fee54_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27ecf658-b1a2-405f-b7a1-c51dbe15cf2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 26).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '140e78c744a5b6c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8baaeb7-689f-4878-8009-34902bd2e565', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 26).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'fc910bbd06fe9eaa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8e68912-1683-42be-ae55-60ddf7e5f287', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 26).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '465375555f90bee9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('003956b9-6fe3-4e95-84d8-69352bef8104', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 26).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 26).', '{}', 'IP Connectivity', 12.0, '9799e042bf18392f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4740ed54-ff23-45b5-9e76-ae21b85d3ed3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 26).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '08bfe640b995a35f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27fcb650-7a54-4b60-83dd-d920da6505da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 26).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e1af4bd82be1d3f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7bdfb70-2f23-467f-bf8b-fe6f1f5366d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 26).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f9f4fe272e2a2140_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92d0d7e7-53a2-41fd-bc69-307185e305f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 26).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '330f2ce74598da59_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1be0867-2c9e-4e32-93cb-147dd5500a01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 26).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'cb48f5b703f0f300_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57185881-c192-4912-8784-4a705071ec9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 26).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4f5944841489c951_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('804bbcbe-43b4-410b-b435-e65102793c38', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 26).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 26).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '53e3cf1cb14f8061_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeb49d4f-0533-464d-a622-dbb69499bb8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 26).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 26).', '{}', 'Automation', 10.0, '1e111e2da9025536_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f91d5f2e-4375-4c2c-8b62-202aac02bed3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 27).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8801a8d3f82b0f24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c015a17-ee5c-4398-8041-9c67e6fad721', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 27).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '268920fa86a953e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffa4433e-7b47-48eb-af30-1fca85db2e3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 27).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 27).', '{}', 'Network Fundamentals', 12.0, 'eed7b0e202e9a091_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da1b4179-80c4-4f86-8cf3-a802dce75464', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 27).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 27).', '{}', 'Network Fundamentals', 12.0, '35bc2cc78a289bb3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc296791-ee1f-4212-ae1b-8152a28f6ef3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 27).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd054f78ead638554_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5718bcb2-054d-4ca9-a459-34fe3c024cc1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 27).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '84c9b0c6175be3e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87959518-6b27-45fd-9a4f-5e86042c4db8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 27).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3369e868615c434e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ef3605b-0135-450e-9b27-785e30933689', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 27).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8aca533f933fba24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a9025b4-eac4-4867-9d50-b04fcd2e83a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 27).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c05783000f3a83da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3ecc6a6-ce1d-46b4-83ad-32f7688f8099', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 27).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '755697084142328a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fab7d3e-4c3b-4c96-bfe4-cc0dc5b72b8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 27).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '4c442199593938d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('334b5f35-ac5b-4a22-9055-33337de1dcf7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 27).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 27).', '{}', 'IP Connectivity', 12.0, '3fe0d1bd6035625d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c14f4f85-1f6d-4f78-b5f9-036567a89fbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 27).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a2067400583269f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('222ddfd9-20d5-4cfc-9909-c7b5b93f418d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 27).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5e557b973f91d41d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5098c9d2-8e09-49e8-ad5a-a2ee579121ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 27).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'a30e39dd7977259e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f58a7132-4cec-4b75-a62a-420043e898c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 27).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '48b68bb6e358cf1e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('871bc6c4-0f30-4e38-8d09-35cfdc00520a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 27).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '71491cc42a7bb4ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd5df00f-f23f-4f31-80e6-b511971835ad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 27).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c3cb2be75a517789_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a5b5639-e1f4-473f-8bae-57c29d479662', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 27).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 27).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'eba537d07b790b42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1e52fbe-9efa-43a5-8bb0-b7e35a67b636', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 27).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 27).', '{}', 'Automation', 10.0, '52d970fbf768e807_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a364006-2e58-4f8a-ab1f-7aa41f1e3b44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 28).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '02d67fbb3a119f19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32bf670e-3510-4f9e-86d9-9793e1dfc74a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 28).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ab6c20e9adac0372_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02d7d371-9a73-4b2d-ba6a-2f38f4d7ebe3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 28).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 28).', '{}', 'Network Fundamentals', 12.0, '2048cc064bbb1213_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87a026e7-8d0e-4692-a898-f5716479bb30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 28).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 28).', '{}', 'Network Fundamentals', 12.0, 'c142a96e58bf8974_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0fe2f90-8068-4e2a-b465-9e0adb6d5827', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 28).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0ef7a7f9bc6ca8ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14031e24-aac7-43a3-96ae-b1e88e2f2cb0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 28).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3b3a1f00e5ba96fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c5047d5-e6f4-484f-b1fb-8880c2f9ac80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 28).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7ae686478d6788dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b983bf66-815e-418a-8d02-95d37a407eae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 28).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '070662b87e056d6b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03f0472c-f44c-474b-9b31-19575dfc85ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 28).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7d8b6e249ac85b79_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbb61bdf-9372-4d47-bab5-10323536be05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 28).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '89f2da7113d9df68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94f47efd-b31e-4411-80df-891bb841398e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 28).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd6b548ba088e41f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13a641b5-07dd-4d89-ad01-d112242597d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 28).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 28).', '{}', 'IP Connectivity', 12.0, '24a44f1ac793a0f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00a9b520-7659-49d1-ba4e-9e668273f607', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 28).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '168283c180b5491b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd88f137-725f-4d74-83da-0cf21a0308ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 28).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b534c1b17218b235_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('226d8f98-3edc-40d6-b675-2ded486d267a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 28).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b7415fa4415f5bdc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15bf9755-9df8-4daf-afa2-dc9c349a183b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 28).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '274c232a26d95b29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a720205e-2a94-4517-a3f5-d5b1b9341ff1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 28).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '29951ff9bdb647ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b0fad8a-cb16-4c38-af27-4918063801df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 28).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e6935aaabe56aff6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57f1d808-7630-4e6a-bf2b-d0a42ecca641', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 28).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 28).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '932388fd0d7110a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8293ff88-2360-4cee-a00b-ed53b0e395dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 28).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 28).', '{}', 'Automation', 10.0, '1db5964f9167fa59_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e5a37de-32fc-45ca-bb90-19a41d4e5292', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 29).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f9c88aee72dac4de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('352e907a-349b-4f80-a332-9f9fcb97bacf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 29).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '18c3326fd5773eed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e07c49e-663c-4408-b3e8-7a39840bae71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 29).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 29).', '{}', 'Network Fundamentals', 12.0, 'd54dcc13cfbf4c2c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3ef4e9c-7387-4aba-a8d8-f9422bcb7956', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 29).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 29).', '{}', 'Network Fundamentals', 12.0, '2832085682ff599e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ec70d90-9a50-41c7-80d7-421bc8704e58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 29).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7efa20bf743ca3e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('777fa5cf-0dd3-48c0-bbd1-50facebde593', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 29).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0b7fab2ba4e57256_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4216902-6895-4143-bac6-6d77f5bb43bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 29).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9a742e7f90bcfa9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a471d18-602d-49aa-8b27-823561488fcc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 29).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5160c45c66e447dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c932f5a1-ecba-4c62-9bee-c0ea861b5fbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 29).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0780b2e503b43aee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('427887f0-fe69-41d2-9adc-0d9281a9a15e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 29).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '39fea1bfc7aee08f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89729c66-ae49-4ace-96c9-22aed39564da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 29).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '37410998859d783f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ed76c95-2247-4f04-b1e7-7267b25d7461', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 29).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 29).', '{}', 'IP Connectivity', 12.0, '86d742a297e4d60c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffe37345-38c4-4c81-8622-32b4666b7be6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 29).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7b937698f1b5227f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8b31295-b1cb-47ae-b2c6-0d6347fb6dd4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 29).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c6457794663837c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51e691fc-7291-4172-b0d1-2627257a8304', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 29).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f5ff26898a8c3c3e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04468e05-4e1a-4349-8cb0-8c686135afec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 29).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0120343e0db8f00a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5fa0793-f1a7-466a-aa75-414e509e1c14', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 29).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '04ea79310bb2889a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('197b5a17-774f-49e4-b28b-004e01b4a1b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 29).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd1e0f423d4c9c969_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35810b18-8259-4162-8217-7e44eb176773', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 29).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 29).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'f2ceac0cae669eb1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c472f27b-cc31-4209-94f8-b2b80842062c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 29).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 29).', '{}', 'Automation', 10.0, '3cbc8d9479cb4bbb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f492e9ab-5169-47fc-a5d1-98d684e712d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 30).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1f956d4a5f9e8ff1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ca2923c-b935-4adc-a4dd-4607c24f108f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 30).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5e7f12b316598f26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8603532d-aa7a-4709-91f5-e95e7d994f6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 30).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 30).', '{}', 'Network Fundamentals', 12.0, 'a4ec5b6974ddd20e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4673fb24-1579-4d3e-aa4c-4cdefff367b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 30).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 30).', '{}', 'Network Fundamentals', 12.0, '4ba80bd6fe244d6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89ded655-74f7-4794-b7f3-be91935069a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 30).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f164fc1321de359d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c14f2cff-bc7a-4be2-8427-1612fe05660f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 30).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '38f3548cc52d41a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8b662c3-e210-407c-9f05-21389c4c400b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 30).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '38f389d2cd25c2e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e836d237-8262-462f-8e86-f242226fe0d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 30).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd4262b7fd3daa813_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29699f17-2b78-4254-b5a9-0997851c2c6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 30).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '46ea23f37e2cb33a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2600490-92bb-4405-9112-2a590341c489', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 30).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5462222a2c9c575e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5805c269-9446-49d1-b1f7-74f47870b2ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 30).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '47448310810b24ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09469683-d1d2-4771-b1b9-a94bdf940921', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 30).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 30).', '{}', 'IP Connectivity', 12.0, '3bce444f465fc882_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e53e5c65-6202-45b2-ad18-9afdf7dae4fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 30).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ede967faac1caeaf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bec491a-8645-4f72-935e-f8bd50c5b295', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 30).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5996cca037bb32af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72a9ff60-52e2-4aae-9640-5430d2a52df2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 30).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'eb4712d64ac07a3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66d7295a-0308-4001-bb41-553329faac71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 30).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a409a8ac4dc999f5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36b0e412-6c97-4ae0-851e-9f24a388d86d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 30).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ff200ad6f40b6a5a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4eaf31a3-8037-40a3-ae7b-02591f46779f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 30).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e96d2e1b6eda86ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ec6f8c3-80e6-4420-a6bd-43a13689a29c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 30).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 30).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9a6a055ba804f0ff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a51faa4e-2104-47ce-8c76-9bb9ac9a9f57', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 30).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 30).', '{}', 'Automation', 10.0, '4ccf718933475fe2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6baf07a4-e472-4327-9f7c-38efe45f0a60', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 31).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'eeaa86250b2d1846_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aad9897e-329c-40ef-86eb-0fbb9311b978', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 31).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '07344eaa0f119347_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dd5f422-5ba3-4533-8f7d-1e41db0860b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 31).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 31).', '{}', 'Network Fundamentals', 12.0, '9f7278cf5e199f98_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c6cc446-400f-4278-a677-c3be8185ad19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 31).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 31).', '{}', 'Network Fundamentals', 12.0, 'a43da8df0d1a8ccc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22578a09-3e7d-466d-bcdc-d5d67a136498', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 31).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9657371166bbcbce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6561273b-d1f4-4f23-8397-81ade65dc171', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 31).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6774e9736fbcb5e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a94f3922-2d0b-4284-9501-79038f6e7dce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 31).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8aff54a0aa822e01_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9bd0b96-eecb-4a25-a99f-20146f243f93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 31).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f7e8956cad40db61_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47bd0c92-6d25-48de-88da-dd4a4c845570', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 31).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '64b01949411e4361_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('302b1554-ee5e-449f-8a17-cf1ef4389dae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 31).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4fc73153f5503aac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aabf4bc-d8b8-4183-a096-1f5699ca3900', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 31).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0a7ecaac7f213ed4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6877c37-e9ac-417a-ac4a-273df33c76d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 31).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 31).', '{}', 'IP Connectivity', 12.0, '99922c9e7c9d52ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7525a768-fc88-440d-a9e7-d6bcb1226c26', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 31).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9c655e3d8a0a17f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74219d8f-e6cd-409d-956d-aa643445f387', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 31).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '82f38d9743e182f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fbf5916-e2e8-4998-8f0b-08b48c6eb299', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 31).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'd22017f71059a2fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dadff319-65eb-49d1-9358-d18492798d5c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 31).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c447dc8da12b610c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c565740-ef5e-40da-a22e-059ee1857c57', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 31).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '86f8ce67bf48880a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('481ef4a4-706f-4c9d-a3b0-b52dd88d8091', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 31).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f3cdde4aaf7931dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7db8098-9d77-4b32-b413-8feb0153825d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 31).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 31).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '101f086cde2b705e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a6e12ff-8580-4517-b4d4-5dc682f1f1a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 31).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 31).', '{}', 'Automation', 10.0, 'b8b143bdc0d30f6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24aa4449-a118-46c8-a58c-f9848655f984', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 32).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '17175665b50f176f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3789f1d7-d7e1-4c83-8346-84cc55f231ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 32).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0c9d235a5a64f354_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a18f8ea-a687-4910-a3a5-df300d62cbbb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 32).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 32).', '{}', 'Network Fundamentals', 12.0, 'e8327344933416bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa5ce838-f2c3-480d-9afc-4ccb62ec3fa0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 32).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 32).', '{}', 'Network Fundamentals', 12.0, '549891eba8bf26ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baef2c91-8971-4cbb-bba0-ecaa1cf2ae02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 32).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c0b97438549149b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cef71c77-2e3a-436b-8868-ec8aa1a350aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 32).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'afe88efb71b641af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5614759-6145-4932-9dcc-3e446a3b1bb9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 32).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2861451762df1a15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddccaf7a-b99c-4853-92ae-58c011aa7ef6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 32).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '87b8230506bfe381_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdee00e6-3ee6-44be-b817-b3d75d6e5336', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 32).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '04568fbad97866b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31648439-5a7a-47ed-9b3b-bb7eb1236c12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 32).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '3cf4f301373d1a3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f91966e8-962d-4906-95bb-dca785167a31', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 32).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '09dadf2112cdd98b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9262881e-ef29-4383-a932-74b50f8225f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 32).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 32).', '{}', 'IP Connectivity', 12.0, 'd5a72cfdb37983f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('558a2ede-1ffa-4b90-87bf-0cc77fec5a07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 32).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fe8b7e835c220727_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f508e01a-4909-4e24-99bb-ec3eb5e74fbf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 32).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ed30527ff0aa83e9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('690ca1e6-3e35-4d07-8bf4-abac1e96f4ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 32).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ad8eb4cfde065983_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f26c4396-9c87-401f-9a77-58bd142ddcca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 32).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c702a4fd4f40d3fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f52711e1-591f-4a59-baf5-286567438168', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 32).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9192378fd1cffa5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e10a4e58-d502-4cc7-9b40-39ee35773d03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 32).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '28f8ae5aa9b0418f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39ddf00a-7ab1-463e-b300-8523a21e72b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 32).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 32).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '281496402319eab2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dced08bc-7b7f-41e4-99be-c43bb1ad13ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 32).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 32).', '{}', 'Automation', 10.0, 'b1cccbff90aaf4bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52b218c5-dc55-464d-83e7-a98f5c18e9b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 33).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7131d29f61095f08_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fd17514-dad9-4dfb-b2e8-b8b2854c8990', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 33).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '51fa922a184e1a27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c02c579f-a4a4-4c98-b3de-3ec817ad1948', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 33).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 33).', '{}', 'Network Fundamentals', 12.0, 'bf365752e09200b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e8a413c-4ce5-4346-b88d-2d3f6049ae3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 33).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 33).', '{}', 'Network Fundamentals', 12.0, '38ea88f6d52ace96_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41f4f811-7a85-49d8-a7b4-038537175067', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 33).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '56d356114cd2b785_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4bfa8a6-c59e-4356-8726-e005a056929c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 33).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cde6bc952fccbe3f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36f75f76-d2e5-44c5-9503-0971f981b5e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 33).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ec2426adf86c7598_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('feebef85-2e8c-482b-bb6f-bc57a315b167', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 33).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6e3dbc9815af0cf8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8386265f-8dd4-4b2e-ae59-2042ad29a2f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 33).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8a1d5e68cec62478_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e04b25fc-10d0-4e80-9152-c130efd255a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 33).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '63c2b0b3d6766a2d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36013e37-7f41-4a07-8626-52f9c7755d75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 33).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'fdf125cf50b9586e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7146f1c1-2141-46e6-8b8a-b615d1a9c983', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 33).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 33).', '{}', 'IP Connectivity', 12.0, 'b039cdef3dc60fd1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bae4c0e-6c6e-4f88-9b8e-fb3b2b8fa3a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 33).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fefcbc1329fecb7b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25a24f1c-83f7-43cf-8d91-ccf95a28237d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 33).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a7492eb2c1990d6a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac7586df-e6f1-4482-8e70-f98e25170bcb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 33).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f8c3cd61e6ce5df7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f6bae2b-5c84-4569-b28e-aebcacb44a65', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 33).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b0e805bde0869bd5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1419f3f-228c-40a8-8db6-413166157578', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 33).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ebba31605356069e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dc6d2cc-2077-4554-a9c8-99fb2a35979a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 33).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4c5f6263bca9df99_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c98247ff-3b16-4814-b9d5-bc9c0e876911', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 33).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 33).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '938d91e6fe481d5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59bb389d-5626-45e5-a7a9-04619e5f19df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 33).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 33).', '{}', 'Automation', 10.0, '5a307b89f7a9754c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6201297-171d-4bfc-8802-82fbc2abd9ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 34).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2e476ca3e15b28d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e10a6b2-5e30-44e2-ba8c-786206636216', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 34).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '86caab2e999b35ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a7efd78-994e-4b80-a824-1d3e9a42aed1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 34).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 34).', '{}', 'Network Fundamentals', 12.0, '4c05d5bd535d7f56_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2aceba4-0649-4f0b-9dbf-9d713532a35c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 34).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 34).', '{}', 'Network Fundamentals', 12.0, '73de8881669358de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff0263e6-a99c-46d5-9520-fb1ed114d3d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 34).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dcc423bbbaeed9d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1619417-2a9d-445e-ae9b-3824aa613e21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 34).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '34422deab0a784f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2566cf4-9f5f-433c-a98d-e187d4df1a19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 34).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '62fef6705c545b08_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab50b5d6-0c09-48d3-885b-d26d4ced9da3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 34).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7b308ee57395d31d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdf903cb-eec0-45a2-ab28-7d94fd6ffa92', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 34).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '384a7e32b2b3256f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c49c5b5d-d9a3-45aa-af20-97e6de2f1122', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 34).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'bf2322385f3a4b0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d7ac9f8-da30-4f64-9f73-381e4fac95ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 34).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '176ad919b6ba768b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac6ec4fe-01a6-43d0-bfc7-42457423bba9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 34).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 34).', '{}', 'IP Connectivity', 12.0, '9f24222a72fa32a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b6b4525-38d9-46aa-88d1-0e476ced3d87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 34).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e70ac35882fcd931_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2125f45-7e3a-4722-99c3-01cb0e9435ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 34).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '767511c777856efe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87e863ad-2432-4dfe-9ccf-b5df3d8e6965', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 34).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5a9a0d941fa881c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3f51b1d-abed-4c0f-ac91-e02b0dd80005', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 34).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2cd1206dd9059a6f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca4104e3-a79b-46a4-93e7-d7120ddeed01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 34).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '1abca79b61963e97_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fd27a53-d2d2-4f4b-803a-d2a2a19ad189', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 34).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '76a999224ef04187_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acff9171-556d-43f8-9774-499c2f57c8c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 34).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 34).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2fec4bb14c5dc27e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b4a0582-248e-4aad-98ea-cac41f45d52a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 34).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 34).', '{}', 'Automation', 10.0, 'a5f65fa208a01833_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05a3c896-6410-4660-ae87-db06b6cb9d30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 35).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd8340d90da0faa8e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb1df44b-f3ce-42a9-9a0d-2c56a285c5fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 35).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8ea23b0c30cd8c91_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92348a04-e448-448c-bfa6-cd844adb6ecb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 35).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 35).', '{}', 'Network Fundamentals', 12.0, '20d14f068d5f7f2b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64d64445-909b-430d-a974-b6b605ff99b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 35).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 35).', '{}', 'Network Fundamentals', 12.0, '578ddd38bd78ef1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0abdfc54-47b4-4735-8f0f-291f1bbab17a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 35).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '92e8654825a869f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34127c71-9093-4c4d-bc21-822cca89e0d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 35).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '146470fd91aaba48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa270274-07a0-4805-82a0-259a466214f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 35).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a231bf9a0afd6d0d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35e479a8-21da-43b8-8f19-22d65a5817f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 35).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ddd6cdd1c128a871_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd087d41-415a-41e7-89c0-99ce1c70d789', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 35).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3be740f59b3e65ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f39be408-7b85-4138-9e1a-1e46abd40e8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 35).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e514881f9261da14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77a481d1-ff2b-4fe6-a11d-be60eb28286f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 35).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '83393e3928bf93e1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('097a71c5-87cd-45c8-a090-9fc53760a62a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 35).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 35).', '{}', 'IP Connectivity', 12.0, 'fef0a6451fecbd37_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8ace460-0382-46f4-a22f-f61fe6559275', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 35).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6936b59bae29e385_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3004819-0706-43d3-ac37-f91689af669c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 35).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '66e8d9701aa49720_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70a6fcb8-0429-4e65-85d3-23ce1db6d838', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 35).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '52d83762fd8473ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccd15451-ce9d-4331-b28a-5490167ece5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 35).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3810a1d294c932fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7ec15e7-a77e-4650-a276-64a1ccb59c0b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 35).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'faaf9ce5a0a2a1ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('136e0b7d-7cdc-42d3-9851-2c15da50cc48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 35).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b2a56b20d9b75b98_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92f494e5-f98e-4166-b2ae-2f831aef6c6b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 35).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 35).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c7011e765ea547bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95dbc1ac-527c-4b4e-b06f-4de550d4cbf8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 35).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 35).', '{}', 'Automation', 10.0, '132d1f1672300dbe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad8042cb-c58c-43ab-97e5-6e794bfc680c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 36).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c7501ab8979d315e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dd8012a-de57-4fdd-b50f-a6213cd2f89e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 36).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '04af5b5f3efa870f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9a4bb5e-1ab4-4be2-a2ce-67c3f5e950b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 36).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 36).', '{}', 'Network Fundamentals', 12.0, '6aadd7aa11dfad01_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75fc7bd9-eb19-48d8-92e0-3d033c44a4e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 36).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 36).', '{}', 'Network Fundamentals', 12.0, 'f84dc82f988ccb7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('560f938a-274c-4ceb-be50-33e1dfd93440', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 36).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd323f5b4d696cfe2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70105b98-65af-47db-8aff-1063e19aba0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 36).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a5f9f8ddd7a9dbc0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e5bdfab-ec79-4613-9741-52df03254efd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 36).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8cb6c003324e9815_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74efacf0-5a37-4f1f-b41c-45289d97dcb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 36).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4dc185c159ce90e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0940d3d8-6219-42cf-9c89-f9674bdd0c91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 36).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7aa139615e3b6c71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dab72646-2ebf-47c6-99df-e707e17d718d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 36).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b7936078a3fe88e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4936c4d4-b119-47dd-a04b-6ca4e0c214c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 36).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '91570befde512b68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('672ba847-d202-4a0d-86b6-6ccfbb879860', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 36).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 36).', '{}', 'IP Connectivity', 12.0, 'f4c33e1339058e7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59937042-f8e2-4377-acf4-5abadc0b7982', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 36).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '452a7d765eeeedd3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b65e1b41-4b13-4af9-ac44-d73d41fea6c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 36).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c272a2daf6ebfd0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fb8007d-1b6b-4f07-9dfa-3eaab28500d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 36).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '82a4f65ac4d4c5dd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae0a6e39-42f6-4034-ab3b-e08adf607825', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 36).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '23e30a0811f51ed1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e747b728-abb9-42f6-99fa-dc4e1274c394', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 36).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a930c35e5329948d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ec1f312-7ea0-4e49-babe-c70e47b0b7bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 36).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b4c5d13fa2b3fa90_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1372ff4-a80b-4a43-81a2-c52adbdc3810', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 36).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 36).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '13836f1f1f92b2cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32e88359-634a-46f1-93e7-f73b74a722e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 36).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 36).', '{}', 'Automation', 10.0, 'c0a07a90651cce4a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bca203ce-db6c-4c9c-995d-d14d601a2d27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 37).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b023451d8124df1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe0cb879-5f2d-4a0c-82dc-57fa8b248cbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 37).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '80c76240a065a0d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c22e32a-cec7-455e-a86f-06f60677661f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 37).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 37).', '{}', 'Network Fundamentals', 12.0, '9a445550deaa1e80_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('887c763d-5e1d-4579-b034-c683ba3f0eb7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 37).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 37).', '{}', 'Network Fundamentals', 12.0, 'eca87be8787a9705_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74b92add-e150-474c-a4ef-2df01741c401', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 37).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '674d999d6e99edc8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dea90a0-cf64-4b74-99b4-1b08ddd01bd4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 37).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '713e83b0809b9108_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91d1381b-d4dc-4895-986d-caa8c9be7fca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 37).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd3b7513c88819631_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0eb9544d-c0d2-454a-b920-583b6f7fc59a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 37).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e93744e675422c6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dce4975b-b3ee-428f-86b6-8e0b9912967d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 37).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'fc862072921940d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2d5d1c4-7399-4394-a482-f194221ef93c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 37).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '93225defb6e509c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d51c3753-7504-420d-b305-45755cbda404', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 37).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '85dbd8745c0c1b14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d6a2d0d-a8ef-4b6d-967e-3fa910c60bd7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 37).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 37).', '{}', 'IP Connectivity', 12.0, '5da4cd3fa37902ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec7fc9c8-5563-441d-8b04-708da7e8c62e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 37).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd61370d5fe42eecc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a9ce190-db9b-45ec-9824-15ef2447a839', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 37).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cd579f3ea59eedf4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f3d1eaf-82a1-454f-9381-842dd805673b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 37).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5911aea5d5cb135a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dd544dd-a272-4fe4-8b76-785f92aac2ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 37).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c960bf6713c39557_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('409ea840-e85f-4078-b984-775a4d23eb53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 37).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0aa0a218ae32be2c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61a82e91-df17-41cf-993e-1ed3e861f5ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 37).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '69fe56e2a56c3d9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04f72ebf-dc3b-4830-bb36-2a8ca650b81e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 37).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 37).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '79541f1575bb3dd0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3d444d3-0e8d-4ef9-b934-f680ab578735', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 37).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 37).', '{}', 'Automation', 10.0, 'b0b8b86e73aaefcf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d10099b-1046-4567-be55-f46dc2e5cafd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 38).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '982f270d54572213_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc27d896-9673-44b1-baab-f12edebe2ee5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 38).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '86bf22b19fd92943_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b142c9e-68e8-4372-ac4f-e99676d94b94', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 38).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 38).', '{}', 'Network Fundamentals', 12.0, 'dbc8022d6dbba2a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8a435a2-5242-4761-b6bc-da229140b892', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 38).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 38).', '{}', 'Network Fundamentals', 12.0, '979a7db874d7de2f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79000fbd-cd6b-4b2d-8d80-0fafca68a94d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 38).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4ddbb5f3d97ae802_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31aa2980-72f2-4611-8f63-97b421467a9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 38).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0954c4eec2844196_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f532cfd1-ca49-4e72-ada2-bf3679201089', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 38).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6a79d07a83b4206d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d46a411-4634-40da-be8a-19748489406a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 38).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '57bf2b7da2ad622b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9888d49-687b-440c-b33b-174b86e4ec39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 38).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '6acfd0d100a8839e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27ed3fe3-3b6f-4182-9970-4d77135ad4bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 38).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c93b1b90c5191393_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72d7105d-7218-4c36-912d-e2883dae4ad0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 38).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '8139cd8343605de2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f54d95b-0c45-4198-a34c-f183dffa3b5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 38).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 38).', '{}', 'IP Connectivity', 12.0, 'e86f2b28de67eeb1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3a8f9b5-9206-4b8e-b94d-1d9b994073e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 38).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '117bbc315f8a902a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('933731f6-58bc-4b3e-8718-e9b0ddc372de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 38).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2b8f82c6d14fc2f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7fa9b16-36e5-45f3-be6a-f135f39b2e7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 38).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'bd33d64dccaba0e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1c131b2-be74-4b8b-91c2-a9fe2c06932f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 38).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '414e3086b642d731_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04c40ad7-80e1-493d-9b16-6335b4c03c7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 38).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b2b5e861e25f3d09_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d5f7a2e-4a20-4234-8bbe-cd5d5972be29', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 38).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ac5acc6b665b0509_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc4b67f3-ce7a-432e-82a0-4e785c605c9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 38).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 38).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd2226e3653412293_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6015c09b-c831-4b89-b058-19bca008e792', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 38).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 38).', '{}', 'Automation', 10.0, '4694669b0140e69d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93736ca5-8298-4fa6-8a2a-cb8dab05694c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 39).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '91cbaeddbe2145ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1405cbd-395a-489d-93be-e707e0cba902', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 39).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bebf50fd5662372a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d500287-aa33-4075-b9fa-e422a6c64e5c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 39).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 39).', '{}', 'Network Fundamentals', 12.0, '4e736a1e74050549_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be49fe2d-b0c9-482e-94ae-ed004069903a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 39).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 39).', '{}', 'Network Fundamentals', 12.0, '4ed1e10670aae33a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aff6f3e6-42c7-47c4-b184-c543f311ffff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 39).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a6ab640e9bd2b245_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdb7beb4-fd7a-494a-b78a-f1c1e88c0318', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 39).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eacf3514d8df7394_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('114b6600-67d3-4700-91aa-19dad625579f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 39).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a5e633088997cd30_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94aaa63e-f309-4dc9-98bb-e32686f0776a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 39).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7d8a82ae81c34b38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89edf9a4-0286-4279-9429-736b1955707f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 39).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '25ef559548f2e99a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00673d81-535e-4765-9c4e-bc056ba9a119', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 39).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '6ee98866bc785fa0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d22b666-ec14-491e-98f8-b64322a82d08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 39).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f8a75ef632a3c657_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa186fc4-68e8-474d-9a22-6a2a81b8516b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 39).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 39).', '{}', 'IP Connectivity', 12.0, 'f238fef5d8d71c26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('239d670a-3b3c-44d0-b8c9-8805999e180e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 39).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8dc8bd9f255e4edd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4d6f853-ffc2-4237-b082-b423b4252cb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 39).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cfa6e9dc7a298479_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c24017cd-c807-497e-a9e5-046f4be89fa6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 39).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9a414773f963adb7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1febbc5b-2be4-45ed-86fa-8b468b9c3b43', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 39).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2ebbee82fa38a35a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca5f69cc-4481-4ad0-88b3-52bc317167ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 39).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '97413dee8be46f8a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9f3aa91-bf30-4612-afdb-3ac929b499da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 39).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '90eef26f648d167c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9103067b-67f0-42fd-b6a4-cc146049dcc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 39).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 39).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e4d9ed057a194755_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bec18d0b-5ac4-4adc-8504-cd1d6473375d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 39).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 39).', '{}', 'Automation', 10.0, '6fd2745e314a523c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3618df2d-9fc4-4d4b-87a0-1f59b9236496', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 40).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '510224c274eacf50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b44dd1f1-a273-43b8-9a24-6482dcba807d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 40).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ac6f26f4c831f2d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('652281da-6fb2-45aa-ba95-9e8ca68a5f7f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 40).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 40).', '{}', 'Network Fundamentals', 12.0, '010e216d3d36c372_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f801b09c-8ba5-4d5f-91be-d748221756a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 40).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 40).', '{}', 'Network Fundamentals', 12.0, 'd31e4eaf0c8333d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff6920eb-9aca-4ae6-8848-0658ab08d023', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 40).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b178165fd3077350_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('657b333e-0c9a-4db9-a077-9fafdc61fa91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 40).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '138c8db35dac0706_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b00be70-aae6-4c91-a4ba-d9165b45c738', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 40).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e113524a98ab400d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d2f044f-7f14-4063-8796-ba757c9dce2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 40).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1b39fedb507404b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e0d8925-cc78-4ff2-833f-67778df7de86', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 40).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b73ea8b1c035e6a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18f48dad-4e5b-4b28-8090-5991d788625b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 40).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8ee6c16df3ad9c9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5396c4e3-5904-44f6-b4ff-13f0c44d77b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 40).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '706f46164f03c7c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e35b936-91c7-4924-a658-80993caa2e39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 40).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 40).', '{}', 'IP Connectivity', 12.0, '444ff44343fdfabd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ac26d73-8009-4b2f-bc5f-22557350bc2c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 40).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '11468b2ae8652995_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('912ebc6b-7223-45fd-9abc-715811b7b204', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 40).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fbe3621a8d4a4aed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0da13a9-9339-4945-9588-b8e6ac781f1e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 40).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'd4a96373e42696b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a75dd1b-1841-4cc9-9afc-1ee849639c79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 40).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4126d5ca466a1c02_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1b3cadf-01fe-4601-987e-4c7fd7dad3fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 40).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '580131e5daf84f9a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('deda7127-5111-49c2-86e6-76a6487e8307', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 40).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8d1ffb368b46715b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79b5744f-ff0c-49bb-bec4-393e246e991f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 40).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 40).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd4e56489725b0724_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb59ef37-0bd1-4f3c-8713-582cd513e102', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 40).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 40).', '{}', 'Automation', 10.0, 'e85f978401a7d753_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('601aaed6-382e-4242-81ce-ac3c58e4ef92', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 41).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8bc9dcd8dca13bbf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c736563b-a9bf-4974-8941-f152dfcbc587', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 41).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd3670717ea8384ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf6877ff-81cd-48f5-bdca-724f4eed2b2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 41).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 41).', '{}', 'Network Fundamentals', 12.0, 'fa9d6c7a07738dc7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26ddc627-6cba-48c7-9cae-46d6073de03e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 41).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 41).', '{}', 'Network Fundamentals', 12.0, 'f5db9113244a6257_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3670c3f6-7d69-4eb5-91fe-d9e182cca2ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 41).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2d77877ce10d6ad9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19f5d0fe-dc18-46ea-b17d-73af21268ae0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 41).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f2d4e6a8623bca7b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52572391-00e0-406b-bda7-da189c8eaf22', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 41).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a5d1487324b1f213_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71929452-1e45-4abd-af79-4d218e786a45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 41).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c7978dd927e9c868_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23f49d25-13fe-4878-b720-75426c00130f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 41).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'df442cca4dec4970_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('374b062c-658b-4848-89ff-e8c056fcbd9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 41).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '90220951d93fe2f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93f990a1-fa54-4fe6-b370-0598481e0df5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 41).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'af98b7c9b1bbe846_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90509653-4622-4160-8fc8-8c88ea6ee810', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 41).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 41).', '{}', 'IP Connectivity', 12.0, '6392607a6832fa5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d513f47-4e9a-4c00-90ce-6534c6299eb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 41).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5337b50fe86c1163_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aeb1e0e-04a7-4a07-8fb8-ca2dbc378dd4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 41).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4e1f2d3f75578f47_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dc43717-da16-44f4-bb36-041a13f73a19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 41).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7eb16174c53c85d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c34982d-ce12-4f31-9e83-185c5271e0b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 41).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '35dc1581956c7a26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a1473f2-1c09-44e8-9b0c-67865e61d928', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 41).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c3bc79e13036766e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04615361-6069-4fca-9c1d-bb0e717a47bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 41).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6d28534fbd9ca476_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adbf6872-b41d-4d2f-8cc0-f72536aa3900', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 41).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 41).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '4b58df1712cbc077_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54cde957-9293-4677-aa2d-aeeedc8ac51f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 41).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 41).', '{}', 'Automation', 10.0, 'a399e3fb75bb6587_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8afc8e4-c6e3-4c03-8e0e-272dfbb2c1a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 42).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '568420825a92f83e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('757acd86-9712-445c-a076-6fc0e1092a6a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 42).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3b60b22baec60a85_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bf79ac4-2305-4d05-9231-a4a2c1aa3d84', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 42).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 42).', '{}', 'Network Fundamentals', 12.0, '55d60b59f68efa36_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('759be834-0b12-46db-a6e8-a333698f0144', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 42).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 42).', '{}', 'Network Fundamentals', 12.0, '7eef130b5ed2fe38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('add504dc-4a19-41d8-84aa-87a7782d8b05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 42).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0fae225570e49b55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7252d9e-74a1-4acc-a5e1-eb991439c871', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 42).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '65d7af5220af92b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39189581-b080-45c4-b9a6-96848efacac3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 42).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ecd98896e56c2291_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('254c6357-95d2-49e2-824c-92f47ad7fb8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 42).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8de48eac2b110c33_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7407d3fb-eb0b-4b7e-9912-2492359651f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 42).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b569824191485011_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fb2ea41-7161-477e-a5d0-d4d1c166d5da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 42).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd4db7c86a45013b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3b744ec-d68d-4ee0-a86e-e412dd17e7d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 42).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '97c225e92c4a4a0e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba3fa5ed-27e6-4912-875b-feea0fbc3ca4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 42).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 42).', '{}', 'IP Connectivity', 12.0, '1c8428ce6b24cc62_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4335e5dd-2e43-43a7-a274-fa92832bfa83', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 42).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2c98b42a209f2c58_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81c2abc3-699a-414e-bf9a-271d887406bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 42).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a7d47a505eb9e7e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e363d56-d392-4022-9b88-00e61efcf71e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 42).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '161ce56773d5eb4a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b279b3e8-c19d-408c-a39f-16cfcd983687', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 42).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5966463a82064453_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa02842b-517e-465f-ae04-32e1e4456858', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 42).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '520d9d82670bcbe3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64b1923d-069e-4bdd-8bca-4af7101ab802', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 42).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3862e3df42a520e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('969c806b-df72-45bf-87f1-32f7cec5f872', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 42).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 42).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c2311ba5ee225dd8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ade93ae-96cb-4955-a83e-eb34bc2b47f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 42).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 42).', '{}', 'Automation', 10.0, 'bcee33df71a42173_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8a1973b-0d21-4636-979b-eb5d6d7ed269', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 43).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3fee992b00cfcd1a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d17edba-e5db-4d36-8f44-acdbc71992a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 43).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd1f4b1d1ec93860a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7eacfb6-c66e-478f-a4cc-4fc9176ea01c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 43).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 43).', '{}', 'Network Fundamentals', 12.0, 'd61318d7f03ce775_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9516f9f9-2ccd-40a6-b051-9fe7d1856779', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 43).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 43).', '{}', 'Network Fundamentals', 12.0, 'ff3abd4077d92f7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d5cb505-e4cd-4014-bd4f-2a923cb10d34', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 43).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '22586aac80bf3242_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bce7bdf-2295-4d07-b4d5-b5fa742b9c95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 43).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '513635935602a03a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4fd58f8-4c95-45ad-80cc-793c5a5ab39f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 43).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '667dd4979cc116d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6820e49a-77af-4aee-b29b-5cad250a40ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 43).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fde01fdc120854d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9aab8ee-6bf6-46a5-8c0e-40a3efe9daef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 43).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ae4a6aff56296b19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92b1c41d-1a77-4793-9435-1831e12e428f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 43).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '93dd3d248217f92b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40527b17-0d2b-42fb-b1e5-e979e170d66a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 43).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '572260e55ecf1270_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ac17588-b417-4d16-85be-96c83eab5cb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 43).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 43).', '{}', 'IP Connectivity', 12.0, '586f451f2039424c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b14471f-f0ea-4481-9698-720b766d5ce5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 43).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ad765ede2f5abba9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9b32407-487f-4984-83df-a0279e4bbc59', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 43).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6a25e53bed89fc7f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba138ac1-06c0-41ee-835e-309e8e654340', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 43).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '29065d79f3604237_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10acfc48-95e5-4263-a8fa-35f98f609411', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 43).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '978cd35fb3547609_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e846d6ca-7b1f-4af4-9558-66d31e27a750', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 43).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '3e84d2c8e03da64b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec6cff3d-6bd3-46fc-9d9e-b0b99be100c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 43).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1b1767266b577973_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('266440b2-2391-4bb8-87a3-b5a7f71f5c0a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 43).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 43).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '94a1b6b563194ecb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ebbd5a0-fff5-40a4-abc1-c4dc0a2f709b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 43).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 43).', '{}', 'Automation', 10.0, '3d5c81fd4c0a2408_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5145ac5a-c9be-4778-a7e2-d3a540b96f86', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 44).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2a41c82b540e30ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c072ff81-f6ed-4eff-926c-e5925ec253af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 44).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1fdffa107939228d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('385e84cf-36e4-46a6-934d-79dac31aa947', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 44).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 44).', '{}', 'Network Fundamentals', 12.0, 'd5a8ae87180d077b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4079ba26-4f7b-4c74-a3a6-5604cbb03c42', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 44).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 44).', '{}', 'Network Fundamentals', 12.0, 'f04c2ec1ac7e2b51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ff65750-6bd9-4766-80fd-2978f93c666b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 44).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3738f71953ce21dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d63b8131-e24b-450e-adb2-e3d4c21f50db', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 44).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4f5284812b3cf872_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4bfb073-508b-4f90-b367-e32aaad8a719', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 44).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '255a4fa3d2664d31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83ab7aa7-4191-4dc2-99e0-5503a75036b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 44).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '12523c9dcc21558b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6820a8bd-b20b-4f91-aefb-f0673ee259dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 44).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c4bfa514293c1406_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('549fa412-6dd2-420b-a440-5428ece0cc62', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 44).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '93af8befda7c5798_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1961079f-45c8-4b3c-9074-985d097da1d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 44).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '116cdd320e3f02cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23acc700-6696-4a81-9242-cdb6287857aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 44).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 44).', '{}', 'IP Connectivity', 12.0, '38b33cb9e0f76ec1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64297420-02d2-4a4a-88bd-ba8c5b32ebdb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 44).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6f6942a96c224ea5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce59634e-9293-4bb2-8455-12264b37dea1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 44).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0166bcef9a310afd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72c8eff3-92c2-4734-9632-abe78b45f209', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 44).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'fdaf5e96bf7b427d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2680945-7658-4677-9519-c497cbd33666', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 44).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '58e9af2c5245f469_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efd2de07-70e2-47c7-a47c-4c47a25f3175', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 44).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f158f654049c0c40_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28ac74bc-fc46-4802-b8d8-a1b84edf4af4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 44).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'fdec29a37274691b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16351f5c-52b7-437f-973f-c1904da1600d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 44).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 44).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '37af17ead7ac4790_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af7b9bb2-8f19-4823-941c-0e585df5c3ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 44).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 44).', '{}', 'Automation', 10.0, '25e0629dec791f37_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adffc0ed-f59e-45b0-b0f6-efe5aaa8d1c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 45).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '535c52d728aa06e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abc0770e-1419-4103-ac68-ba975f145f71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 45).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6a0bbb55b6b16642_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('171a598c-6155-4d97-a5cf-b4761d324083', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 45).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 45).', '{}', 'Network Fundamentals', 12.0, 'b399bc0d2f9d9f62_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f835800b-e0a4-4e2a-b6c8-c699145ebb37', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 45).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 45).', '{}', 'Network Fundamentals', 12.0, '20eb9b2d18d744b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5566005f-f0b1-48c6-935f-e6a24989c0e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 45).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '509b0dae36ec6fda_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06ea6f21-56e8-4e86-9e63-6f1cb6e24358', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 45).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bbdb7658839eaa6d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60cef142-3eab-4af8-a557-20a1e3fe6218', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 45).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4351ece75db9d915_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0ac3ffc-103f-4631-9563-20446e448498', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 45).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '612d9d2a77dcc3ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('169f07d0-86d6-46e5-8299-bc4a854195be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 45).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a9b3991f29e0b918_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea706ef4-c947-49e9-a7d9-1033d037c430', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 45).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ddda437aca5713d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78881007-2fdd-4f6d-8b2a-f8f7935cdf6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 45).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '99231f836c7866f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcb803e4-9b35-4c37-8dfc-56de14fe2b8b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 45).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 45).', '{}', 'IP Connectivity', 12.0, 'd7188fb8d73a9493_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98d340a7-8eb1-4af6-81aa-bba04f95785a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 45).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4ea2f4b288f4dfcb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1800ab8e-e6d7-4738-918d-3bb75567298c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 45).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '87f06b29dd546ae4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7179420a-c5d4-4049-9b2c-1d5346b6abd5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 45).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5e8c0e6ca67bce23_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f3aac68-5622-44bf-8444-6637f6434c10', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 45).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3531725e1db708d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71bec7a2-b54f-4ed3-9b03-7a8c34610cb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 45).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '03d37b701cc5e009_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44e6f220-3950-4002-a75a-b1efc26e32f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 45).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'fe95f5e174ec7e27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ba5e37b-8857-4fdf-aacd-7bb4bc51693e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 45).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 45).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e040d962c00ea65d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f0295b3-b5dd-4293-a747-89fa354160f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 45).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 45).', '{}', 'Automation', 10.0, '24759a750845d973_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cde3c8b-97ff-44ed-a577-e184c3823e83', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 46).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0f3b885d34c5d180_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70728382-6a04-4284-ad2c-170fd1107644', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 46).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd2dd6d2e54d02c14_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('459a850a-bc80-4561-8128-60517af4d108', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 46).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 46).', '{}', 'Network Fundamentals', 12.0, '33c9f179016e2353_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ceb4bd5-6e53-4a8a-b3ca-130a46e0fe4d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 46).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 46).', '{}', 'Network Fundamentals', 12.0, '1657ccf2e341e9a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30069240-a6dc-4886-97ae-42a5ede63e8b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 46).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ab37a0ad360b21c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5279fc8c-5966-4121-a9b0-68caa16e6525', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 46).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c5ad23800637231e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('236c44f7-abcd-4c10-9530-772abdf89997', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 46).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9ceac9693bbf3036_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ecc6b31-0418-4557-ace1-c0e84dc53b3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 46).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c1f8368294aec5e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bcd3c39-b9ed-4605-b353-4de3bc155544', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 46).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ccd57d60047794c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e467cd61-5d0a-4b8f-a74b-297b3740c911', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 46).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '3001d702472289cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b62ce48-7e45-4b0a-a62f-5d1431ed254a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 46).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '90f520676d9c4250_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2812c16a-f692-43e4-a634-d345293cc755', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 46).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 46).', '{}', 'IP Connectivity', 12.0, '1bc63abbf25e44f5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95d1117c-824a-4097-8c7c-6c31c8efa6eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 46).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd8ab2e9d3f32cf40_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d71506f8-34f4-4597-b411-64050a0d9123', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 46).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9af53a36678d5952_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acac9113-e538-4a6b-b67d-68b634c63cb0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 46).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1c6b29da0bd52224_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eebf8fa0-7ec8-41f1-b165-01fb20340d75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 46).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '84cd5fa4b25ef106_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66696e57-6229-4790-816b-c1569c60c503', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 46).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c71e31b11ef4866a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44160855-0559-49bc-b23f-b9b94a0675bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 46).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c28c01e4724f9123_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66588142-2143-4ca9-b21f-ab5505d40bc4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 46).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 46).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0cd4679e1c8b2555_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9942e6c-7d01-498d-8529-eb690060983e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 46).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 46).', '{}', 'Automation', 10.0, '3a623460166d1067_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45b772a9-6360-460e-be8a-1f4bf95c3a60', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 47).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9896fcab29e949ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2415ddb6-6ce7-4129-be21-713dbdaf0c47', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 47).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd02c4ae90ad0d341_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cacce886-069e-49f7-b9ed-07679c0bb5ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 47).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 47).', '{}', 'Network Fundamentals', 12.0, 'd0488dd12c09b3ac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12575e18-20ff-4f76-966d-3fbf09f4a0f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 47).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 47).', '{}', 'Network Fundamentals', 12.0, 'd36d6720b3b859ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3f2410f-391d-41eb-bee3-4c5148e7e265', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 47).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8624cbac47da7adb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e42e3c0-7d7e-4ad3-9f47-f6a7c0a1a415', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 47).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f5783c8253122954_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0161b280-7cb0-4243-8160-228a3b5a3e64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 47).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ead392788fadb969_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4deceff-9613-449d-bd0d-890d4e68f9d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 47).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b734fb40d3a6828_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36f4b94d-cadf-4328-9306-2e2213e4fb6a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 47).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'd4d33fb5faf84259_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e29f9504-e41d-4e48-b096-f00345973034', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 47).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1ad6758d4e02d4b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('835693f3-32bc-499c-89c2-236009bd76ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 47).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0eefa1497398b12c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3622ef3-00b6-409f-9d5b-61ab4009122e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 47).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 47).', '{}', 'IP Connectivity', 12.0, '98411a0ea8f6328a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('784d035a-ff5e-4563-ab2d-4642b6a3f01a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 47).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '444f8e596caadf24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2038fc09-dd0f-426c-9b9f-c6fb2806758f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 47).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '71d701e86e5d3170_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fa59107-d1dc-4ce2-8ac5-0817e70c143e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 47).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7d301965a3e3e95b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a6f8d40-2078-4657-8e28-f2548f73dbbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 47).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'bdf30a56ae25f38d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f39dd176-c95b-430d-b001-3a1561bf3f9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 47).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '90b0a8c7e39b5395_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7547e50-560a-45d0-b631-faf290c635ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 47).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '30dd4754849e77a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('840a5e6f-916e-4956-9f02-54149e18a438', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 47).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 47).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '7ecb0fefea55e051_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e1cc8c6-0103-45bc-a797-c35329937ead', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 47).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 47).', '{}', 'Automation', 10.0, '4c3e56aaa499a4cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34c6f438-7c95-4d2b-bfd5-6bec0ba95e45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 48).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1e6581cf836ebac5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e215588-f562-4d5d-a7bd-26c5e0d9141d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 48).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '72e032f2977ea6c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a37c13a3-1b2d-4c89-9cc9-d1a6e005b182', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 48).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 48).', '{}', 'Network Fundamentals', 12.0, '33ec8ca2c3a28c38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18cf7a49-4a44-4eb1-b986-b5ce3867e8b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 48).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 48).', '{}', 'Network Fundamentals', 12.0, '6f701415d50df81e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1e07003-1858-4837-8cd6-3b409bde57cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 48).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cf2aee303d8936a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('216bf70f-ab6c-432e-9707-024fcffe8416', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 48).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b6b9fe7a03047708_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c982dee0-2975-4d6e-bac4-7e4f617ddd23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 48).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '02cff85016e636c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6caf2838-9b80-456c-8027-356635ecd828', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 48).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e8994fe6ee9a96b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('751f16ec-6dd6-42d8-baee-e8984af57efc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 48).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '54ad7c1be9dda5cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ee15073-83d5-4ff8-bbf9-ff91d06ffc53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 48).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd498c3de629c3800_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efcd361a-f0f9-483f-9277-da1886b9cff8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 48).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '14bc2dc8c4915bd3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf1de49b-8f7a-4538-9e87-a00f6d9e6faf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 48).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 48).', '{}', 'IP Connectivity', 12.0, '84e73a9aa92f7c5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51a6b666-f22a-4400-9730-2e5b998d5fdc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 48).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '080da5233d00374b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4d9006e-4d1f-4626-8a87-796609bef716', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 48).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '938f96ac207fb8b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c05ee70-38ed-45fd-8a54-e8b2ab007ae2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 48).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '6af6b8a52762c1f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aab5ab27-47a5-489b-a5de-6b42bdf62ca5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 48).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '02f3b18460d71eff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('579d7739-1418-4f34-a719-18e3a99159f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 48).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '98c2eefee0c9b4c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daa54e25-a166-4da4-82b4-e265fd813c7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 48).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd09ecb4c7b5be6c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8f543ca-e5f8-4862-b9b2-a7c9fd05ff6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 48).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 48).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '1e158e973356d317_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd31ec73-a7cb-4255-b6ac-3670bd9da761', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 48).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 48).', '{}', 'Automation', 10.0, '940f0422f009bb7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f654155c-d3d5-473d-a90d-930076faff47', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 49).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '147bdae6c99148f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb9d4f09-105f-4465-8bb2-8f3cbebcf5fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 49).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '83c77f672b3c5e62_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6bdfb05-9c90-4bf6-a04a-68332c6f031f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 49).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 49).', '{}', 'Network Fundamentals', 12.0, '9e52cba8fd700133_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fd1fdb7-9cfe-4cf9-b65a-bb45b0f650d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 49).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 49).', '{}', 'Network Fundamentals', 12.0, 'ab2bf84a6befee5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70c6161c-059a-4723-9250-c2d8bc6da26b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 49).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '83e726e96d082bfa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5045baa1-128f-4d05-9aa3-abbd7ebd4a69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 49).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e7094749b6b4f956_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca64773d-34c1-459a-bf02-ce5f263f7cdb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 49).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '23d610caac03b8d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2489b6bf-e2cd-449b-bed0-b711d2671651', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 49).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f387ecf7e6f1fb87_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e125bbad-c991-4777-a823-0aa7c5dfc985', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 49).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'd651f7df711fea5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d93dda8c-4580-4ea8-9e5a-7e91b2bda487', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 49).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e8520f156f966512_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc80f84f-33ad-4b6d-a4cc-6bc3b38274f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 49).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd5e352f50686e700_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca7b16a7-80da-4c22-b5ad-cd5f07d35d70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 49).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 49).', '{}', 'IP Connectivity', 12.0, 'fe821eebc3b7765d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('976e0a8d-639e-47af-a1b2-aeb92b01dddd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 49).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'dc6e89f84af39b13_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a60e70e-ee7d-483b-8fd7-da2c59335c4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 49).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '89e3d031716c5fd0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('673071ef-bc7b-4379-9312-5dc53a5755d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 49).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4b028f1629ff3a1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc2db926-c29e-4e45-980f-15461457a17a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 49).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b3e4d87ce7f25039_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5345aad0-1193-4515-a5c0-79cc9b8da4b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 49).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8e4785f4cb38545c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c485748-603f-450c-a79e-5f48c5995103', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 49).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e8ccb9a694d458fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ace23eaf-c7f7-4f56-afa0-0a4445f583b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 49).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 49).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e8ae007eba40d5b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fa00290-63b0-404e-9c8b-e4dd561cd18a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 49).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 49).', '{}', 'Automation', 10.0, '0845e0c34a0b7d70_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50ba86c0-3605-4388-8ab7-5b79e9bfe7c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 50).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6aab3f4c2a9a55c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e5138bf-2676-4f4e-95c2-f0195957225e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 50).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e615639ce47d44ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e3a804-4a59-4f71-ade2-f34624c3e428', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 50).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 50).', '{}', 'Network Fundamentals', 12.0, 'dfaed63fd4212246_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09bb5664-7f50-4716-8027-0c2f16154b4a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 50).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 50).', '{}', 'Network Fundamentals', 12.0, '74eff7ee58ffc8ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a87f7f24-0d34-44c0-aa7c-83c492fdefd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 50).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ad560d2726abfb2b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('261d3510-fedc-43b6-a5e8-ef8bf90ff99c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 50).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a69a682d02ccc1f7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bd639d5-54e2-4cab-80ed-31eb1fb54b47', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 50).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9ab17ca9fae209c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c736e509-aacc-4991-b6c5-26b936b22cf4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 50).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'df374e8d48e7153d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3db634e1-262d-4f9e-982f-d5f4e0a9b443', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 50).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3dac86b2de3ceb53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c8af41a-712b-444a-809d-effaa218abaf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 50).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '027eaffdc0b577b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ecb9e1e-3e44-49bc-abc6-5346dccc2c30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 50).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '42b4f30f0f3db033_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('535cd053-b281-4cea-95c5-c045f2e5610e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 50).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 50).', '{}', 'IP Connectivity', 12.0, '42c62b0d566e683c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d292dca-db41-4bb6-a083-469f4b877921', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 50).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd8eabb3ac23df375_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2099b396-9484-4989-b681-0de5b111e16a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 50).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4fea27b37351eb04_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03ed5ad4-36b2-4fcb-a66b-ab20dfe34428', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 50).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e7ba697e67eb78d9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68606736-0bbf-403b-9f3b-fd04a829b6bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 50).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '09457a2e130b76b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b05075fc-e5fd-43a1-8562-531fe9bb2724', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 50).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '7656a33ffde7cbc8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f40169f-c66e-499e-88a5-7dad510c9876', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 50).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ce703c87cf39f46c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dae7eaa-35a3-4281-9829-1207bd44b9d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 50).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 50).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'f15b8a44f523ac3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f35e094-a87d-4d5c-a55d-5bcdc612294c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 50).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 50).', '{}', 'Automation', 10.0, '027b029e22a6645a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5f37b69-b8c6-4c1d-af24-e08a657c6838', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 51).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'aa014f8b330e09f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56fcd98f-b877-401b-9f70-3b6e82a98af3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 51).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '285e92214f55e7b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2f86a8f-325a-4f15-80ae-e527ba2ce582', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 51).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 51).', '{}', 'Network Fundamentals', 12.0, 'a6faa70e7b43f18f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a603c355-33c7-4e09-8b53-81d998a9c9df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 51).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 51).', '{}', 'Network Fundamentals', 12.0, 'a62ec6c9d2d475f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37c6a599-ac86-4127-9a5d-8dc3a4d7fe20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 51).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '35e6a4ea8855f90c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbd5dd4e-89d9-43dd-be16-2c9316c5d240', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 51).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '06d288b5e315a6f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08cd3f9a-edd5-4334-b06d-9d13ba740fa8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 51).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '364d5b0d508fc8fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50a44947-fb2a-45af-94cb-94f30b2d0830', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 51).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3202e99611c8e606_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4df9bdec-8eb0-4f27-a775-98918c77d928', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 51).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '67a2b710bee3aa8d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bc0e82d-1e61-45f7-8321-f959af74c021', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 51).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '7c8ab499dac03fa4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bc5c696-5f5f-4bcb-b60f-389ad76ce29e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 51).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a9391f9b3f1f270f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc7568dc-ad1d-4b97-8075-c79209078548', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 51).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 51).', '{}', 'IP Connectivity', 12.0, 'bd4db9f27816d0e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba2eaa76-dabc-45b3-86c1-0d88f6f4b4c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 51).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f110c0988d2c8b3f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab6a4080-a7e5-4ab1-9952-8afa3b461b64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 51).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ec597cc9276b3175_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11ffe5e8-acfb-489b-8de0-bf3a6525070b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 51).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1b6ad5c6e64e7a53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('929334bc-5df1-42ad-9779-f320d3d8ebe8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 51).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b46b68f58991050e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66decee5-cdcd-4119-abd7-dbbd553d68a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 51).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'bb37e60c491e7bfd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('feaf0c4a-ad1c-41c7-a3c4-929380dbd22e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 51).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0ecc08ffc29977a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('056d96d9-81be-4742-82a1-a13f32cf05f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 51).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 51).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '69e64b8ff50ee97b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2892287f-e8e3-445f-bb9f-1de9c032f649', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 51).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 51).', '{}', 'Automation', 10.0, '41014a4abb0ef197_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('097aebf6-6665-4e2e-a7d0-d670c7d11421', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 52).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1998bb9444c985e1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4b796ef-9d9c-4e0a-bb6e-13a3aa870099', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 52).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c8a5be86f48f8872_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2da1cc7-faa3-4700-94d9-6bad66e5a467', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 52).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 52).', '{}', 'Network Fundamentals', 12.0, '3bd140e8330da720_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9557baa-c926-4c6a-97e6-72a0b26f6e75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 52).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 52).', '{}', 'Network Fundamentals', 12.0, 'b5ae0b7a9bed61a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36c7f9f6-67ea-4ae8-b1d6-5f70ebd0b726', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 52).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4f23f9f007f9ebc7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ac178ac-4828-4303-8ee5-fed409767821', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 52).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd69a10a61b92adc6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32bccd29-2af2-4499-aa42-ad94c0af826b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 52).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2bd6db7fae6c59c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff35c5dc-7cf9-4a59-b277-f7591bc6ea40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 52).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b7c8e6cc3e7e27e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c90b962c-0752-40a0-8823-7748ba7e8d9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 52).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3d4252652cc708d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('741ed5b8-1bc3-4029-81c8-d9d809fabeec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 52).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '79a3038182f29476_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bc9033b-b68b-403e-89af-a34a177fd29d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 52).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '1a24271eab196f68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd091a70-0fad-4e9d-8fb5-2b42510f47d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 52).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 52).', '{}', 'IP Connectivity', 12.0, '154be2fdb63c4322_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed6e743f-d300-4423-8b6f-e54f29ecd4e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 52).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f3748fa1708a1878_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('826586d1-d8c5-4582-813d-bd6575eb3d03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 52).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f21c3f24f2933c0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('221d8842-4420-41c4-a444-4083dd001e93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 52).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ecaf80a7947bd293_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fbddda4-c7ed-43cb-b670-5e8afb6644e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 52).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cadc8a493054b08e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd2ef3bd-5275-46a0-8c3a-e2609787eb13', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 52).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ecbbf647de0792af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c52916b-1434-4890-bb2c-39da26d4ae4f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 52).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3c3dd0f0b804c266_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9a62b09-430e-41ae-96df-1340c0dfb471', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 52).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 52).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'db06952a837a1f28_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11427e98-0768-4ad5-ba45-7f914d8a6f6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 52).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 52).', '{}', 'Automation', 10.0, '6c45e93ee6550a21_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77e77ab1-b10f-4df9-ad3e-6f720dd31bf4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 53).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3d3bf35de097dc13_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dfb450e-5363-4fad-8f7a-c478e3fda9d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 53).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '88228c65daf73035_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36e498c0-fbe3-4270-ad04-3db3cdbe9254', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 53).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 53).', '{}', 'Network Fundamentals', 12.0, '5497fc3098d7ac72_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e82f0ec1-cdd2-4aa2-8916-7dee46a07eab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 53).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 53).', '{}', 'Network Fundamentals', 12.0, '0ac62775876ce682_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a1b63ba-9af4-4cb9-81ae-4e8f824281ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 53).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '481b6381c4759821_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cda7825-93d3-4417-b3c6-9effb381266b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 53).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cd68f7541ae7ea4c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93295157-c684-4f60-82d3-228aa187ea96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 53).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1f609f46fc479d4c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf0673a9-5813-493e-896b-2d2c5d10f99c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 53).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1ed18924b879dedf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cac53859-992d-41f0-9d32-4be1b786f7a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 53).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '9305a4fadc541266_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b908748-7b24-4938-aadc-8d6becd12497', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 53).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4289920d85b42e9f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5963863b-0985-407a-a873-a7d5e8f111ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 53).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '96c5e57b9b918af6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f16dbaee-f8da-42d6-8bd5-bd4f50d6c73d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 53).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 53).', '{}', 'IP Connectivity', 12.0, 'e927cc29bf3e5df4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c089b96-4e61-439f-bd0a-6e5a2834e2f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 53).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e88e12aa9f52c2c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12833049-2d49-4c11-9126-153df196890b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 53).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1910d2339b27620e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63ee14f9-1633-4584-a6d9-fbaa0f7385d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 53).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5dadc934e1749c7c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c544716-1644-4c8a-86ca-a87a1207b48c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 53).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'eba14e0a29c53f1d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d026768d-3096-47ee-8461-25a3371e33c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 53).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f7971dee4840e016_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c49ea103-0b5e-4214-acf8-d895bc99d437', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 53).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '18691337e4441eba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71a6d667-85b9-4455-9d38-d2111581ff2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 53).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 53).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'f402be4b9bf148a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c170e2e-35af-4c09-bffe-358bc20bee7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 53).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 53).', '{}', 'Automation', 10.0, '850fa5dbbf38e993_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bef3fb4d-4b2a-4a4d-9f87-80c95f09fac6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 54).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bb1c2db37f587342_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82f1c4e8-5aaa-4c90-9206-6fde9f55408f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 54).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6b6f08b19b7caa5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee636a2b-5340-473d-b4ce-d0c67b6a7df3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 54).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 54).', '{}', 'Network Fundamentals', 12.0, 'd650371b7169404b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efbec93d-78bf-442a-93b4-4b48df6e9ceb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 54).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 54).', '{}', 'Network Fundamentals', 12.0, 'ddf603bb6c055c22_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0945ebcc-7a65-49fa-85b7-b4379f85a409', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 54).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '16ec72f8814e8d4e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3177d562-7e0e-4226-af85-5a14a1832c66', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 54).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1a25b4f640fea847_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf8dc87e-cf34-4352-8104-9fd103eb5b44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 54).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd7f81c2442fd25dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc641c90-ab30-47e9-b3dd-7b47b9165e40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 54).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '218399cf285a0147_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ba18526-cc4c-4534-8aa2-fb35cf3394bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 54).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a1d943ad98512546_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecaba63f-86e1-41dc-adcd-dd3fe2aa8e6b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 54).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0b8fa518775baaff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32705226-e2ca-4fbc-ae3d-14c86a0da6e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 54).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '00c0d33b2a603d42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56d5fb96-6edf-44a4-b96e-04ec2f5b59da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 54).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 54).', '{}', 'IP Connectivity', 12.0, 'e6db17a76c4d0418_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7626ec1e-0f12-4c42-a48c-7ac13d208909', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 54).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0a431131560140a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79e7561e-ed3f-4dc8-99e8-68ba6e8729b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 54).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9f4743f2141456d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('085d6523-082b-421d-9b3b-0963311b783e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 54).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b26c8f6f19141dba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bbeea26-8377-45c6-b9c7-108e83063a8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 54).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c36c0b4330742119_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad24c037-71ee-443f-911a-617a56f5ef10', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 54).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'bf5ee15b0b5a92fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f9319be-bea0-418e-8096-b453968b07ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 54).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '39b15a737d901b51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4379c2b3-83eb-46cd-9603-c78b61480956', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 54).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 54).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0b29b73b40644c24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6887d2e-6358-42ad-8bb0-456f2fb37b29', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 54).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 54).', '{}', 'Automation', 10.0, '5f2c00f89888fdbb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c25d7d3a-85a7-4750-89e5-ae2393f5052e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 55).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '43e7ab71a1788df6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3071148-0151-4a13-b8e2-ad500d7c353c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 55).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ab454a5d22ea4454_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03cdd279-2e5a-4966-af0d-010f03697130', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 55).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 55).', '{}', 'Network Fundamentals', 12.0, '78ed1363f645f63d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f963ce22-02e2-47a9-b1a5-ed95a17020a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 55).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 55).', '{}', 'Network Fundamentals', 12.0, '1984a6ff701a2486_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abb0b4db-ca8c-4a00-8620-394f381c003a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 55).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '945d8f0cd8907990_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad748e0d-4b72-4185-9969-48a13d001d7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 55).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '78cef806170b7b88_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae4e9172-dcba-4af9-a8d5-ea5c44965545', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 55).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '16c13f4995a5ab09_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a962c68a-efd8-407a-8ea0-5655fe028cda', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 55).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3efd7983c4d8eef6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de840e86-2464-4a4d-8a8e-38d8092e8180', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 55).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'd1f208eddd8a173a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('784445ad-d5a0-4c64-aed8-0f2a7967d77c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 55).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c2c715801a4616e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ad1d7b2-ee1a-4ae9-96ab-889db8dd061d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 55).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '432e6c48dae655b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12b0a983-d511-445f-a8b1-f4ec36444de2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 55).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 55).', '{}', 'IP Connectivity', 12.0, 'a3289a8ed4eb206e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3c46219-fccb-4473-be29-cbf8c51ecdd0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 55).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '116f4b11739e9cce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91d16193-bdbd-4a41-a806-e2aa7c9408f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 55).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4573c19c3f95dc8b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94ea0a9e-1546-4185-bb35-47ad626125bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 55).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'caf75aaf71669095_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43c30155-55ec-4f10-aca9-7f260b775f96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 55).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '58d1c08e46c6d4f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b95da0f-7a31-4727-af71-fff04a21f6a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 55).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e1126746e83bd650_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de2b3e0c-4d64-43fd-811f-1b4103ecf345', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 55).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6f44fe63f939adc1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4633d793-3377-4d37-8320-1969000a5b02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 55).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 55).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'bb486a4e490ab402_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adf15227-ccac-4e8f-97ec-781886cd4f80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 55).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 55).', '{}', 'Automation', 10.0, '36611f8e4cec7877_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dac7f7b-51c8-44f1-8a66-d5579fbf0bff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 56).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'fd8588b7796f9f42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d193f7d6-b05a-4fb5-af51-07c542a6edaf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 56).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '637bde42f5900717_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a867166-53cd-499b-bd38-b8d700d83ebf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 56).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 56).', '{}', 'Network Fundamentals', 12.0, 'eb019b45b680a23c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('591ccf92-7f2e-4738-b5d1-a18230bf8dd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 56).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 56).', '{}', 'Network Fundamentals', 12.0, '11ab4efdfe806232_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('928f40fa-0b32-4381-993c-df195bb8b3ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 56).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0742fa3d8deaa687_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c24723c9-980c-41e6-a422-1ca75d6a67c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 56).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd9dccc1ab80e83a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd33db85-fe73-4ad6-ae5b-be6f3e50aa63', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 56).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '033719d416e33019_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a7a10eb-9ae4-4f37-993f-7e0bf2bedf6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 56).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c6147371b2e0ad51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c59b6d35-de86-4977-b041-4b9135c07bba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 56).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '136e53d591602004_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2586504d-b3a9-4c90-a380-07b93bdcc7d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 56).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '48268a9aba288387_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c86ea18-c89f-4e85-9717-6b63d99fbb5f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 56).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ebf49cd4ce92645c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c151203-6b7c-40fc-be2e-7f3dc326788c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 56).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 56).', '{}', 'IP Connectivity', 12.0, '8527b550242e7c1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcd8c9d9-ea25-4015-924e-b67b5591b25d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 56).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '17934ba5393c8c4a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de7c95f2-7a34-406f-8ba0-f59991797c2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 56).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fb0a46fe1c06108e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf62ce5b-c96a-49c8-a9f1-2d0389e087f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 56).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f8a0e1df5935cc7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce26b2dc-013e-492e-a4e3-bf36a694ab55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 56).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '31f2f03ea17af4e4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c01e02cb-17cf-4e1b-9abc-f559ca1753c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 56).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8ae1572b3a036895_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42e28772-9682-4ac2-b2f9-59ea8fa73a10', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 56).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2713647d8c4014ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c351c66-1443-41ae-a568-9c799cc4ff7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 56).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 56).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '5011a68e99d96dbf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('039e2ce1-ef9b-4b09-acfe-1fe4ddaa4859', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 56).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 56).', '{}', 'Automation', 10.0, 'd677e7410b6db567_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20d00db1-900e-493b-a340-cea09cff4a3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 57).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3e975e446b9bd822_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65715958-0f05-4483-ba99-f5da829b937a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 57).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4178cd5038ffc644_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2bf87ea-29df-4310-9f67-19f7cd393401', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 57).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 57).', '{}', 'Network Fundamentals', 12.0, '0c426dd74d177c6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bf172a5-2d22-4510-a76a-f2febd46f165', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 57).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 57).', '{}', 'Network Fundamentals', 12.0, '0b205f1add5a2fbb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7c0ca3a-db90-4289-bf46-0c41af4d8c75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 57).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b9a027c99d4ffb5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16ad3b1b-a62d-412f-8a7b-a58ad5484b19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 57).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a890a50b5c27a921_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c5eaf0b-9cce-4fea-ae57-ca09ab993896', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 57).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a3148e8a0c287ecc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('991ee068-c2d8-4f3d-aa2f-c710538e276e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 57).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '58486a6ca8c9d961_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9b4abdc-c621-40b3-a8f0-4f3c4b92e12c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 57).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '72397e2f3a38a9c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9be26f5-b283-4bf6-8ee4-4e3ae56bfa25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 57).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '9f89c11c21f354ac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cde5ce6-7ef1-463d-82f4-52cb0bc659e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 57).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '70822eca1d526f5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c84b9e9-48c1-4d17-ac65-7239e4cd07fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 57).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 57).', '{}', 'IP Connectivity', 12.0, '90028aae9a358bb0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68e22946-ecb3-41ad-a0aa-ecd99d62c3cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 57).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '66abb35adf114cbc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee30c39a-611a-4dc8-8bb3-21149c4721db', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 57).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5366b21a4c6373c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81f8e8de-2379-4c11-93fb-9905c6fb9e4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 57).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b28e063e7a43951b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70565f9b-04d5-44a9-8710-7609c901e166', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 57).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0a32a8965bfd7b91_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7182d085-4a69-42cc-a819-f15ecd274d8f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 57).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0bc652ff1842dcad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9e2f698-5d24-4e79-9a09-00e3d8a96ead', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 57).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ddb1ea7a006cc33a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeb1902c-64fe-4f94-84e7-57d6de6582bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 57).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 57).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '98f36879e2b65fae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b85c8f3d-7f9d-482a-a863-fb936f40a509', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 57).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 57).', '{}', 'Automation', 10.0, '5d0e12d8d945f33c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77189742-f3e7-4f5c-a241-827b618bbbc5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 58).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd9cbc98b0d64eb7b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa39c6eb-2d7d-43fc-b6db-090d5c86905c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 58).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '043609f8f09a3958_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('febb37c2-18cf-4820-becc-d3ae18030f08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 58).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 58).', '{}', 'Network Fundamentals', 12.0, '9d471e9932f503c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf278401-8f7b-4e0f-8644-fa16f77eaefc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 58).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 58).', '{}', 'Network Fundamentals', 12.0, '1b2c9a710c7fe264_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b39255f-2b1e-4632-b90a-1f71d0faf291', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 58).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a7230f114801c351_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f50dc3b4-6f74-4d58-90e6-f957532c949e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 58).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1acec55c9e07ee9d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a00c9a21-2483-47b1-a099-65163cf6b8bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 58).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '53a098804e047596_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0620991b-bf75-4a69-bdc0-ca829bca28a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 58).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'baa21b5e6183a03f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1e79b0a-358a-4009-8543-8f57954738f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 58).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '4035cfafaabafd8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5a73224-0e8e-4df3-a878-126be320d205', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 58).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '147ccae8aa30501b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ab42edb-9666-4a5d-8d38-bb3da5052652', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 58).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'afec96a6d9165940_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdac5387-d4e7-4e2b-8bc7-fe73990c8d77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 58).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 58).', '{}', 'IP Connectivity', 12.0, 'a62215267d969028_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45895b6e-e39f-4350-973e-0e0bc6342429', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 58).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a167de0dac475416_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('485e8135-2836-4ed0-adea-0e34f37bbea3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 58).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e6a6cb26dd58d203_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a77e3eba-1e5c-48b5-8fed-b652996b544d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 58).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'dfb49f5cfaa4211c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('806b8c58-1ad4-4f11-a3b7-66179731915b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 58).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9296ae9667027933_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b30f9b6-67a3-42ad-a6a5-9c853826f3c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 58).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '12dbf0139058ffd1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfc20b76-6d3a-42bb-881d-00ec40909d05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 58).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1f28e2b4cf67ef7a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('904b9a87-b5df-4a23-aea6-cad54a693dd4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 58).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 58).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '706ea9184d69a48a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f273a0c8-fcae-4030-97a5-b56ecb9a7ffa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 58).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 58).', '{}', 'Automation', 10.0, '58f417df11ea05be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('524dff63-d0b8-4e9c-a524-76a0b4010289', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 59).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bb329cd0acb4c4f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b50be274-6fda-4706-8ad5-005a48a1e03e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 59).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '56bdeb0de77c4a1d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f78d399-82d1-402d-b3ab-b87ff8395ad0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 59).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 59).', '{}', 'Network Fundamentals', 12.0, '50f7f43daaaa6d4b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d65b02b2-69ab-48f1-81e4-4c4061f51894', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 59).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 59).', '{}', 'Network Fundamentals', 12.0, '2e8c05b76a46a667_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32159a10-0265-41fb-a959-ca2e706b6b25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 59).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eb294efbb22e0cf0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b90ce4a-75a1-4cf4-817f-31c567233ca7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 59).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2cb131c1b02a1426_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b353549-5879-485c-8154-d5c026fb19d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 59).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ec73df53ac698e41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4b40f9b-fc06-4ab4-8b33-ed8e7300c110', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 59).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bea416d5757c1857_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38e7c031-40ef-4b54-85ac-e18c3e197735', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 59).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c1405c6c41b0a9eb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21e45850-94b8-4898-be07-8f95c9e76132', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 59).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '986a0ea4eda9f333_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d123bf6a-f03c-4828-8714-12269b4c142f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 59).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '56e8bb9dd98a26b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f7bb5e5-5fce-4bbf-bf65-fd375c0f4910', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 59).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 59).', '{}', 'IP Connectivity', 12.0, 'e8120b6e7c48e478_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('494713ee-c39e-4909-93bd-64dbff7a8947', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 59).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd9adda00e9542cdf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cf66715-944b-48e3-a1a1-a17da136473f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 59).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '261b254e209d2777_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eac10ce4-fb79-4a2a-943c-78ab22adaa8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 59).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2083e6cea5f0ef83_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ffc35d2-827b-4565-9046-fc6d313c8a22', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 59).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0cf2dcad2b4a1f35_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e329cdd8-c870-49f0-a65d-1727c0d81e76', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 59).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ae452999eef3867a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53a62dbc-5520-4005-aef5-03acf6378f28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 59).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9514db26657fcde7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f637e35-8323-49e2-b201-e668b985a661', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 59).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 59).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'aa9a4940d35ec4cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44bc7492-cd34-4ded-81ea-b6cf197a5545', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 59).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 59).', '{}', 'Automation', 10.0, '1aa417ffd65f7bc6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbd14174-5aa0-4682-a392-c01df24b0dcf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 60).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7cfcb6fa333ecef5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c10b0db-40e2-47b3-8ead-35dd96526f5d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 60).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c13d6286ec372ad5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2972018-97b2-4ff3-81b4-a2f59c02a532', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 60).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 60).', '{}', 'Network Fundamentals', 12.0, '6578dd004e575d5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f49bc133-1258-4fcc-bbfa-af52bcef6ca8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 60).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 60).', '{}', 'Network Fundamentals', 12.0, 'b3f75fdfcce7d7ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff55dc6e-49d2-43e9-b2f1-e60f852d5f2c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 60).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '86bc0d21027c99ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95b17a60-563f-424d-84c0-f098020e8c06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 60).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f3f82480e95eb46a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15274028-35f6-499c-8f25-7f8478a7418f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 60).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b51f8e802fb64229_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da6a706f-1e6e-4cf0-abda-349ba61ad311', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 60).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '20ba1ffb4edc1e15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82202760-c44e-4e0c-99ba-6c40af37b935', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 60).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'd6c8ac51d76504f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('888ab954-92cf-4d12-92a3-48a19f63db35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 60).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1c81db4dd0da9bf5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19b4241b-b51d-4835-9527-6f4f8e85a784', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 60).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '36428e74bad2a756_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7ebc4d7-5444-46fa-b1f1-781b875a5146', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 60).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 60).', '{}', 'IP Connectivity', 12.0, 'c9ad4bec83a9ef0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e48b585-d12d-44c7-88c8-e48238a240cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 60).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'becff5ee32871adc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8838cdf0-e369-46bf-85a9-6ed110b81aa1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 60).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f446b75780679353_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f049a662-fa39-41c5-9c9f-5d8cd86b6cd7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 60).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5b4864e21511495a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd3b3c00-55e9-45a2-82fc-e3db939f347e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 60).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7ab8bf93ca7efb3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('419221d3-05d1-4c68-a89b-083a7cdb5a5e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 60).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'd4865a269ab48908_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81fced7f-b63e-44d0-8435-d259fc69b677', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 60).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4f0f5a344c003e55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c11e70d4-754f-4e74-8990-33c7bab86cb2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 60).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 60).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '524538b594f384c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('650402d2-ec25-447c-a056-8c21895e0566', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 60).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 60).', '{}', 'Automation', 10.0, '1031715372892558_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2074fea-e41b-448b-b767-893a1967296f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 61).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '76ba8f0912afa610_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d4faea6-fbb8-47fc-b4a1-73cee1a38b35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 61).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '154f03dc22d13f34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8464e969-1962-4b70-8479-1d10fe3bff6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 61).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 61).', '{}', 'Network Fundamentals', 12.0, '048b9ea95ae7a595_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63862ced-e84b-467f-b9b6-5e2200a9c1bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 61).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 61).', '{}', 'Network Fundamentals', 12.0, '15009786ad91d6d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79a6fc35-c25f-481a-b406-c5de52d2ba8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 61).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2bae7e9aae57d2fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ba9b3c4-d610-49cd-9ca6-e2892bad4e0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 61).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '840d3905b600e832_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70f832af-cf79-4b2c-a862-776f3dc42a9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 61).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f561487ffbe0c4d9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('139a18ec-c25a-43f1-af7a-a932a95872b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 61).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c17840bf08af8a7c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30633e2f-910e-4db6-8dab-9cbe6d8c9fd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 61).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '6a15af694f755754_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c61fb6fe-c2a9-4726-a502-63887e448109', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 61).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ea4ced52d5a8e1c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80b5f3b2-3df3-4ad5-9aca-ca284b047cd5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 61).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '2916bda074ac9065_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6037c4fa-c24d-4901-8775-950f64ca4f56', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 61).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 61).', '{}', 'IP Connectivity', 12.0, '0a91ab437048d3cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f085f90-ce20-484f-8b03-4ef283907ec1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 61).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'abfcb468be1cb0b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f6e454a-5fa4-441e-8780-3ab0cee74ae5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 61).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ec804835d43bfd5d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56f4165f-e04d-4543-8b78-d9327fb634a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 61).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9793ef7b41de79f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15419f86-2980-4227-bc66-d9a3478df476', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 61).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '653beece27a44528_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85455eb3-73fd-46fb-968b-29f2aff77285', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 61).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6068f1b944555c50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a795325a-3859-4125-beb5-4a6c1c9d56d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 61).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '716608e69c7477a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28b03387-1f68-4a44-97b7-0f9dc5ad082e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 61).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 61).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ae10b984e376cefd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c15df332-f594-452d-8406-b6c2921191f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 61).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 61).', '{}', 'Automation', 10.0, '1689f878caf6bb34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8ceee97-c656-4057-bb16-00831f4d22d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 62).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd9a3469484843f08_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59667025-c823-4b9a-aa7a-197c19f426d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 62).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b612d4b1788cd4d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('132f4787-e628-41f0-b6ae-84d5668a6bf7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 62).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 62).', '{}', 'Network Fundamentals', 12.0, '475ac4e5ba5126b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c231621-efae-49f7-82b9-4a6bcff5c232', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 62).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 62).', '{}', 'Network Fundamentals', 12.0, 'dbbe7ab6443ab93b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc70d62c-e9cd-49c5-9edb-2914e27022fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 62).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2648f403999d1809_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('babb1007-92db-4567-b057-3459b7abad73', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 62).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6d2788ed37ce54bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25641c06-2620-4538-a835-91c62322a3b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 62).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cafc6bf08df9795c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b21c5cdd-e178-47f9-931b-ec9f4c51aeca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 62).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '706524166e60861e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8b4cf5e-c16f-4000-91d9-7c02c7ea3021', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 62).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1e4ee4b1a77408a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('386bbada-3839-4878-9c64-af013640653a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 62).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'a25d32a57336477a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('564e9256-7e87-4920-9154-842fdab96412', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 62).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ff7c30432f45adbd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5cc574a-5218-4fd1-8698-8924128455b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 62).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 62).', '{}', 'IP Connectivity', 12.0, 'a163575bfaef83e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9448f2ec-d4f0-43dd-914e-423a65c57ade', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 62).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cb79d7efa02172e1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('490f8801-1595-4f87-a5ce-d1bb9387029f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 62).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6f89970b6ff4b587_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a01c986-7ca7-4d87-abeb-c63bf114ebe3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 62).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '339af63e171dcf2f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bf9cb4b-dd33-4462-b1b5-381732aecf97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 62).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '223dca6749102232_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7143c97-9596-43f4-8b0c-5252416f163f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 62).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '645ad7c40a9edb8d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('183f0a00-20e3-4663-a334-28afa2947f21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 62).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1689ae29e5b6bbb8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c2b48c9-4446-4b42-b83b-cf7d3323ba36', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 62).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 62).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '3a53806d7fc5733f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74cee5e9-3dbf-4acf-8403-9c9bf61a3b09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 62).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 62).', '{}', 'Automation', 10.0, 'ec97bc24898e6140_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac51ac47-655e-4516-a519-d736a59fc639', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 63).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '449b8cab1788aaf9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dd7cdea-b885-4714-a263-f1bedd3e1642', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 63).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5009c167cd7e7fce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28d3e7ee-6c92-4183-a050-5e0dbb719980', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 63).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 63).', '{}', 'Network Fundamentals', 12.0, '3e986440f8c85d64_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02b77912-fd6c-4ca2-b2d7-fb28e5d93637', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 63).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 63).', '{}', 'Network Fundamentals', 12.0, '1609b675e68d06c2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eaa5d25-d3c6-4285-92b3-e95055b59c0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 63).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eaf7390109440bce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05e2213f-b142-4659-97ac-eb7441f23a63', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 63).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9a4414a848f9b048_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('389c95c1-7fc4-47cb-a73f-8606d6cad526', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 63).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2e274b57db63d3fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5ef1e23-b879-4af0-9bf9-f33f9cebfc48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 63).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5c411183dc20afe1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbaa7896-849e-4778-8fe3-1735d989a110', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 63).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '39c16c54fdc277ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('855deeea-3e01-406f-899f-69f52b25fb59', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 63).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'bbed4fe7515cdb7c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a22fc98a-af23-4db1-8fbb-d48c777c4693', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 63).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd1426298b6a0c902_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d8b9644-422b-4341-8e97-1388f8987f09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 63).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 63).', '{}', 'IP Connectivity', 12.0, '2b4917392311fc7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dce8669b-5bc7-4362-9f1c-af9b4a87c5d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 63).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c218f2687d9e674c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca95895c-f026-454b-819d-ffe2820f49d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 63).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '845695053a410b2a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f30f83b-650f-4299-a861-1ab39c59b8d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 63).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1b23840b15aa35b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87001088-e63a-4cc7-afb2-3598ebfa1c6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 63).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2b625c7df0f77920_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0b36737-da43-42b9-974d-7837f45e8f96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 63).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ce6435befaa0f9e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92b4b2e5-3151-49ce-a240-8f24314b70ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 63).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '148fae44004a9e95_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('633ab64c-af7a-4140-969f-b6e38496d195', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 63).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 63).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '50b73bb8c996a6b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07ebedac-2a32-43fb-99bf-2dd3ac023454', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 63).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 63).', '{}', 'Automation', 10.0, 'fc33b768a7e38ebf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c406c5a-c186-4492-843e-0bdb6bd3438d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 64).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f0ff422b4e9fcd49_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bcb2654-222d-4020-86cd-34913a1a5e1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 64).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c2ab7c51a82d964f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcc4635b-f4a4-4e4a-b944-e12640eeb1bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 64).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 64).', '{}', 'Network Fundamentals', 12.0, '4adb21b2da90ee13_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2865742-dafe-4f01-b440-6cdce1004315', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 64).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 64).', '{}', 'Network Fundamentals', 12.0, 'a0d6d10edb92bb73_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e67b5901-c0f7-4686-b363-cda1404db245', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 64).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0e878a916f73967f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e08dca15-13ca-41a4-a687-1c8006f571ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 64).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c7bfe08e5f6f5c96_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c89b80c-b5fe-408a-aaec-65af87740b68', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 64).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2bd927fcb5c8bdf9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afc03420-e89f-4602-a403-d8f7fd5f0698', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 64).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'de6deca571a489bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a488d7b3-813d-499b-8ef1-451bac56e9f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 64).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ef146e6bf5f6d4eb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4c414b2-0dc0-44f6-9417-6a5518d12134', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 64).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '399d6e3fb80d164f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dd652a4-6109-4a51-b78f-9a2f73fa9610', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 64).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '140c8d082850a88f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72e6ccd2-7e0b-412b-873a-02a5d84abe2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 64).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 64).', '{}', 'IP Connectivity', 12.0, 'c9c87761defe6882_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdf77c58-4643-442c-af66-e9b1b81b1ccf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 64).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cd714200c874f851_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b452fb6-5423-44c2-b2f7-c7bb02c45203', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 64).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3e29597f21b94de6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9a37550-f433-48da-bd83-910ebc638b08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 64).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8f66ad0afff713f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('061bec39-c9dc-4d88-8848-4d981a3a24d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 64).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd51f0901d566eacc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7a143e0-8179-443a-9351-941735c6a58a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 64).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f57a98421e6d786b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da032fbe-08dc-4c6a-a5bb-c53998946535', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 64).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b8644af928afdcaa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a93daef4-d891-4be9-84a2-87b79230b7e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 64).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 64).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b1a32cad91af2bff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7d04b14-84fa-4815-ba55-9430bdc9823f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 64).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 64).', '{}', 'Automation', 10.0, '6751950492cbf2e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c94b425-8650-430e-8a4f-50d555ce7b77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 65).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '14672f747deab126_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2498417-0cde-414b-8cc0-fedae25d6869', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 65).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b702b1dd10799997_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f30ed98f-9a70-43e4-af5e-d90ca8a523d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 65).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 65).', '{}', 'Network Fundamentals', 12.0, '8dd823c19d641123_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a6647f3-3a8a-4c4d-9643-f4b42b153c0d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 65).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 65).', '{}', 'Network Fundamentals', 12.0, '8bc61e3fa7fe46fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b72ef37f-6371-40b8-8590-85c5796396c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 65).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5f4661b7df747328_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad14314e-7874-4895-9fda-8c11c02d1d5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 65).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '848e6429f9c06d41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('109ee879-5c62-41fa-9d00-c443bfb9960f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 65).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '142209432e99cc91_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15e958fd-494e-417a-a87a-c9ca49ed3a3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 65).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cb5cf1a662637d6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72737403-47af-4729-96fc-2e2bc4b26b6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 65).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8d355fad4364b331_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7582c41-d110-4bf8-8f57-5970ee2ebee2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 65).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '3ea16224c45b800e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15585c4a-3c1a-4fa3-9ffa-1efda3b28556', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 65).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '2ddab0e088630506_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a20ecc6b-6629-45e3-8b1c-a83bc01fdf1d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 65).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 65).', '{}', 'IP Connectivity', 12.0, 'b6e1cf307629171f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('753d4e71-91ce-426b-87e5-09a62d0fa847', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 65).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd3234449447b9628_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee20c344-97bd-439c-8f3c-39c503f8b7b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 65).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'dbd59efca3694165_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e043f9d9-fffe-45b7-954c-06bd23e9646e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 65).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b754070df5f540aa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c2875f8-5bd0-4144-8e7a-18a4900d3db5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 65).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3379a485592385bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21b984db-a896-4b8e-8df7-cfacea683706', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 65).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2b525105c261fb31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3bfdc27-a3bf-4d58-aa39-b4427d9707d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 65).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '06d45eefb20060b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11e27b79-97b1-4a0f-b52a-af2f1aa22193', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 65).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 65).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b8d385ea05d793a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1915be54-20a9-4008-b4de-1948a785f48f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 65).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 65).', '{}', 'Automation', 10.0, '60fe0108647e0265_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8adfe28-3731-4e0b-92e2-eac89d90570f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 66).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'aecb8b873c46387c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('679406b6-867e-4dc4-bd65-0f664d84ebbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 66).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '91f9ed4379faf1ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efb8db5c-2d1d-4f96-8657-4c593ee406fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 66).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 66).', '{}', 'Network Fundamentals', 12.0, '885add812135b334_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('774a0d9c-5f08-4d60-8d4d-7ba7c626ee06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 66).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 66).', '{}', 'Network Fundamentals', 12.0, '5d8ee542e40b87d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('911b164b-1f67-4286-a135-877fee56dedf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 66).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c4a39fdbc3831952_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1efd5236-02c4-4080-bc6c-983d6322b67a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 66).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '31187970410d92d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5c3551d-4792-4a7b-a7ac-965484f4edc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 66).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2efd827e40724e7f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b45edd92-25d1-4811-83da-53f1f6d502b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 66).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6f5cfae2f29258d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22b82909-62dc-4834-ab02-58b85b2149be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 66).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0340ef7cd38a9eaa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8118d3c6-a8a5-4bcc-9fc9-38a5f3ac51c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 66).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '43356cae3081838a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5e74b2c-b04e-4951-99d9-804525f3648a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 66).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '7222185adc7132ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1082e48-3e8e-442a-8437-90783dd05617', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 66).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 66).', '{}', 'IP Connectivity', 12.0, 'c91c3c95495f7a19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b431a8a7-57a2-4765-bb90-defbccfae771', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 66).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0524a75800249a49_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d242e9c-24ba-45e1-8cd9-603dae8d451d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 66).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '19ae4dd53ea03f6e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77980c1e-65da-463b-adce-b485776a56df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 66).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'a38aad791a6e3d38_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c529696b-3ece-44d0-a454-f75ad8467a1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 66).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ceadad818e6c087b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15822b82-2865-4e73-8c67-f852a7739875', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 66).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '816c9ea9790d7af0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac2cc71b-c0cc-4912-8993-a575e069997f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 66).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '351d491aafa8d13b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7330ba1-b122-4c5a-a81d-f8a5f14a0e5d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 66).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 66).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'db7b7c401fb60066_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bc285e1-190a-4a1a-9e65-df6ad994a29b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 66).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 66).', '{}', 'Automation', 10.0, 'b6508eeb0c754afc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('956b4b29-cd10-4c96-8080-5c582ab6ba9f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 67).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd5bb5dc0d97c7689_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29a8f466-080d-4ac8-a74a-b76b846cecc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 67).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '69510a482c7d5ba3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cec2b67f-6389-42c0-9ce9-7d331842c8c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 67).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 67).', '{}', 'Network Fundamentals', 12.0, '5f438f42c31ddfc9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c074f955-864c-458b-ba6a-4e30e2c847c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 67).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 67).', '{}', 'Network Fundamentals', 12.0, 'cdd7f8367ea18b8a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca23ec5b-5436-43a2-bd93-45901728ac22', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 67).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2aa33c309fff22b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49cc4e53-ba0e-4ca5-8f90-ab823da7833c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 67).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8c3b1a4520c6dd28_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd90387b-fb6b-4b0b-9acf-8921c1e5fc0b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 67).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7b941a1e6af61816_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c39dd4f0-d7f0-446b-b51b-a7cfc51b23e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 67).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '60a25fb7d2ec9f89_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e428ad46-2776-4389-8517-0893c26b19d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 67).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '370e9ed5c1459bc9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e92ca20c-f1ad-4ea1-937d-7412ba481b7e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 67).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b2aa7b2c5de7a7ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e388a49-2103-4c3e-86b8-b47fa84cd827', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 67).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd05fea7041a85b56_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e6e1c7b-9064-4835-8804-26472d102694', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 67).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 67).', '{}', 'IP Connectivity', 12.0, '7b6ea6d595457a1a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d96e801e-462b-4df2-9cbd-40cbeb753ee0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 67).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f14ba8378c39825b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b25723f6-3125-435a-a474-a61fccac311b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 67).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '502e25c39b9a86af_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00e3fe92-0c29-4912-8369-61fdc4159981', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 67).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '247c1c96cec61d96_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fae76e02-12ad-440e-a47e-0a051e845b39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 67).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '88f3bdb4017f6730_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a204321-3a31-4fc5-ae59-6d4144dafdd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 67).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '505e3d794178fb63_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c81c5d6-85d0-4103-aabc-417760c5a192', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 67).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9f42c52b838f1022_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0919aa96-c1d5-45ed-84ba-f7f902c9d6fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 67).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 67).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '129a410a7931e1d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98572aa9-a6e4-4b40-a8d4-b763df39a818', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 67).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 67).', '{}', 'Automation', 10.0, 'ba9ea2a65720056d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64b15212-49db-4342-821b-fb2aeb583db4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 68).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'aa58729529723269_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6087ab2f-128d-41fc-8312-8bccaf32dda3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 68).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6e1ccd5058dd248d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c670da1-3f77-4764-8623-12c9f2e28a77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 68).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 68).', '{}', 'Network Fundamentals', 12.0, '6ff8cd3ad8ba336c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69f1fc39-bbc7-4aed-aa80-a7789da7e01c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 68).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 68).', '{}', 'Network Fundamentals', 12.0, '1a47c81074e22722_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('636682c6-01f8-477c-b0ac-d8e979002189', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 68).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ee86877ec83e5c8e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dd045a3-ab49-47c7-9aca-24505880722a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 68).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '13f7d7d139f8e68f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ae1e0f7-acae-47f2-9d8c-9937b3b8bedb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 68).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd89e22baa458bfa1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c33f48e-f9d8-4dbf-95b5-d2747695f690', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 68).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2f6f977195292da2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47ca4e27-14d4-475f-a4b3-4702a9e831bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 68).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '39a3cb42c042028d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c079ef33-6a07-4493-b980-97af727d46fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 68).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd9661050f4ba2335_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b778851-a0b4-402a-abf8-68b309bb1f6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 68).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'fd25801df1a5f271_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7db5ebed-a0fc-4eeb-9597-a7ec0f464b93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 68).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 68).', '{}', 'IP Connectivity', 12.0, '921da9b5fc07c4a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('924e36f2-3bc5-4780-abcd-e1c0fb147a57', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 68).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b5c6c3cdd3a64671_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c9e1019-020e-4b03-ac86-27bfb7d8cae6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 68).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fbdb74a34325b419_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8f78177-fb0a-480c-a04a-73b5612a92c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 68).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f48bc9f27eba7fab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88cc1d8a-900e-40ea-bac3-b5fc26abe371', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 68).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'da57fbd7bc31e23d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22ec98f2-cbaf-47f0-8287-bf2a76b01348', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 68).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f1f9674faea45efb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85e6ec8c-df1f-40a9-94d6-95cae348d8f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 68).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'fa80f1ae3358806d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67293226-6143-4b71-b730-bec76ee01d81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 68).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 68).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '34c43836a1009391_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f95c2185-fe3b-4688-971b-50e5b5e37a2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 68).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 68).', '{}', 'Automation', 10.0, '0331f63d5985d724_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abd22637-d077-42bd-9e26-ae4cb34266a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 69).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e4008321ba904654_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79a9108c-6391-462d-8545-54b368bc2349', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 69).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c8393117cef2cf26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c80a558-43e1-49b3-bf84-781afe6354d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 69).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 69).', '{}', 'Network Fundamentals', 12.0, '0d23c80735cadc76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1022b8db-0e08-4c58-8197-c42c2a295801', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 69).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 69).', '{}', 'Network Fundamentals', 12.0, 'e2dabae79f7b3194_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cd122cd-5e75-4469-837e-f66a842437ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 69).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2a94262c234e59c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('948f37c6-a438-4e03-84c3-1951e9e40515', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 69).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6cdd0607cdfc545c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ba3f2b3-6037-49fb-99a9-754ccbbce0fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 69).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c89db1793b787733_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cde5415-1441-4c62-ac4e-06b29d102d3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 69).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6b0fa51fefef4b3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1feda7f2-8b07-4dd1-a3c3-6854370c1656', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 69).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '9400fd4e453726c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0f28113-92c9-45d5-9e74-02610775ec43', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 69).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'fe6bb3c20cd92242_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e6cbd24-361f-4014-b7d4-e0ff652a68fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 69).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '499136b4f874c26f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08f4017a-b491-44db-8c20-afe46129ccba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 69).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 69).', '{}', 'IP Connectivity', 12.0, '30dac250cd564900_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c09cf47c-c51b-4e61-b664-11383b305cef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 69).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2e316fe29b22bf3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a783c47b-7090-403c-b526-30964d3770ad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 69).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '74b328e58aaaedaa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de402860-596e-43ef-83c4-d471aff71ec5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 69).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'bfead84d498dfe7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cc1681e-c1a2-428e-9096-b01843f60f01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 69).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '85f3312e7dc295a9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b971f99-0f5b-4936-a65f-ec8cd5c94200', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 69).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'bff72dd8b3a4e6e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3e105ab-e3c0-43af-8c5f-bc0ea753dd1b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 69).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0b984cefa3353b3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('747f0ad3-c265-445a-b739-d3f752d4b3d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 69).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 69).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '3eba8d8da35e8138_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f61b46b-9786-4f32-9aa0-42f09aed8b3a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 69).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 69).', '{}', 'Automation', 10.0, '221300e98a71a4a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('324fa6a3-f8e8-4d5a-8ba8-c8ac9a113312', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 70).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f30586e8165c96e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f4cd8de-064c-4e68-8be3-a795fb027fef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 70).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '75227cd3eb4b410a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d3216f7-686f-4f67-a794-9c2901cf03ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 70).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 70).', '{}', 'Network Fundamentals', 12.0, '75e01aa5f7eab0f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d158d17-a85e-4ce8-aa0b-58dddbf5a707', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 70).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 70).', '{}', 'Network Fundamentals', 12.0, '2e5f4a824df25f67_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('308e217e-3ebc-4286-b582-40a60ed89a82', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 70).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fefef488a9691b17_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27995d9c-de6a-42d1-b3a1-6169ed5829fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 70).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '83a883a42bd5c591_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33203174-8771-4cd6-80dc-f998651314e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 70).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2df022f5f0a1128b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f75cf36b-1ff0-4ee3-a8c9-c178c375c1b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 70).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ef7b0c2401690bb0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64d250cd-553b-45ad-96b3-1234188a19fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 70).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'edbcfb39ac928cd2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a2cccd5-2090-410a-882e-43af0fb020ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 70).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '3ae89d046b6df75b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7d2b441-5969-42b1-b87f-1834339c4b00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 70).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9dfbaccd6a25792d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e03230b8-3202-4f64-830c-96fe5c342efe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 70).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 70).', '{}', 'IP Connectivity', 12.0, '4e7daba1ded659d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50e39658-4693-4df0-bca1-35ef660af33b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 70).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c3ebdabdec71975f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a6ca66e-67a3-4e08-a139-ccee69041d0f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 70).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '80ab10827f6a6e95_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a844ed1-f07c-4079-9581-b68e9833e1c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 70).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'eff4712435c3a928_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72d7ad54-0a32-4249-bcbe-3c57fc6c0183', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 70).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0b16f9c40cb44900_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bf479b3-97cf-4ba0-8755-14929c244b8f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 70).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8c9a5a67c4a114f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d910316-3e11-4781-8115-c595bbdb3405', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 70).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '073735f2f57d2138_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ad0377e-ca0c-4c8d-bbaf-4c3a34f54fee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 70).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 70).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c2b39b8cdfdf79d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e210e6b2-4db3-4a1b-b54d-7155f8cc9970', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 70).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 70).', '{}', 'Automation', 10.0, '4ebd29a4d3efc86f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e9d4afa-34cc-49b6-98fa-658897429de6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 71).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'de0612d61d36e0f9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7b4a70c-5ca8-4f6f-83e8-6ebb4228dc16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 71).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '53cc58b65dff8c68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bd9e31f-cb8a-44ef-8a4b-fce5292a36c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 71).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 71).', '{}', 'Network Fundamentals', 12.0, '523517775c2705f6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3f91167-a6bc-4d72-8919-0d589e936ec4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 71).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 71).', '{}', 'Network Fundamentals', 12.0, '333201b0cbd4062f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c69704f3-df13-4abc-98f3-0ea80e4d6d06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 71).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a95e2a96aa4e01e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06b94561-e9fc-4682-8bfd-9953c8b0b0d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 71).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '24364ada5e2f43ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d92f7c4-2c33-4dbd-80bd-d0f71d485367', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 71).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2a02f960835af6dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efd24530-6fbf-427c-8a4f-abeadb766086', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 71).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'add0c1ddbe893973_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c621ea6-1ba8-4508-a7d8-21f16b7c24da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 71).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '09ef63a67c8a7d5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0da5822-59b9-46b0-b03b-6390189c9a6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 71).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c27b2ddcd75e9af0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb943f9a-cab6-48a0-b3c9-732d168e617e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 71).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9c66de71394aeb95_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('977ce301-cad9-4d1f-b31d-e5deed0a98ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 71).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 71).', '{}', 'IP Connectivity', 12.0, '45d6a60f1d8fb454_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22712a8b-3cce-4188-a96b-ff4af0836c96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 71).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '582c4d2427089214_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd48738b-a1cf-48b5-a6ac-f5ca8b66f9a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 71).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '160c740a4a79e770_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edef64cc-4501-4447-a961-97f9c5676c7d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 71).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e7c73adc0c12044c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('075de3cf-72fb-4c3b-a6a8-32261f7e16be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 71).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1ccccc5514696d68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('110676b4-8799-44bb-88ad-c6f75ad5147a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 71).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a48373c261ebcf31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adfbc5d3-e212-4c39-813c-abe6a5986cb4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 71).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5890ad8c706c3368_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6477f7f5-d1ea-43d3-97e2-b0724ea3a26c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 71).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 71).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '653717a26930eafc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d31901ca-c3ea-46f5-aae1-892a38d2d49f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 71).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 71).', '{}', 'Automation', 10.0, 'cf35f8f53fc290f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c3fc555-1326-4955-b1c6-90974a4a4adc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 72).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '41cda29a42bfaae5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc87a0e9-c6f5-445d-a171-49833db7fe91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 72).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '553623e0bb49b02f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2e6bc83-b4a1-4320-9dec-d753ac119ce6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 72).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 72).', '{}', 'Network Fundamentals', 12.0, 'ae8c87c5a7958c51_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bd97396-78d5-476e-8ca0-e7dc34e979b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 72).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 72).', '{}', 'Network Fundamentals', 12.0, 'fa6a1f2608f4e3ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5897d7cc-7172-4e93-b97d-4fe69e95c300', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 72).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9ab36ff1168563bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f24abfb5-bf19-4d13-9919-e59e07986cd9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 72).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'df8ff994eeb5fc7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a655275-0727-4aad-85e5-9d0a6898e6af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 72).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a05edb59e426f974_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c7c1d07-98ae-496e-bef2-672db18c9cde', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 72).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1b93f96e20100278_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b592fa68-7278-43c5-807f-12bddc85ea17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 72).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a85c0425beaac2b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fa3bf51-97be-4607-87fe-731fa67c54b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 72).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1a846a01280084ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b63a188-cdac-46d5-8d13-bed655d87d46', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 72).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '141bb861b82cc9a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14c42ebc-8d51-4a67-a8ac-c0997b442c51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 72).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 72).', '{}', 'IP Connectivity', 12.0, '04c43c976180dea4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2b88775-0564-4801-a6bb-93a509a6350b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 72).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '28813c615eecc154_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17e39cfd-a368-4408-9395-ca0397f53bfa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 72).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1543a6cb3f127959_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7db65ee2-108a-4c75-875b-6d9540c73f51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 72).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8447fd352a57c1f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88cf87d3-d3b5-4ecd-a5cf-3cc3109a69bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 72).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '22485f908407c88a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f2b8ed4-2265-4eb4-a05e-44867b31a734', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 72).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f291793dce1c5e20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb75f0d7-3ee1-4d5b-bd42-150df9fc1e64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 72).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '464b14123e837bd9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3ef33cf-2adb-4514-965e-f2705d7a218e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 72).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 72).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '066f926d37258e97_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45987a2d-c051-4b09-a670-ba469b81016f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 72).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 72).', '{}', 'Automation', 10.0, 'e83ebb1c101f1d10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf611812-405f-4d4a-a7fb-5874ff0b22ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 73).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8787f93dbda7b5b7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bc12fc4-794e-490f-9d2f-446b5a677134', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 73).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '853915f22a15f835_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b69d7d7c-a9fe-40fe-8012-f5c75cc62a99', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 73).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 73).', '{}', 'Network Fundamentals', 12.0, 'ea8dea038785c617_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34858096-7dab-4edd-a679-1c6a979ec3bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 73).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 73).', '{}', 'Network Fundamentals', 12.0, '195d41aed3d07373_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a590ca20-db40-4ee3-b6a1-c733db82e8e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 73).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b387a71e25ab3359_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbd454e9-51fb-46e9-880a-500c3ebe6be7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 73).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '960fd647a2c8223d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a816427-eba7-43f3-a8a2-5ef35c649be9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 73).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0c1562c2a8b14f63_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a798852a-125b-4bbe-8464-59e7edb77617', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 73).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '42244531639aa520_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bc1335d-8886-4d71-9f8e-38aab68905ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 73).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e9d661820a93bf29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('022ae556-9916-450e-91e4-6d6c096d9290', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 73).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '703f0c98be03357f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ba68535-88bc-4edc-8c12-8fcfc87c9410', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 73).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'dbb27662e99c4f04_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f3e36e5-8105-4008-9a34-bf8c5d805471', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 73).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 73).', '{}', 'IP Connectivity', 12.0, 'ec4c0fe00dfc8460_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eaa554d-250f-4ff9-9833-c8e505df97dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 73).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '032c1ac9bd7a3fec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1eef0f9f-400f-4c43-aa9a-87d7dffae154', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 73).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6ab86e744eacba86_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd055bc1-e919-42d3-b089-1c079c5e73b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 73).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '65b7768caf660555_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a566d587-07c5-4e2b-b035-e653d85dea12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 73).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '48c924f58012d613_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fce8bdad-6c2c-4f65-99ac-095ae588e193', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 73).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b2b1a6a780592ce8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c89003e9-1bc1-4636-9537-7479b28c8e8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 73).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4f6ea50fcc526da7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4ff90e3-8265-43dd-a829-693ab2000ea9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 73).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 73).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e33f784347050c44_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6c01426-8129-45b0-897e-bee1acedc755', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 73).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 73).', '{}', 'Automation', 10.0, '4a96b9051bf25dd3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d10bc02-b1ed-4c98-8b73-39e379bf12e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 74).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '89e925ebffc1a6fb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85b6f04b-023e-4765-bc36-762c48061a80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 74).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '835a74d14de2f983_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('338b003b-c3a7-4575-b3c6-9f2442211d9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 74).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 74).', '{}', 'Network Fundamentals', 12.0, '577c39d8a1c40332_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e9e2467-862a-4886-88bb-ad111f1cb317', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 74).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 74).', '{}', 'Network Fundamentals', 12.0, '40b7ed2ea9baaa0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5c92ddb-0879-4746-8194-65b056dfc477', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 74).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac31773c75038cc3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c677a710-bfa9-4ef8-98ed-30f4db12b136', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 74).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd8a52979b5284a18_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8377fe6-e1c1-4b51-af68-a015539c6f89', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 74).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1187752f73956214_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('881a802a-8ead-467b-9ef8-d57037695c81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 74).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a07b896c11959aaf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6a7f753-d9f1-402c-914c-33ae403d89a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 74).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '68bf1ef71bd8e287_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8668687f-6845-4dc7-81e3-dc0aed4447fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 74).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '7b60291a07f122ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('864d3fdf-d7fa-4e04-b66c-9ee69a21e693', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 74).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ccb9730cf6adfebf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baa877df-fa72-4337-930e-b8059d86c437', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 74).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 74).', '{}', 'IP Connectivity', 12.0, '272fb64e04003f61_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f67683a-3103-438f-8e83-7c54f02273fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 74).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3821704ff1d94672_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9687e31-bd30-4b79-8d22-7bebff57ce74', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 74).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '988712cd072ad4c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3019a8d1-5d8c-4751-b296-3a85e5c52952', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 74).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '3360550e4575c548_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02841b61-3801-434c-8f0d-2e3c5a0000a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 74).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5e1153bbde42c61c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b24a7e48-06ec-457e-aded-99ac349aa88f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 74).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '418c052fe2e2773a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('905a1d77-b49d-4b17-ab13-3f74c7ba4aa1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 74).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6260ec4ba63a3e42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8128f80b-26d6-42f7-b065-62ca8ac99a95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 74).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 74).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '62fb09a83ccd2db0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34d1c5ee-9c60-418a-b7d9-9dc612e0ee35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 74).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 74).', '{}', 'Automation', 10.0, '86f291e07f070e98_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('951a675c-96b0-4d39-9c64-7687bf6e8315', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 75).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '38056359b76b5414_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d01b55d-d52e-47ac-9507-f5fda875ecb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 75).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '89bc9503c9a88169_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7074eb4-49a0-43ad-bc01-796a23dffd63', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 75).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 75).', '{}', 'Network Fundamentals', 12.0, '381160e7b1205c05_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bf81aca-fd18-41a6-99c1-3eba95a5a113', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 75).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 75).', '{}', 'Network Fundamentals', 12.0, '9c011eb29f1c7fdf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95368ddf-ca58-4188-b56f-00c85363faf4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 75).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '94d2874e84c349ff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('727f60b9-83ac-43e6-b3b3-71d34c476f9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 75).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '93f4bb03afa7c2c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0031d4fe-0687-4759-a3f7-f5d0ff91b3bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 75).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '18fcf5614d36cc20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd52d8cc-e6fb-4b32-b6d4-9f41ca76a945', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 75).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a8021ee124ae40be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af378a1a-e552-4e0b-b1d3-a39747550408', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 75).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a96419a170eca6df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d1038d8-b2c7-4742-ae55-3f8684d44e30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 75).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5ba07883934d507a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b1ac512-b4e3-4a14-81fb-85c864d11ef8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 75).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a8d1d04266a76c06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0635affd-9637-4cd6-8342-bb12ea3cf84a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 75).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 75).', '{}', 'IP Connectivity', 12.0, 'c832f3afcf6c6fde_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10b530ac-a233-4283-b831-391c6b3a8046', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 75).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '47f1b0a8cfe9eab6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2279bf8-d4b3-4008-94e9-8679f61342cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 75).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cb752efe145d3613_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa74f978-3354-4ce8-b5e9-3487d83a00dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 75).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '250a8d1680f0fcc4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7cfcb32-1343-47e1-bc77-a4b25b1d4ad2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 75).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5b8ed913119ea6c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60d19369-1744-478e-84df-696594d49b42', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 75).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '719e0de471466f9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd3fc30e-b70f-454c-996e-b8f3c5fd54ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 75).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4995a887d7852304_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85c26eb7-a302-4c09-903a-5186f46c4910', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 75).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 75).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '288c87d1f7fa3638_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f481d2e-fbc7-4876-b83a-fb2ae9ec28d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 75).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 75).', '{}', 'Automation', 10.0, 'd63b596a8c956c2a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('feeecda9-5df3-487a-a041-367eadd45d15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 76).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9c41b9958082d4d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4338ec68-ffa3-4a8b-b495-668401707436', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 76).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a8f3c4f627b73bbf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('709e1689-3b66-4362-a016-5e49b1f267c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 76).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 76).', '{}', 'Network Fundamentals', 12.0, '30819d767a6b5967_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3dc7adb-9706-4f17-aa83-441be93df61f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 76).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 76).', '{}', 'Network Fundamentals', 12.0, 'e8c7672405c6e73e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('736bec23-9d33-4d35-835f-f9f6630b717d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 76).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5379da452b6a611d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69dc277f-22b7-4b62-b520-52661dfd121c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 76).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd155fe0c81ce5cf2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98168b91-df9f-4f48-af59-165b5c587cb4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 76).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3eac1df27197a707_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52e87217-2e5d-4279-ba57-e9eb2ce0772d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 76).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a544dbddfcdd40d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da7b1096-0c8b-468d-9a09-286ccbfd7160', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 76).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '40fab865c61d1df5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d099e8c-f064-4cd0-a342-50cd243602eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 76).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'fb89a57673e16805_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4871b38e-f6c9-4f4a-bfcc-812ed9598d45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 76).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'fb767d230e8440c0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a86450a3-61c0-4d1a-a8af-cec7b20ca1af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 76).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 76).', '{}', 'IP Connectivity', 12.0, 'b9eb4938dccdfae7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75adf394-93f9-48f7-acac-93ba4f1b5d53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 76).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '01a4d7302a9e7938_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91c867c7-c431-4144-91fc-463f2e4cd288', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 76).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '87c98fd291fcb7ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1b161e6-8ddf-410c-8d3d-7cb0618589ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 76).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'cdb451829db4d799_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f482ef40-d47d-4974-85f8-f5cdcb2d06a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 76).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '80b5455274f903a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2378f247-9ab2-4408-845f-3c895e52d0d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 76).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '65cf4929be228ae5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9f89e36-2067-4c79-bf7c-80287fb8994f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 76).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f580206bd056b4d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ed5d488-531e-4f5f-bc35-796ed12b61fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 76).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 76).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2311dc5ef97c4c3b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db853c78-bc15-4cf7-8c4b-1664aa83788b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 76).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 76).', '{}', 'Automation', 10.0, 'a54ab2d7532f9583_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c740169e-da8a-475c-830f-d687c6fb64fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 77).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '43e4bd7dc3e32872_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49434c0a-5496-40f7-a87f-af0161ec2f0c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 77).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd2fe12a2f0c5674d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ce8f282-067a-4e8f-ab99-516cca78dac7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 77).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 77).', '{}', 'Network Fundamentals', 12.0, 'a76f10cff7c953a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c80a47ad-180f-438d-ac82-4f543a527e06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 77).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 77).', '{}', 'Network Fundamentals', 12.0, '62eafc261f1d9992_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41e6eba1-e4c5-4c55-bb80-829852157c17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 77).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4b6d5c6d0ef4966d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b86a0ec-83cd-418c-9ad0-1b10987bb546', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 77).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5068fc35d9be1953_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e11b315e-c89d-4c1c-89b1-abc7f21e2c2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 77).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cb328bc51be6e4fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1c50b32-b824-4acd-85b1-34d4dcc92947', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 77).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4b5833a22be7b2ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9c42f1a-5d96-4b68-b480-1631eb580bd0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 77).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '19616b16b27e2c5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fb09ce0-b866-4e62-aa26-9dc009e6b6b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 77).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0bb9a08d1f801943_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be2a2e58-6a9b-4277-a78d-891009f64852', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 77).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9d1f2f6372dc7d4b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82895632-f7b2-4653-80d2-7ba50ccd6ece', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 77).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 77).', '{}', 'IP Connectivity', 12.0, 'c4d64675ee4d2e29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6453363a-a9db-4cab-88dd-c5ea6fe90fb9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 77).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '306fb5b5d8c45c7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('183f651a-3ea9-4c0c-9ed0-9d5d746b268c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 77).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cb75e35311f9959e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ff8df76-5d7d-478e-8746-64f27dd05a13', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 77).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4f3c224202d4d42b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9b77c5f-0ba6-4be0-9d2c-673cb5763988', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 77).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '77272833c685a4b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fde101f-1705-46ca-b358-d4f456ea01b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 77).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2499ca40419f5fe7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49dc7f41-593f-4379-bfa3-57d7853ef165', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 77).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'aaf23d330d65f2cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('981b0da2-a080-482b-bb06-50481a42a6bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 77).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 77).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '64d8b3341f6eb31a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a0332ff-f7d8-41d7-a111-ad74afd80e1e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 77).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 77).', '{}', 'Automation', 10.0, '656a5a05bda7c051_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56fe2f98-fb17-4a8a-bc0f-c9298e886ca9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 78).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8f3bc52ed77de3dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('616e1a0f-1235-486e-8c05-47b939b79ad3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 78).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f3f30479847e238e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c612690c-1b6e-4834-b35f-b70bad32b0f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 78).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 78).', '{}', 'Network Fundamentals', 12.0, 'f6271df5bd8fc8ce_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f40d3d83-5c7f-4841-8f78-f9824a90b61e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 78).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 78).', '{}', 'Network Fundamentals', 12.0, 'dd628e60f2777909_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34f5a05e-a5c6-4cb0-b6ef-d31d3ad49ca7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 78).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cb8c649796d2902e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63dd1daf-aab1-4c11-aaf5-7051bd2b7e26', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 78).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '10d8df68cf1b2e62_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f127cb8e-fdbb-4743-a0d7-571a091efdd8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 78).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8413c145178c4d90_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd934ec7-0478-46e7-9ce2-96865b37a872', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 78).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6f419754ceb34ace_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dbe2e3a-b6d8-445a-a341-59c93e088825', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 78).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b056732d03ef9674_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81398d95-87cd-44d1-abf5-a9f5c42c7c19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 78).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '44345d9d17ff5410_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8d9ad20-e939-44ee-b011-e5bdcea0efba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 78).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '360d12755c53ed75_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('001b2844-0eb3-4119-ae36-a772295c2e75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 78).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 78).', '{}', 'IP Connectivity', 12.0, '7ca0a473ef271c53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44b206b5-c6cb-4b9a-8acb-837a4d042761', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 78).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0464dd1334e997b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7731d951-799a-4a15-b687-719df7aae5c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 78).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '753c0f44a40ac770_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('846697f5-eda9-4e3e-ab47-1545a690c54f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 78).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '530ad8ea9d9e09be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d106f81e-605f-421a-bf47-e2b51de96b7d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 78).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ae2a2e4ed87af39d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b7f77b9-cae6-44d0-8f84-bd47348b98ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 78).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'dfe0471286565d74_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fa0de80-a882-4130-85b6-be110811d361', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 78).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '86d762f54d7de74d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90bcdbb5-e486-422b-a009-35fb309f4432', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 78).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 78).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c9492d9a9a0eed6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61b3689f-6cf5-42d8-9fb8-b6283a19ae80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 78).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 78).', '{}', 'Automation', 10.0, 'd52464bfe8adefb2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('232a71a2-c511-4194-9e01-1c222e0c3552', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 79).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6627636dc7ca5022_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cafd7dd9-941d-41b2-8cc1-adb8f04f1959', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 79).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5e42fd7a63be92f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('337eef02-c9ad-4909-9841-a5df9de45341', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 79).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 79).', '{}', 'Network Fundamentals', 12.0, 'ca893faa1cac3b78_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3b34d1e-5bc9-4fa2-ad62-9ba35bdb0c83', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 79).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 79).', '{}', 'Network Fundamentals', 12.0, '5333b1daf027b288_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb043a53-e719-40b5-84e8-6bdac86d5dbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 79).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '75324686f75460cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5eaba34c-3a36-497e-9e65-2b6a14ce6f05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 79).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '28def313fc9e97c7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24952470-fdfc-475f-9cea-04f7d30a8c22', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 79).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f6be1b9769104026_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87e5a9a5-1f40-42df-b6d0-dc2333d6dca7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 79).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4b9b7edab7c86b07_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e43c0c5-3d5b-4873-a696-7cba45185105', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 79).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'dc916ba618b05747_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09f7656b-b181-4d22-bd37-eaa96ea3918a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 79).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8303fef04e552ad8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b23b7711-2a82-4a48-ab3a-dd3aaa6d1d97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 79).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c730c5455346ae77_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3ce8d6e-99a1-4397-87d4-270a085d1cc1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 79).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 79).', '{}', 'IP Connectivity', 12.0, 'c2c86c08d21ae4d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('277a524b-1f87-439d-86c5-10c614072a1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 79).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8e3e9e22eae35c35_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb035cb1-0407-49ff-abe4-7afe7f4533c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 79).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '53c44f29a2f71c11_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54824e07-d6f0-47ef-99e1-2dd80d81a10c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 79).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '74ac869102a481cd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d562b453-854a-4d53-970a-641ebb0c8243', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 79).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1247ad136cf60674_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0060ed3-e90a-4d2e-882d-2a211c0fd866', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 79).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9bf69cc803c2bcc9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd82cec0-1f1a-4a83-aa60-864815a8021a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 79).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1802cd27cf738db1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7188465b-bdab-4574-8cf0-8242f9f7e2b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 79).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 79).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '386cf0cc188b9d9a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb3db43a-6d31-4e04-96b5-469588711cd8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 79).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 79).', '{}', 'Automation', 10.0, '7773b5f227962b65_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e214faea-2fc2-4427-af2b-808719e5a2a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 80).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2abf2b569ae71e58_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73b55062-fc91-4203-9df9-0c2a41683bd8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 80).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0de9951825ee31bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('143211cd-572a-4ed1-8454-2c1b594e7e41', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 80).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 80).', '{}', 'Network Fundamentals', 12.0, '762b35c8727d6189_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1d65147-77e1-4366-8ade-aaa6668d9d8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 80).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 80).', '{}', 'Network Fundamentals', 12.0, 'a154fca06d972b29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed598d4f-3037-415f-97e6-deb3221a2bd8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 80).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b02dd86e5fbc3957_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a08a1997-af7d-48de-b8ab-469421841f1a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 80).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '07c44853621c7537_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5c74744-733b-4b85-96ce-2214c3c45619', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 80).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '17cb43d7fd9a1c71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b81bc48-0b9f-4b99-9c72-40872031a838', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 80).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e2ba3da94cf0cff7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4f81e95-2f5a-45a0-a259-be8287e99ae7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 80).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '86856ec466251e7b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8f827a1-752b-4a00-95a9-d5015eb93939', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 80).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5ccb3460eeb9a012_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86f368b2-6106-4234-80af-304b9f58244e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 80).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6166a38da00a466e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('723fcb3d-1b68-447e-a3f8-16c5765b11f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 80).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 80).', '{}', 'IP Connectivity', 12.0, '8ae93584c01b6d41_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('466260eb-e374-44dc-b9e0-9a0e31c9f68d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 80).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '83598e3ea061e537_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7ca3f9a-61e2-4b5a-9ff1-feb5bf54894b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 80).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '64a969ce004a277b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c22158dc-b24e-4633-b86a-e03cf9aa37f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 80).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'aba0afcb7901ac2b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1e368f3-9778-4a4b-88cf-2c204c3ef792', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 80).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '210b84bca6e8c378_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('faecee82-07ba-406b-81c6-0691513a586c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 80).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '24ac20b5823727d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1187343-08eb-452b-8b4b-a455c5825bdf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 80).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'dfba522943da1057_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26fc2b62-dcad-4e25-81f7-8194f2d0f395', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 80).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 80).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '34011ba182181238_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12244753-f0e5-414e-a8cc-0c2b9129cdfe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 80).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 80).', '{}', 'Automation', 10.0, 'b21414b8a0933a87_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a828e56a-7c52-485d-a3bd-4b7256afb7b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 81).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '58d5c0f0e35be634_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b532a915-def7-4f16-bd4c-89d85bf116d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 81).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bebfe9a315d751b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2becd4cb-4245-4b65-af75-19ae1bf9e258', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 81).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 81).', '{}', 'Network Fundamentals', 12.0, '4df6d9d62252c957_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('737009fa-51bc-4c68-83dd-3e725f9fb324', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 81).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 81).', '{}', 'Network Fundamentals', 12.0, 'ab23c7c6cfa1de9f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97e3aa9f-3e64-4441-a38b-257773a56539', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 81).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e14f5b8139c58880_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4e5767d-6ac6-486d-a650-efaa0066c40c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 81).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1c0952d7700481c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16a209af-c4f8-41d7-aabc-9b04f7a0e70c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 81).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b2ac032214dbd88c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4097215e-cbda-41f6-99de-bb68b15ece58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 81).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd412efa2f6645512_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('540ff3f0-65be-4944-8ec8-47a2b810b3d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 81).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7d02caa3c69df860_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7527822-ce76-44be-8b62-314672686811', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 81).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '6d1369f4321764bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b093da2c-93d0-4058-9880-3b5f62aff0ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 81).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '7589389596e9f347_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f73d7c73-ef9a-47d5-8f2a-0965e23a9b6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 81).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 81).', '{}', 'IP Connectivity', 12.0, 'b7cc3034613ee2b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af816864-5681-48ce-80b3-768c66106d45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 81).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '01f0646b2d5ebc3c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('075d46a4-cf8d-447c-8fcd-b9fb8837b0e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 81).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cec6c23a5e749b76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83888ac3-b10c-4d6e-a5f1-380f0a0278d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 81).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '6d1f6deee01ec42d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86cd7cd2-c115-47c3-8944-a4c6f730fbc1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 81).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ef1bd0f8483c77e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52eff836-310e-4ab2-bca9-6d79109c7ac1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 81).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9456e724cd582901_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c026a13e-8231-4b44-ab76-26d75aa9c90b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 81).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1fef56845cb2f067_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35e9853a-6217-4cab-b237-e3973e7c8f64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 81).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 81).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b4ab5213e2827956_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a01c369-59ec-480c-9c8a-4eeb1fd3e244', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 81).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 81).', '{}', 'Automation', 10.0, 'c3b296aaf0742eb7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a985a81e-e70b-42b4-ab01-a55c62a5fa30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 82).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7352db8d1a3d1a7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2506a70a-4620-4a59-8aa7-9731c4f4f07d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 82).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '441fa388217681d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c38bba13-7d23-44e7-86d3-6f3980e33055', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 82).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 82).', '{}', 'Network Fundamentals', 12.0, '7472524f771632da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25110e3a-d9b9-49e8-bbd1-ad9c0c0e26eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 82).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 82).', '{}', 'Network Fundamentals', 12.0, 'd16c71c3a96755ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('339c51c7-55b9-4261-92b0-c3c6a1d6b555', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 82).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b2cae84690ec84a0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39a35957-be0c-423f-b4f7-3f7f508c0c33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 82).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1b85c5a5ff542997_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('023aaf2e-4482-4efd-9a40-70128c5178b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 82).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ab4dab7bb720d572_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26589959-6b2b-4e39-9406-eefb01b658fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 82).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '71884593c122a90a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39127746-6515-4e47-8fce-dddd7fcf6569', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 82).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'f29c5d781fc6e7d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6b25cca-5a95-4278-bcf1-966ea25b4c82', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 82).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '529e7d845ce9a58b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49518b5d-655e-4b94-ab28-e2b405c87e21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 82).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '07298499abfa716d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13c8eb95-9419-4630-8ebb-87d7d7d06532', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 82).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 82).', '{}', 'IP Connectivity', 12.0, '2d5f387730f5eaa8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0843206-cfce-4851-a0e2-cd85d92127be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 82).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'dbf28f1f9cfe039d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39989dbb-215d-4b62-873c-a5db07af81fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 82).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a13167fa96d8a8e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d52f2f8-e56c-4ff9-9345-c97b727f9706', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 82).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8a788902d6477349_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfeda79a-509f-45dc-8164-6079e078f5f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 82).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e947067ddafa0eb1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f882bd85-2527-49da-9441-466cfce93675', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 82).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9315500f67ea6231_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76ad9e9c-9d9a-4fe4-923c-01cc60fc0545', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 82).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'dc59dea0c09c678c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ceccd4f-c152-4e40-86e8-ea91c77ea32e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 82).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 82).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd02e5eaf2152f1ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e9586f0-9777-43e4-b7e8-228227f1b35f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 82).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 82).', '{}', 'Automation', 10.0, '3b673bf0ef6916cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4e12edf-7316-46cb-8949-d9996ab6b602', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 83).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8c34fe97073e4567_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b821322e-086f-4c88-8860-9986c0a54ad1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 83).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '96faef05713e47b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3e904c7-0817-4a29-ba79-1afe960ae3f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 83).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 83).', '{}', 'Network Fundamentals', 12.0, 'c27bfe06b37b7c58_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c20efc4f-915b-4969-b69d-ba17c188f4ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 83).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 83).', '{}', 'Network Fundamentals', 12.0, 'a6a2292b7a594868_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9135cc64-dfd0-4435-b33f-927ea6a15476', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 83).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'edf979f906863b74_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dd9c872-bcb3-40cc-b86b-7ee284c4d59c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 83).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0aa485e842095e25_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('137a0218-43c5-49f1-8037-df9744566f07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 83).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd1c8a7f36dbbd79d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c2c9bb7-cef7-41f3-a8d8-b250059e5e1e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 83).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fbe4dc1cccbe2951_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b09ca4d7-4364-4cef-b6f7-c8b98e3146bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 83).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '9480ee8c00911107_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24678d65-a005-474f-a095-2a49ecf553d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 83).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '2e56e1ba8e1c7945_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f718e25d-2003-49cf-a326-77f68d162f20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 83).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a302a028979c1616_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea6ccd0a-18bd-46b2-a277-442372447af3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 83).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 83).', '{}', 'IP Connectivity', 12.0, '617a70556d1290d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b1ca4a5-211e-4f73-b30e-103a9ec9893d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 83).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7a360513d5df5bd5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f8e728e-7ff4-4633-b215-b094bc3a80d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 83).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '29f1a11fd2994d23_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f7b7039-7816-4ab8-b143-2a5bb0b25e28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 83).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'fff30f68c5d80755_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eedcb7c4-3b82-4eb2-b255-02efc39d1a43', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 83).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '679fa9788fa94f57_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cd89660-e291-49f3-8f28-d435f4229f21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 83).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'cbfd8431cacd918a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df4de76a-6e3d-43a2-aed4-61184b184379', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 83).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7bfdc640fcffccda_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43a1378f-47ec-4080-a7ab-3a8323a39989', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 83).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 83).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2d0aa1149ae3c85e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('575381fe-f2fc-49b6-aa3c-a9975502733d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 83).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 83).', '{}', 'Automation', 10.0, 'f7a3a7b2d4e5d00b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8def582a-aad1-4f4c-8fd2-8cb55ac1440d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 84).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f707a09b0e8fa578_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77a877df-2d3d-46fb-a474-98e7814db63d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 84).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '19d6937899b36b27_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69aa5482-2c9a-466e-aed9-73ebcb181eb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 84).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 84).', '{}', 'Network Fundamentals', 12.0, '6748197c1d5c37d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c99fc3a-9a1e-4c8f-aaef-5df9b7052050', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 84).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 84).', '{}', 'Network Fundamentals', 12.0, 'dbf01c73b4d2a5cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6f6d0a4-cdbc-4515-a0d6-7cdbd047daa7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 84).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cde6fd084638551c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2c3289b-6c7d-40fe-985c-5e7792e3f559', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 84).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1a0f2eb8d8374891_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94052405-228a-473a-bd91-f449e362baad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 84).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'aa8c992a2f530ce4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ff1fb40-2fda-494c-a9f6-890de7e8f62f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 84).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8dcb25e160698260_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6bcc3f6-0f6b-403a-b2b5-846b65e99484', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 84).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'fbe04a885f37b617_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0793f119-f4c0-4511-b38e-cf26902008dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 84).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e1963e095b32ba1d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02af7c0c-a467-4505-8dac-dc87c3b85bc5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 84).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '85c5679f15938207_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6fa95a3-495f-4e02-a144-c6ded9b2055f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 84).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 84).', '{}', 'IP Connectivity', 12.0, '2fd4da5e7985a57c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74e01690-7c44-45dd-a442-4316baabd76f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 84).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '091ac52a52d42f40_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('686018ef-e234-4fea-8db3-7822d864d39a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 84).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a6e5fcae540690a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c69d3457-14a4-4ab0-8c62-935d3f873b44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 84).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ff9034f11d6012fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3e9ce8e-d7ea-424a-9b83-278b9bba070f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 84).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e98f4f08b9e09185_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45b32af7-cec8-461d-8d58-abcdba88906a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 84).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f802231967402878_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7890a08a-4574-41e5-adfa-b8e9f1e46522', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 84).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'fc3b7bfe4f663956_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b995341-24bc-4e86-8338-18c9cbeb646d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 84).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 84).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2ec0a893d06ec23d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('039a1cb8-5594-43a7-8a51-9efc8ba72226', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 84).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 84).', '{}', 'Automation', 10.0, 'de46416119a00357_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f729cae-ad79-4492-b0c4-6ac5cba6142d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 85).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f298584aaa87ef10_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dce2688-7a24-4318-b66b-696e8aae826c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 85).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1db50147512c96d9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1507226-bdb9-4cea-9adb-bc29509628bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 85).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 85).', '{}', 'Network Fundamentals', 12.0, '16d592582e2fc24e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae273773-2961-4046-857c-c7284ebbc111', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 85).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 85).', '{}', 'Network Fundamentals', 12.0, '41bf7c28a4f74cb2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4a110f2-2299-425d-9199-b22ed213523d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 85).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b2ae64d1a18364e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('911ac4c3-b9e2-4546-aac4-5c39cdbd881a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 85).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4cf213df55e299ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b17e3301-3920-418d-9558-c447337001a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 85).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '20a9c90553ca4aea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eb1eb23-8a2c-48e9-8453-1b33774843ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 85).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8fdb4c6f279f5698_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90c9c02d-51d9-4440-a14e-a67631665dec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 85).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '602d1fb473a91551_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9582e864-d188-4d9f-84d0-ac4e6cb78111', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 85).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '97612e2f57b2f38f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d88b582d-d7c3-4f99-924c-d62c46682ba0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 85).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '432c2c078d7006dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4226cf29-aba9-4363-a076-283393df49f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 85).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 85).', '{}', 'IP Connectivity', 12.0, 'b37a9930c9013d6a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83d9e710-70e7-4902-983e-6a1d78b8a80e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 85).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ceb47bdb7e467f49_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8401b14d-1fa4-4e08-a1b7-56f6ce1da5b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 85).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd48118700977b427_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abf808f2-49c8-412e-8fca-6a9e5f492632', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 85).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '6c9fe5ef9f92386f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02a12feb-4fc3-4ba9-8947-33211aba13b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 85).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ce41f656f0bb0dc3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f99218a4-599d-4755-9e34-9a35efe7bef2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 85).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'dea9b21ac63342b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f8ee252-aa35-4fae-a6a1-c3afc41f371c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 85).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c41863ca5b6e2c5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ba78088-5006-4cfc-985c-5a81851f40b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 85).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 85).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '384af3e984c237bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64670dd8-91a9-4d36-acf4-38990088076a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 85).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 85).', '{}', 'Automation', 10.0, '9f934451102fa7a8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a966163c-3e2c-4e0a-90df-41bdcddc27b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 86).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e33227ca8707614e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('970c8472-84d8-4fe3-bf42-1fc992bf2fa8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 86).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '64d0a5cb83d056b1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3000350a-e701-436e-9019-7c1223d9c5f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 86).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 86).', '{}', 'Network Fundamentals', 12.0, '44d27e6201df0c45_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee2b8248-96e3-4612-bdb9-ef465e0edea9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 86).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 86).', '{}', 'Network Fundamentals', 12.0, '17fb47cf4557a365_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('305c2ea7-c970-467c-9f19-0c6240af524c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 86).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5558c254daac264a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bd5ac27-21b3-4da2-8e37-6e4780de60ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 86).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1d78eb4a983aba85_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30837509-b171-4f2c-87e0-c154c09a590b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 86).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '205a3d958f2dd24e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65d962c7-dc1a-4996-8549-7fc0da5399ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 86).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7d991a18a26cbf0c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45d183f7-d038-422f-8d55-fba3b563d046', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 86).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '50985f612bbce1a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33fa5e79-0098-417c-a6ea-6aa88ee650d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 86).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5e2d3c84140142ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78796090-4d48-4852-80fc-91c20cf65ad2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 86).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '3c55b296dd5b5781_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fe957a6-c915-4c3d-977b-7c14dcd41f86', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 86).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 86).', '{}', 'IP Connectivity', 12.0, 'a16c012a8bb28e74_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('603f7da5-5a69-4777-9ebd-581696b16314', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 86).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '08dbbc2115cca5e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43421420-25cc-44ae-a641-4bba02cca451', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 86).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '46c301205627c9c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17f2f610-40f3-4763-af52-4faeaabeb629', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 86).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '444668a7b1d5572e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1987ff6a-3c6a-4c5d-bea7-29b676a22bee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 86).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '915b3aad98c9ef00_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0102ec83-8b70-4809-9888-73fef52f43b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 86).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '66fc3b9f7507fa7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56be31d6-ee84-4d98-9860-565d50ffbb02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 86).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '14c544567a5ea6f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32487ae1-8ff4-49e9-b7e9-ead6fdff35f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 86).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 86).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ad5fe4a2839ed668_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71f63b00-0938-45f3-a997-0c4abb8b7b5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 86).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 86).', '{}', 'Automation', 10.0, '5c18bf36ffbb2dd7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7adf441c-ca17-453b-b5df-0e7952461cef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 87).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5aa980ee6af9ec3e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ac3da01-9631-43ec-9352-6f5611355562', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 87).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '20c0ecf504aaca46_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5aad8e9-a6cb-414a-8c12-a80d8acc1039', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 87).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 87).', '{}', 'Network Fundamentals', 12.0, 'da803bbe98ce279f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df940f6c-c32b-4d13-af0b-337b760090fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 87).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 87).', '{}', 'Network Fundamentals', 12.0, '206ad89aec89b73d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('519a3081-f771-4b24-8882-0bc5bb8aa9f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 87).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b1b90bba5e067c9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('057ad039-c5b2-4803-94b9-235b8d78dd32', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 87).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '55cd2ccb5870ff06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('334e5172-59f0-4ec5-8aa5-9d27db875f4d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 87).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c3bb94c2f0c8cd92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7cb0f3a-a0d8-4bb4-8270-430d6689b016', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 87).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e09b0c1165b51faf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9247df1-a413-4440-94a2-8746c08d7612', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 87).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7fa87be0bff1f0cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca89a12b-cf44-4e67-a28d-d3491daaff44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 87).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '51175eb5b7790376_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4461bec-2b82-4958-a890-793e8edcb124', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 87).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '710f0897d00a2d66_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8619a5f7-1076-4a16-b105-05e7241e28b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 87).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 87).', '{}', 'IP Connectivity', 12.0, 'c5c16e51b49b6992_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea654ca3-9224-4270-9179-9ad8dde1ff32', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 87).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b6e3739aa370422a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('078d3051-314e-4f8c-9842-9886182010e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 87).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '13b17040282c8a05_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('903b324b-99fb-4675-b2ca-034359b84dad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 87).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '02932c2b206095bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6f22392-9ca7-4300-9134-eedaa3bf95e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 87).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'caafb2f4058497a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb27db80-8062-40a0-8149-ae5f1e0a9ff1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 87).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'edf812daaadf6f49_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b7f8fb4-ed2d-4024-8692-e8b3bd4e9a72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 87).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9df390116e2942ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0161d820-a5e1-4810-814f-0ab8130d89be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 87).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 87).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6a62a08931d20f9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc9a3593-db12-43dc-81b7-87a0f90b2822', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 87).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 87).', '{}', 'Automation', 10.0, '8cc76dfcc4c0965c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('962372f2-08e5-425e-8be5-244ddddfcc72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 88).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '79e4d89cc290cf4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('871c591f-1658-4944-af7c-eeb5289e57bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 88).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7e3a312da52dce3d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e9e1343-e6c1-44c2-b327-3f52c1c53fad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 88).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 88).', '{}', 'Network Fundamentals', 12.0, '0c166dbf96262db6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2243c9af-4201-42d2-bd99-5551d4970840', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 88).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 88).', '{}', 'Network Fundamentals', 12.0, '84a9c7e9e6cc0976_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f838f2f-4481-4121-9068-bafbd473752e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 88).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b89639d160e3efe4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1131c40d-8913-41fd-b214-aac384365bec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 88).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '19a88310c6ffc3db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e56f8fb-8b53-4330-9bde-f6cdb2f0a61a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 88).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ccfc19a6eed1c32d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf1bee27-a4cd-4d0a-89ba-df57bac6530e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 88).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4ba0484880e76b7b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bc0c72e-64c9-4958-9e7c-27a5b046df15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 88).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3bed30e7c8a65a71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1a7a4eb-1e89-4163-9226-06d66b5537db', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 88).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ae82635868dc8c5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43c79ff0-11c8-459a-b412-293fc5e881af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 88).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'e1f13821492cf973_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9af9557e-2d49-449a-83a0-24fc87464fba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 88).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 88).', '{}', 'IP Connectivity', 12.0, 'efe26231fbf7e3f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ca409c7-6ecb-4fd0-96eb-6311d2110a45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 88).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '71164cd2f4dd6509_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c92180f-70ce-4b7c-a982-02623515fd10', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 88).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '597b411121144af1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('480b9150-2e89-433f-8fe0-44f30dc6ec25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 88).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7bbac38eacfdc724_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8db3d35b-6211-463a-9f08-9a0dc4477a2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 88).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '910bb7d7a3c0e4cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29e760b8-519d-457e-be71-fd90bdea6d16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 88).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '5763a6dff8574693_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca6d7e7b-59c2-4b73-9c11-18db19a267ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 88).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '86c2f61ddb64f975_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34aca1d7-3867-4391-98ae-f45a3574d738', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 88).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 88).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '781c6be101076ee4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a092014c-c850-4a7a-ad26-2487db824c48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 88).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 88).', '{}', 'Automation', 10.0, '9307a7c5566c8262_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4de27c1d-8b4a-479b-b216-d3512974bc7e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 89).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e336236351a820e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9050de3e-d744-48c5-b5dd-5107d6623366', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 89).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '53b6c0a73eb5806f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbd370d5-c49d-42ea-bfe9-d82b182fd340', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 89).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 89).', '{}', 'Network Fundamentals', 12.0, '193f8f10b0ed1749_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf1e71c9-f3d3-4370-bb9a-c81ea93ea68f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 89).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 89).', '{}', 'Network Fundamentals', 12.0, '3e6edf4cc61dd5a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49634f47-6afc-4bc9-8be6-a6a7b12271da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 89).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cc83d7cc68391f98_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d82a83dc-fde4-4bae-937a-43dbb66ce8b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 89).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4825d80f5c61af9a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b49dd0e-42cc-41be-925b-cee1294f2245', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 89).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd8bd2ff7c5fd3656_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7daf63d-5882-4696-a472-f0baba49f377', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 89).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b208f33881e1d022_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a4f2439-e1da-47f6-91ff-6c0819583ed6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 89).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3e6fdfef7869efff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8d9f09b-7f77-4412-931e-1f454f339f90', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 89).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd2e126542b141d07_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('660e2f0e-d27d-49ce-b707-6d4390ebafca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 89).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '2e68174e02db1bb3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3a903e3-89cc-400e-a64c-56f9b58f1375', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 89).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 89).', '{}', 'IP Connectivity', 12.0, '90fd55cac1583ba3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12c1a92b-2d46-4c14-8967-301613070592', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 89).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '17ff62e889e0eef8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58b71dfb-e72a-45c8-8071-ca5944e181c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 89).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '51f11d8438566aa6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fa61cc5-a728-44b0-b27b-dab964330121', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 89).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'abbbdc198938b3f2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c4b3111-f686-4fbf-aa91-f327fe6389e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 89).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '390da0776a59538a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffc2e2a5-e573-4bf6-960a-d140436d8d06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 89).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '68f9b128ac8925b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70984c2a-a548-4aea-ace2-0871975d191b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 89).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '01be11e0ad0204f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea82f0bf-d605-40b6-b237-36cce0fbcca6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 89).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 89).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '4109045034260291_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60e6d545-669b-4b32-9b94-0d1af886dec5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 89).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 89).', '{}', 'Automation', 10.0, '60e8c45e1b0aba3a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0612838e-7f55-45b4-b63a-0c036267251a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 90).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '44d0cf132464cca2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5eaaad22-8076-4704-8d95-381ea172fcc8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 90).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd279670338f2a0e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9072dc74-329f-4b7e-8d06-a6f5a2e6cca5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 90).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 90).', '{}', 'Network Fundamentals', 12.0, 'cb5d71974714777a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfbf2fed-0775-4ba0-b357-9408503c186e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 90).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 90).', '{}', 'Network Fundamentals', 12.0, '5605d88d4eba03b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7aef44f1-19fd-435e-bca0-3d7aa96f1dee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 90).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7738192a6e1bf297_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('792e8858-9d57-458e-a601-9f04e23c6907', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 90).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'aa71e231826c30e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('826b81da-7022-46ee-84e6-57f9ce8e037b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 90).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e7e22cd215f38ae8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0502cbf-82a6-41c7-b64c-74949d7bf31c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 90).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5c0f44142fe864e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9db3a2c-571e-4b70-9f47-ec73f450b1d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 90).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '5e4bebc1b9a80d12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89da8cf1-c1a2-477b-b9fe-99868bc346f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 90).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0a7afc8c9894e257_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('524f0520-afdc-42e2-a77a-003a885de84a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 90).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6b43ee65f40b788b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e844060-d186-4be7-ac0d-7a2343d89c3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 90).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 90).', '{}', 'IP Connectivity', 12.0, '6b7b9288400aa6fe_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb7e5772-6439-4fd7-a556-76e3ae9216b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 90).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '483bec6716c91b5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d599a4c2-a963-4091-a88e-5a6938b150df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 90).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd3efc94dc1cdaf87_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a041323d-158d-4c55-9197-91298bf6c0a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 90).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7327914d7047e540_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6240607b-e907-4043-b3cc-220456c01bc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 90).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '98fc6af57261a96d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99a7a4f7-6ad6-43f3-b55d-6678c3193cc4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 90).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'df99f1138b4bb0de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baaab7f9-93de-42cd-aa06-94936727d7fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 90).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd397128e9ddfeefc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7d70bb3-82c5-46cd-8bf1-61b7c538b929', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 90).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 90).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0297e1565741ca9d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('190785cc-f6d2-4fe4-9ea1-1ea1e536333e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 90).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 90).', '{}', 'Automation', 10.0, 'ef76b64fa86d5996_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('762291f3-0d0b-4f8c-b174-46964558deed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 91).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1629933413d840db_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('656d2a03-9240-4619-a980-13c27fd5f14c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 91).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '375a2b05a765da67_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('246eabb8-f464-49b3-ba8d-5d5675fb8d1b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 91).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 91).', '{}', 'Network Fundamentals', 12.0, 'f681559b9417043c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b1c592c-2cc7-4d33-8e70-23f309a4f32a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 91).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 91).', '{}', 'Network Fundamentals', 12.0, '7d3496472605a8fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('393666dc-a3ff-444f-9556-1218ef93ab7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 91).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c7b8543f440abfa5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bad1895b-5398-49f7-b019-465a40e28bb4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 91).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fc003545ec7770ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a01af59c-598e-42f2-a7fb-cb901527a500', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 91).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7c87c372352a461e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a47cc8da-017a-4709-9863-215c404e9b49', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 91).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '06b2bcb3ac3a1835_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08532661-0e4a-488f-8544-2954f6e0c399', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 91).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c2c062f3434d1e45_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36f621b0-8169-4f06-9a31-dc9fca8d08a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 91).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '176df3c347908eaf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06ad866e-b08b-4d1c-bafd-16d95e79b79a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 91).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '26e0a61b35252116_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0a915e2-985e-4bbf-b4f0-fd0364f39673', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 91).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 91).', '{}', 'IP Connectivity', 12.0, '224b01eb14a9b1bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b0b62e0-3664-4156-ab82-632f17e0ef88', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 91).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '43af305c71be4ebb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87eb4b0f-9d05-4671-997a-8297c714dbe2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 91).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e18a041033a92b7d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbb42a42-f011-4558-8c0a-d84f88f10732', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 91).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e85b23f334a46552_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae7aa28c-c6c6-4b1e-8931-41500afb0127', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 91).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '065c276611ac95dd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1eaf7f5-ce1b-47b6-9df6-10293046792c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 91).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '7a4671e32fda09c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ac93ca4-a939-4762-82b9-c4514daf84f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 91).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0fda28702b5a8b07_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c8d7a64-d0cf-4454-8121-b08aa95a18d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 91).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 91).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'eabdcd506cebca55_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96158796-32a8-477a-99dc-1a318bb19119', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 91).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 91).', '{}', 'Automation', 10.0, '8930ac637d830c03_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('380bda68-a9f2-4322-9205-aad5a78fe1a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 92).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c1565e6d7e5bfb63_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cf27816-4460-4310-abab-a4d80c374c3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 92).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8495233ee64030ca_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dba0749-6760-4ba4-bb09-89948d71e2c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 92).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 92).', '{}', 'Network Fundamentals', 12.0, 'cd095581bcc08cfb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c7e187e-4a29-467a-9f3a-125506d56d67', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 92).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 92).', '{}', 'Network Fundamentals', 12.0, '9c4108f3508ccf1f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ff4dd1b-35d3-426f-9115-daed0ef09a5d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 92).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd78b0e6b3f1ff96e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cb9df16-229f-4d83-aba5-659ab66d3436', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 92).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8ff8ab2864f77811_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0e3b7be-6142-474a-9ad6-77953842628f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 92).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e7ced772ed5ddff8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dfac147-ca28-4e05-b602-94d5e5803289', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 92).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'aa2fc04b52a47c92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2957d37-e249-4426-ae22-6cfcbdb33a07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 92).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '4eb031782652046b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cde6b5b-2c2f-4114-a4f7-2300bf32b698', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 92).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '67785887110657ff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('948aed4a-cc91-4e98-a981-d177957c4e34', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 92).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a2f46bac2f8f58e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d494c3b6-c977-4902-abf2-6839fa27b660', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 92).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 92).', '{}', 'IP Connectivity', 12.0, 'f0798209c86542b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72cd4de1-c2bb-44f9-a3cc-b1ccc75d97cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 92).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bac4a440c149911d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc78227c-e962-4079-8d08-187bd20dc5d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 92).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b44822135c17de92_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89ecf700-4f17-488c-8d83-a5f72b39f488', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 92).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '50fc57c8363ccf21_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e146ad4d-24eb-4173-8502-f89c46563ffc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 92).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd1825760e1b21736_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bb94861-c8a8-4e89-8501-5db5008d06b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 92).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8a1a78bbd8879a05_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7286526-9262-421c-93ef-93ec6cd364c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 92).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '370b5a29d97e0c5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('029fbc30-8540-43c0-8f39-1c271ba29a45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 92).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 92).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '00620ae1e604ef33_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('414589ac-b12d-42bf-9689-204ac7f5d743', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 92).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 92).', '{}', 'Automation', 10.0, '875fc144d6734bf0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddc7e4c2-c55d-44b0-bbcf-98fa188a87ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 93).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e3a0db1356cfbed0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2a1e171-4cd5-4351-9d8d-bfca0fdec3d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 93).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3767689619e11bf2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46348d5a-3848-4550-a3b1-8df72e8b6203', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 93).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 93).', '{}', 'Network Fundamentals', 12.0, 'b1a292a1fe571fff_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8593fa0c-307f-4143-a73e-7f7b02200832', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 93).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 93).', '{}', 'Network Fundamentals', 12.0, '344d29ab58d69611_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2c1b03e-c214-4d6f-9cff-a73768470ff6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 93).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dd356d134c123b5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7e3ecfe-b9bb-429a-88e0-41a5daaa9d0d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 93).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a41e829f816f10c3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cae27150-1568-46ec-96a5-4b51135ea1e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 93).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '53063b702ec312ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1195375-267a-45e1-a4a9-4260b94287be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 93).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e1eba97e5681b18a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('154bacae-fc84-4b00-85c6-45718576af0f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 93).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'bddc06b10735884a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65c4e62b-2ae3-4837-aaa8-359676e5bc24', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 93).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '847ac08eb996a372_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5f8e3a5-27d3-4ab6-adc1-e639176fc046', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 93).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f3861d11bbeeefab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4083b760-27af-47b6-ab28-79ab0a9ed800', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 93).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 93).', '{}', 'IP Connectivity', 12.0, 'a05130ad1de55dba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9a8b366-5838-4052-8dc4-a185a667d698', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 93).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '85c8dba1640838b6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('050972ae-ed95-49c6-bc6b-7047140af9de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 93).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd6bf65b0f8705d91_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32a808b0-1b3c-45b5-aaf8-27c479c4d1f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 93).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9611ebc9f0b788f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f097be1c-65f6-4961-bb42-abc59a922e51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 93).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd0bf4a5d99662f12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48a710a5-feb9-4bc0-a230-a8551ca9c940', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 93).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9d549f6a0dc78836_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b76960d4-06f6-4f3a-b663-3b809a031f54', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 93).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3fbce8b0c8883953_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a28fc00c-bd56-40be-a559-541fd7ab7db2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 93).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 93).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '77861b3839204706_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a622706-13da-4abd-bb99-fa5a726e3585', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 93).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 93).', '{}', 'Automation', 10.0, '3b8daec8ae955fbd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d2835c1-3b8b-4e7c-b2c0-8218efa4083a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 94).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '84d230dc6b55bfb4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95f2c474-6b12-4d82-8e2e-a902d8573f6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 94).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1dab640ee3304e60_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7040299d-4313-4832-b076-17c741863ae5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 94).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 94).', '{}', 'Network Fundamentals', 12.0, '2452d31ae5d0694a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7727fa1c-4026-40cf-8092-449e21769b2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 94).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 94).', '{}', 'Network Fundamentals', 12.0, 'ba3809452d1e93a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc87c7ca-f59d-488f-8aaa-f2b3ad510f45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 94).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '584addfe6fe28111_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e85f3dfe-55ab-4fda-aa64-2af39a015aba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 94).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f67bd7f0dadd0875_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37f8403e-38cb-46ee-80b2-1d054d8188bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 94).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '100f4e36b197b310_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d09bae47-225e-4daa-8557-5b292b440538', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 94).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd068a49f53f9ad53_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eff00bc8-a124-4f21-baba-3b2a99012185', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 94).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7e3044dfc8fa0044_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39553137-eb18-4874-a5c1-dce4c76f561f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 94).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd15b9885bfd68ff5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1fb0b73-9270-4528-ae13-43b48688a69b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 94).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '092e32093558f5ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c34feb8-a8b3-4136-b486-8fe9c6a8131a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 94).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 94).', '{}', 'IP Connectivity', 12.0, '07f6380190c1bb8d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d696c58-f6ed-4603-82ca-950dcc0d2c9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 94).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '161ee6db8eabc776_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5455f74b-3401-46db-8e2b-329032680800', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 94).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '995992e4b55ec6d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d38b691-c868-4665-8fef-bafc405075af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 94).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '96ab6cea3920c9da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e822ad51-d899-4732-bf0b-3e89aabc4c61', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 94).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ef98314489c8be75_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abd02d3f-453c-40c4-a594-e70a78670ff0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 94).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b3873ecb09c75220_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc0edc48-d6ad-4347-b0f4-33dcc42f67c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 94).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3a0656b85018b854_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca26f4a8-218d-462f-9641-f66938e9182f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 94).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 94).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '3b0a8a4fba665010_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c24e53fd-246a-4986-a6a8-41162f60a995', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 94).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 94).', '{}', 'Automation', 10.0, 'fb52fe0c2af1c3f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fa93975-12cb-4717-bd11-c65eb339be7a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 95).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '93bdb8156d9a5318_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76a279f7-308f-449c-b544-5d3a898fdb50', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 95).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '48ee3c65632133d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e206b55e-cf10-42c5-9889-b910ea14fb8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 95).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 95).', '{}', 'Network Fundamentals', 12.0, '6e6aa95d13f9887d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bff85cb7-4f5c-424e-bc74-f9b84864f935', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 95).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 95).', '{}', 'Network Fundamentals', 12.0, 'e4ffc6948335257e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff732298-b611-4965-8815-d8c1c61e09ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 95).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '646ddad065bbb69c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e50f45d0-53a0-4117-a826-6b69c11a4cd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 95).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd6b78130079ab1df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9f3a7cf-4a10-4294-bf30-c947df2376b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 95).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fa3264a45c2aa46a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('340c092c-490a-47c4-92b3-918d04eb1782', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 95).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cfbff5d16b2f1916_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb472b9e-d948-4b5e-9a55-5fa327d883f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 95).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0b0ba384515df245_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('246ee78f-3c9d-4f56-bb97-440ada4a782f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 95).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'f97a35bae87acb0f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a60eed01-1edc-4071-b177-f284591740f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 95).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '865da1dd7518453a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36346197-e8a1-447a-a435-9abc07beb9da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 95).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 95).', '{}', 'IP Connectivity', 12.0, 'f3df309b8b7ac9a7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d90ba2b-c977-4859-b3da-93c11cb81828', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 95).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b8240e9b63aa6b09_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da1d3bbc-550e-47bc-a55d-7f3480795f57', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 95).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '85c52822cae3b332_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91225de3-52a3-4365-82da-fe302e22a579', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 95).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '51f8377fa693012b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26d1c8c5-23db-49ff-842a-9a9d15a206c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 95).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9ee3d4c627afb448_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97623f96-fd1a-408c-b2f4-023d71a0b753', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 95).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ca33b1811a11019f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dce6532-8704-4464-9aba-4e5743e6f59c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 95).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b1a767bca20b1f7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67f66379-6ddf-488d-9706-75c331389c6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 95).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 95).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '64e02547451069f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('055d8e86-422f-45d3-9be8-64ef3606e384', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 95).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 95).', '{}', 'Automation', 10.0, 'a92644e7d01f4418_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c43a840f-328e-4603-9607-6dbfbe465e29', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 96).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e978e624796bea63_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfb3ba36-abdc-48d0-b5ff-0d86b14887ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 96).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '66fc98c7d0d0443c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c14356d7-aa71-4f08-adb9-7fc84e7265ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 96).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 96).', '{}', 'Network Fundamentals', 12.0, '5f4af68e70cd796d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd83e4d2-d353-4181-85e0-5c7815cbcef1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 96).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 96).', '{}', 'Network Fundamentals', 12.0, 'b1c38f9e54b2a858_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acad2502-1ea8-4afb-92b3-da8ffcec1de1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 96).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '860511de8a51a6ae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a7ef03c-7ec9-40f4-a095-97443f33789b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 96).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c89c9e93727ea1a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7cbbf25-5f08-43d7-8397-bb8d4752ff9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 96).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5926e5cdc1621b34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed2293f1-0adb-4b90-9fa5-64185227fde9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 96).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '52a828c79a196a70_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26657ee2-a6e4-40c8-bde1-f94735be7bea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 96).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8d5b574aba2eb1e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10ccd61e-1d08-4d49-93d0-906323222b21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 96).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '7be0f9b456828f6f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebf78640-0cf4-4532-a116-e5a4b59718ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 96).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0095cffa0b6f4024_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a39c4da-234b-40c1-b3b1-b31e88a82ccd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 96).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 96).', '{}', 'IP Connectivity', 12.0, '91a02d2ce039d284_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('971dbebe-54d8-4347-b5cc-10a90caef4a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 96).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ba5ea959bf59d932_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb391ed2-c590-451a-a74f-49a5fe73ada7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 96).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'af0c1992411588ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9f2c4c5-0bc9-4dcd-9c45-87affb60a0bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 96).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '94acac965446ade9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83671db7-7980-45d6-af6f-0089bac3006c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 96).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4ba34875cb328518_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('917cef6a-f7aa-42dd-9ace-c3c0889b8cc2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 96).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '5749fa480111ffde_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d620c00-4f39-4eed-bb1f-e633fb32ab64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 96).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1ace4e744fa8021b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad9f0a6b-1210-4a15-a17c-1e621e8081d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 96).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 96).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'a7d87e2e826df109_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a09fc8f1-b251-4acd-af63-6156e73df45e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 96).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 96).', '{}', 'Automation', 10.0, '5f98b080385dd731_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fff58c6f-330b-44c8-b1f8-bb587ca46040', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 97).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b2a6466e18f8f0e7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6961981-2cf7-4aa7-b0f1-8cc8289e0f6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 97).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4a0b75fa949f1571_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7c18c4c-1f3f-4bec-b6f0-8c50d36fe80a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 97).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 97).', '{}', 'Network Fundamentals', 12.0, '25fc52ce20c3dc2e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdfdfc00-9db9-40d0-ab38-063a017cf169', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 97).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 97).', '{}', 'Network Fundamentals', 12.0, 'cd44045b473af590_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2e5e7ae-eff2-4b60-a243-6da22b66c64c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 97).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '30ffa64bee74a6f8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15c64c68-6227-4e1b-b2ea-89cff5d8e2c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 97).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1bdeeee23f7ac400_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3da0265-7151-4d1f-b702-7fede900cf03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 97).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9c820c5f8f3a9d82_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53f01bf6-2e98-4ac0-b09f-655dd93443f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 97).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bfa88ccd06995f2e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23c96e76-3570-4e29-bd9a-a3a574d30e6b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 97).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1242544c9501ae20_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3597085-a654-435a-8a21-32e1da8f5d14', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 97).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ae24bc4360ef9ccd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f4e7bfe-a9b0-4800-91bb-78f7feb16639', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 97).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '818e3d84af3c23e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7018d709-b7f1-44f3-a631-b6faf3368f7b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 97).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 97).', '{}', 'IP Connectivity', 12.0, 'c9b119069ef7094e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f11d4a7c-aed8-4097-a31e-585f04d999cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 97).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '078c1bb5e01232e8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdbbfee4-d9f0-4f55-97ba-ec888f2c3051', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 97).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '524cb27c0ab26423_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('155750aa-7f53-48c9-874d-738d4a16aeae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 97).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '34ee3cdd30cbb2d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('828fbe8d-7350-4be7-b139-5d4e8e703e01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 97).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1937a713e2dae324_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('313057f3-03a1-470e-bdcf-12ddec9667e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 97).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'bea0eb8a666b551b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e51319de-d73d-4302-8357-797dd2ca5407', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 97).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5e74a59ab98f2c68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b16f5fb-d7b6-49e7-98e3-e0fad5fe4544', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 97).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 97).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '37c24a7e2e0e7351_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81d1cd42-56f3-4531-b656-a25cd5eed45d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 97).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 97).', '{}', 'Automation', 10.0, '9b7e3a219faa41cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('206e70f4-aac0-4671-8a23-df7922e0a398', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 98).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '162cbd74528876c2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35b79e37-707d-4818-9c23-646530e6f4ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 98).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '705ff7a686b720a3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1767ca3-3332-4e96-82fd-f0726ce716a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 98).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 98).', '{}', 'Network Fundamentals', 12.0, '8a5ceac612e7ef08_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ecc0bfd-eecc-48ec-8dbf-f47b40532e25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 98).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 98).', '{}', 'Network Fundamentals', 12.0, '263abaf81407172f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4925d2e2-75dd-4e2b-b63a-8b8dd663f9f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 98).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9b935d7e86cd05a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26a552fc-ff75-40eb-af78-be4567ce69de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 98).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a8ae782667585f4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9f30870-c78a-43e1-819b-ff9ca544f6a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 98).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0d7ded0d379442ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f0ea5e0-9e2a-4251-be0f-7ac6e70eb80e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 98).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd6f3b2c04086b28e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('341326ea-3bf7-4873-a53b-da3db2085b22', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 98).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'cb5902cc4bd6187e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a56333a-b356-4ef0-8baa-c70ed22f8dc7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 98).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '10b700a64977427a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8a6884c-7571-444a-b206-26393bde3832', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 98).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'cff54da7d535fc9b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f9737d3-4ead-4ab9-ad39-75750e889f0f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 98).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 98).', '{}', 'IP Connectivity', 12.0, '082254dd1eab8fd1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e17ab245-604f-4581-9493-324b189ab3d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 98).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8bf95a4fd1127bd0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f1bf0ec-d984-45b7-b47a-4b45e98d4bba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 98).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a32b458e42365b8e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90093f18-3a31-44d7-a8e1-d4bdd0ceb9fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 98).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '40429298043a3732_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('493458b2-adc5-4652-92b0-2f1337743f23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 98).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '79caa7a7b2ed9d5b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6b0c487-a6bc-4200-ab3f-d108f9294553', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 98).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '848eb849f16a4d3f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e017870a-082d-42c9-9e15-f0525b2f6130', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 98).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '931ef22a9e9edca1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a3dd1fa-be82-4de8-a01a-9b49bc7fc5d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 98).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 98).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'adc35fb7d16f99c2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44e409a2-895f-468f-95ba-30cf49700b35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 98).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 98).', '{}', 'Automation', 10.0, '0b8f01c5343865d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f9d3b23-3e8b-48de-8fc6-a98446649f67', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 99).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b89c763deb9aba9d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('406e060d-1288-47a7-85c7-2b76ee240092', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 99).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '60202a4c91a09c0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ea1a192-2d41-4455-892f-b1caf623137b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 99).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 99).', '{}', 'Network Fundamentals', 12.0, 'b704d66cba07f372_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a10d4812-e4af-4e6f-96f4-8540549f0a40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 99).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 99).', '{}', 'Network Fundamentals', 12.0, '589f61f25ca7ca15_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fad00807-d771-4024-a064-cb93e5b291bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 99).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ebb0dc282438c88b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69091f0f-b5d5-4eec-98b0-f271c9e96a09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 99).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '396cb754b26e0b29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c70bb1b9-5905-4e8a-9986-11502b44235d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 99).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a5520004168ec54b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9021262f-ad09-4ea3-94f3-ec25ab3c50fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 99).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0e6e0586025d938f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83dd0e3b-e660-49d1-947a-8fc67e785d48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 99).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '5e7cc19628a89253_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('343edc6b-4a9f-41ad-a1d1-9e6d1a6f01d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 99).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'a77f6a023b1fc2fc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eed8aba0-541d-44dd-8786-b9adc09510b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 99).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '1ff5d305997e4ded_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19734631-9215-442e-a651-9a8696fdbb91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 99).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 99).', '{}', 'IP Connectivity', 12.0, 'fe975e2f47b6fe76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1da65326-feba-48cc-89b1-b4a3f4c29dda', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 99).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e9bc46095f7c018b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25971c49-8254-404a-89a7-52419213a3f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 99).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '93c753b6f652b8e5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c576c08-e951-4eb1-94f8-59ca96e091e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 99).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c8e9d753597b63c1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4bed019-f327-40d0-8745-16a970ece77d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 99).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1e779a0554d52708_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cb439b9-fba3-4f6f-8a1b-9204a1b1b893', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 99).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'beb52fcc0feb137d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38f5a333-6053-410c-b248-e1b9750eb3fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 99).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1ad7046323c3ae4a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a26836cc-d4c4-460c-bfdf-129b6f90a46f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 99).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 99).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd036ad78455735ee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b42c4a3-4c38-466a-84d1-2fdc2a96fa79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 99).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 99).', '{}', 'Automation', 10.0, 'd66f3da135da7782_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8ca217f-b4a4-4eb2-bb28-df0444c2293d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 100).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'cb1257db1274b8d7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df8ffca7-8984-46bb-aa14-d80490516045', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 100).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4c215294b006264f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf58a30c-0597-489a-b0f3-a313d4463b8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 100).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 100).', '{}', 'Network Fundamentals', 12.0, '9d4f5c7008d7f640_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('900aca57-4810-4bfa-b64a-f09df150fcdc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 100).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 100).', '{}', 'Network Fundamentals', 12.0, 'aa7d6af560e7b688_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae3af500-a3e7-452c-984a-5105504f8e50', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 100).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c1b511095e501b02_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('578e9d1d-83f7-40b2-8bed-c580e95b5ee3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 100).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2d3f71d075010a1a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b766a8bd-0aad-4b84-82a1-ab90124190f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 100).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac27ceb4dd4cbdf5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd5b14f4-6a7f-4693-a477-6e12d44d12ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 100).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c074907bd469a954_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daa320fc-efd3-4e25-bcf1-673e7fd66f69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 100).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '6530c66f90f6c883_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c9490da-904c-4deb-b047-7b2dfcd28456', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 100).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '70a8e53319ce9416_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdfe4a43-b6a2-42be-a7ca-a14bf38068be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 100).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '45c48440b5a77998_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dbcc144-571b-4a36-8fae-3a2342b2468c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 100).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 100).', '{}', 'IP Connectivity', 12.0, 'ef2be987d89363bb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1736a4b-06ea-4279-bd66-20b214db275d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 100).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'db2be475aa065d69_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4781be50-2cf7-4c57-b675-afc4969dbcb2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 100).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '65c5906f123148a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91261b61-23aa-41e9-bf49-fc695ef3aa91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 100).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8f7ebdfa22488698_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('289d5adb-af4b-4310-b230-59fcbb1a128e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 100).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0ad617223af7aa09_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f09b678-dd46-4c3f-b64a-274a947a0d97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 100).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'bd1a086655ff1712_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9124655-0c7f-4755-b0a0-c510204ca0de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 100).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f8c628a913074fc0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a5e5391-b6c4-4b74-a1eb-ba92d4a554e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 100).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 100).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '24be603f23631725_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26249ad6-baa8-4e4f-b8d1-5df155bba7c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 100).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 100).', '{}', 'Automation', 10.0, '730a64d95fedf953_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35fadb87-9fea-4623-89f5-154964128390', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 101).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c1f7d9b69ea59619_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('664ee230-229f-4cab-814c-262434c497f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 101).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1208b22efebc7d46_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('954e2cef-69f5-4c27-a2a3-a62539c778ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 101).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 101).', '{}', 'Network Fundamentals', 12.0, '7e287fb327e52a08_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33262a9f-57a3-4a69-be72-dc637af78f52', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 101).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 101).', '{}', 'Network Fundamentals', 12.0, '9ff3dff85a682549_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a505b53-1b6f-4bce-95a8-79b520093edf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 101).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b780437e5242cddd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1be83147-307a-47e9-9417-a8bed56907da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 101).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '52b2b3b5c5ba8aab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dde7d012-3c4d-4115-a828-0d90467cfce3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 101).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '316a50dd77088fdf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f5be244-cfc6-4551-bb4e-f1a38942b140', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 101).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7f8d622aa7463619_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c330063-b14a-4eaa-a119-4f9a4a5cb297', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 101).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '176072fa1d912bbd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92123245-551d-4c7d-a574-477c0e78eb1d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 101).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b85f64ad32ebcf29_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03c479c1-7ec6-490b-a69f-197ccfdba228', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 101).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '2f814781501b9a49_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f52057f-af3b-444c-a294-ea6d3345ad4a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 101).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 101).', '{}', 'IP Connectivity', 12.0, 'b2eb53852abf0a2a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8278ee7d-b913-46b4-b4e8-ae1e217c8abb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 101).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7c487790b228f26f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aff48b9e-64ae-4bb2-9b6f-669736ebc575', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 101).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9a9f07726d692625_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3f0de39-eb9e-4c86-9052-d845866cdd8b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 101).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '21c21d4c07643dfc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04bef7d8-183f-405e-8b0e-1064bdc67df7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 101).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '978488402b623bb1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c322ff1f-ae98-463e-9158-9a873fb19af1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 101).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e32d9531e8586c48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dba5abd3-5912-4baf-a1a4-51abc7c8ffb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 101).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ace049702a41fbdc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e2a5416-0e82-4c8a-9a8f-5b8f68046f03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 101).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 101).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd754d47e5be449ac_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1b18e3e-434b-4b43-95fb-ad27fd0c0d82', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 101).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 101).', '{}', 'Automation', 10.0, 'aeff9af5e69378d6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c6e8263-2893-4b3d-bb6f-b802758195bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 102).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '23077931659c8c00_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05828d6a-b236-40a7-a91a-ae7ce48d3e69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 102).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '58d59c194a14b4c6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5380aeec-49f3-4cbd-b15e-f844133c0398', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 102).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 102).', '{}', 'Network Fundamentals', 12.0, '45bf280353f21668_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('412a40fa-ea9f-4fcb-a363-63a5555114df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 102).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 102).', '{}', 'Network Fundamentals', 12.0, 'a680174e091effe7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('763b75c3-e182-412d-8a8f-e72ac678968f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 102).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ef0eaa829fe9cb07_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a8e6cb4-2059-4668-837d-c75a48b734e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 102).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '425b4259a0da05a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4283e8d0-1bae-4c8f-85c8-297a2d971862', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 102).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f83833a45d57825e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bc279f7-5cef-4581-ae00-4be95b671c80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 102).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'be7aeb1b868970d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27420b0d-4e88-40af-9dca-bf711a59bfb7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 102).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '81a9c1024dcef04c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ffcb481-1792-4334-b1df-7caeae2468ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 102).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1d423e5ad488f679_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef53f605-9b4b-4e29-8db2-874bbd20a293', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 102).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd8dd1030e376dd06_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc477eb1-3488-4db9-87da-f297958aaf38', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 102).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 102).', '{}', 'IP Connectivity', 12.0, '44f57e04bbb27102_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('350f1858-b637-43df-9853-d7dfb18608ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 102).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'dea3eda466bb9793_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8090b756-a62a-46aa-9756-762242705b71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 102).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '903cfc2a12815bd0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f7e134c-d0ca-4e16-a080-c4ad505c9c2f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 102).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7a080814fb04fc75_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a164e3ce-a2d5-4287-8969-83fc2b2024de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 102).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'df5dd3aa35512216_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb9f2418-3e97-4cd7-bf1d-70de8e70613c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 102).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2da34a3bc38ca3e6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b3f62dd-e0f1-43ef-bc10-999728c91595', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 102).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4164c24683fe8c65_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d60e889-b9df-42c0-8e95-dca6e07b080e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 102).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 102).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '1a2cf8c7f54c078e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c21ba016-3eaf-4525-bf2a-b4071d8db823', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 102).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 102).', '{}', 'Automation', 10.0, 'a5deb5a9daf7c43f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56b8689d-e8f8-4dac-8ac0-61fe7cb36430', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 103).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b5b7b0c1ad1591b2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('243e3fbe-8cab-4009-9d0a-872e0bd071d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 103).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c0f686fb603316cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca694964-f9d5-4a9b-8312-92c9d25635bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 103).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 103).', '{}', 'Network Fundamentals', 12.0, 'df264813b280fb24_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72ab309a-a9a3-4d94-888d-b9610e995d46', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 103).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 103).', '{}', 'Network Fundamentals', 12.0, 'ad7438d4f3bf0340_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('429a7fbd-5609-489c-b61c-a16a2f4c75ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 103).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '15a319b46654531d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc017d99-450c-4775-b841-3b955fc4b766', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 103).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c7b47fdae24ef13c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c52a5d0-c824-4a23-ba01-3546a7defedd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 103).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '93688f79294e465a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66974389-b51d-44ad-b448-e22ae023f7f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 103).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '21a609281856afad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad37cc6c-b4fe-478d-93ff-f5261e4848e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 103).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '660b0f82586e94e1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb91f2c5-2226-42b6-bada-5c470a13ffe8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 103).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '9f02e6735dac2ac2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9c3ab05-4fa4-423c-bf67-8312728214dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 103).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '590f242f6d9dd821_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0834055d-ac67-4054-aaf1-f4a1ad8f6e17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 103).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 103).', '{}', 'IP Connectivity', 12.0, 'b42027bea1674cc4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0a6b976-0386-4ffa-8bdf-f130da3a4f39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 103).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3818ba66c6ad9d7f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a821f8f9-97ad-4168-ab80-135fe41adcc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 103).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9a9f0f79789f675a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1ccda1e-8e71-4f5a-907f-5ffbbde91dff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 103).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '993e34d3f56dce11_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f44a4039-1bae-4b4d-831a-e86dd5e46d74', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 103).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1bb4ab16367f68be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('434b614a-f317-4575-a720-62c4a31e6e31', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 103).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '16a934185df126a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e0ddfbc-4658-4b41-9c61-b0026ec74d6b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 103).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8593a909efd220fa_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03fcdbe1-d717-4054-9191-f33e2a3e503b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 103).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 103).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '624e8d15f50b3bf9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99e67164-33e2-4128-8a7e-ba25e77d3185', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 103).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 103).', '{}', 'Automation', 10.0, 'cce23b93a6b251bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24c78725-b909-43e0-b622-b6d2bb1186cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 104).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5c63d0ee020aa43e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6eb5efb9-60b1-472c-9b62-f780dbc8fa77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 104).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8f73aa30c8a51c12_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9437c6ff-708a-4361-b190-a1a3392268aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 104).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 104).', '{}', 'Network Fundamentals', 12.0, '24ad5e8eb0138090_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb71ea82-e1f8-4379-ad07-a67e0dac0214', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 104).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 104).', '{}', 'Network Fundamentals', 12.0, '7a336ab63a34fce7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d653a385-9499-4ae2-a164-1839e0a9c529', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 104).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f77370708fe413f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3e0416c-a5e1-4145-96ac-e6c3b4fd6fc3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 104).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eb2d768e12c5dce2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dff176ab-eafa-4edf-8d86-32787b86c710', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 104).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '65c1e832ba2d9418_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8628f88e-08dd-4e75-9c69-490664b823e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 104).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8ee76d9c96b567a5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('957c3a1e-1162-431f-8d46-f765ee20f390', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 104).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c5b8f63812950953_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07d64df0-8b52-492a-98fc-2eb4ed73131a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 104).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8d24c0e3c790f152_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a568965f-c911-4120-bb01-f73a88d1aa4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 104).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'cb28a954b58d5131_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8c97992-24f4-4ca4-b6c8-3aa2197b3947', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 104).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 104).', '{}', 'IP Connectivity', 12.0, '04f6030aec47def1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f458d35-5f47-44c3-a945-f48e78698dee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 104).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f590f36a25bd905f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b13e4cb5-3fb4-47a8-8118-0575017c6312', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 104).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '91625dce9ac32088_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85d1ab50-855f-444b-9037-707ea446a865', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 104).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '304c4498f5eef6d5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc6dddb6-bee0-437b-96e9-913871f5d95d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 104).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6c6f0638cf477115_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3f5680e-9160-4e56-bbf7-53cfcb3fddc4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 104).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '4bdae688a6ce9733_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34e07de4-ae4a-422f-ad5d-b98b818735c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 104).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0e4ef764c9880d6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d37e109e-768b-45eb-918e-c077a8097c45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 104).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 104).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '590b1ad5f089fe9c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('896d3d3e-4a85-4adb-a8e9-f72ca0832dd9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 104).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 104).', '{}', 'Automation', 10.0, '962da687daba1b60_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceb53558-87fd-49bf-a12c-c0e642e44f65', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 105).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c3faea8e580e877d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd1bcbcc-1858-4ab4-b7de-1214e9fb070b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 105).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '03250a6924950b07_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b03f241-5784-40ba-a9fa-7111e97f9c47', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 105).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 105).', '{}', 'Network Fundamentals', 12.0, '847ae0b6aa6daea7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55b8a2f8-6191-44d3-aeaa-f023b61479e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 105).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 105).', '{}', 'Network Fundamentals', 12.0, '0c5e50a72bfb2c5e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4023f580-eed0-4635-933c-cb7a109aed85', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 105).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4e00db508b21a4cb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c3f110d-b933-4be7-81a3-c06ab8c955e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 105).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ed04430180d2c62e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5766e80a-56cf-4a70-90c3-37e94a7a873d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 105).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2523fba31ee749ab_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcdecc2d-7b76-4479-bbc4-c59db1135b27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 105).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '21c7f09fb00c018b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41b53a6e-4a5a-4099-b73e-4e16d8ae8caf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 105).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '77c28a026b46d763_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1de322f8-52b2-4e9d-97bd-9c86d9effa13', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 105).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '606684d2916e3845_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('541765be-ddfe-4cda-91aa-2399ffd998d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 105).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'dce6299f08d96a60_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1319ed62-2cf9-40fb-8ed1-95b73b9b04a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 105).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 105).', '{}', 'IP Connectivity', 12.0, '9201f340178f7f8d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b007dec-72a5-4571-a1b4-9337376f029c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 105).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '934da9e947d66d36_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f3b541c-3791-43eb-8942-9292b3747557', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 105).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '730fe53865a5aab5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7bcc558-cdbf-4328-a7a8-4877ee15884e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 105).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '362b7b2b2d5f90d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68c5c926-5551-4bfb-b82c-e806e9a81693', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 105).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7f47da8510818981_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8df291d-d86e-427a-a14f-6a8420741460', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 105).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8108cfcddc6cd99a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eec83fae-581d-4369-bdc0-b041acad2181', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 105).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9ac233307d1dd46e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3899acc1-e33d-4e3b-a5c9-1830a5805af7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 105).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 105).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '3aa97db0809e0f54_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2946a606-55de-4f24-a60e-21ee05f8fbf1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 105).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 105).', '{}', 'Automation', 10.0, 'e72b2a778399d91b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a25a6de9-d0ad-4e33-b0a1-24b1e6799ce5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 106).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ff4731967b1fcda0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41709f27-9273-4c99-9ba0-720bd60ce92c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 106).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'dc94c3640e031ded_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bd943ad-25a6-409d-ad4d-6acfc0ad11cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 106).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 106).', '{}', 'Network Fundamentals', 12.0, '084c2da479d6e9f4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aac5a1f9-7a92-469e-9457-b77a00191d40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 106).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 106).', '{}', 'Network Fundamentals', 12.0, '7a968aac5138f177_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44e70a5b-6469-430d-ae4b-81d9de56428c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 106).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b57715071f45037d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d15d2d2a-e655-4f55-9243-7331a71b41b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 106).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4ecfb9e93bdc19bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ec3baba-49ad-446e-88f4-0dd2d8f52098', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 106).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e4e744f0112bb306_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('990ce72b-9644-4168-9778-658db66f429e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 106).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bbf5c4778d62575e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fb6f166-8c5e-4f44-97b1-f1bf2f2c3c62', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 106).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'afc53ec322ea960b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42e04635-0b76-4355-a5b3-d11cfcfe71b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 106).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'eafd4a5b0b2648d9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d67cfef-d89f-4b77-aa92-37ea1fa2c0fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 106).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '00588ebb5cd14a82_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cc8574c-2ae7-4a8e-9829-206ae0702c65', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 106).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 106).', '{}', 'IP Connectivity', 12.0, '57bdbc171ce8610a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c31bc9d-2093-4d94-ba97-71d97dfd2580', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 106).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '19bf0f513444956b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a44c3132-42c6-446c-8619-cc0ec96ad2ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 106).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '345df5cd88eebd1c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b48762cb-e6c4-424f-a443-1386b229160f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 106).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5de33b68b3ef2455_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5403542-c291-49bb-bbf2-8cb5bf1fc338', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 106).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '41e4e2438b4fa988_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b79b5df-4bea-448d-9938-c72b634958e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 106).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '22482c8cffeebb22_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df1fdd90-63f8-4a6d-9636-57c6da9bed27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 106).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3d7395dbb72af728_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('505a6a13-8b1e-42c8-8e31-7dcc8de3c97f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 106).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 106).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b32fa742d1c5b3b0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be4730bd-4cf3-4f68-8470-c4c49733a1ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 106).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 106).', '{}', 'Automation', 10.0, 'db962c3fd87066b4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9218ab6-e563-47e5-ac45-1e3f77a49cef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 107).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '85a0478d66db9f71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37cd8e78-755f-4702-a115-bcc665f637ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 107).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f020a20a657fad3c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6218e3a-aea0-417c-8bcb-91452d70ab7a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 107).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 107).', '{}', 'Network Fundamentals', 12.0, '9dfae3964e8bd097_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7171f869-3c17-412a-bdb8-8776efb86818', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 107).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 107).', '{}', 'Network Fundamentals', 12.0, '6cfd8773fdfb4807_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad31b16e-6aa1-4840-8499-0e6ff8a8862d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 107).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4678dd3286dca4ec_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66b2f95f-d237-4e6d-a637-e35a4765173e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 107).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd6f1ad892dee1430_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('557e95d4-d145-4cd8-84fb-9def62f5f27f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 107).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '68ac579fd1d543f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('780bac5d-0de7-4c23-982f-24f6db3e5917', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 107).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '734d1610be7fb841_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('105fc38f-7055-44b2-9c46-166889cc05a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 107).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '84edb35268af4d9a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68677588-b578-4d3a-9282-5fc96333e036', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 107).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '6c701d60d8a2daef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd5cda69-6805-4563-98bf-091452041f70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 107).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c809b5397283e87e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cec00df-0c21-47f8-be47-29e38f169ca4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 107).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 107).', '{}', 'IP Connectivity', 12.0, '79637bfdd23e54a2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c38795ad-5d14-4d6b-8f4b-64eaadd5f5f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 107).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9c563884953c630f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a73465a-3070-4606-9619-377cb719e4ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 107).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9527204b5c0f4ff5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1d7dec5-6690-4406-b5d2-9917ee142d7d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 107).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f32dfa596a64feaf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c354c85a-75ee-430b-be6c-d4a142303e59', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 107).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'aa4e2cb077e35fc6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de0f4aac-2283-4dab-9ded-6627092750d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 107).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9f87359a3f0eed0d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f37a97b1-895f-46c7-9c2b-141f02e45eb9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 107).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7d08908c486d97a4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8ad99c1-6f4b-4a4a-8b2e-b909ae20ba21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 107).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 107).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c286bb9f30f3886a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f094902-3f49-4c67-861a-12de707965ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 107).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 107).', '{}', 'Automation', 10.0, '5577a83aaa11fc0a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fa82a9c-e074-4161-9d48-ae5b44329f8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 108).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ad150411e504c5a1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15456dbc-1879-480d-89c0-0e895c6a796f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 108).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bd0b0b90bcae8867_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('124752f7-5661-42dd-8550-06f6ecca62eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 108).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table (Variant 108).', '{}', 'Network Fundamentals', 12.0, '7c862233c42b23ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ec0da1c-7982-495a-a9c5-d130bb2a1bfe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 108).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit (Variant 108).', '{}', 'Network Fundamentals', 12.0, 'f800f4ab8d5b24dc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('086929ae-46df-49ca-88aa-f3a66b4bbbd8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 108).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c9054316a8fc5b65_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('523ee223-6d1b-420e-8c4d-f615d5ae8bce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 108).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a494f40257525f50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f0d2d99-2152-41e0-8018-d8a3d948119b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 108).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '333ef93f4d40e07c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c2be0ee-031a-404e-97e6-89ec328ea364', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 108).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a89a3e5a2a7144c4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03de48c3-45d2-4e87-bfa2-3c169a93cc87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 108).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'aebd6d242ea2e210_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16b4d487-348c-4c81-aca1-1af79b28eb0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 108).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '24f76d371a0dfc7e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b667139-0bc8-4be7-854d-ff171d36a9da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 108).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '714d7f8bb6471b77_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb1a4f20-aeb5-4572-b4c6-5a1d61de4e2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 108).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol (Variant 108).', '{}', 'IP Connectivity', 12.0, '5a65cfd55a385ad8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2946152a-25d5-4522-9b7a-1b920d070290', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 108).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '461b8292393ed648_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6656cde4-e118-4b57-a51f-22277fb6a6b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 108).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1353f059f2d9573d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a5492be-4ef7-4304-80e1-5a6f0e91e26f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 108).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4cdc581d8bff6b97_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba6e05de-32d2-443e-bdc1-1717488904de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.0.0.0/24 network (variant 108).', '[{"id": "A", "text": "access-list 1 permit 10.0.0.0 0.0.0.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.0.0.0 0.0.0.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.0.0.0 255.255.255.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.0.0.0 0.0.0.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.0.0.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '97873416bdb31cbc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bfd5059-7ba0-4aa8-93a0-cb4f863faf81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 108).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a482de295924cb31_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ec3eae4-0e46-4b02-9c71-09639d8038c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 108).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '05228cdeda067071_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49bba53b-5b5a-44d6-8d76-7cb6621ccc0a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 108).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040 (Variant 108).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ee173842e57dc0d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac32eb42-b1d9-44a9-b2cf-b23c962483a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 108).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages (Variant 108).', '{}', 'Automation', 10.0, '4c0b07485c80c3d1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('732c581a-f260-4061-885c-a8f6879f6db6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP?', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '1a258a468b5dc495_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed1fc776-cca1-4b9c-b98d-2e7e15177e4d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute?', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Selecting the best path", "is_correct": false}, {"id": "C", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '24a835cbff91e9bb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88ebff2c-1646-4d5c-8ba9-1c3666418612', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution?', '[{"id": "A", "text": "LDP", "is_correct": true}, {"id": "B", "text": "RSVP-TE", "is_correct": false}, {"id": "C", "text": "MP-BGP", "is_correct": false}, {"id": "D", "text": "SR-MPLS", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, 'e48179221a57df81_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2e646f0-485b-4201-8a46-c8567dccd2c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos?', '[{"id": "A", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "B", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'd1ed732e1169a2cf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fac5a742-e1b8-40a6-a516-b71fa81757da', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide?', '[{"id": "A", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "B", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "C", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '818a19eac3cf8c37_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ee4d9d1-f9dd-4f46-ae62-95f7ada52978', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct?', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "C", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "D", "text": "FRR protects against node failures only", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, 'c1307652d2aac65c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab6ff8ca-1a4a-4c3f-b9b9-7b284deee875', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO)', '[{"id": "A", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, 'e99c57c6e4c605de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('def0b71d-bdac-402b-87d9-c25d4a2912b4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos?', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "BGP community 100:1", "is_correct": false}, {"id": "C", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '2abedf62a642cab5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e431d1fa-7e1c-4ae6-9055-be7b52fa47d3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection''?', '[{"id": "A", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "B", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "C", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "D", "text": "Client-to-client reflection is disabled by default", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection''.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '9be97f94a090ec02_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ff5fd90-3c09-46ab-a135-30b2d427dffb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos?', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp neighbor", "is_correct": false}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '3babdbba0ee2f9fd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51a96e30-3185-4d33-a6a2-c4f164b8a41b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 2).', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '2bbc5603285cb176_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf1f61b3-dea2-4ea2-979e-3eea486d5002', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 2).', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Selecting the best path", "is_correct": false}, {"id": "C", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '0dfb5baf85bf1ed4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3289a01b-d853-4dbb-9bc0-1ee0bb542347', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 2).', '[{"id": "A", "text": "LDP", "is_correct": true}, {"id": "B", "text": "RSVP-TE", "is_correct": false}, {"id": "C", "text": "MP-BGP", "is_correct": false}, {"id": "D", "text": "SR-MPLS", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, 'dc30e55b4e32b3e2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fc6e5fe-9df2-4a43-b65e-6e03eddd4d85', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 2).', '[{"id": "A", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "B", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '6719582978cc3a3c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
