INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f28a27aa-fe23-4b79-bbaf-1388f59594fb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 38).', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp neighbor", "is_correct": false}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state (Variant 38).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '4a1b2eb605200544_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('990f697e-80a4-40c6-9f79-46a429a51a43', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 39).', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'fc493d3dd132d346_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('999043fe-307f-42a6-9cc5-061d4fcf3aa7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 39).', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Selecting the best path", "is_correct": false}, {"id": "C", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, 'd7eb4ef576349abd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5072673a-8343-4ca3-97b0-cf3b1352fe46', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 39).', '[{"id": "A", "text": "LDP", "is_correct": true}, {"id": "B", "text": "RSVP-TE", "is_correct": false}, {"id": "C", "text": "MP-BGP", "is_correct": false}, {"id": "D", "text": "SR-MPLS", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, '8fa46582712d5d83_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a8693d0-4162-4d5b-9b2c-f5931108395c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 39).', '[{"id": "A", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "B", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'fd013da9a9be50ba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0eeaab05-7523-4e1d-942b-5b3adefe81b4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 39).', '[{"id": "A", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "B", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "C", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '29e5bb4452445ee6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c50f8dfc-83d8-4e68-9cb8-0bc2762c4aef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 39).', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "C", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "D", "text": "FRR protects against node failures only", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '15de021170355996_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9effed5-6b28-45ec-afa0-8a7541440c8f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 39).', '[{"id": "A", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, '8c8cbd003cdd3633_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b063d7a3-c438-4092-a745-7e62041dc36c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 39).', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "BGP community 100:1", "is_correct": false}, {"id": "C", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '6ff577cb1fa93a2e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0b6a505-57ec-436b-bac1-94834707fcda', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 39).', '[{"id": "A", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "B", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "C", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "D", "text": "Client-to-client reflection is disabled by default", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection'' (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '9642b81730c993b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f508dc8-3e8e-4051-9c81-377525fb57ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 39).', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp neighbor", "is_correct": false}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state (Variant 39).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '0181bcb1e93e6617_gen_v3', true) ON CONFLICT (id) DO NOTHING;
