INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8a9eaf7-06cb-44f6-8050-860db976e027', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 62).', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '543e6861d212dbdd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9984f45f-7ad4-48b5-828c-539421e30765', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 62).', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Selecting the best path", "is_correct": false}, {"id": "C", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '52e5027cd719f1b8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b6f8fb0-ba51-4aa8-9873-0ecbad7ceffa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 62).', '[{"id": "A", "text": "LDP", "is_correct": true}, {"id": "B", "text": "RSVP-TE", "is_correct": false}, {"id": "C", "text": "MP-BGP", "is_correct": false}, {"id": "D", "text": "SR-MPLS", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, '2cb261318d306d7b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81b1ac72-81e5-486a-beec-79f8f95ff866', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 62).', '[{"id": "A", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "B", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'bb02d7b6b9fa720b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('659e6c5d-d98b-4b86-a59a-0c321163a9bd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 62).', '[{"id": "A", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "B", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "C", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'c2cad73a620cffae_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed653a2d-0285-4dd9-ba5c-fe6aa6034015', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 62).', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "C", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "D", "text": "FRR protects against node failures only", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, 'dc0d7208575f1b8d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ded04c51-a53b-4940-bcd6-a1e8e05021ac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 62).', '[{"id": "A", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, 'bc54eb052e672aa1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a323e8d-5353-4d54-9d01-3b7e48e95b5b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 62).', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "BGP community 100:1", "is_correct": false}, {"id": "C", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '42d48d1561531d7f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07e4fdf0-87eb-4ccc-a808-69622adc7cf8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 62).', '[{"id": "A", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "B", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "C", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "D", "text": "Client-to-client reflection is disabled by default", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection'' (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '2da14859ca936854_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('914ceee9-4765-458b-946d-b6c31cba1c71', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 62).', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp neighbor", "is_correct": false}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state (Variant 62).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, 'c571d37ea23fc15f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7969e4e7-da69-4b05-bb36-cc39270d0f01', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 63).', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID (Variant 63).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'a9405d7b070b88f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
