INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('277adb0b-d3cc-4862-8c3f-61605e5e72ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 72).', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "C", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "D", "text": "FRR protects against node failures only", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, 'b7f84e0e067244e0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25f1a568-d7d1-43f4-b9a7-f99d61686da0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 72).', '[{"id": "A", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, 'b14faba414587884_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85019b49-04c9-4853-93c7-8fd898e07bf1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 72).', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "BGP community 100:1", "is_correct": false}, {"id": "C", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '462b742b38b9e352_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb1e8a13-f8aa-4bce-ac1b-d3eef6f25385', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 72).', '[{"id": "A", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "B", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "C", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "D", "text": "Client-to-client reflection is disabled by default", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection'' (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '53a624e89ffedc19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e74d529-821d-4627-ac1b-000cf44fe08a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 72).', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp neighbor", "is_correct": false}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state (Variant 72).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, 'ac3dbe123b4d517d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('444a34ec-3a6b-4095-97ae-448d92bd3d19', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 73).', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '3bd2a9c70a9cd6ed_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bffbdad-5511-41c9-88c8-f7db0e7d72da', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 73).', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Selecting the best path", "is_correct": false}, {"id": "C", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '139e718d4af65ad5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47e0d1ce-4733-4a10-86c7-7cc91e25027c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 73).', '[{"id": "A", "text": "LDP", "is_correct": true}, {"id": "B", "text": "RSVP-TE", "is_correct": false}, {"id": "C", "text": "MP-BGP", "is_correct": false}, {"id": "D", "text": "SR-MPLS", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, '791d570c4049496c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f70e1e6-8032-4363-b719-d993994b4f10', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 73).', '[{"id": "A", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "B", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, 'dd4d7cb76f61b3b9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d515314c-776e-4ea7-a159-b349281846f4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 73).', '[{"id": "A", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "B", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "C", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '649f59a83aec34eb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1b66b03-ad67-43d4-a0ea-0031fc658ef4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 73).', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "C", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "D", "text": "FRR protects against node failures only", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms (Variant 73).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '7576a2a627aea9c9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
