INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65e1f196-7aea-494e-9994-edb06d43f90e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 5, 'understand', 'Which two statements about MVPN (Multicast VPN) are correct? (Select TWO) (variant 19).', '[{"id": "A", "text": "MVPN uses a Default-MDT and Data-MDT model", "is_correct": true}, {"id": "B", "text": "PIM-SM must run in the core for all MVPN types", "is_correct": false}, {"id": "C", "text": "NG-MVPN uses BGP for auto-discovery", "is_correct": true}, {"id": "D", "text": "MVPN is not supported in Junos", "is_correct": false}]', 'MVPN uses Default-MDT for control traffic and Data-MDT for data traffic. NG-MVPN (RFC 6513/6514) uses BGP for auto-discovery (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/mvpn/"}', 'MVPN', 14.0, '97823c53970a0718_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdd8bf62-83cc-43a7-8092-ec44c7dfb5ef', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'In Segment Routing, what is the function of the ''adjacency SID'' (variant 19).', '[{"id": "A", "text": "Identifies a specific adjacency on a node, forcing traffic through that link", "is_correct": true}, {"id": "B", "text": "Identifies the node itself", "is_correct": false}, {"id": "C", "text": "Represents a prefix in the IGP", "is_correct": false}, {"id": "D", "text": "Carries MPLS EXP bits", "is_correct": false}]', 'Adjacency SID identifies a specific link/adjacency. Traffic steered through an adjacency SID must traverse that specific link, enabling strict path control (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/segment-routing/"}', 'Segment Routing', 14.0, '3ceca5669aee91f5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72991c1f-6430-4e15-9321-940fb7308ddc', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option A (variant 19).', '[{"id": "A", "text": "VRF-to-VRF connections at the ASBR using separate physical/logical interfaces", "is_correct": true}, {"id": "B", "text": "MP-eBGP between ASBRs with labeled VPNv4 routes", "is_correct": false}, {"id": "C", "text": "BGP labeled unicast across ASes", "is_correct": false}, {"id": "D", "text": "LDP session between ASBRs", "is_correct": false}]', 'Option A (VRF-to-VRF) uses an ASBR as a VRF-to-VRF gateway. Each ASBR is a PE for its VPN, connected via sub-interfaces. This approach does not scale well (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '9b4022eca95ee10a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe7b0a2a-ee0c-4d33-90e8-62005a7b2695', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the purpose of BGP add-path feature in Junos (variant 19).', '[{"id": "A", "text": "Allows advertising multiple paths for the same prefix to BGP peers", "is_correct": true}, {"id": "B", "text": "Adds a new BGP path to the routing table", "is_correct": false}, {"id": "C", "text": "Increases the maximum number of BGP prefixes", "is_correct": false}, {"id": "D", "text": "Enables BGP multipath for load balancing", "is_correct": false}]', 'BGP add-path enables a router to advertise multiple paths for the same prefix, providing fast convergence and better load balancing in redundant topologies (Variant 19).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 14.0, 'd6bf97484dfe2680_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62285403-811d-48ba-8ab1-171ec85dd695', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option B (variant 20).', '[{"id": "A", "text": "ASBRs exchange labeled VPN-IPv4 routes via MP-eBGP without running IGP between ASes", "is_correct": true}, {"id": "B", "text": "VRF-to-VRF connections at the ASBR", "is_correct": false}, {"id": "C", "text": "MPLS LDP between ASBRs", "is_correct": false}, {"id": "D", "text": "A full mesh of IBGP sessions between all PEs", "is_correct": false}]', 'In Option B, ASBRs peer via MP-eBGP exchanging labeled VPN-IPv4 routes. The ASBR must swap both the transport and service labels (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '402151ec50dd4833_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1697417-4e55-4b2c-8736-55e9c059cff9', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'Which Junos feature enables seamless MPLS handoff between domains in inter-AS Option C (variant 20).', '[{"id": "A", "text": "BGP labeled unicast (inet-labeled-unicast)", "is_correct": true}, {"id": "B", "text": "LDP between ASBRs", "is_correct": false}, {"id": "C", "text": "RSVP-TE across AS boundaries", "is_correct": false}, {"id": "D", "text": "Static MPLS labels", "is_correct": false}]', 'Option C uses BGP labeled unicast (family inet-labeled-unicast) to distribute loopback reachability with MPLS labels across AS boundaries (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '5616056d00e672e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56b8354b-8c67-4983-b5e1-95191b64d6da', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the function of ''autonomous-system lo0'' in Junos BGP configurations (variant 20).', '[{"id": "A", "text": "Allows a router to appear in a different AS for BGP purposes on the loopback interface", "is_correct": true}, {"id": "B", "text": "Sets the BGP AS number globally", "is_correct": false}, {"id": "C", "text": "Configures the loopback IP address for the AS", "is_correct": false}, {"id": "D", "text": "Enables BGP on the loopback interface", "is_correct": false}]', '''autonomous-system lo0'' allows a router to use a different AS number for BGP peering. Used in AS migration scenarios and inter-AS designs (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '51ad46013e7eeadc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
