INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45bdb9ec-10a7-4769-97f9-80963b19c928', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 20).', '[{"id": "A", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "B", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "C", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}, {"id": "D", "text": "Geo-IP based blocking", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, '4d92e74e2c0e45b3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1e9019e-2159-4207-82d8-0340c5f7631f', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 20).', '[{"id": "A", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "B", "text": "Route mode (Layer 3)", "is_correct": false}, {"id": "C", "text": "NPB (Network Packet Broker) mode", "is_correct": false}, {"id": "D", "text": "All of the above are supported", "is_correct": true}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, '84b87fe129f224c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c98ebbe-1800-4c26-8cbb-833357c58196', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'Which SRX feature enables inter-chassis communication in an active-active cluster (variant 20).', '[{"id": "A", "text": "Chassis cluster control link for session state synchronization", "is_correct": true}, {"id": "B", "text": "Spanning Tree Protocol", "is_correct": false}, {"id": "C", "text": "VRRP between cluster members", "is_correct": false}, {"id": "D", "text": "LACP between cluster members", "is_correct": false}]', 'Active-active clustering requires the control link for IPC and fabric link for session state synchronization between the two cluster members (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster Advanced', 14.0, 'cfb3982c5c20251f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d6b042b-40ca-4819-a7f6-bed80581fdb2', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of ''security forwarding-options'' on SRX (variant 20).', '[{"id": "A", "text": "Configures flow-based processing options including fallback to packet mode", "is_correct": true}, {"id": "B", "text": "Sets routing preferences for security zones", "is_correct": false}, {"id": "C", "text": "Enables NAT on specific interfaces", "is_correct": false}, {"id": "D", "text": "Configures IPsec VPN forwarding", "is_correct": false}]', '''security forwarding-options'' configures the flow-mode behavior, including packet-based fallback for high-throughput traffic that should bypass stateful inspection (Variant 20).', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-forwarding/"}', 'Forwarding Options', 12.0, '5924bff66de74967_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48fa23e1-317c-4fb9-885e-f9e65d598d9a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 21).', '[{"id": "A", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "B", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}, {"id": "C", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "D", "text": "Load balancing between two independent firewalls", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover (Variant 21).', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, 'b798e82ddabb0abd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
