INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2390dba-365c-475a-8bde-e6f685f8d16a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 41).', '[{"id": "A", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "B", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "C", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}, {"id": "D", "text": "Geo-IP based blocking", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, 'f2afd1c7b9b128bb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebf41505-7e62-4ffb-b79b-8d79516bc194', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 41).', '[{"id": "A", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "B", "text": "Route mode (Layer 3)", "is_correct": false}, {"id": "C", "text": "NPB (Network Packet Broker) mode", "is_correct": false}, {"id": "D", "text": "All of the above are supported", "is_correct": true}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, 'f5f441034ca35cde_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a93c381-5543-44d0-8ba7-47c67f6375bf', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'Which SRX feature enables inter-chassis communication in an active-active cluster (variant 41).', '[{"id": "A", "text": "Chassis cluster control link for session state synchronization", "is_correct": true}, {"id": "B", "text": "Spanning Tree Protocol", "is_correct": false}, {"id": "C", "text": "VRRP between cluster members", "is_correct": false}, {"id": "D", "text": "LACP between cluster members", "is_correct": false}]', 'Active-active clustering requires the control link for IPC and fabric link for session state synchronization between the two cluster members (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster Advanced', 14.0, '3b433c45cde96905_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed34a999-1c0f-46ee-8154-6a1aae7bc736', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of ''security forwarding-options'' on SRX (variant 41).', '[{"id": "A", "text": "Configures flow-based processing options including fallback to packet mode", "is_correct": true}, {"id": "B", "text": "Sets routing preferences for security zones", "is_correct": false}, {"id": "C", "text": "Enables NAT on specific interfaces", "is_correct": false}, {"id": "D", "text": "Configures IPsec VPN forwarding", "is_correct": false}]', '''security forwarding-options'' configures the flow-mode behavior, including packet-based fallback for high-throughput traffic that should bypass stateful inspection (Variant 41).', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-forwarding/"}', 'Forwarding Options', 12.0, '37bf4916676e964d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff4bf220-2bb8-4caf-9949-e5b1fc498735', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 42).', '[{"id": "A", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "B", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}, {"id": "C", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "D", "text": "Load balancing between two independent firewalls", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover (Variant 42).', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '8342f71e3e4c59f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
