INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe0b6c10-d6e1-4f22-b16e-c404a25f5067', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN (variant 3).', '[{"id": "A", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}, {"id": "B", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "C", "text": "VPLS over GRE between DCs", "is_correct": false}, {"id": "D", "text": "LDP-based MPLS between DC gateways", "is_correct": false}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, '58d5fe1e56b80537_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e11328ee-250e-416e-b6a2-b09ebea586b0', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN Route Type 4 (Ethernet Segment Route) (variant 4).', '[{"id": "A", "text": "Used for designated forwarder (DF) election for multi-homed segments", "is_correct": true}, {"id": "B", "text": "Advertises MAC addresses only", "is_correct": false}, {"id": "C", "text": "Carries VXLAN tunnel information", "is_correct": false}, {"id": "D", "text": "Signals IP prefix routes", "is_correct": false}]', 'Route Type 4 is used for DF election in multi-homed segments. PEs advertise the same ESI; the PE with the highest IP is elected DF for each VLAN (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Advanced', 14.0, '76d2172f3771a0da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fb20f8f-3515-4c6d-8b52-43b056b01daa', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 5, 'understand', 'Which two features are supported by EVPN Type 5 (IP Prefix Route)? (Select TWO) (variant 4).', '[{"id": "A", "text": "Inter-subnet forwarding (IP prefix advertisement across VNIs)", "is_correct": true}, {"id": "B", "text": "External network connectivity", "is_correct": true}, {"id": "C", "text": "MAC learning", "is_correct": false}, {"id": "D", "text": "DF election", "is_correct": false}]', 'Type 5 carries IP prefixes across VNIs, enabling inter-subnet forwarding without an L3 gateway per VNI. It also provides external connectivity (e.g., to WAN router) (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Type 5', 14.0, '38109fe87eec06f7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4b2bbd3-d197-4ba0-bbd5-e0c6e264b3e8', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model (variant 4).', '[{"id": "A", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}, {"id": "B", "text": "Only the ingress VTEP performs routing", "is_correct": false}, {"id": "C", "text": "Routing is done on a central gateway", "is_correct": false}, {"id": "D", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, '98352ecfe0f35d0d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe87377a-6b5f-4ab5-8110-61930c67cc2e', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN multi-homing ''all-active'' mode (variant 4).', '[{"id": "A", "text": "CE is multi-homed to multiple PEs with all links active; load balancing occurs per flow", "is_correct": true}, {"id": "B", "text": "Only one PE is active; others are standby", "is_correct": false}, {"id": "C", "text": "All traffic is duplicated to all PEs", "is_correct": false}, {"id": "D", "text": "CE connects to a single PE with redundant links", "is_correct": false}]', 'In all-active multi-homing, the CE connects to multiple PEs with all links forwarding traffic. Load balancing is per-flow based on hash of MAC/IP (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, '5b40806fdd69b23e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d813e1f1-9c40-498e-9f79-a41178c375b5', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN (variant 4).', '[{"id": "A", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}, {"id": "B", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "C", "text": "VPLS over GRE between DCs", "is_correct": false}, {"id": "D", "text": "LDP-based MPLS between DC gateways", "is_correct": false}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, '05cbbce6e24c8b6c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
