INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4038f84c-6eb3-4150-98a1-8beab98ccbdf', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 5, 'understand', 'Which two features are supported by EVPN Type 5 (IP Prefix Route)? (Select TWO) (variant 36).', '[{"id": "A", "text": "Inter-subnet forwarding (IP prefix advertisement across VNIs)", "is_correct": true}, {"id": "B", "text": "External network connectivity", "is_correct": true}, {"id": "C", "text": "MAC learning", "is_correct": false}, {"id": "D", "text": "DF election", "is_correct": false}]', 'Type 5 carries IP prefixes across VNIs, enabling inter-subnet forwarding without an L3 gateway per VNI. It also provides external connectivity (e.g., to WAN router) (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Type 5', 14.0, 'a927f4ceb6f53965_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06b460ef-ea4d-4b50-b210-a1f396e794a8', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model (variant 36).', '[{"id": "A", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}, {"id": "B", "text": "Only the ingress VTEP performs routing", "is_correct": false}, {"id": "C", "text": "Routing is done on a central gateway", "is_correct": false}, {"id": "D", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, 'c69bf015137d4f1e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f83a36d5-4b7f-4044-b3c1-7c396c52ce7a', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN multi-homing ''all-active'' mode (variant 36).', '[{"id": "A", "text": "CE is multi-homed to multiple PEs with all links active; load balancing occurs per flow", "is_correct": true}, {"id": "B", "text": "Only one PE is active; others are standby", "is_correct": false}, {"id": "C", "text": "All traffic is duplicated to all PEs", "is_correct": false}, {"id": "D", "text": "CE connects to a single PE with redundant links", "is_correct": false}]', 'In all-active multi-homing, the CE connects to multiple PEs with all links forwarding traffic. Load balancing is per-flow based on hash of MAC/IP (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, '91ce936500a2411d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab89273a-86ba-452a-b0fe-a746f60b0264', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN (variant 36).', '[{"id": "A", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}, {"id": "B", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "C", "text": "VPLS over GRE between DCs", "is_correct": false}, {"id": "D", "text": "LDP-based MPLS between DC gateways", "is_correct": false}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding (Variant 36).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, 'a41887f9fba08101_gen_v3', true) ON CONFLICT (id) DO NOTHING;
