INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00a38727-5592-4734-a556-f826c3e3b9bf', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 46).', '[{"id": "A", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "B", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "C", "text": "SNMP MIB walker", "is_correct": false}, {"id": "D", "text": "Syslog-ng", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, '6da80ff7860e3604_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f0e4425-4618-4a9c-88c7-bb43f6a7dc76', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 46).', '[{"id": "A", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "B", "text": "CRON scheduler", "is_correct": false}, {"id": "C", "text": "SNMP traps", "is_correct": false}, {"id": "D", "text": "Manual CLI monitoring", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, 'cb1f5196309dfd23_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae58c46f-2827-4b7d-8d41-e4424065f78e', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 46).', '[{"id": "A", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "B", "text": "Commits the configuration permanently", "is_correct": false}, {"id": "C", "text": "Displays the commit history", "is_correct": false}, {"id": "D", "text": "Checks configuration syntax only", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs (Variant 46).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, '85a48378f2775b05_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d084d5c6-4129-4292-89f2-73e30e3a98c1', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 47).', '[{"id": "A", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "B", "text": "Directly push configuration to production", "is_correct": false}, {"id": "C", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "D", "text": "Use only SNMP for configuration", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production (Variant 47).', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, 'e8f1223a2fcb5d26_gen_v3', true) ON CONFLICT (id) DO NOTHING;
